insert into content(key,data,updated_at) values('sec:a-r8-p7',$mkd${"id": "a-r8-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 3, "round": 8, "level": "중급", "title": "A급 과제 8회 · PART 7 (기출독해 3문항 15·16회)", "notes": [], "items": [], "sets": [{"range": "155-157", "sub": "기출독해 3문항 15회", "passage": "NOTICE: HERALD PARK FESTIVAL UPDATE\nAs in previous years, staff members are being asked to accept overtime hours to work this coming weekend, especially on Sunday, when we expect up to 5,000 festival attendees. We will be providing special bright-green T-shirts to distinguish you as staff. At the start of the day, please prioritise guiding musicians as well as food and merchandise vendors to their assigned locations. Remember that maps will be posted on the bulletin boards throughout the park if you do not have a printed one handy.\nJohn Ashmore is the lead for this event, so if you have any questions, please send him an e-mail at jashmore@heraldpark.org.uk. The event organiser, Cresthouse Events, will have a representative at a meeting on Wednesday at 3:00 P.M. in our administration building. We will review the weekend performance schedule and go over the park areas where each of you will be assigned. This is a mandatory meeting for all staff.", "tr": "공지: HERALD PARK 축제 업데이트\n예년과 마찬가지로 직원들은 이번 주말, 특히 최대 5,000명의 축제 참석자가 예상되는 일요일에 초과 근무를 수락해 주시기 바랍니다. 여러분을 직원으로 구분할 수 있도록 특별한 밝은 초록색 티셔츠를 제공합니다. 하루를 시작할 때 음악가들과 음식·상품 판매자들을 지정된 위치로 안내하는 일을 우선해 주십시오. 인쇄된 지도가 없으면 공원 곳곳의 게시판에 지도가 게시된다는 점을 기억하세요. John Ashmore가 이 행사의 책임자이니 질문이 있으면 jashmore@heraldpark.org.uk로 이메일을 보내 주세요. 행사 주최사 Cresthouse Events의 대표자가 수요일 오후 3시 행정동 회의에 참석합니다. 주말 공연 일정을 검토하고 여러분 각자가 배정될 공원 구역을 살펴볼 것입니다. 이 회의는 전 직원 필수입니다.", "vocab": "previous 형 이전의 / overtime 명 초과 근무 / attendee 명 참석자 / distinguish 동 구별하다 / prioritise 동 우선시하다 / merchandise 명 상품 / vendor 명 판매업자 / assigned 형 배정된 / bulletin board 명 게시판 / handy 형 가까이에 있는 / representative 명 대표자 / go over 구 검토하다 / mandatory 형 의무적인", "g": {"notice": ["명사", "공지"], "herald": ["고유명사", "헤럴드(공원명)"], "park": ["명사", "공원"], "festival": ["명사", "축제"], "update": ["명사", "업데이트"], "as": ["접속사", "~처럼, ~로서"], "in": ["전치사", "~에, ~안에"], "previous": ["형용사", "이전의"], "years": ["명사", "년, 해", "year"], "staff": ["명사", "직원"], "members": ["명사", "회원들, 직원들", "member"], "are": ["동사", "~이다", "be"], "being": ["현재분사", "~되고 있는", "be"], "asked": ["과거분사", "요청받은", "ask"], "to": ["전치사", "~로, ~하기 위해"], "accept": ["동사", "받다, 수락하다"], "overtime": ["명사", "초과 근무"], "hours": ["명사", "시간", "hour"], "work": ["동사", "일하다"], "this": ["한정사", "이, 이것"], "coming": ["현재분사", "다가오는", "come"], "weekend": ["명사", "주말"], "especially": ["부사", "특히"], "on": ["전치사", "~에"], "sunday": ["명사", "일요일"], "when": ["접속사", "~할 때"], "we": ["대명사", "우리"], "expect": ["동사", "예상하다"], "up": ["부사", "(team up) 함께, 최대"], "5,000": ["숫자", "5,000"], "attendees": ["명사", "참석자들", "attendee"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "providing": ["현재분사", "제공하는", "provide"], "special": ["형용사", "특별한"], "bright-green": ["형용사", "밝은 초록색의"], "t-shirts": ["명사", "티셔츠들", "t-shirt"], "distinguish": ["동사", "구별하다"], "you": ["대명사", "당신, 여러분"], "at": ["전치사", "~에서"], "the": ["관사", "그"], "start": ["명사", "시작"], "of": ["전치사", "~의"], "day": ["명사", "날, 하루"], "please": ["부사", "부디"], "prioritise": ["동사", "우선시하다"], "guiding": ["동명사", "안내하는 것", "guide"], "musicians": ["명사", "음악가들", "musician"], "well": ["부사", "잘"], "food": ["명사", "음식"], "and": ["접속사", "그리고"], "merchandise": ["명사", "상품"], "vendors": ["명사", "판매자들", "vendor"], "their": ["한정사", "그들의"], "assigned": ["과거분사", "배정된", "assign"], "locations": ["명사", "지점들", "location"], "remember": ["동사", "기억하다"], "that": ["접속사", "~라는 것, ~하는"], "maps": ["명사", "지도들", "map"], "posted": ["과거분사", "게시된", "post"], "bulletin": ["명사", "게시(bulletin board 게시판)"], "boards": ["명사", "게시판들", "board"], "throughout": ["전치사", "~전역에, 곳곳에"], "if": ["접속사", "만약 ~라면"], "do": ["동사", "하다"], "not": ["부사", "~아니다"], "have": ["동사", "가지다, (완료)~했다"], "a": ["관사", "하나의"], "printed": ["형용사", "인쇄된"], "one": ["대명사", "하나, 한 곳"], "handy": ["형용사", "가까이 있는"], "john": ["고유명사", "존(이름)"], "ashmore": ["고유명사", "애슈모어(이름)"], "is": ["동사", "~이다", "be"], "lead": ["명사", "책임자"], "for": ["전치사", "~을 위해, ~동안"], "event": ["명사", "행사"], "so": ["접속사", "그래서, 그러므로"], "any": ["한정사", "어떤, 모든"], "questions": ["명사", "질문들", "question"], "send": ["동사", "보내다"], "him": ["대명사", "그를"], "an": ["관사", "하나의"], "e-mail": ["명사", "이메일"], "jashmore@heraldpark.org.uk": ["명사", "이메일 주소"], "organiser": ["명사", "주최자"], "cresthouse": ["고유명사", "크레스트하우스(회사명)"], "events": ["명사", "행사들", "event"], "representative": ["명사", "대표자, 담당자"], "meeting": ["명사", "회의"], "wednesday": ["명사", "수요일"], "3:00": ["숫자", "3시"], "p.m": ["명사", "오후"], "our": ["한정사", "우리의"], "administration": ["명사", "관리, 행정"], "building": ["명사", "건물"], "review": ["동사", "검토하다"], "performance": ["명사", "공연"], "schedule": ["명사", "일정"], "go": ["동사", "가다"], "over": ["부사", "살펴보다(go over)"], "areas": ["명사", "구역들", "area"], "where": ["관계사", "~하는 곳"], "each": ["대명사", "각자"], "mandatory": ["형용사", "의무적인"], "all": ["한정사", "모든"]}, "questions": [{"no": 155, "q": "For whom is the notice written?", "options": ["Merchandise vendors", "Park employees", "Festival attendees", "Cresthouse Events staff"], "answer": 1, "explain": "정답 (B) Park employees\n해석: 이 공지는 누구를 위해 작성되었는가?\n정답 근거: \"직원들은 초과 근무를 수락해 달라\", \"여러분을 직원으로 구분\", \"배정될 공원 구역\" → 공원 직원 대상.\n오답 분석: (A) 상품 판매자는 안내를 받는 대상. / (C) 축제 참석자는 안내 대상 아님. / (D) Cresthouse Events는 주최사로 대표자가 회의에 올 뿐.\n지문 개요: Herald Park 직원들에게 예년처럼 주말(특히 5,000명이 예상되는 일요일) 초과 근무를 요청하며, 초록 티셔츠 지급, 음악가·판매자 안내 우선, 게시판 지도, 담당자 John Ashmore 연락처, 수요일 3시 필수 회의(공연 일정·배치 구역 검토)를 안내하는 공지.", "translation": "이 공지는 누구를 위해 작성되었는가?", "vocab": "Paraphrase: staff members / park areas where each of you will be assigned → park employees", "g": {"for": ["전치사", "~을 위해, ~동안"], "whom": ["대명사", "누구"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "notice": ["명사", "공지"], "written": ["과거분사", "쓰인", "write"]}}, {"no": 156, "q": "What is indicated in the notice?", "options": ["Maps will be distributed to visitors.", "Additional staff will be hired.", "The festival is free of charge.", "The event has been held before."], "answer": 3, "explain": "정답 (D) The event has been held before.\n해석: 공지에서 언급된 것은?\n정답 근거: \"예년과 마찬가지로(As in previous years)\" → 행사가 이전에도 열렸음.\n오답 분석: (A) 지도는 직원용으로 게시판에 게시됨. / (B) 추가 채용이 아니라 기존 직원 초과 근무. / (C) 무료 여부 언급 없음.", "translation": "공지에서 언급된 것은?", "vocab": "Paraphrase: As in previous years → the event has been held before", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "언급된", "indicate"], "in": ["전치사", "~에, ~안에"], "the": ["관사", "그"], "notice": ["명사", "공지"]}}, {"no": 157, "q": "What topic will likely be discussed at the meeting on Wednesday?", "options": ["The schedule for musical entertainment", "The promotion of T-shirt sales", "Food preparation guidelines", "Rehearsal space limitations"], "answer": 0, "explain": "정답 (A) The schedule for musical entertainment\n해석: 수요일 회의에서 논의될 주제는?\n정답 근거: \"주말 공연 일정(performance schedule)을 검토\" → 음악 공연 일정.\n오답 분석: (B) 티셔츠는 직원 구분용이며 판매 아님. / (C) 음식 준비 지침 언급 없음. / (D) 리허설 공간 언급 없음.", "translation": "수요일 회의에서 논의될 주제는?", "vocab": "Paraphrase: review the weekend performance schedule → the schedule for musical entertainment", "g": {"what": ["한정사", "어떤"], "topic": ["명사", "주제"], "will": ["조동사", "~할 것이다"], "likely": ["부사", "아마"], "be": ["동사", "~이다, 되다"], "discussed": ["과거분사", "논의된", "discuss"], "at": ["전치사", "~에서"], "the": ["관사", "그"], "meeting": ["명사", "회의"], "on": ["전치사", "~에"], "wednesday": ["명사", "수요일"]}}]}, {"range": "158-160", "sub": "기출독해 3문항 15회", "passage": "To: Koshi Okamoto <kokamoto@emailright.co.uk>\nFrom: Effix Homes <info@effixhomes.co.uk>\nDate: 28 March\nSubject: Lease signing\nDear Mr. Okamoto,\nCongratulations on choosing a new residence in Cardiff. Your lease signing is scheduled for tomorrow, 29 March, at 9 A.M. It is a two-year lease starting in April. Please bring proof of employment (such as a pay stub), two forms of personal identification, and your current landlord's contact information. At the lease signing, be prepared to pay the real estate agent's fee to us and the security deposit to the landlord. Your first month's rent will be due on 1 April.\nPlease contact us with any questions.\nBest, Effix Homes", "tr": "수신: Koshi Okamoto / 발신: Effix Homes / 날짜: 3월 28일 / 제목: 임대 계약 서명\nOkamoto 씨께, Cardiff의 새 거주지를 선택하신 것을 축하드립니다. 임대 계약 서명은 내일 3월 29일 오전 9시로 예정되어 있습니다. 4월부터 시작하는 2년 임대입니다. 재직 증명(급여 명세서 등), 신분증 2종, 현재 집주인의 연락처를 가져오십시오. 계약 서명 시 저희에게 부동산 중개 수수료를, 집주인에게 보증금을 지불할 준비를 하십시오. 첫 달 임대료는 4월 1일이 납부 기한입니다. 질문이 있으면 연락 주십시오. Effix", "vocab": "residence 명 거주지 / lease 명 임대 계약 / proof 명 증명(서) / employment 명 고용 / pay stub 명 급여 명세서 / identification 명 신분증 / landlord 명 집주인 / real estate agent 명 부동산 중개인 / fee 명 수수료 / security deposit 명 보증금 / rent 명 집세 / due 형 지불 기일이 된", "g": {"to": ["전치사", "~로, ~하기 위해"], "koshi": ["고유명사", "코시(이름)"], "okamoto": ["고유명사", "오카모토(이름)"], "kokamoto@emailright.co.uk": ["명사", "이메일 주소"], "from": ["전치사", "~로부터"], "effix": ["고유명사", "에픽스(회사명)"], "homes": ["고유명사", "홈즈(회사명)"], "info@effixhomes.co.uk": ["명사", "이메일 주소"], "date": ["명사", "날짜"], "28": ["숫자", "28"], "march": ["명사", "3월"], "subject": ["명사", "제목"], "lease": ["명사", "임대 계약"], "signing": ["명사", "서명"], "dear": ["형용사", "친애하는"], "mr": ["명사", "~씨(남성)"], "congratulations": ["명사", "축하합니다", "congratulation"], "on": ["전치사", "~에"], "choosing": ["동명사", "선택하는 것", "choose"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "residence": ["명사", "거주지"], "in": ["전치사", "~에, ~안에"], "cardiff": ["고유명사", "카디프(도시)"], "your": ["한정사", "당신의"], "is": ["동사", "~이다", "be"], "scheduled": ["과거분사", "예정된", "schedule"], "for": ["전치사", "~을 위해, ~동안"], "tomorrow": ["부사", "내일"], "29": ["숫자", "29"], "at": ["전치사", "~에서"], "9": ["숫자", "9"], "a.m": ["명사", "오전"], "it": ["대명사", "그것"], "two-year": ["형용사", "2년의"], "starting": ["전치사", "~부터"], "april": ["명사", "4월"], "please": ["부사", "부디"], "bring": ["동사", "가져오다"], "proof": ["명사", "증명"], "of": ["전치사", "~의"], "employment": ["명사", "고용, 재직"], "such": ["형용사", "그러한"], "as": ["전치사", "~같은(such as)"], "pay": ["동사", "지불하다"], "stub": ["명사", "명세서(pay stub)"], "two": ["숫자", "2"], "forms": ["명사", "종류들", "form"], "personal": ["형용사", "개인의"], "identification": ["명사", "신분증"], "and": ["접속사", "그리고"], "current": ["형용사", "현재의"], "landlord's": ["명사", "집주인의", "landlord"], "contact": ["동사", "연락하다"], "information": ["명사", "정보"], "the": ["관사", "그"], "be": ["동사", "~이다, 되다"], "prepared": ["형용사", "준비된"], "real": ["형용사", "진짜의, 부동산의"], "estate": ["명사", "부동산(real estate)"], "agent's": ["명사", "중개인의", "agent"], "fee": ["명사", "수수료, 요금"], "us": ["대명사", "우리를"], "security": ["명사", "보안, 보증"], "deposit": ["명사", "보증금"], "landlord": ["명사", "집주인"], "first": ["형용사", "첫 번째의"], "month's": ["명사", "달의", "month"], "rent": ["명사", "임대료"], "will": ["조동사", "~할 것이다"], "due": ["형용사", "납부 기한인"], "1": ["숫자", "1"], "with": ["전치사", "~와 함께, ~으로"], "any": ["한정사", "어떤, 모든"], "questions": ["명사", "질문들", "question"], "best": ["형용사", "(맺음말) 안부를 담아"]}, "questions": [{"no": 158, "q": "What does the e-mail suggest about Mr. Okamoto?", "options": ["He will be changing jobs in April.", "He plans to move soon.", "He currently lives near his landlord.", "He plans to stay in Cardiff for only one year."], "answer": 1, "explain": "정답 (B) He plans to move soon.\n해석: 이메일이 Okamoto 씨에 대해 시사하는 것은?\n정답 근거: \"새 거주지 선택 축하\", \"4월부터 시작하는 임대\" → 곧 이사할 계획.\n오답 분석: (A) 4월에 이직한다는 언급 없음 — 재직 증명을 요구할 뿐. / (C) 현 집주인 근처 거주 언급 없음. / (D) 2년 임대이므로 1년만 머무는 것이 아님.\n지문 개요: Effix Homes가 Koshi Okamoto에게 3월 29일 오전 9시 Cardiff 거주지 2년 임대 계약 서명 일정을 알리며, 재직 증명·신분증 2종·현 집주인 연락처를 지참하고 중개 수수료와 보증금을 준비하라 하며, 첫 달 임대료는 4월 1일 납부라고 안내하는 이메일.", "translation": "이메일이 Okamoto 씨에 대해 시사하는 것은?", "vocab": "Paraphrase: choosing a new residence / two-year lease starting in April → plans to move soon", "g": {"what": ["대명사", "무엇"], "does": ["조동사", "조동사(의문문)", "do"], "the": ["관사", "그"], "e-mail": ["명사", "이메일"], "suggest": ["동사", "시사하다"], "about": ["전치사", "~에 대해"], "mr": ["명사", "~씨(남성)"], "okamoto": ["고유명사", "오카모토(이름)"]}}, {"no": 159, "q": "What does Mr. Okamoto NOT need to bring to the meeting with Effix Homes?", "options": ["Proof of employment", "Payment for April rent", "Forms of identification", "Money for a security deposit"], "answer": 1, "explain": "정답 (B) Payment for April rent\n해석: Okamoto 씨가 Effix Homes와의 만남에 가져갈 필요가 없는 것은?\n정답 근거: 첫 달 임대료는 \"4월 1일이 납부 기한\"이라 서명 당일에는 불필요. 재직 증명(A), 신분증(C), 보증금(D)은 지참·준비 대상.\n오답 분석: (A) 재직 증명을 가져오라고 함. / (C) 신분증 2종을 가져오라고 함. / (D) 보증금을 지불할 준비를 하라고 함.", "translation": "Okamoto 씨가 Effix Homes와의 만남에 가져갈 필요가 없는 것은?", "vocab": "Paraphrase: first month's rent will be due on 1 April (계약일 다음 날) → payment for April rent (가져올 필요 없음)", "g": {"what": ["대명사", "무엇"], "does": ["조동사", "조동사(의문문)", "do"], "mr": ["명사", "~씨(남성)"], "okamoto": ["고유명사", "오카모토(이름)"], "not": ["부사", "~아니다"], "need": ["동사", "필요하다"], "to": ["전치사", "~로, ~하기 위해"], "bring": ["동사", "가져오다"], "the": ["관사", "그"], "meeting": ["명사", "회의"], "with": ["전치사", "~와 함께, ~으로"], "effix": ["고유명사", "에픽스(회사명)"], "homes": ["고유명사", "홈즈(회사명)"]}}, {"no": 160, "q": "The word \"due\" in paragraph 1, line 6, is closest in meaning to", "options": ["billed", "considered", "owed", "scheduled"], "answer": 2, "explain": "정답 (C) owed\n해석: 첫 단락 여섯 번째 줄의 \"due\"와 의미가 가장 가까운 것은?\n정답 근거: \"rent will be due on 1 April(임대료가 4월 1일에 지불되어야 한다)\" → 지불해야 할, 빚진 → owed.\n오답 분석: (A) billed: '청구된' — 청구가 아니라 지불 기한의 의미. / (B) considered: '고려된' — 불일치. / (D) scheduled: '예정된' — 납부 의무의 의미와 다름.", "translation": "첫 단락 여섯 번째 줄의 \"due\"와 의미가 가장 가까운 것은?", "vocab": "Paraphrase: rent will be due → owed", "g": {"the": ["관사", "그"], "word": ["명사", "단어"], "due": ["형용사", "납부 기한인"], "in": ["전치사", "~에, ~안에"], "paragraph": ["명사", "단락"], "1": ["숫자", "1"], "line": ["명사", "줄, 행"], "6": ["숫자", "6"], "is": ["동사", "~이다", "be"], "closest": ["형용사", "가장 가까운", "close"], "meaning": ["명사", "의미"], "to": ["전치사", "~로, ~하기 위해"]}}]}, {"range": "161-163", "sub": "기출독해 3문항 15회", "passage": "— [1] —. Every five years, engineers hired by Hartpool's town council inspect our sidewalks for damaged areas. A sidewalk inspection was completed last week. Sidewalks that are slated to be repaired have been marked with red circles. They are also shown on a map on Hartpool's Web site, www.townofhartpool.gov. If your home or business is adjacent to a marked sidewalk, you will receive a letter notifying you of when the repairs will take place. The letter will include contact information in case you have questions about how the repairs might affect you. — [2] —. If your driveway connects to a marked sidewalk, you will be required to park on the street during the two-day repair period. — [3] —.\nThe town council is still taking bids from construction companies for the repair work. — [4] —. The project is expected to begin in early May and to take five weeks, weather permitting.", "tr": "— [1] —. 5년마다 Hartpool 시의회가 고용한 엔지니어들이 보도의 손상 구역을 점검합니다. 지난주 보도 점검이 완료되었습니다. 보수 예정인 보도는 빨간 원으로 표시되었습니다. Hartpool 웹사이트 www.townofhartpool.gov의 지도에도 표시되어 있습니다. 귀하의 집이나 사업장이 표시된 보도에 인접해 있다면 보수 시기를 알리는 편지를 받게 됩니다. 편지에는 보수가 귀하에게 미칠 영향에 관해 질문이 있을 경우를 위한 연락처가 포함됩니다. — [2] —. 귀하의 진입로가 표시된 보도와 연결되어 있다면 이틀간의 보수 기간 동안 거리에 주차하셔야 합니다. — [3] —. 시의회는 아직 보수 공사에 대한 건설사 입찰을 받고 있습니다. — [4] — [시공사가 선정되면 모든 주민에게 알릴 것입니다.] 공사는 5월 초에 시작해 날씨가 허락하면 5주가 걸릴 것으로 예상됩니다.", "vocab": "inspect 동 점검하다 / sidewalk 명 인도, 보도 / be slated to 구 ~할 예정이다 / repair 동 수리하다 / adjacent to 구 ~에 인접한 / notify 동 알리다 / take place 구 일어나다 / affect 동 영향을 미치다 / driveway 명 진입로 / bid 명 입찰 / weather permitting 구 날씨가 허락하면", "g": {"1": ["숫자", "1"], "every": ["한정사", "모든, 매"], "five": ["숫자", "5"], "years": ["명사", "년, 해", "year"], "engineers": ["명사", "엔지니어들", "engineer"], "hired": ["과거분사", "고용된", "hire"], "by": ["전치사", "~까지, ~에 의해"], "hartpool's": ["고유명사", "하트풀의(도시명)"], "town": ["명사", "도시, 마을"], "council": ["명사", "의회"], "inspect": ["동사", "점검하다"], "our": ["한정사", "우리의"], "sidewalks": ["명사", "보도들", "sidewalk"], "for": ["전치사", "~을 위해, ~동안"], "damaged": ["형용사", "손상된"], "areas": ["명사", "구역들", "area"], "a": ["관사", "하나의"], "sidewalk": ["명사", "보도"], "inspection": ["명사", "점검"], "was": ["동사", "~이었다", "be"], "completed": ["과거분사", "완료된", "complete"], "last": ["형용사", "지난"], "week": ["명사", "주"], "that": ["접속사", "~라는 것, ~하는"], "are": ["동사", "~이다", "be"], "slated": ["과거분사", "예정된", "slate"], "to": ["전치사", "~로, ~하기 위해"], "be": ["동사", "~이다, 되다"], "repaired": ["과거분사", "보수되는", "repair"], "have": ["동사", "가지다, (완료)~했다"], "been": ["과거분사", "~였던", "be"], "marked": ["과거분사", "표시된", "mark"], "with": ["전치사", "~와 함께, ~으로"], "red": ["형용사", "빨간"], "circles": ["명사", "원들", "circle"], "they": ["대명사", "그들"], "also": ["부사", "또한"], "shown": ["과거분사", "표시된", "show"], "on": ["전치사", "~에"], "map": ["명사", "지도"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "www.townofhartpool.gov": ["명사", "웹 주소"], "if": ["접속사", "만약 ~라면"], "your": ["한정사", "당신의"], "home": ["명사", "집"], "or": ["접속사", "또는"], "business": ["명사", "사업장"], "is": ["동사", "~이다", "be"], "adjacent": ["형용사", "인접한"], "you": ["대명사", "당신, 여러분"], "will": ["조동사", "~할 것이다"], "receive": ["동사", "받다"], "letter": ["명사", "편지"], "notifying": ["현재분사", "알리는", "notify"], "of": ["전치사", "~의"], "when": ["부사", "언제"], "the": ["관사", "그"], "repairs": ["명사", "보수 공사", "repair"], "take": ["동사", "(일이) 있다, 걸리다"], "place": ["명사", "장소(take place 열리다)"], "include": ["동사", "포함하다"], "contact": ["명사", "연락(처)"], "information": ["명사", "정보"], "in": ["전치사", "~에, ~안에"], "case": ["명사", "경우(in case ~할 경우)"], "questions": ["명사", "질문들", "question"], "about": ["전치사", "~에 대해"], "how": ["부사", "얼마나, 어떻게"], "might": ["조동사", "~할지도 모른다", "may"], "affect": ["동사", "영향을 미치다"], "2": ["숫자", "2"], "driveway": ["명사", "진입로"], "connects": ["동사", "연결되다", "connect"], "required": ["형용사", "필요한, 요구되는"], "park": ["동사", "주차하다"], "street": ["명사", "거리"], "during": ["전치사", "~동안"], "two-day": ["형용사", "이틀간의"], "repair": ["명사", "보수"], "period": ["명사", "기간"], "3": ["숫자", "3"], "still": ["부사", "여전히"], "taking": ["현재분사", "받고 있는", "take"], "bids": ["명사", "입찰", "bid"], "from": ["전치사", "~로부터"], "construction": ["명사", "공사, 건설"], "companies": ["명사", "회사들", "company"], "work": ["명사", "일, 작업"], "4": ["숫자", "4"], "project": ["명사", "프로젝트"], "expected": ["과거분사", "예상되는", "expect"], "begin": ["동사", "시작하다"], "early": ["형용사", "초의"], "may": ["명사", "5월"], "and": ["접속사", "그리고"], "weeks": ["명사", "주", "week"], "weather": ["명사", "날씨"], "permitting": ["현재분사", "허락하면(weather permitting)", "permit"]}, "questions": [{"no": 161, "q": "What is the purpose of the notice?", "options": ["To schedule driveway inspections", "To invite contractors to submit bids", "To inform town residents of construction work", "To explain how some sidewalks were damaged"], "answer": 2, "explain": "정답 (C) To inform town residents of construction work\n해석: 공지의 목적은?\n정답 근거: 보도 보수 대상 표시, 통지 편지, 주차 안내, 공사 시기 → 주민에게 공사 작업을 알림.\n오답 분석: (A) 진입로 점검 일정이 아니라 보도 보수. / (B) 입찰은 진행 중이라는 정보일 뿐 초대가 목적 아님. / (D) 손상 원인 설명 없음.\n지문 개요: Hartpool 시의회가 5년마다 실시하는 보도 점검 결과 보수 대상 보도를 빨간 원으로 표시하고 웹사이트 지도에도 표시했으며, 인접 주민에게는 공사 시기를 편지로 통지하고 이틀간 거리 주차가 필요하며, 시공사 입찰 진행 중으로 5월 초 착공해 5주 소요 예정이라는 공지.", "translation": "공지의 목적은?", "vocab": "Paraphrase: repairs will take place / project is expected to begin → inform town residents of construction work", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "notice": ["명사", "공지"]}}, {"no": 162, "q": "According to the notice, what is one way that repair locations can be identified?", "options": ["By calling the town council", "By visiting the town's Web site", "By reading the local newspaper", "By looking for signs posted on buildings"], "answer": 1, "explain": "정답 (B) By visiting the town's Web site\n해석: 공지에 따르면 보수 위치를 확인할 수 있는 한 가지 방법은?\n정답 근거: \"Hartpool 웹사이트의 지도에도 표시되어 있다\" → 시 웹사이트 방문.\n오답 분석: (A) 시의회 전화 언급 없음. / (C) 지역 신문 언급 없음. / (D) 건물 표지판이 아니라 보도 위 빨간 원.", "translation": "공지에 따르면 보수 위치를 확인할 수 있는 한 가지 방법은?", "vocab": "Paraphrase: shown on a map on Hartpool's Web site → visiting the town's Web site", "g": {"according": ["부사", "~에 따르면(according to)"], "to": ["전치사", "~로, ~하기 위해"], "the": ["관사", "그"], "notice": ["명사", "공지"], "what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "one": ["대명사", "하나, 한 곳"], "way": ["명사", "방식"], "that": ["관계사", "~하는"], "repair": ["명사", "보수"], "locations": ["명사", "지점들", "location"], "can": ["조동사", "~할 수 있다"], "be": ["동사", "~이다, 되다"], "identified": ["과거분사", "확인되는", "identify"]}}, {"no": 163, "q": "In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"All residents will be advised when one has been selected.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 3, "explain": "정답 (D) [4]\n해석: [1], [2], [3], [4] 중 \"All residents will be advised when one has been selected.\"가 들어가기에 가장 적절한 곳은?\n정답 근거: \"시의회가 아직 건설사 입찰을 받고 있다\" 바로 뒤에 \"하나(one = 건설사)가 선정되면 모든 주민에게 알린다\"가 이어져야 one의 지시 대상이 명확함 → [4].\n오답 분석: (A) [1]은 공지 첫머리로 one이 가리킬 대상이 없음. / (B) [2]는 편지 연락처 설명 뒤라 선정 대상이 없음. / (C) [3]은 주차 안내 뒤라 one의 지시 대상이 없음.", "translation": "[1], [2], [3], [4] 중 \"All residents will be advised when one has been selected.\"가 들어가기에 가장 적절한 곳은?", "vocab": "Paraphrase: still taking bids from construction companies → when one has been selected → [4]", "g": {"in": ["전치사", "~에, ~안에"], "which": ["한정사", "어느"], "of": ["전치사", "~의"], "the": ["관사", "그"], "positions": ["명사", "위치들", "position"], "marked": ["과거분사", "표시된", "mark"], "1": ["숫자", "1"], "2": ["숫자", "2"], "3": ["숫자", "3"], "and": ["접속사", "그리고"], "4": ["숫자", "4"], "does": ["조동사", "조동사(의문문)", "do"], "following": ["형용사", "다음의"], "sentence": ["명사", "문장"], "best": ["부사", "가장 잘"], "belong": ["동사", "들어가다, 속하다"], "all": ["한정사", "모든"], "residents": ["명사", "주민들", "resident"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "advised": ["과거분사", "통지받은", "advise"], "when": ["접속사", "~할 때"], "one": ["대명사", "하나(업체)"], "has": ["조동사", "(현재완료) ~했다", "have"], "been": ["과거분사", "~였던", "be"], "selected": ["과거분사", "선발된", "select"]}}]}, {"range": "155-157", "sub": "기출독해 3문항 16회", "passage": "More Changes at Local Magazine — By Ellen Khumalo\nCAPE TOWN (2 May)—After 36 years at Toast of the Town magazine, Amina Naidoo has resigned as editor in chief to launch her own line of home decor products.\nThis is the most recent development in the reorganisation of the iconic publication, known for its vivid photos and unique recipes.\nSince the magazine's acquisition by Topics Publishing earlier this year, CEO Abdul Dubois has retired and many staff members have been transferred to the company's other publications.\nNow the focus is on the redesign of Toast of the Town. Jillian Fourie has been hired to take over the vacant editorial role on 1 June.\n\"Exciting changes are coming,\" said spokesperson Derek Steyn, \"including more features on international cuisine and interviews with celebrity chefs.\"", "tr": "지역 잡지의 더 많은 변화 — Ellen Khumalo 기자\n케이프타운(5월 2일) — Toast of the Town 잡지에서 36년을 보낸 Amina Naidoo가 자신의 홈 데코 제품 라인을 출시하기 위해 편집장직을 사임했다. 이는 생생한 사진과 독특한 레시피로 유명한 이 상징적 간행물의 재편 과정에서 가장 최근의 변화다. 올해 초 Topics Publishing이 잡지를 인수한 이후 CEO Abdul Dubois가 은퇴했고 많은 직원이 회사의 다른 간행물로 옮겨 갔다. 이제 초점은 Toast of the Town의 재설계에 맞춰져 있다. 공석인 편집 직책을 6월 1일부터 맡도록 Jillian Fourie가 영입되었다. \"흥미로운 변화가 다가오고 있습니다.\" 대변인 Derek Steyn이 말했다. \"국제 요리에 관한 특집과 유명 셰프 인터뷰가 더 많아지는 것을 포함해서요.\"", "vocab": "resign 동 사임하다 / editor in chief 명 편집장 / launch 동 출시하다 / home decor 명 실내 장식 / reorganisation 명 개편 / iconic 형 상징적인 / publication 명 출판물 / vivid 형 생생한 / acquisition 명 인수 / transfer 동 전근시키다 / take over 구 인계받다 / vacant 형 공석인 / cuisine 명 요리", "g": {"more": ["형용사", "더 많은"], "changes": ["명사", "변경, 변화", "change"], "at": ["전치사", "~에서"], "local": ["형용사", "지역의"], "magazine": ["명사", "잡지"], "by": ["전치사", "~까지, ~에 의해"], "ellen": ["고유명사", "엘런(이름)"], "khumalo": ["고유명사", "쿠말로(이름)"], "cape": ["고유명사", "케이프(타운)"], "town": ["고유명사", "타운(지명·잡지명)"], "2": ["숫자", "2"], "may)—after": ["전치사", "5월)—~후에"], "36": ["숫자", "36"], "years": ["명사", "년, 해", "year"], "toast": ["고유명사", "토스트(잡지명)"], "of": ["전치사", "~의"], "the": ["관사", "그"], "amina": ["고유명사", "아미나(이름)"], "naidoo": ["고유명사", "나이두(이름)"], "has": ["조동사", "(현재완료) ~했다", "have"], "resigned": ["동사", "사임했다", "resign"], "as": ["전치사", "~로서"], "editor": ["명사", "편집자"], "in": ["전치사", "~에, ~안에"], "chief": ["명사", "장(editor in chief 편집장)"], "to": ["전치사", "~로, ~하기 위해"], "launch": ["동사", "출시하다"], "her": ["한정사", "그녀의"], "own": ["형용사", "자신의"], "line": ["명사", "제품 라인"], "home": ["명사", "집"], "decor": ["명사", "장식, 인테리어"], "products": ["명사", "제품들", "product"], "this": ["한정사", "이, 이것"], "is": ["동사", "~이다", "be"], "most": ["부사", "가장"], "recent": ["형용사", "최근의"], "development": ["명사", "개발, 변화"], "reorganisation": ["명사", "재편"], "iconic": ["형용사", "상징적인"], "publication": ["명사", "간행물"], "known": ["과거분사", "알려진", "know"], "for": ["전치사", "~을 위해, ~동안"], "its": ["한정사", "그것의"], "vivid": ["형용사", "생생한"], "photos": ["명사", "사진들", "photo"], "and": ["접속사", "그리고"], "unique": ["형용사", "독특한"], "recipes": ["명사", "레시피들", "recipe"], "since": ["전치사", "~이후로"], "magazine's": ["명사", "잡지의", "magazine"], "acquisition": ["명사", "인수"], "topics": ["고유명사", "토픽스(회사명)"], "publishing": ["고유명사", "출판(회사명)"], "earlier": ["부사", "앞서, 일찍이"], "year": ["명사", "해, 년"], "ceo": ["명사", "최고경영자"], "abdul": ["고유명사", "압둘(이름)"], "dubois": ["고유명사", "뒤부아(이름)"], "retired": ["동사", "은퇴했다", "retire"], "many": ["한정사", "많은"], "staff": ["명사", "직원"], "members": ["명사", "회원들, 직원들", "member"], "have": ["동사", "가지다, (완료)~했다"], "been": ["과거분사", "~였던", "be"], "transferred": ["과거분사", "옮겨진", "transfer"], "company's": ["명사", "회사의", "company"], "other": ["형용사", "다른"], "publications": ["명사", "간행물들", "publication"], "now": ["부사", "이제"], "focus": ["명사", "초점"], "on": ["전치사", "~에"], "redesign": ["명사", "재설계"], "jillian": ["고유명사", "질리언(이름)"], "fourie": ["고유명사", "푸리(이름)"], "hired": ["과거분사", "고용된", "hire"], "take": ["동사", "맡다(take over)"], "over": ["부사", "맡아(take over)"], "vacant": ["형용사", "공석인"], "editorial": ["형용사", "편집의"], "role": ["명사", "역할, 직책"], "1": ["숫자", "1"], "june": ["명사", "6월"], "exciting": ["형용사", "흥미진진한"], "are": ["동사", "~이다", "be"], "coming": ["현재분사", "다가오는", "come"], "said": ["동사", "말했다", "say"], "spokesperson": ["명사", "대변인"], "derek": ["고유명사", "데릭(이름)"], "steyn": ["고유명사", "스테인(이름)"], "including": ["전치사", "~을 포함하여"], "features": ["명사", "특집 기사들", "feature"], "international": ["형용사", "국제적인"], "cuisine": ["명사", "요리"], "interviews": ["명사", "인터뷰", "interview"], "with": ["전치사", "~와 함께, ~으로"], "celebrity": ["명사", "유명 인사"], "chefs": ["명사", "요리사들", "chef"]}, "questions": [{"no": 155, "q": "Why did Ms. Naidoo leave her job?", "options": ["She is starting a new business.", "She accepted a job at another magazine.", "She is relocating to a new city.", "She was in a temporary position."], "answer": 0, "explain": "정답 (A) She is starting a new business.\n해석: Naidoo 씨는 왜 직장을 떠났는가?\n정답 근거: \"자신의 홈 데코 제품 라인을 출시하기 위해 사임\" → 새 사업 시작.\n오답 분석: (B) 다른 잡지 이직 아님. / (C) 이주 언급 없음. / (D) 36년 근무한 정규직.\n지문 개요: Toast of the Town 잡지의 편집장 Amina Naidoo가 36년 만에 사임하고 자신의 홈 데코 제품 라인을 출시하며, Topics Publishing 인수 후 CEO 은퇴와 직원 이동에 이어 잡지 재설계가 진행 중이고 6월 1일 Jillian Fourie가 편집장을 맡아 국제 요리 특집과 유명 셰프 인터뷰를 늘릴 것이라는 기사.", "translation": "Naidoo 씨는 왜 직장을 떠났는가?", "vocab": "Paraphrase: to launch her own line of home decor products → starting a new business", "g": {"why": ["부사", "왜"], "did": ["조동사", "과거 의문·부정 조동사", "do"], "ms": ["명사", "~씨(여성)"], "naidoo": ["고유명사", "나이두(이름)"], "leave": ["동사", "그만두다"], "her": ["한정사", "그녀의"], "job": ["명사", "일, 직장"]}}, {"no": 156, "q": "Who will be the new editor in chief?", "options": ["Ms. Khumalo", "Mr. Dubois", "Ms. Fourie", "Mr. Steyn"], "answer": 2, "explain": "정답 (C) Ms. Fourie\n해석: 새 편집장은 누가 될 것인가?\n정답 근거: \"공석인 편집 직책을 6월 1일부터 맡도록 Jillian Fourie가 영입되었다\" → Fourie.\n오답 분석: (A) Khumalo는 기사 작성 기자. / (B) Dubois는 은퇴한 CEO. / (D) Steyn은 대변인.", "translation": "새 편집장은 누가 될 것인가?", "vocab": "Paraphrase: Jillian Fourie has been hired to take over the vacant editorial role → Ms. Fourie", "g": {"who": ["대명사", "누구"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "the": ["관사", "그"], "new": ["형용사", "새로운"], "editor": ["명사", "편집자"], "in": ["전치사", "~에, ~안에"], "chief": ["명사", "장(editor in chief 편집장)"]}}, {"no": 157, "q": "What most likely is the focus of Toast of the Town magazine?", "options": ["Sports", "Cooking", "Entertainment", "Interior decorating"], "answer": 1, "explain": "정답 (B) Cooking\n해석: Toast of the Town 잡지의 초점은 무엇일 것 같은가?\n정답 근거: \"독특한 레시피로 유명\", \"국제 요리 특집과 유명 셰프 인터뷰\" → 요리.\n오답 분석: (A) 스포츠 언급 없음. / (C) 연예가 아니라 요리. / (D) 인테리어는 Naidoo의 새 사업 분야.", "translation": "Toast of the Town 잡지의 초점은 무엇일 것 같은가?", "vocab": "Paraphrase: unique recipes / international cuisine / celebrity chefs → cooking", "g": {"what": ["대명사", "무엇"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "focus": ["명사", "초점"], "of": ["전치사", "~의"], "toast": ["고유명사", "토스트(잡지명)"], "town": ["고유명사", "타운(잡지명)"], "magazine": ["명사", "잡지"]}}]}, {"range": "158-160", "sub": "기출독해 3문항 16회", "passage": "To: All Weston City Spring Fair ticket holders\nFrom: Amanda Willard\nDate: May 6\nSubject: Important information\nThis e-mail is to inform you that the Weston City Spring Fair, scheduled for Saturday, May 9, will instead be held on Saturday, May 16. We apologize for any inconvenience this may cause you, but the weather forecast for May 9 does not look promising.\nWe hope you will be able to attend on May 16. The fair begins at 10:00 A.M. Food and beverage vendors will open for business at 11:00 A.M. The fair will close at 10:00 P.M. Parking is available at the fairgrounds; the fee is $5.00.\nIf you cannot attend the fair on the new date, the city will refund you the cost of your ticket. If you purchased tickets online, go to www.westoncity.gov/events and submit the online refund form. If you paid in cash, visit Weston City Hall during regular business hours and go to the front desk. Please note that no refunds will be given after May 29.\nSincerely, Amanda Willard, Coordinator, Weston City Spring Fair", "tr": "수신: Weston City 봄 축제 티켓 소지자 전원 / 발신: Amanda Willard / 날짜: 5월 6일 / 제목: 중요 안내\n5월 9일 토요일로 예정되었던 Weston City 봄 축제가 대신 5월 16일 토요일에 열린다는 것을 알려 드립니다. 불편을 드려 죄송하지만 5월 9일의 날씨 예보가 좋지 않습니다. 5월 16일에 참석하실 수 있기를 바랍니다. 축제는 오전 10시에 시작합니다. 음식·음료 판매자는 오전 11시에 영업을 시작합니다. 축제는 오후 10시에 끝납니다. 축제장에 주차할 수 있으며 요금은 5달러입니다. 새 날짜에 참석하실 수 없다면 시에서 티켓 비용을 환불해 드립니다. 온라인으로 티켓을 구매하셨다면 www.westoncity.gov/events에서 온라인 환불 양식을 제출하세요. 현금으로 지불하셨다면 정규 업무 시간에 Weston 시청을 방문해 프런트로 가십시오. 5월 29일 이후에는 환불이 불가하다는 점을 유의하십시오. Amanda Willard, Weston City 봄 축제 코디네이터 드림", "vocab": "ticket holder 명 입장권 소지자 / inform 동 알리다 / instead 부 대신에 / inconvenience 명 불편 / forecast 명 예보 / promising 형 좋을 것 같은 / beverage 명 음료 / fairgrounds 명 행사장 / refund 동 환불하다 / submit 동 제출하다 / note 동 유의하다 / coordinator 명 진행 담당자", "g": {"to": ["전치사", "~로, ~하기 위해"], "all": ["한정사", "모든"], "weston": ["고유명사", "웨스턴(도시)"], "city": ["명사", "도시"], "spring": ["명사", "봄"], "fair": ["명사", "박람회, 축제"], "ticket": ["명사", "티켓"], "holders": ["명사", "소지자들", "holder"], "from": ["전치사", "~로부터"], "amanda": ["고유명사", "아만다(이름)"], "willard": ["고유명사", "윌러드(이름)"], "date": ["명사", "날짜"], "may": ["명사", "5월 / (조)~일 수 있다"], "6": ["숫자", "6"], "subject": ["명사", "제목"], "important": ["형용사", "중요한"], "information": ["명사", "정보"], "this": ["한정사", "이, 이것"], "e-mail": ["명사", "이메일"], "is": ["동사", "~이다", "be"], "inform": ["동사", "알리다"], "you": ["대명사", "당신, 여러분"], "that": ["접속사", "~라는 것, ~하는"], "the": ["관사", "그"], "scheduled": ["과거분사", "예정된", "schedule"], "for": ["전치사", "~을 위해, ~동안"], "saturday": ["명사", "토요일"], "9": ["숫자", "9"], "will": ["조동사", "~할 것이다"], "instead": ["부사", "대신에"], "be": ["동사", "~이다, 되다"], "held": ["과거분사", "열리는", "hold"], "on": ["전치사", "~에"], "16": ["숫자", "16"], "we": ["대명사", "우리"], "apologize": ["동사", "사과하다"], "any": ["한정사", "어떤, 모든"], "inconvenience": ["명사", "불편"], "cause": ["동사", "야기하다"], "but": ["접속사", "하지만"], "weather": ["명사", "날씨"], "forecast": ["명사", "예보"], "does": ["조동사", "조동사(의문문)", "do"], "not": ["부사", "~아니다"], "look": ["동사", "~해 보이다"], "promising": ["형용사", "유망한, 좋아 보이는"], "hope": ["동사", "바라다"], "able": ["형용사", "~할 수 있는"], "attend": ["동사", "참석하다"], "begins": ["동사", "시작하다", "begin"], "at": ["전치사", "~에서"], "10:00": ["숫자", "10시"], "a.m": ["명사", "오전"], "food": ["명사", "음식"], "and": ["접속사", "그리고"], "beverage": ["명사", "음료"], "vendors": ["명사", "판매자들", "vendor"], "open": ["형용사", "열려 있는, 영업하는"], "business": ["명사", "사업, 영업"], "11:00": ["숫자", "11시"], "close": ["동사", "닫다"], "p.m": ["명사", "오후"], "parking": ["명사", "주차"], "available": ["형용사", "이용 가능한"], "fairgrounds": ["명사", "축제장"], "fee": ["명사", "수수료, 요금"], "$5.00": ["숫자", "5달러"], "if": ["접속사", "만약 ~라면"], "cannot": ["조동사", "~할 수 없다", "can"], "new": ["형용사", "새로운"], "refund": ["동사", "환불하다"], "cost": ["명사", "비용"], "of": ["전치사", "~의"], "your": ["한정사", "당신의"], "purchased": ["동사", "구매했다", "purchase"], "tickets": ["명사", "티켓들", "ticket"], "online": ["부사", "온라인으로"], "go": ["동사", "가다"], "www.westoncity.gov/events": ["명사", "웹 주소"], "submit": ["동사", "제출하다"], "form": ["명사", "양식"], "paid": ["동사", "지불했다", "pay"], "in": ["전치사", "~에, ~안에"], "cash": ["명사", "현금"], "visit": ["동사", "방문하다"], "hall": ["명사", "홀, 청사"], "during": ["전치사", "~동안"], "regular": ["형용사", "정규의"], "hours": ["명사", "시간", "hour"], "front": ["형용사", "앞쪽의(front desk)"], "desk": ["명사", "책상, 안내 데스크"], "please": ["부사", "부디"], "note": ["동사", "유의하다"], "no": ["한정사", "어떤 ~도 없는"], "refunds": ["명사", "환불", "refund"], "given": ["과거분사", "주어진", "give"], "after": ["전치사", "~후에"], "29": ["숫자", "29"], "sincerely": ["부사", "진심으로(맺음말)"], "coordinator": ["명사", "코디네이터, 담당자"]}, "questions": [{"no": 158, "q": "What is the purpose of the e-mail?", "options": ["To inform people of new parking fees", "To announce the rescheduling of an event", "To recruit vendors for an event", "To ask for volunteers to sell tickets"], "answer": 1, "explain": "정답 (B) To announce the rescheduling of an event\n해석: 이메일의 목적은?\n정답 근거: \"5월 9일 예정 축제가 대신 5월 16일에 열린다\" → 행사 일정 변경 안내.\n오답 분석: (A) 주차비는 부가 정보. / (C) 판매자 모집 아님. / (D) 자원봉사자 모집 아님.\n지문 개요: Weston City 봄 축제 코디네이터 Amanda Willard가 5월 9일 예정된 축제를 기상 악화 예보로 5월 16일로 연기한다고 알리며, 운영 시간과 주차비를 안내하고 새 날짜에 참석 못 하면 온라인 구매자는 온라인 환불 양식, 현금 구매자는 시청 프런트에서 5월 29일까지 환불받으라는 이메일.", "translation": "이메일의 목적은?", "vocab": "Paraphrase: scheduled for May 9, will instead be held on May 16 → rescheduling of an event", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "e-mail": ["명사", "이메일"]}}, {"no": 159, "q": "According to the e-mail, who should go to Weston City Hall?", "options": ["People who purchased tickets online", "People who purchased tickets with cash", "People who are able to attend the May 16 event", "People who lost their tickets"], "answer": 1, "explain": "정답 (B) People who purchased tickets with cash\n해석: 이메일에 따르면 누가 Weston 시청에 가야 하는가?\n정답 근거: \"현금으로 지불했다면 시청을 방문해 프런트로 가라\" → 현금 구매자.\n오답 분석: (A) 온라인 구매자는 온라인 양식 제출. / (C) 참석 가능한 사람은 환불 불필요. / (D) 티켓 분실 언급 없음.", "translation": "이메일에 따르면 누가 Weston 시청에 가야 하는가?", "vocab": "Paraphrase: If you paid in cash, visit Weston City Hall → people who purchased tickets with cash", "g": {"according": ["부사", "~에 따르면(according to)"], "to": ["전치사", "~로, ~하기 위해"], "the": ["관사", "그"], "e-mail": ["명사", "이메일"], "who": ["대명사", "누구"], "should": ["조동사", "~일 것이다, ~해야 한다"], "go": ["동사", "가다"], "weston": ["고유명사", "웨스턴(도시)"], "city": ["명사", "도시"], "hall": ["명사", "홀, 청사"]}}, {"no": 160, "q": "The word \"note\" in paragraph 3, line 4, is closest in meaning to", "options": ["write down", "call for", "observe", "show"], "answer": 2, "explain": "정답 (C) observe\n해석: 세 번째 단락 네 번째 줄의 \"note\"와 의미가 가장 가까운 것은?\n정답 근거: \"Please note that ~(~을 유의하세요)\" → 주의 깊게 알아 두다 → observe.\n오답 분석: (A) write down: '적다' — 불일치. / (B) call for: '요구하다' — 불일치. / (D) show: '보여 주다' — 불일치.", "translation": "세 번째 단락 네 번째 줄의 \"note\"와 의미가 가장 가까운 것은?", "vocab": "Paraphrase: Please note that → observe", "g": {"the": ["관사", "그"], "word": ["명사", "단어"], "note": ["동사", "유의하다"], "in": ["전치사", "~에, ~안에"], "paragraph": ["명사", "단락"], "3": ["숫자", "3"], "line": ["명사", "줄, 행"], "4": ["숫자", "4"], "is": ["동사", "~이다", "be"], "closest": ["형용사", "가장 가까운", "close"], "meaning": ["명사", "의미"], "to": ["전치사", "~로, ~하기 위해"]}}]}, {"range": "161-163", "sub": "기출독해 3문항 16회", "passage": "https://www.pineconepackaging.co.nz/reviews ★★★★★\nI used Pine Cone Packaging for a job that my company was doing, and I can't recommend this company's services highly enough! — [1] —. We were recently renovating a home in which there was a lot of artwork. — [2] —. The art needed to be safely packed and stored for the duration of the construction project. Pine Cone custom built several wooden crates so that the items could be easily transported and stored off-site. — [3] —. Everyone I interacted with at Pine Cone was knowledgeable, and I was impressed with the assistance we received throughout the process. — [4] —. My company will use Pine Cone again in the future. —Delroy Ocampo, 14 May", "tr": "https://www.pineconepackaging.co.nz/reviews ★★★★★\n저희 회사가 진행하던 작업에 Pine Cone Packaging을 이용했는데, 이 회사 서비스는 아무리 추천해도 모자랍니다! — [1] —. 최근 미술품이 많은 주택을 개조하고 있었습니다. — [2] —. 공사 기간 동안 미술품을 안전하게 포장하고 보관해야 했습니다. Pine Cone은 물품을 쉽게 운반하고 외부에 보관할 수 있도록 나무 상자 여러 개를 맞춤 제작했습니다. — [3] — [물품을 개봉했을 때 하나도 손상되지 않은 것을 보고 기뻤습니다.] Pine Cone에서 제가 상대한 모든 분이 전문 지식이 있었고, 전 과정에서 받은 도움에 깊은 인상을 받았습니다. — [4] —. 저희 회사는 앞으로도 Pine Cone을 다시 이용할 것입니다. — Delroy Ocampo, 5월 14일", "vocab": "recommend 동 추천하다 / highly 부 매우 / renovate 동 개조하다 / artwork 명 예술품 / for the duration of 구 ~하는 동안 / custom build 구 맞춤 제작하다 / crate 명 나무 상자 / transport 동 운반하다 / off-site 부 외부에서 / interact with 구 ~와 소통하다 / knowledgeable 형 아는 것이 많은 / assistance 명 도움", "g": {"https://www.pineconepackaging.co.nz/reviews": ["명사", "웹 주소"], "i": ["대명사", "나"], "used": ["동사", "이용했다", "use"], "pine": ["고유명사", "파인(회사명)"], "cone": ["고유명사", "콘(회사명 일부)"], "packaging": ["고유명사", "포장(회사명)"], "for": ["전치사", "~을 위해, ~동안"], "a": ["관사", "하나의"], "job": ["명사", "작업"], "that": ["접속사", "~라는 것, ~하는"], "my": ["한정사", "나의"], "company": ["명사", "회사"], "was": ["동사", "~이었다", "be"], "doing": ["현재분사", "하고 있는", "do"], "and": ["접속사", "그리고"], "can't": ["조동사", "~할 수 없다", "can"], "recommend": ["동사", "추천하다"], "this": ["한정사", "이, 이것"], "company's": ["명사", "회사의", "company"], "services": ["명사", "서비스들", "service"], "highly": ["부사", "높이(추천)"], "enough": ["부사", "충분히"], "1": ["숫자", "1"], "we": ["대명사", "우리"], "were": ["동사", "~이었다", "be"], "recently": ["부사", "최근에"], "renovating": ["현재분사", "개조하고 있던", "renovate"], "home": ["명사", "집"], "in": ["전치사", "~에, ~안에"], "which": ["관계사", "~하는 (것)"], "there": ["부사", "거기에(there is ~이 있다)"], "lot": ["명사", "많음(a lot of)"], "of": ["전치사", "~의"], "artwork": ["명사", "미술품"], "2": ["숫자", "2"], "the": ["관사", "그"], "art": ["명사", "미술품"], "needed": ["동사", "필요했다", "need"], "to": ["전치사", "~로, ~하기 위해"], "be": ["동사", "~이다, 되다"], "safely": ["부사", "안전하게"], "packed": ["과거분사", "포장된", "pack"], "stored": ["과거분사", "보관된", "store"], "duration": ["명사", "기간"], "construction": ["명사", "공사, 건설"], "project": ["명사", "프로젝트"], "custom": ["부사", "맞춤으로"], "built": ["동사", "만들었다", "build"], "several": ["한정사", "여러"], "wooden": ["형용사", "나무로 된"], "crates": ["명사", "나무 상자들", "crate"], "so": ["접속사", "~하도록(so that)"], "items": ["명사", "품목들", "item"], "could": ["조동사", "~할 수 있었다", "can"], "easily": ["부사", "쉽게"], "transported": ["과거분사", "운반된", "transport"], "off-site": ["부사", "외부에서"], "3": ["숫자", "3"], "everyone": ["대명사", "모든 사람"], "interacted": ["동사", "교류했다", "interact"], "with": ["전치사", "~와 함께, ~으로"], "at": ["전치사", "~에서"], "knowledgeable": ["형용사", "아는 것이 많은"], "impressed": ["형용사", "감명받은"], "assistance": ["명사", "도움"], "received": ["동사", "받았다", "receive"], "throughout": ["전치사", "~전역에, 곳곳에"], "process": ["명사", "과정"], "4": ["숫자", "4"], "will": ["조동사", "~할 것이다"], "use": ["동사", "이용하다"], "again": ["부사", "다시"], "future": ["명사", "미래"], "delroy": ["고유명사", "델로이(이름)"], "ocampo": ["고유명사", "오캄포(이름)"], "14": ["숫자", "14"], "may": ["명사", "5월"]}, "questions": [{"no": 161, "q": "For what type of business does Mr. Ocampo most likely work?", "options": ["A real estate agency", "A construction company", "A moving company", "An art restoration firm"], "answer": 1, "explain": "정답 (B) A construction company\n해석: Ocampo 씨는 어떤 종류의 업체에서 일할 것 같은가?\n정답 근거: \"주택을 개조하고 있었다\", \"공사 프로젝트 기간 동안\" → 건설(시공) 회사.\n오답 분석: (A) 부동산 중개 아님. / (C) 이사 업체는 Pine Cone 쪽 역할. / (D) 미술품 복원이 아니라 보관.\n지문 개요: Delroy Ocampo가 주택 개조 공사 중 많은 미술품을 안전하게 포장·보관해야 해 Pine Cone Packaging의 맞춤 나무 상자를 이용했고, 개봉 시 하나도 손상되지 않았으며 직원들이 전문적이고 도움이 되어 다시 이용하겠다는 후기.", "translation": "Ocampo 씨는 어떤 종류의 업체에서 일할 것 같은가?", "vocab": "Paraphrase: renovating a home / the construction project → a construction company", "g": {"for": ["전치사", "~을 위해, ~동안"], "what": ["한정사", "어떤"], "type": ["명사", "종류"], "of": ["전치사", "~의"], "business": ["명사", "사업, 영업"], "does": ["조동사", "조동사(의문문)", "do"], "mr": ["명사", "~씨(남성)"], "ocampo": ["고유명사", "오캄포(이름)"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "work": ["동사", "일하다"]}}, {"no": 162, "q": "What does Mr. Ocampo like about Pine Cone Packaging?", "options": ["Its competitive prices", "Its varied products", "Its convenient scheduling", "Its helpful employees"], "answer": 3, "explain": "정답 (D) Its helpful employees\n해석: Ocampo 씨는 Pine Cone Packaging의 무엇을 마음에 들어 하는가?\n정답 근거: \"상대한 모든 분이 전문 지식이 있었고 전 과정에서 받은 도움에 깊은 인상\" → 도움이 되는 직원들.\n오답 분석: (A) 가격 언급 없음. / (B) 다양한 제품 언급 없음 — 맞춤 상자. / (C) 일정 편의 언급 없음.", "translation": "Ocampo 씨는 Pine Cone Packaging의 무엇을 마음에 들어 하는가?", "vocab": "Paraphrase: Everyone was knowledgeable / impressed with the assistance → its helpful employees", "g": {"what": ["대명사", "무엇"], "does": ["조동사", "조동사(의문문)", "do"], "mr": ["명사", "~씨(남성)"], "ocampo": ["고유명사", "오캄포(이름)"], "like": ["동사", "좋아하다"], "about": ["전치사", "~에 대해"], "pine": ["고유명사", "파인(회사명)"], "cone": ["고유명사", "콘(회사명 일부)"], "packaging": ["고유명사", "포장(회사명)"]}}, {"no": 163, "q": "In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"When we unpacked the items, we were pleased to see that not one was damaged.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 2, "explain": "정답 (C) [3]\n해석: [1], [2], [3], [4] 중 \"When we unpacked the items, we were pleased to see that not one was damaged.\"가 들어가기에 가장 적절한 곳은?\n정답 근거: 상자에 포장해 외부 보관했다는 문장 뒤에 \"개봉했을 때 하나도 손상되지 않았다\"는 결과가 이어져야 자연스러움 → [3].\n오답 분석: (A) [1]은 추천 서두라 아직 포장 이야기가 없음. / (B) [2]는 개조 중이라는 상황 설명 뒤로 포장 전. / (D) [4]는 직원 칭찬 뒤라 개봉 결과 서술이 어색.", "translation": "[1], [2], [3], [4] 중 \"When we unpacked the items, we were pleased to see that not one was damaged.\"가 들어가기에 가장 적절한 곳은?", "vocab": "Paraphrase: easily transported and stored off-site → When we unpacked the items → [3]", "g": {"in": ["전치사", "~에, ~안에"], "which": ["한정사", "어느"], "of": ["전치사", "~의"], "the": ["관사", "그"], "positions": ["명사", "위치들", "position"], "marked": ["과거분사", "표시된", "mark"], "1": ["숫자", "1"], "2": ["숫자", "2"], "3": ["숫자", "3"], "and": ["접속사", "그리고"], "4": ["숫자", "4"], "does": ["조동사", "조동사(의문문)", "do"], "following": ["형용사", "다음의"], "sentence": ["명사", "문장"], "best": ["부사", "가장 잘"], "belong": ["동사", "들어가다, 속하다"], "when": ["접속사", "~할 때"], "we": ["대명사", "우리"], "unpacked": ["동사", "포장을 풀었다", "unpack"], "items": ["명사", "품목들", "item"], "were": ["동사", "~이었다", "be"], "pleased": ["형용사", "기쁜"], "to": ["전치사", "~로, ~하기 위해"], "see": ["동사", "보다, 알다"], "that": ["접속사", "~라는 것, ~하는"], "not": ["부사", "~아니다"], "one": ["대명사", "하나"], "was": ["동사", "~이었다", "be"], "damaged": ["과거분사", "손상된", "damage"]}}]}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r9-p6',$mkd${"id": "a-r9-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 3, "round": 9, "level": "중급", "title": "A급 과제 9회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "5 September / Rachel Hutchinson / 8451 Woods Circle / Springfield, IN 62704\nDear Ms. Hutchinson,\nThank you for informing us about the product you purchased recently. We are sorry that the television you ordered did not arrive in perfect condition. In order to meet your ---131---, we will send a sales representative to pick up your defective product and drop off a replacement at no additional cost.\n---132---. Please call the office at 217-555-0121 to ---133--- your delivery time.\nWe strive to make all our customers happy, and hope that you find this ---134--- satisfactory.\nThank you, Jackson Allarty, Customer Service, Parandon Electronics", "tr": "9월 5일 / Rachel Hutchinson / 8451 Woods Circle / Springfield, IN 62704\nHutchinson 씨께, 최근 구매하신 제품에 대해 알려 주셔서 감사합니다. 주문하신 텔레비전이 완벽한 상태로 도착하지 못해 죄송합니다. 고객님의 기대(131)를 충족하기 위해 영업 담당자를 보내 불량 제품을 수거하고 추가 비용 없이 교체품을 전달해 드리겠습니다. 정확히 같은 모델을 받으시게 됩니다(132). 배송 시간을 정하시려면(133) 사무실 217-555-0121로 전화해 주십시오. 저희는 모든 고객을 만족시키기 위해 노력하며, 이 해결책(134)이 만족스러우시길 바랍니다. 감사합니다, Jackson Allarty, 고객 서비스, Parandon Electronics", "vocab": "inform 동 알리다 / purchase 동 구매하다 / condition 명 상태 / meet 동 충족하다 / expectation 명 기대 / sales representative 명 영업 담당자 / defective 형 결함 있는 / drop off 구 갖다 주다 / replacement 명 교체품 / arrange 동 정하다 / strive to 구 ~하려 노력하다 / resolution 명 해결(책) / satisfactory 형 만족스러운", "questions": [{"no": 131, "q": "", "options": ["expecting", "expectations", "expects", "expected"], "answer": 1, "explain": "정답 (B) expectations\n해석: 고객님의 기대를 충족하기 위해\n정답 근거: 타동사 meet 뒤 「소유격 your + 빈칸」 → 명사 자리 → expectations(meet one's expectations).\n오답 분석: (A) expecting: 분사 — 소유격 뒤 명사 필요. / (C) expects: 동사 — 불가. / (D) expected: 과거분사 — 불가.\n지문 개요: Parandon Electronics 고객 서비스의 Jackson Allarty가 Rachel Hutchinson에게 불량 상태로 도착한 TV에 대해 사과하며, 영업 담당자가 불량품을 수거하고 동일 모델 교체품을 무료로 전달할 예정이니 전화로 배송 시간을 정하라는 편지.", "translation": "고객님의 기대를 충족하기 위해"}, {"no": 132, "q": "", "options": ["You will receive the exact same model.", "The serial number is invalid.", "All our televisions are certified energy efficient.", "The product is no longer covered by our warranty."], "answer": 0, "explain": "정답 (A) You will receive the exact same model.\n해석: 정확히 같은 모델을 받으시게 됩니다.\n정답 근거: 앞 문장의 \"교체품을 전달한다\"에 이어 교체품이 어떤 것인지(같은 모델) 설명하는 문장이 자연스러움.\n오답 분석: (B) 일련번호 무효는 교환 안내와 무관. / (C) 에너지 효율 인증은 무관. / (D) 보증 만료는 무료 교체와 모순.", "translation": "정확히 같은 모델을 받으시게 됩니다."}, {"no": 133, "q": "", "options": ["cancel", "change", "arrange", "sign"], "answer": 2, "explain": "정답 (C) arrange\n해석: 배송 시간을 정하시려면 전화해 주십시오.\n정답 근거: 교체품 전달을 위해 배송 시간을 \"정하다\" → arrange.\n오답 분석: (A) cancel: '취소하다' — 교체 안내와 모순. / (B) change: '변경하다' — 아직 정해진 시간이 없음. / (D) sign: '서명하다' — 불가.", "translation": "배송 시간을 정하시려면 전화해 주십시오."}, {"no": 134, "q": "", "options": ["resolution", "discount", "advertisement", "demonstration"], "answer": 0, "explain": "정답 (A) resolution\n해석: 이 해결책이 만족스러우시길 바랍니다.\n정답 근거: 불량품 수거·교체라는 문제 해결 조치 전체를 가리킴 → resolution(해결).\n오답 분석: (B) discount: '할인' — 제공된 바 없음. / (C) advertisement: '광고' — 불가. / (D) demonstration: '시연' — 불가.", "translation": "이 해결책이 만족스러우시길 바랍니다."}], "g": {"5": ["숫자", "5"], "september": ["명사", "9월"], "rachel": ["고유명사", "레이첼(이름)"], "hutchinson": ["고유명사", "허친슨(성)"], "8451": ["숫자", "8451(번지)"], "woods": ["고유명사", "우즈(도로명)"], "circle": ["명사", "원형 도로(주소)"], "springfield": ["고유명사", "스프링필드(지명)"], "in": ["전치사", "~에, ~안에"], "62704": ["숫자", "62704(우편번호)"], "dear": ["형용사", "친애하는"], "ms": ["고유명사", "~씨(여성 호칭)"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신"], "for": ["전치사", "~을 위해, ~동안"], "informing": ["동명사", "알리는 것", "inform"], "us": ["대명사", "우리를"], "about": ["전치사", "~에 대해"], "the": ["관사", "그"], "product": ["명사", "제품"], "purchased": ["동사", "구매했다", "purchase"], "recently": ["부사", "최근에"], "we": ["대명사", "우리"], "are": ["동사", "~이다", "be"], "sorry": ["형용사", "미안한"], "that": ["접속사", "~라는 것"], "television": ["명사", "텔레비전"], "ordered": ["동사", "주문했다", "order"], "did": ["조동사", "(과거 의문 조동사)", "do"], "not": ["부사", "~아니다"], "arrive": ["동사", "도착하다"], "perfect": ["형용사", "완벽한"], "condition": ["명사", "상태"], "order": ["명사", "(in order to) ~하기 위해"], "to": ["전치사", "~에게, ~으로"], "meet": ["동사", "충족하다"], "your": ["한정사", "당신의"], "will": ["조동사", "~할 것이다"], "send": ["동사", "보내다"], "a": ["관사", "하나의"], "sales": ["명사", "영업, 판매", "sale"], "representative": ["명사", "담당자, 직원"], "pick": ["동사", "(pick up) 수거하다"], "up": ["부사", "(pick up) 가져가는"], "defective": ["형용사", "결함 있는"], "and": ["접속사", "그리고"], "drop": ["동사", "(drop off) 갖다 주다"], "off": ["부사", "(drop off) 내려놓는"], "replacement": ["명사", "교체품"], "at": ["전치사", "~에, ~에서"], "no": ["한정사", "어떤 ~도 없는"], "additional": ["형용사", "추가의"], "cost": ["명사", "비용"], "please": ["부사", "부디, ~해 주세요"], "call": ["동사", "전화하다"], "office": ["명사", "사무실"], "217-555-0121": ["숫자", "전화번호"], "delivery": ["명사", "배송"], "time": ["명사", "시간"], "strive": ["동사", "노력하다"], "make": ["동사", "~하게 만들다"], "all": ["한정사", "모든"], "our": ["한정사", "우리의"], "customers": ["명사", "고객들", "customer"], "happy": ["형용사", "만족한, 행복한"], "hope": ["동사", "바라다"], "find": ["동사", "(~라고) 여기다"], "this": ["한정사", "이"], "satisfactory": ["형용사", "만족스러운"], "jackson": ["고유명사", "잭슨(이름)"], "allarty": ["고유명사", "알라티(성)"], "customer": ["명사", "고객"], "service": ["명사", "서비스"], "parandon": ["고유명사", "파란던(회사명)"], "electronics": ["명사", "전자제품(회사명)"]}}, {"range": "135-138", "passage": "Web Site Lists Albury Jobs\nThe Albury Job Directory is an online board for announcing new employment opportunities. It ---135--- free of charge to Albury residents and helps match them with job openings in the local area. All businesses are welcome to post open positions on the directory at no charge. Employers ---136--- use the service should be aware that the directory may become temporarily inaccessible for a variety of reasons. ---137---. Whenever periodic updates are scheduled, we will do our best to notify users ahead of time.\n---138---, the Albury Job Directory assumes no liability in the event that the Web site is completely or partially unavailable.", "tr": "웹사이트, Albury 일자리 목록 제공\nAlbury Job Directory는 새 고용 기회를 알리는 온라인 게시판입니다. Albury 주민에게 무료로 제공되며(135) 지역 내 구인 공고와 연결해 줍니다. 모든 기업은 무료로 디렉터리에 공석을 게시할 수 있습니다. 이 서비스를 이용하는(136) 고용주는 디렉터리가 다양한 이유로 일시적으로 접속 불가가 될 수 있음을 알아 두셔야 합니다. 이러한 이유는 정기 점검부터 시스템 오작동까지 다양합니다(137). 정기 업데이트가 예정될 때마다 사용자에게 미리 알리도록 최선을 다하겠습니다. 그러나(138) Albury Job Directory는 웹사이트를 전체 또는 일부 이용할 수 없는 경우에 대해 책임을 지지 않습니다.", "vocab": "directory 명 안내 목록 / employment 명 고용 / free of charge 구 무료로 / resident 명 주민 / job opening 명 채용 공고 / employer 명 고용주 / temporarily 부 일시적으로 / inaccessible 형 접근할 수 없는 / range from A to B 구 A에서 B에 이르다 / malfunction 명 오작동 / periodic 형 주기적인 / ahead of time 구 미리 / assume liability 구 책임을 지다 / in the event that 구 ~할 경우에", "questions": [{"no": 135, "q": "", "options": ["is provided", "provides", "providing", "has provided"], "answer": 0, "explain": "정답 (A) is provided\n해석: Albury 주민에게 무료로 제공됩니다.\n정답 근거: 문장의 동사 자리. provide는 타동사인데 빈칸 뒤 목적어 없이 free of charge + 전치사구 → 수동 is provided. 주어 It(단수).\n오답 분석: (B) provides: 능동 — 목적어가 없어 불가. / (C) providing: 분사 — 동사 없음. / (D) has provided: 능동 — 목적어 없음.\n지문 개요: Albury 주민에게 무료로 제공되는 온라인 구인 게시판 Albury Job Directory가 기업 공고도 무료로 받으며, 정기 점검부터 시스템 오작동까지 다양한 이유로 일시 접속 불가가 될 수 있고 사전 공지에 노력하지만 이용 불가 시 책임지지 않는다는 안내문.", "translation": "Albury 주민에게 무료로 제공됩니다."}, {"no": 136, "q": "", "options": ["who", "any", "some", "whose"], "answer": 0, "explain": "정답 (A) who\n해석: 이 서비스를 이용하는 고용주는 알아 두셔야 합니다.\n정답 근거: 동사 2개(use, should be aware)이므로 접속사 필요. 선행사 Employers(사람) 뒤 주격 관계대명사 who.\n오답 분석: (B) any: 한정사 — 접속사 역할 없음. / (C) some: 한정사 — 접속사 아님. / (D) whose: 소유격 — 뒤에 명사 필요(동사 use가 옴).", "translation": "이 서비스를 이용하는 고용주는 알아 두셔야 합니다."}, {"no": 137, "q": "", "options": ["The site is funded by the City of Albury.", "Volunteers are now being trained.", "Others will appear on separate lines within the Directory.", "These range from routine maintenance to system malfunction."], "answer": 3, "explain": "정답 (D) These range from routine maintenance to system malfunction.\n해석: 이러한 이유는 정기 점검부터 시스템 오작동까지 다양합니다.\n정답 근거: 앞 문장의 \"다양한 이유(a variety of reasons)\"를 These로 받아 구체화하고, 뒤의 정기 업데이트 공지로 이어짐.\n오답 분석: (A) 자금 출처는 접속 불가 설명과 무관. / (B) 자원봉사자 교육은 무관. / (C) Others가 가리킬 대상이 없음.", "translation": "이러한 이유는 정기 점검부터 시스템 오작동까지 다양합니다."}, {"no": 138, "q": "", "options": ["Again", "However", "As a result", "For example"], "answer": 1, "explain": "정답 (B) However\n해석: 그러나 웹사이트 이용 불가에 대해 책임을 지지 않습니다.\n정답 근거: \"미리 알리도록 최선을 다한다\"와 \"책임지지 않는다\"의 대조 → However.\n오답 분석: (A) Again: '다시' — 반복 내용 없음. / (C) As a result: '그 결과' — 인과 아님. / (D) For example: '예를 들어' — 예시 아님.", "translation": "그러나 웹사이트 이용 불가에 대해 책임을 지지 않습니다."}], "g": {"web": ["명사", "웹"], "site": ["명사", "사이트"], "lists": ["동사", "목록을 올리다", "list"], "albury": ["고유명사", "앨버리(지명)"], "jobs": ["명사", "일자리들", "job"], "the": ["관사", "그"], "job": ["명사", "일자리"], "directory": ["명사", "안내 목록"], "is": ["동사", "~이다", "be"], "an": ["관사", "하나의"], "online": ["형용사", "온라인의"], "board": ["명사", "게시판"], "for": ["전치사", "~을 위해, ~동안"], "announcing": ["동명사", "알리는 것", "announce"], "new": ["형용사", "새로운"], "employment": ["명사", "고용"], "opportunities": ["명사", "기회들", "opportunity"], "it": ["대명사", "그것"], "free": ["형용사", "무료의"], "of": ["전치사", "~의"], "charge": ["명사", "요금"], "to": ["전치사", "~에게, ~으로"], "residents": ["명사", "주민들", "resident"], "and": ["접속사", "그리고"], "helps": ["동사", "돕다", "help"], "match": ["동사", "연결해 주다"], "them": ["대명사", "그들을"], "with": ["전치사", "~와 함께, ~으로"], "openings": ["명사", "빈자리, 공석", "opening"], "in": ["전치사", "~에, ~안에"], "local": ["형용사", "지역의"], "area": ["명사", "지역"], "all": ["한정사", "모든"], "businesses": ["명사", "기업들", "business"], "are": ["동사", "~이다", "be"], "welcome": ["형용사", "환영받는(자유로이 ~해도 되는)"], "post": ["동사", "게시하다"], "open": ["형용사", "비어 있는, 공석인"], "positions": ["명사", "일자리들", "position"], "on": ["전치사", "~에, ~에 관해"], "at": ["전치사", "~에, ~에서"], "no": ["한정사", "어떤 ~도 없는"], "employers": ["명사", "고용주들", "employer"], "use": ["동사", "이용하다"], "service": ["명사", "서비스"], "should": ["조동사", "~해야 한다"], "be": ["동사", "~이다, 있다"], "aware": ["형용사", "알고 있는"], "that": ["접속사", "~라는 것"], "may": ["조동사", "~일지도 모른다"], "become": ["동사", "~이 되다"], "temporarily": ["부사", "일시적으로"], "inaccessible": ["형용사", "접근할 수 없는"], "a": ["관사", "하나의"], "variety": ["명사", "다양성(a variety of 다양한)"], "reasons": ["명사", "이유들", "reason"], "whenever": ["접속사", "~할 때마다"], "periodic": ["형용사", "주기적인"], "updates": ["명사", "업데이트", "update"], "scheduled": ["과거분사", "예정된", "schedule"], "we": ["대명사", "우리"], "will": ["조동사", "~할 것이다"], "do": ["동사", "하다"], "our": ["한정사", "우리의"], "best": ["명사", "최선"], "notify": ["동사", "알리다"], "users": ["명사", "사용자들", "user"], "ahead": ["부사", "(ahead of time) 미리"], "time": ["명사", "시간"], "assumes": ["동사", "(책임을) 지다", "assume"], "liability": ["명사", "법적 책임"], "event": ["명사", "경우(in the event that)"], "completely": ["부사", "완전히"], "or": ["접속사", "또는"], "partially": ["부사", "부분적으로"], "unavailable": ["형용사", "이용할 수 없는"]}}, {"range": "139-142", "passage": "10 March / Ms. Norma Barnes / Human Resources Office / Clearview Shopping Mall / 2011 Dunston Road / Oakville, ON L6H 6P5\nDear Ms. Barnes,\nI am writing to you to report a very ---139--- experience with one of the mall's parking area attendants. Last Thursday afternoon, I visited the mall to return an item. I was in such a hurry that I accidentally locked my keys inside my car. I was so upset and was not sure what to do! ---140---, the parking attendant, Mr. Warren Ton, came to my rescue. Within minutes, he had opened the car door ---141--- a tool that I had never seen before. He would not accept any gratuity for his trouble. ---142---. Could you please convey my thanks to him?\nSincerely, Eun Joo Kang", "tr": "3월 10일 / Norma Barnes 씨 / 인사부 / Clearview Shopping Mall / 2011 Dunston Road / Oakville, ON L6H 6P5\nBarnes 씨께, 몰의 주차장 관리인 한 분과의 매우 긍정적인(139) 경험을 알려 드리려고 편지를 씁니다. 지난 목요일 오후 물건을 반품하러 몰을 방문했습니다. 너무 서두르다 실수로 열쇠를 차 안에 두고 잠가 버렸습니다. 너무 당황해서 어떻게 해야 할지 몰랐습니다! 다행히(140) 주차 관리인 Warren Ton 씨가 저를 구하러 와 주었습니다. 몇 분 만에 그는 제가 한 번도 본 적 없는 도구를 사용해(141) 차 문을 열었습니다. 그는 수고에 대한 어떤 사례도 받으려 하지 않았습니다. Ton 씨는 칭찬받아 마땅합니다(142). 제 감사를 그에게 전해 주시겠습니까? Eun Joo Kang 드림", "vocab": "report 동 알리다 / positive 형 긍정적인 / attendant 명 안내원 / in a hurry 구 서둘러 / accidentally 부 실수로 / upset 형 속상한 / fortunately 부 다행히 / come to one's rescue 구 ~을 구하러 오다 / with the use of 구 ~을 사용하여 / gratuity 명 사례금 / commend 동 칭찬하다 / convey 동 전하다", "questions": [{"no": 139, "q": "", "options": ["similar", "positive", "amusing", "puzzling"], "answer": 1, "explain": "정답 (B) positive\n해석: 매우 긍정적인 경험을 알려 드리려고\n정답 근거: 편지 전체가 관리인의 도움에 대한 칭찬과 감사 → positive(긍정적인).\n오답 분석: (A) similar: '비슷한' — 비교 대상 없음. / (C) amusing: '재미있는' — 구조된 경험과 불일치. / (D) puzzling: '당혹스러운' — 감사 편지와 불일치.\n지문 개요: Eun Joo Kang이 Clearview Shopping Mall 인사부 Norma Barnes에게 차 안에 열쇠를 두고 잠갔을 때 주차 관리인 Warren Ton이 특수 도구로 금방 문을 열어 주고 사례도 받지 않았다며 그의 공로를 인정하고 감사를 전해 달라는 편지.", "translation": "매우 긍정적인 경험을 알려 드리려고"}, {"no": 140, "q": "", "options": ["Instead", "Generally", "Otherwise", "Fortunately"], "answer": 3, "explain": "정답 (D) Fortunately\n해석: 다행히 주차 관리인 Warren Ton 씨가 저를 구하러 와 주었습니다.\n정답 근거: 곤경(열쇠를 두고 잠금) 뒤 도움을 받은 긍정적 전환 → Fortunately.\n오답 분석: (A) Instead: '대신에' — 대체 관계 아님. / (B) Generally: '일반적으로' — 특정 사건과 불일치. / (C) Otherwise: '그렇지 않으면' — 불가.", "translation": "다행히 주차 관리인 Warren Ton 씨가 저를 구하러 와 주었습니다."}, {"no": 141, "q": "", "options": ["having been used by", "with the use of", "that he used", "for using"], "answer": 1, "explain": "정답 (B) with the use of\n해석: 제가 한 번도 본 적 없는 도구를 사용해 차 문을 열었습니다.\n정답 근거: 이미 완전한 절(he had opened the car door) 뒤에 명사구 a tool을 연결하는 수단 표현 → with the use of(~을 사용하여).\n오답 분석: (A) having been used by: 도구가 문에 의해 사용되었다는 뜻이 되어 불가. / (C) that he used: 관계절이면 선행사가 car door가 되어 의미 불가. / (D) for using: '~을 사용하기 위해' — 의미 불가.", "translation": "제가 한 번도 본 적 없는 도구를 사용해 차 문을 열었습니다."}, {"no": 142, "q": "", "options": ["The parking area is clearly marked.", "It happened again on Friday.", "Mr. Ton is to be commended.", "I did not expect to see so many vehicles there."], "answer": 2, "explain": "정답 (C) Mr. Ton is to be commended.\n해석: Ton 씨는 칭찬받아 마땅합니다.\n정답 근거: 사례도 받지 않았다는 칭찬에 이어 \"그는 칭찬받을 만하다\"는 결론 뒤 \"감사를 전해 달라\"는 요청이 자연스러움.\n오답 분석: (A) 주차장 표시는 무관. / (B) 금요일에 또 일어났다는 내용은 없음. / (D) 차량 수는 무관.", "translation": "Ton 씨는 칭찬받아 마땅합니다."}], "g": {"10": ["숫자", "10"], "march": ["명사", "3월"], "ms": ["고유명사", "~씨(여성 호칭)"], "norma": ["고유명사", "노마(이름)"], "barnes": ["고유명사", "반스(성)"], "human": ["형용사", "인간의(human resources 인사)"], "resources": ["명사", "자원(인사부)", "resource"], "office": ["명사", "부서, 사무실"], "clearview": ["고유명사", "클리어뷰(상호)"], "shopping": ["명사", "쇼핑"], "mall": ["명사", "쇼핑몰"], "2011": ["숫자", "2011(번지)"], "dunston": ["고유명사", "던스턴(도로명)"], "road": ["명사", "도로"], "oakville": ["고유명사", "오크빌(지명)"], "on": ["고유명사", "온타리오 주(ON)"], "l6h": ["고유명사", "우편번호 일부"], "6p5": ["고유명사", "우편번호 일부"], "dear": ["형용사", "친애하는"], "i": ["대명사", "나"], "am": ["동사", "~이다", "be"], "writing": ["현재분사", "쓰고 있는", "write"], "to": ["전치사", "~에게, ~으로"], "you": ["대명사", "당신"], "report": ["동사", "알리다, 보고하다"], "a": ["관사", "하나의"], "very": ["부사", "매우"], "experience": ["명사", "경험"], "with": ["전치사", "~와 함께, ~으로"], "one": ["대명사", "하나, 한 사람"], "of": ["전치사", "~의"], "the": ["관사", "그"], "mall's": ["명사", "쇼핑몰의", "mall"], "parking": ["명사", "주차"], "area": ["명사", "구역"], "attendants": ["명사", "관리인들", "attendant"], "last": ["형용사", "지난"], "thursday": ["명사", "목요일"], "afternoon": ["명사", "오후"], "visited": ["동사", "방문했다", "visit"], "return": ["동사", "반품하다"], "an": ["관사", "하나의"], "item": ["명사", "물건"], "was": ["동사", "~이었다", "be"], "in": ["전치사", "~에, ~안에"], "such": ["한정사", "그렇게, 그런"], "hurry": ["명사", "서두름"], "that": ["접속사", "(such ~ that) 너무 ~해서"], "accidentally": ["부사", "실수로"], "locked": ["동사", "잠갔다", "lock"], "my": ["한정사", "나의"], "keys": ["명사", "열쇠들", "key"], "inside": ["전치사", "~안에"], "car": ["명사", "자동차"], "so": ["부사", "너무"], "upset": ["형용사", "당황한, 속상한"], "and": ["접속사", "그리고"], "not": ["부사", "~아니다"], "sure": ["형용사", "확신하는"], "what": ["대명사", "무엇(을 ~할지)"], "do": ["동사", "하다"], "attendant": ["명사", "관리인"], "mr": ["고유명사", "~씨(남성 호칭)"], "warren": ["고유명사", "워렌(이름)"], "ton": ["고유명사", "톤(성)"], "came": ["동사", "왔다", "come"], "rescue": ["명사", "구조"], "within": ["전치사", "~이내에"], "minutes": ["명사", "분", "minute"], "he": ["대명사", "그"], "had": ["동사", "가졌다", "have"], "opened": ["과거분사", "열었던", "open"], "door": ["명사", "문"], "tool": ["명사", "도구"], "never": ["부사", "한 번도 ~않다"], "seen": ["과거분사", "본", "see"], "before": ["부사", "이전에"], "would": ["조동사", "~할 것이다", "will"], "accept": ["동사", "받다"], "any": ["한정사", "어떤"], "gratuity": ["명사", "사례금, 팁"], "for": ["전치사", "~을 위해, ~동안"], "his": ["한정사", "그의"], "trouble": ["명사", "수고"], "could": ["조동사", "~할 수 있었다", "can"], "please": ["부사", "부디, ~해 주세요"], "convey": ["동사", "전하다"], "thanks": ["명사", "감사"], "him": ["대명사", "그에게"], "sincerely": ["부사", "진심으로(맺음말)"], "eun": ["고유명사", "은(이름)"], "joo": ["고유명사", "주(이름)"], "kang": ["고유명사", "강(성)"]}}, {"range": "143-146", "passage": "To: All Patrons <patronlist@fflibrary.net> / From: Darah Park <d.park@fflibrary.net> / Date: September 3 / Subject: Changes\nDear Patrons,\nOn behalf of the Fulton Falls Library board, I am reaching out to our patrons ---143--- some changes to our offerings. Due to budget limitations and staffing challenges, we have made the decision to cut some of our regular ---144---. We are unable to ---145--- the weekly story time for children as well as the monthly community book club. A new budget will be approved in January, and we hope to see an increase in funding at that time.\n---146---. We are always interested in hearing new ideas.\nThanks to all our patrons for your support of Fulton Falls Library.\nSincerely, Darah Park, Board President, Fulton Falls Library", "tr": "수신: 전 이용자 / 발신: Darah Park / 날짜: 9월 3일 / 제목: 변경 사항\n이용자 여러분께, Fulton Falls 도서관 이사회를 대표하여 저희 프로그램의 몇 가지 변경 사항에 관해(143) 연락드립니다. 예산 제한과 인력 문제로 인해 정기 프로그램(144) 일부를 줄이기로 결정했습니다. 주간 어린이 스토리타임과 월간 지역 독서 클럽을 계속 주최할(145) 수 없게 되었습니다. 1월에 새 예산이 승인될 예정이며 그때 지원금이 늘어나길 바랍니다. 그동안 기존 서비스를 어떻게 개선할 수 있을지 알려 주십시오(146). 저희는 언제나 새로운 아이디어를 듣고 싶습니다. Fulton Falls 도서관을 지원해 주시는 모든 이용자께 감사드립니다. Darah Park, 이사회 회장, Fulton Falls 도서관 드림", "vocab": "patron 명 이용객, 후원자 / on behalf of 구 ~을 대표하여 / board 명 이사회 / reach out to 구 ~에게 연락하다 / regarding 전 ~에 관하여 / offering 명 제공되는 것 / limitation 명 제한 / staffing 명 인력 배치 / cut 동 줄이다 / program 명 프로그램 / host 동 주최하다 / approve 동 승인하다 / funding 명 자금 / in the meantime 구 그동안에 / existing 형 기존의", "questions": [{"no": 143, "q": "", "options": ["along", "barring", "despite", "regarding"], "answer": 3, "explain": "정답 (D) regarding\n해석: 변경 사항에 관해 이용자 여러분께 연락드립니다.\n정답 근거: 「빈칸 + 명사구 some changes」 → 연락의 주제를 이끄는 전치사 regarding(~에 관하여).\n오답 분석: (A) along: '~을 따라' — 불가. / (B) barring: '~이 없다면' — 불가. / (C) despite: '~에도 불구하고' — 의미 불가.\n지문 개요: Fulton Falls 도서관 이사회 회장 Darah Park이 이용자들에게 예산 제한과 인력 문제로 주간 어린이 스토리타임과 월간 독서 클럽을 중단한다고 알리며, 1월 새 예산에서 증액을 기대하고 그동안 기존 서비스 개선 의견을 달라는 이메일.", "translation": "변경 사항에 관해 이용자 여러분께 연락드립니다."}, {"no": 144, "q": "", "options": ["visits", "charges", "refreshments", "programs"], "answer": 3, "explain": "정답 (D) programs\n해석: 정기 프로그램 일부를 줄이기로 결정했습니다.\n정답 근거: 뒤 문장에서 줄이는 것이 스토리타임과 독서 클럽 → programs.\n오답 분석: (A) visits: '방문' — 불가. / (B) charges: '요금' — 불가. / (C) refreshments: '다과' — 불가.", "translation": "정기 프로그램 일부를 줄이기로 결정했습니다."}, {"no": 145, "q": "", "options": ["continuing to host", "continued to host", "continue hosting", "continuing hosting"], "answer": 2, "explain": "정답 (C) continue hosting\n해석: 주간 스토리타임과 월간 독서 클럽을 계속 주최할 수 없게 되었습니다.\n정답 근거: unable to 뒤 동사원형 continue, 타동사 continue 뒤 동명사 hosting(host 타동사 + 목적어 the weekly story time).\n오답 분석: (A) continuing to host: to 뒤에 -ing 불가. / (B) continued to host: to 뒤 과거형 불가. / (D) continuing hosting: to 뒤 -ing 불가.", "translation": "주간 스토리타임과 월간 독서 클럽을 계속 주최할 수 없게 되었습니다."}, {"no": 146, "q": "", "options": ["The library was opened to the public exactly 26 years ago.", "However, the revised schedule is subject to change without notice.", "In the meantime, please let us know how we can improve our existing services.", "Please accept our apologies for the delay."], "answer": 2, "explain": "정답 (C) In the meantime, please let us know how we can improve our existing services.\n해석: 그동안 기존 서비스를 어떻게 개선할 수 있을지 알려 주십시오.\n정답 근거: 1월 예산 증액을 기다리는 \"그동안(In the meantime)\" 의견을 달라는 내용이 뒤 문장 \"새로운 아이디어를 듣고 싶다\"와 연결됨.\n오답 분석: (A) 개관 연도는 무관. / (B) However로 대비할 일정 내용이 없음. / (D) 지연 사과는 문맥에 없음.", "translation": "그동안 기존 서비스를 어떻게 개선할 수 있을지 알려 주십시오."}], "g": {"to": ["전치사", "~에게, ~으로"], "all": ["한정사", "모든"], "patrons": ["명사", "이용객들", "patron"], "patronlist@fflibrary.net": ["고유명사", "이메일 주소"], "from": ["전치사", "~에서, ~로부터"], "darah": ["고유명사", "다라(이름)"], "park": ["고유명사", "박(성)"], "d.park@fflibrary.net": ["고유명사", "이메일 주소"], "date": ["명사", "날짜"], "september": ["명사", "9월"], "3": ["숫자", "3"], "subject": ["명사", "제목"], "changes": ["명사", "변경 사항", "change"], "dear": ["형용사", "친애하는"], "on": ["전치사", "~에, ~에 관해"], "behalf": ["명사", "(on behalf of) ~을 대표하여"], "of": ["전치사", "~의"], "the": ["관사", "그"], "fulton": ["고유명사", "풀턴(지명)"], "falls": ["고유명사", "폴스(지명)"], "library": ["명사", "도서관"], "board": ["명사", "이사회"], "i": ["대명사", "나"], "am": ["동사", "~이다", "be"], "reaching": ["현재분사", "연락하고 있는", "reach"], "out": ["부사", "(reach out) 연락하는"], "our": ["한정사", "우리의"], "some": ["한정사", "몇몇의"], "offerings": ["명사", "제공 프로그램", "offering"], "due": ["형용사", "(due to) ~때문에"], "budget": ["명사", "예산"], "limitations": ["명사", "제한", "limitation"], "and": ["접속사", "그리고"], "staffing": ["명사", "인력 배치"], "challenges": ["명사", "어려움", "challenge"], "we": ["대명사", "우리"], "have": ["동사", "가지다"], "made": ["과거분사", "내린", "make"], "decision": ["명사", "결정"], "cut": ["동사", "줄이다"], "regular": ["형용사", "정기적인"], "are": ["동사", "~이다", "be"], "unable": ["형용사", "~할 수 없는"], "weekly": ["형용사", "매주의"], "story": ["명사", "이야기"], "time": ["명사", "시간"], "for": ["전치사", "~을 위해, ~동안"], "children": ["명사", "아이들", "child"], "as": ["부사", "(as well as) ~뿐만 아니라"], "well": ["부사", "(as well as) ~뿐만 아니라"], "monthly": ["형용사", "매월의"], "community": ["명사", "지역 사회"], "book": ["명사", "책"], "club": ["명사", "모임, 클럽"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 있다"], "approved": ["과거분사", "승인된", "approve"], "in": ["전치사", "~에, ~안에"], "january": ["명사", "1월"], "hope": ["동사", "바라다"], "see": ["동사", "보다"], "an": ["관사", "하나의"], "increase": ["명사", "증가"], "funding": ["명사", "자금"], "at": ["전치사", "~에, ~에서"], "that": ["한정사", "그(at that time)"], "always": ["부사", "항상"], "interested": ["형용사", "관심 있는"], "hearing": ["동명사", "듣는 것", "hear"], "ideas": ["명사", "아이디어", "idea"], "thanks": ["명사", "감사"], "your": ["한정사", "당신의"], "support": ["명사", "지원"], "sincerely": ["부사", "진심으로(맺음말)"], "president": ["명사", "회장"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r9-p7',$mkd${"id": "a-r9-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 3, "round": 9, "level": "중급", "title": "A급 과제 9회 · PART 7 (기출독해 3문항 17·18회)", "notes": [], "items": [], "sets": [{"range": "155-157", "sub": "기출독해 3문항 17회", "passage": "To: All staff / From: Gabriel Petrescu / Date: Monday, May 3 / Subject: Important information\nDear staff:\nI am happy to announce that we have found someone to fill our immediate need for a receptionist in our front office. Beginning today, Sina Ung will be joining our staff. Ms. Ung will be working three days a week on a temporary basis while we conduct a formal search for a permanent office receptionist.\nMs. Ung has extensive experience as a receptionist in the medical and pharmaceutical industries. Consequently, she is accustomed to answering busy phone lines, keeping track of appointments, and greeting visitors daily in a large office.\nOn Mondays, Tuesdays, and Wednesdays, Ms. Ung will be on duty at our reception desk during regular office hours, from 9:00 A.M. to 5:00 P.M. Until we hire a full-time receptionist, Ralph Nilsson will fill in on Thursdays. Jane Sim will fill in on the following day.\nPlease try to stop by our reception desk today to welcome Ms. Ung in person.\nGabriel Petrescu, Human Resources Manager", "tr": "수신: 전 직원 / 발신: Gabriel Petrescu / 날짜: 5월 3일 월요일 / 제목: 중요 안내\n직원 여러분께: 프런트 오피스의 접수 직원이 당장 필요한 자리를 채울 분을 찾았음을 알리게 되어 기쁩니다. 오늘부터 Sina Ung이 합류합니다. Ung 씨는 정규 접수 직원을 공식적으로 찾는 동안 주 3일 임시로 근무합니다. Ung 씨는 의료 및 제약 업계에서 접수 직원으로 폭넓은 경력을 갖고 있습니다. 따라서 바쁜 전화 응대, 약속 관리, 큰 사무실에서 매일 방문객 맞이에 익숙합니다. 월·화·수요일에는 Ung 씨가 정규 근무 시간인 오전 9시부터 오후 5시까지 접수 데스크에 근무합니다. 정규직 접수 직원을 채용할 때까지 목요일에는 Ralph Nilsson이 대신합니다. 그다음 날은 Jane Sim이 대신합니다. 오늘 접수 데스크에 들러 Ung 씨를 직접 환영해 주시기 바랍니다. Gabriel Petrescu, 인사 매니저", "vocab": "immediate 형 즉각적인 / receptionist 명 접수 담당자 / on a temporary basis 구 임시로 / conduct 동 수행하다 / permanent 형 정규직의 / extensive 형 폭넓은 / pharmaceutical 형 제약의 / consequently 부 결과적으로 / be accustomed to 구 ~에 익숙하다 / keep track of 구 ~을 기록하다 / on duty 구 근무 중인 / fill in 구 대신 근무하다 / in person 구 직접", "questions": [{"no": 155, "q": "What is the purpose of the e-mail?", "options": ["To advertise a front office position", "To introduce a new employee", "To discuss a manager's duties", "To announce new office hours"], "answer": 1, "explain": "정답 (B) To introduce a new employee\n해석: 이메일의 목적은?\n정답 근거: \"오늘부터 Sina Ung이 합류한다\", \"들러 환영해 달라\" → 새 직원 소개.\n오답 분석: (A) 채용 광고가 아니라 채용 완료 알림. / (C) 매니저 직무 논의 아님. / (D) 근무 시간은 기존 정규 시간.\n지문 개요: 인사 매니저 Gabriel Petrescu가 정규 접수 직원을 구하는 동안 의료·제약 업계 경험이 풍부한 Sina Ung이 월·화·수 임시로 근무하고, 목요일은 Ralph Nilsson, 금요일은 Jane Sim이 대신하니 오늘 들러 환영해 달라는 이메일.", "translation": "이메일의 목적은?", "vocab": "Paraphrase: Sina Ung will be joining our staff / welcome Ms. Ung → introduce a new employee", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "e-mail": ["명사", "이메일"]}}, {"no": 156, "q": "The word \"conduct\" in paragraph 1, line 3, is closest in meaning to", "options": ["perform", "transport", "behave", "describe"], "answer": 0, "explain": "정답 (A) perform\n해석: 첫 단락 세 번째 줄의 \"conduct\"와 의미가 가장 가까운 것은?\n정답 근거: \"conduct a formal search(공식 탐색을 실시하다)\" → 수행하다 → perform.\n오답 분석: (B) transport: '운송하다' — 불일치. / (C) behave: '행동하다' — 불일치. / (D) describe: '묘사하다' — 불일치.", "translation": "첫 단락 세 번째 줄의 \"conduct\"와 의미가 가장 가까운 것은?", "vocab": "Paraphrase: conduct a formal search → perform", "g": {"the": ["관사", "그"], "word": ["명사", "단어"], "conduct": ["동사", "실시하다"], "in": ["전치사", "~에, ~안에"], "paragraph": ["명사", "단락"], "1": ["숫자", "1"], "line": ["명사", "줄"], "3": ["숫자", "3"], "is": ["동사", "~이다", "be"], "closest": ["형용사", "가장 가까운", "close"], "meaning": ["명사", "의미"], "to": ["전치사", "~에게, ~으로"]}}, {"no": 157, "q": "Who will work at the reception desk on Fridays?", "options": ["Mr. Petrescu", "Ms. Ung", "Mr. Nilsson", "Ms. Sim"], "answer": 3, "explain": "정답 (D) Ms. Sim\n해석: 금요일에 접수 데스크에서 일할 사람은?\n정답 근거: 목요일은 Nilsson, \"그다음 날(the following day)\"은 Jane Sim → 금요일은 Sim.\n오답 분석: (A) Petrescu는 인사 매니저. / (B) Ung은 월·화·수. / (C) Nilsson은 목요일.", "translation": "금요일에 접수 데스크에서 일할 사람은?", "vocab": "Paraphrase: Nilsson on Thursdays / Jane Sim on the following day → Ms. Sim", "g": {"who": ["대명사", "누구"], "will": ["조동사", "~할 것이다"], "work": ["동사", "일하다"], "at": ["전치사", "~에, ~에서"], "the": ["관사", "그"], "reception": ["명사", "접수, 안내"], "desk": ["명사", "데스크"], "on": ["전치사", "~에, ~에 관해"], "fridays": ["명사", "금요일마다", "friday"]}}], "g": {"to": ["전치사", "~에게, ~으로"], "all": ["한정사", "모든"], "staff": ["명사", "직원"], "from": ["전치사", "~에서, ~로부터"], "gabriel": ["고유명사", "가브리엘(이름)"], "petrescu": ["고유명사", "페트레스쿠(성)"], "date": ["명사", "날짜"], "monday": ["명사", "월요일"], "may": ["조동사", "~일지도 모른다"], "3": ["숫자", "3"], "subject": ["명사", "제목"], "important": ["형용사", "중요한"], "information": ["명사", "정보, 안내"], "dear": ["형용사", "친애하는"], "i": ["대명사", "나"], "am": ["동사", "~이다", "be"], "happy": ["형용사", "기쁜"], "announce": ["동사", "알리다"], "that": ["접속사", "~라는 것"], "we": ["대명사", "우리"], "have": ["동사", "가지다"], "found": ["과거분사", "찾은", "find"], "someone": ["대명사", "누군가"], "fill": ["동사", "채우다"], "our": ["한정사", "우리의"], "immediate": ["형용사", "즉각적인, 당장의"], "need": ["명사", "필요"], "for": ["전치사", "~을 위해, ~동안"], "a": ["관사", "하나의"], "receptionist": ["명사", "접수 담당자"], "in": ["전치사", "~에, ~안에"], "front": ["형용사", "앞쪽의"], "office": ["명사", "사무실"], "beginning": ["전치사", "~부터"], "today": ["부사", "오늘"], "sina": ["고유명사", "시나(이름)"], "ung": ["고유명사", "웅(성)"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 있다"], "joining": ["현재분사", "합류하는", "join"], "ms": ["고유명사", "~씨(여성 호칭)"], "working": ["현재분사", "근무하는", "work"], "three": ["숫자", "3"], "days": ["명사", "날들", "day"], "week": ["명사", "주"], "on": ["전치사", "~에, ~에 관해"], "temporary": ["형용사", "임시의"], "basis": ["명사", "기준(on a ~ basis)"], "while": ["접속사", "~하는 동안"], "conduct": ["동사", "실시하다"], "formal": ["형용사", "공식적인"], "search": ["명사", "찾기, 물색"], "permanent": ["형용사", "정규의, 영구적인"], "has": ["동사", "가지다", "have"], "extensive": ["형용사", "폭넓은"], "experience": ["명사", "경력"], "as": ["전치사", "~로서"], "the": ["관사", "그"], "medical": ["형용사", "의료의"], "and": ["접속사", "그리고"], "pharmaceutical": ["형용사", "제약의"], "industries": ["명사", "업계들", "industry"], "consequently": ["부사", "따라서"], "she": ["대명사", "그녀"], "is": ["동사", "~이다", "be"], "accustomed": ["형용사", "익숙한"], "answering": ["동명사", "응대하는 것", "answer"], "busy": ["형용사", "바쁜"], "phone": ["명사", "전화"], "lines": ["명사", "회선", "line"], "keeping": ["동명사", "유지하는 것", "keep"], "track": ["명사", "(keep track of) 기록 관리"], "of": ["전치사", "~의"], "appointments": ["명사", "약속, 예약", "appointment"], "greeting": ["동명사", "맞이하는 것", "greet"], "visitors": ["명사", "방문객들", "visitor"], "daily": ["부사", "매일"], "large": ["형용사", "큰"], "mondays": ["명사", "월요일마다", "monday"], "tuesdays": ["명사", "화요일마다", "tuesday"], "wednesdays": ["명사", "수요일마다", "wednesday"], "duty": ["명사", "근무(on duty 근무 중)"], "at": ["전치사", "~에, ~에서"], "reception": ["명사", "접수, 안내"], "desk": ["명사", "데스크"], "during": ["전치사", "~동안"], "regular": ["형용사", "정규의"], "hours": ["명사", "시간", "hour"], "9:00": ["숫자", "9시"], "a.m": ["명사", "오전"], "5:00": ["숫자", "5시"], "p.m": ["명사", "오후"], "until": ["접속사", "~할 때까지"], "hire": ["동사", "채용하다"], "full-time": ["형용사", "정규직의"], "ralph": ["고유명사", "랄프(이름)"], "nilsson": ["고유명사", "닐슨(성)"], "thursdays": ["명사", "목요일마다", "thursday"], "jane": ["고유명사", "제인(이름)"], "sim": ["고유명사", "심(성)"], "following": ["형용사", "그다음의"], "day": ["명사", "날"], "please": ["부사", "부디, ~해 주세요"], "try": ["동사", "노력하다"], "stop": ["동사", "(stop by) 들르다"], "by": ["전치사", "~까지, ~에 의해"], "welcome": ["동사", "환영하다"], "person": ["명사", "(in person) 직접"], "human": ["형용사", "(human resources) 인사"], "resources": ["명사", "(human resources) 인사", "resource"], "manager": ["명사", "관리자"]}}, {"range": "158-160", "sub": "기출독해 3문항 17회", "passage": "Hathley Magazine / 43 Broad Street / Framingham, MA 01701 / December 1\nMr. James Cho / 262 South Street / Norman, OK 73070\nDear Mr. Cho,\nThank you for being a loyal reader of Hathley Magazine. — [1] —. As you know, each monthly issue is full of thoughtful articles by award-winning writers. — [2] —. We cover an exceptional range of topics including politics, science, culture, and world travel, to inform and entertain our readers.\nTo ensure that you receive uninterrupted service, please consider renewing your subscription now. A subscription to Hathley Magazine normally costs $39.99 per year. — [3] —. However, if you respond to this letter before January 1, we can guarantee a price of $29.99 per year. — [4] —.\nWe will continue to send you printed issues. You can also read the digital version on our Web site, www.hathleymagazine.com. We recently launched a mobile app, so you can even read our magazine's content on your phone or any mobile device.\nWe hope to hear from you soon.\nSincerely, Rochelle Gustave, Subscription Services", "tr": "Hathley Magazine / 43 Broad Street / Framingham, MA 01701 / 12월 1일 / James Cho 씨 / 262 South Street / Norman, OK 73070\nCho 씨께, Hathley Magazine의 충성 독자가 되어 주셔서 감사합니다. — [1] —. 아시다시피 매월호는 수상 경력의 작가들이 쓴 사려 깊은 기사로 가득합니다. — [2] —. 저희는 독자에게 정보와 즐거움을 드리기 위해 정치, 과학, 문화, 세계 여행 등 폭넓은 주제를 다룹니다. 중단 없이 서비스를 받으시려면 지금 구독 갱신을 고려해 주십시오. Hathley Magazine 구독료는 보통 연 39.99달러입니다. — [3] —. 하지만 1월 1일 전에 이 편지에 응답하시면 연 29.99달러의 가격을 보장해 드릴 수 있습니다. — [4] — [사실 이것은 저희가 제공하는 최고의 구독 가격입니다.] 인쇄본을 계속 보내 드립니다. 웹사이트 www.hathleymagazine.com에서 디지털판도 읽으실 수 있습니다. 최근 모바일 앱을 출시해 휴대전화나 모바일 기기에서도 잡지 콘텐츠를 읽으실 수 있습니다. 곧 소식 주시기 바랍니다. Rochelle Gustave, 구독 서비스 드림", "vocab": "loyal 형 충실한 / issue 명 (잡지의) 호 / thoughtful 형 사려 깊은 / award-winning 형 수상 경력이 있는 / exceptional 형 특별한 / uninterrupted 형 중단 없는 / renew 동 갱신하다 / subscription 명 구독 / guarantee 동 보장하다 / launch 동 출시하다 / device 명 기기", "questions": [{"no": 158, "q": "What is suggested about Mr. Cho?", "options": ["He writes articles for Hathley Magazine.", "He is mainly interested in science topics.", "He currently receives Hathley Magazine.", "He has submitted a change-of-address form."], "answer": 2, "explain": "정답 (C) He currently receives Hathley Magazine.\n해석: Cho 씨에 대해 시사된 것은?\n정답 근거: \"충성 독자\", \"중단 없이 서비스를 받으려면 갱신하라\", \"인쇄본을 계속 보내겠다\" → 현재 잡지를 받고 있음.\n오답 분석: (A) 기사 작성자 아님. / (B) 과학 주제 선호 언급 없음. / (D) 주소 변경 언급 없음.\n지문 개요: Hathley Magazine 구독 서비스의 Rochelle Gustave가 독자 James Cho에게 구독 갱신을 권하며, 1월 1일 전에 응답하면 연 39.99달러 대신 최저가 29.99달러를 보장하고, 인쇄본과 더불어 웹·모바일 앱으로도 읽을 수 있다고 안내하는 편지.", "translation": "Cho 씨에 대해 시사된 것은?", "vocab": "Paraphrase: loyal reader / renewing your subscription → currently receives Hathley Magazine", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "suggested": ["과거분사", "암시된", "suggest"], "about": ["전치사", "~에 대해"], "mr": ["고유명사", "~씨(남성 호칭)"], "cho": ["고유명사", "조(성)"]}}, {"no": 159, "q": "What is mentioned as a benefit of a Hathley Magazine subscription?", "options": ["Access to an online message board", "A discount at entertainment venues", "A bonus atlas of world maps", "Mobile access to articles"], "answer": 3, "explain": "정답 (D) Mobile access to articles\n해석: Hathley Magazine 구독의 혜택으로 언급된 것은?\n정답 근거: \"모바일 앱을 출시해 휴대전화에서도 콘텐츠를 읽을 수 있다\" → 기사에 대한 모바일 접근.\n오답 분석: (A) 온라인 게시판 언급 없음. / (B) 공연장 할인 없음. / (C) 지도책 증정 없음.", "translation": "Hathley Magazine 구독의 혜택으로 언급된 것은?", "vocab": "Paraphrase: launched a mobile app / read on your phone → mobile access to articles", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "mentioned": ["과거분사", "언급된", "mention"], "as": ["접속사", "~듯이"], "a": ["관사", "하나의"], "benefit": ["명사", "혜택"], "of": ["전치사", "~의"], "hathley": ["고유명사", "해슬리(잡지명)"], "magazine": ["명사", "잡지"], "subscription": ["명사", "구독"]}}, {"no": 160, "q": "In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"In fact, this is the best subscription price we offer.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 3, "explain": "정답 (D) [4]\n해석: [1], [2], [3], [4] 중 \"In fact, this is the best subscription price we offer.\"가 들어가기에 가장 적절한 곳은?\n정답 근거: \"연 29.99달러를 보장한다\" 바로 뒤에 \"사실 이것이 최고의 구독 가격\"이라고 강조하는 것이 자연스러움 → [4].\n오답 분석: (A) [1]은 감사 인사 뒤로 가격 언급 전. / (B) [2]는 기사 품질 설명 뒤라 가격과 무관. / (C) [3]은 정상가 39.99달러 뒤라 this가 할인가를 가리키지 못함.", "translation": "[1], [2], [3], [4] 중 \"In fact, this is the best subscription price we offer.\"가 들어가기에 가장 적절한 곳은?", "vocab": "Paraphrase: guarantee a price of $29.99 → this is the best subscription price → [4]", "g": {"in": ["전치사", "~에, ~안에"], "which": ["대명사", "어느 것"], "of": ["전치사", "~의"], "the": ["관사", "그"], "positions": ["명사", "위치들", "position"], "marked": ["과거분사", "표시된", "mark"], "1": ["숫자", "1"], "2": ["숫자", "2"], "3": ["숫자", "3"], "and": ["접속사", "그리고"], "4": ["숫자", "4"], "does": ["조동사", "(의문문 조동사)", "do"], "following": ["형용사", "다음의"], "sentence": ["명사", "문장"], "best": ["부사", "가장 잘", "well"], "belong": ["동사", "들어가다, 속하다"], "fact": ["명사", "(in fact) 사실"], "this": ["한정사", "이"], "is": ["동사", "~이다", "be"], "subscription": ["명사", "구독"], "price": ["명사", "가격"], "we": ["대명사", "우리"], "offer": ["동사", "제공하다"]}}], "g": {"hathley": ["고유명사", "해슬리(잡지명)"], "magazine": ["명사", "잡지"], "43": ["숫자", "43(번지)"], "broad": ["고유명사", "브로드(도로명)"], "street": ["명사", "거리"], "framingham": ["고유명사", "프레이밍햄(지명)"], "ma": ["고유명사", "매사추세츠 주"], "01701": ["숫자", "우편번호"], "december": ["명사", "12월"], "1": ["숫자", "1"], "mr": ["고유명사", "~씨(남성 호칭)"], "james": ["고유명사", "제임스(이름)"], "cho": ["고유명사", "조(성)"], "262": ["숫자", "262(번지)"], "south": ["고유명사", "사우스(도로명)"], "norman": ["고유명사", "노먼(지명)"], "ok": ["고유명사", "오클라호마 주"], "73070": ["숫자", "우편번호"], "dear": ["형용사", "친애하는"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신"], "for": ["전치사", "~을 위해, ~동안"], "being": ["동명사", "~인 것", "be"], "a": ["관사", "하나의"], "loyal": ["형용사", "충실한"], "reader": ["명사", "독자"], "of": ["전치사", "~의"], "as": ["접속사", "~듯이"], "know": ["동사", "알다"], "each": ["한정사", "각각의"], "monthly": ["형용사", "매월의"], "issue": ["명사", "(잡지의) 호"], "is": ["동사", "~이다", "be"], "full": ["형용사", "가득한"], "thoughtful": ["형용사", "사려 깊은"], "articles": ["명사", "기사들", "article"], "by": ["전치사", "~까지, ~에 의해"], "award-winning": ["형용사", "수상 경력의"], "writers": ["명사", "작가들", "writer"], "2": ["숫자", "2"], "we": ["대명사", "우리"], "cover": ["동사", "다루다"], "an": ["관사", "하나의"], "exceptional": ["형용사", "특별한, 뛰어난"], "range": ["명사", "범위"], "topics": ["명사", "주제들", "topic"], "including": ["전치사", "~을 포함하여"], "politics": ["명사", "정치"], "science": ["명사", "과학"], "culture": ["명사", "문화"], "and": ["접속사", "그리고"], "world": ["명사", "세계"], "travel": ["명사", "여행"], "to": ["전치사", "~에게, ~으로"], "inform": ["동사", "정보를 주다"], "entertain": ["동사", "즐겁게 하다"], "our": ["한정사", "우리의"], "readers": ["명사", "독자들", "reader"], "ensure": ["동사", "보장하다"], "that": ["접속사", "~라는 것"], "receive": ["동사", "받다"], "uninterrupted": ["형용사", "중단 없는"], "service": ["명사", "서비스"], "please": ["부사", "부디, ~해 주세요"], "consider": ["동사", "고려하다"], "renewing": ["동명사", "갱신하는 것", "renew"], "your": ["한정사", "당신의"], "subscription": ["명사", "구독"], "now": ["부사", "지금"], "normally": ["부사", "보통"], "costs": ["동사", "비용이 들다", "cost"], "$39.99": ["숫자", "39.99달러"], "per": ["전치사", "~당"], "year": ["명사", "해, 년"], "3": ["숫자", "3"], "however": ["부사", "그러나"], "if": ["접속사", "만약 ~라면"], "respond": ["동사", "응답하다"], "this": ["한정사", "이"], "letter": ["명사", "편지"], "before": ["전치사", "~전에"], "january": ["명사", "1월"], "can": ["조동사", "~할 수 있다"], "guarantee": ["동사", "보장하다"], "price": ["명사", "가격"], "$29.99": ["숫자", "29.99달러"], "4": ["숫자", "4"], "will": ["조동사", "~할 것이다"], "continue": ["동사", "계속하다"], "send": ["동사", "보내다"], "printed": ["과거분사", "인쇄된", "print"], "issues": ["명사", "(잡지의) 호들", "issue"], "also": ["부사", "또한"], "read": ["동사", "읽다"], "the": ["관사", "그"], "digital": ["형용사", "디지털의"], "version": ["명사", "판, 버전"], "on": ["전치사", "~에, ~에 관해"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "www.hathleymagazine.com": ["고유명사", "웹사이트 주소"], "recently": ["부사", "최근에"], "launched": ["동사", "출시했다", "launch"], "mobile": ["형용사", "모바일의"], "app": ["명사", "앱"], "so": ["접속사", "그래서"], "even": ["부사", "심지어"], "magazine's": ["명사", "잡지의", "magazine"], "content": ["명사", "콘텐츠"], "phone": ["명사", "휴대전화"], "or": ["접속사", "또는"], "any": ["한정사", "어떤"], "device": ["명사", "기기"], "hope": ["동사", "바라다"], "hear": ["동사", "소식을 듣다"], "from": ["전치사", "~에서, ~로부터"], "soon": ["부사", "곧"], "sincerely": ["부사", "진심으로(맺음말)"], "rochelle": ["고유명사", "로셸(이름)"], "gustave": ["고유명사", "구스타브(성)"], "services": ["명사", "서비스(부서)", "service"]}}, {"range": "161-163", "sub": "기출독해 3문항 17회", "passage": "To: d.marusik@seltermanhospital.org / From: y.shaw@seltermanhospital.org / Subject: Request for assistance / Date: October 15\nDear Ms. Marusik:\nI'm currently teaching a course on hospital management at Stillwater University. One of my goals is to give the students an insider's perspective on how a hospital such as ours is run. To this end, on November 5, I will be taking them on a tour of the most vital departments within our hospital. A 20-minute information session will be held at each department, during which a staff member of the department will briefly describe the daily duties and answer students' questions. The tour will begin at 10:00 A.M. and is expected to end by 3:00 P.M. Lunch will be provided during the break from noon to 1:00 P.M.\nPlease ask your staff members in the medical records department if one of them would be so kind as to participate in this activity. Then pass the person's name on to me at your earliest convenience, but no later than October 31.\nThank you for your assistance in this matter.\nSincerely, Dr. Yuya Shaw, Executive Assistant, Administrative Services, Selterman Hospital", "tr": "수신: d.marusik@seltermanhospital.org / 발신: y.shaw@seltermanhospital.org / 제목: 협조 요청 / 날짜: 10월 15일\nMarusik 씨께: 저는 현재 Stillwater 대학에서 병원 경영 강의를 하고 있습니다. 제 목표 중 하나는 학생들에게 우리 같은 병원이 어떻게 운영되는지 내부자의 관점을 제공하는 것입니다. 이를 위해 11월 5일에 학생들을 데리고 우리 병원의 가장 핵심적인 부서들을 견학할 예정입니다. 각 부서에서 20분간 설명회가 열리며, 그동안 부서 직원 한 명이 일상 업무를 간략히 설명하고 학생들의 질문에 답합니다. 견학은 오전 10시에 시작해 오후 3시까지 끝날 예정입니다. 정오부터 오후 1시까지 휴식 시간에 점심이 제공됩니다. 의무기록 부서 직원들께 이 활동에 참여해 주실 분이 있는지 물어봐 주십시오. 그런 다음 가능한 한 빨리, 늦어도 10월 31일까지 그분의 이름을 제게 알려 주십시오. 협조에 감사드립니다. Yuya Shaw 박사, 행정 서비스 담당 임원 보좌, Selterman 병원 드림", "vocab": "perspective 명 관점 / run 동 운영하다 / to this end 구 이를 위해 / vital 형 중요한 / department 명 부서 / briefly 부 간략히 / duty 명 업무 / medical records 명 의료 기록 / participate in 구 ~에 참여하다 / pass A on to B 구 A를 B에게 전달하다 / at one's earliest convenience 구 가능한 한 빨리 / no later than 구 늦어도 ~까지", "questions": [{"no": 161, "q": "Why did Dr. Shaw send the e-mail?", "options": ["To promote a hospital management course", "To announce an updated room assignment", "To schedule a series of job interviews", "To recruit a volunteer"], "answer": 3, "explain": "정답 (D) To recruit a volunteer\n해석: Shaw 박사는 왜 이메일을 보냈는가?\n정답 근거: \"직원들께 이 활동에 참여해 주실 분이 있는지 물어봐 달라\" → 자원자(참여자) 모집.\n오답 분석: (A) 강의 홍보 아님. / (B) 방 배정 변경 아님. / (C) 면접 일정 아님.\n지문 개요: Selterman 병원의 Yuya Shaw 박사가 Stillwater 대학 병원 경영 강의 수강생들의 11월 5일 병원 견학(오전 10시~오후 3시, 부서 별 20분 설명회, 점심 제공)을 위해 의무기록 부서의 Marusik 씨에게 설명을 맡을 직원 한 명을 10월 31일까지 알려 달라는 이메일.", "translation": "Shaw 박사는 왜 이메일을 보냈는가?", "vocab": "Paraphrase: ask your staff members if one of them would participate → recruit a volunteer", "g": {"why": ["부사", "왜"], "did": ["조동사", "(과거 의문 조동사)", "do"], "dr": ["명사", "박사"], "shaw": ["고유명사", "쇼(성)"], "send": ["동사", "보내다"], "the": ["관사", "그"], "e-mail": ["명사", "이메일"]}}, {"no": 162, "q": "What is NOT indicated about the event on November 5?", "options": ["It will include descriptions of various job responsibilities.", "It will involve staff from different departments.", "It will last for two hours.", "It will include a meal."], "answer": 2, "explain": "정답 (C) It will last for two hours.\n해석: 11월 5일 행사에 대해 언급되지 않은 것은?\n정답 근거: 오전 10시~오후 3시이므로 5시간 소요 → 2시간은 틀림. 직무 설명(A), 여러 부서 직원(B), 점심 제공(D)은 언급됨.\n오답 분석: (A) 각 부서 직원이 일상 업무를 설명함. / (B) 여러 핵심 부서를 견학하며 부서 직원이 참여함. / (D) 점심이 제공됨.", "translation": "11월 5일 행사에 대해 언급되지 않은 것은?", "vocab": "Paraphrase: begin at 10:00 A.M. and end by 3:00 P.M. → (C) last for two hours — 불일치", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "not": ["부사", "~아니다"], "indicated": ["과거분사", "언급된", "indicate"], "about": ["전치사", "~에 대해"], "the": ["관사", "그"], "event": ["명사", "행사"], "on": ["전치사", "~에, ~에 관해"], "november": ["명사", "11월"], "5": ["숫자", "5"]}}, {"no": 163, "q": "What is indicated about Ms. Marusik?", "options": ["She works in the medical records department.", "She regularly gives presentations to hospital staff.", "She used to teach at Stillwater University.", "She is Dr. Shaw's assistant."], "answer": 0, "explain": "정답 (A) She works in the medical records department.\n해석: Marusik 씨에 대해 언급된 것은?\n정답 근거: \"의무기록 부서의 귀하 직원들(your staff members in the medical records department)에게 물어봐 달라\" → 의무기록 부서 소속(책임자).\n오답 분석: (B) 정기 발표 언급 없음. / (C) 대학 강의 경력은 Shaw 박사. / (D) Shaw 박사의 조수라는 언급 없음.", "translation": "Marusik 씨에 대해 언급된 것은?", "vocab": "Paraphrase: ask your staff members in the medical records department → works in the medical records department", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "언급된", "indicate"], "about": ["전치사", "~에 대해"], "ms": ["고유명사", "~씨(여성 호칭)"], "marusik": ["고유명사", "마루시크(성)"]}}], "g": {"to": ["전치사", "~에게, ~으로"], "d.marusik@seltermanhospital.org": ["고유명사", "이메일 주소"], "from": ["전치사", "~에서, ~로부터"], "y.shaw@seltermanhospital.org": ["고유명사", "이메일 주소"], "subject": ["명사", "제목"], "request": ["명사", "요청"], "for": ["전치사", "~을 위해, ~동안"], "assistance": ["명사", "도움, 협조"], "date": ["명사", "날짜"], "october": ["명사", "10월"], "15": ["숫자", "15"], "dear": ["형용사", "친애하는"], "ms": ["고유명사", "~씨(여성 호칭)"], "marusik": ["고유명사", "마루시크(성)"], "i'm": ["대명사", "나는 ~이다", "I am"], "currently": ["부사", "현재"], "teaching": ["현재분사", "가르치는", "teach"], "a": ["관사", "하나의"], "course": ["명사", "강의"], "on": ["전치사", "~에, ~에 관해"], "hospital": ["명사", "병원"], "management": ["명사", "경영"], "at": ["전치사", "~에, ~에서"], "stillwater": ["고유명사", "스틸워터(지명)"], "university": ["명사", "대학교"], "one": ["대명사", "하나, 한 사람"], "of": ["전치사", "~의"], "my": ["한정사", "나의"], "goals": ["명사", "목표들", "goal"], "is": ["동사", "~이다", "be"], "give": ["동사", "주다"], "the": ["관사", "그"], "students": ["명사", "학생들", "student"], "an": ["관사", "하나의"], "insider's": ["명사", "내부자의", "insider"], "perspective": ["명사", "관점"], "how": ["부사", "어떻게"], "such": ["형용사", "(such as) ~같은"], "as": ["전치사", "~로서"], "ours": ["대명사", "우리의 것"], "run": ["과거분사", "운영되는", "run"], "this": ["한정사", "이"], "end": ["명사", "목적(to this end 이를 위해)"], "november": ["명사", "11월"], "5": ["숫자", "5"], "i": ["대명사", "나"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 있다"], "taking": ["현재분사", "데려가는", "take"], "them": ["대명사", "그들을"], "tour": ["명사", "견학"], "most": ["부사", "가장"], "vital": ["형용사", "중요한"], "departments": ["명사", "부서들", "department"], "within": ["전치사", "~안의"], "our": ["한정사", "우리의"], "20-minute": ["형용사", "20분짜리"], "information": ["명사", "정보"], "session": ["명사", "설명회, 시간"], "held": ["과거분사", "열리는", "hold"], "each": ["한정사", "각각의"], "department": ["명사", "부서"], "during": ["전치사", "~동안"], "which": ["대명사", "어느 것"], "staff": ["명사", "직원"], "member": ["명사", "구성원"], "briefly": ["부사", "간략히"], "describe": ["동사", "설명하다"], "daily": ["형용사", "일상의"], "duties": ["명사", "업무", "duty"], "and": ["접속사", "그리고"], "answer": ["동사", "답하다"], "students'": ["명사", "학생들의", "student"], "questions": ["명사", "질문들", "question"], "begin": ["동사", "시작하다"], "10:00": ["숫자", "10시"], "a.m": ["명사", "오전"], "expected": ["과거분사", "예상되는", "expect"], "by": ["전치사", "~까지, ~에 의해"], "3:00": ["숫자", "3시"], "p.m": ["명사", "오후"], "lunch": ["명사", "점심"], "provided": ["과거분사", "제공되는", "provide"], "break": ["명사", "휴식 시간"], "noon": ["명사", "정오"], "1:00": ["숫자", "1시"], "please": ["부사", "부디, ~해 주세요"], "ask": ["동사", "묻다"], "your": ["한정사", "당신의"], "members": ["명사", "구성원들", "member"], "in": ["전치사", "~에, ~안에"], "medical": ["형용사", "의료의"], "records": ["명사", "기록", "record"], "if": ["접속사", "만약 ~라면"], "would": ["조동사", "~할 것이다", "will"], "so": ["부사", "그렇게(so kind as to)"], "kind": ["형용사", "친절한"], "participate": ["동사", "참여하다"], "activity": ["명사", "활동"], "then": ["부사", "그러고 나서"], "pass": ["동사", "(pass on) 전달하다"], "person's": ["명사", "그 사람의", "person"], "name": ["명사", "이름"], "me": ["대명사", "나에게"], "earliest": ["형용사", "가장 이른", "early"], "convenience": ["명사", "편리(earliest convenience 가능한 빨리)"], "but": ["접속사", "그러나"], "no": ["한정사", "어떤 ~도 없는"], "later": ["부사", "(no later than) 늦어도"], "than": ["접속사", "~보다"], "31": ["숫자", "31(일)"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신"], "matter": ["명사", "일, 문제"], "sincerely": ["부사", "진심으로(맺음말)"], "dr": ["명사", "박사"], "yuya": ["고유명사", "유야(이름)"], "shaw": ["고유명사", "쇼(성)"], "executive": ["형용사", "임원의"], "assistant": ["명사", "보좌관"], "administrative": ["형용사", "행정의"], "services": ["명사", "서비스(부서)", "service"], "selterman": ["고유명사", "셀터만(병원명)"]}}, {"range": "153-155", "sub": "기출독해 3문항 18회", "passage": "To: IT Support / From: Xiaolin Yang / Date: April 9 / Subject: Editorial department\nDear IT Support:\nI received a new desktop computer last week for my office. It was working great until today. — [1] —. Now, whenever I try to print a document, the screen freezes and displays a fixed image over all of the other applications that are open on my computer screen. — [2] —. I have to restart the computer every time to unfreeze the screen. Also, I still cannot send anything to the printer. This is happening for others in the editorial department as well. Can you please send someone up to the second floor right away to figure this out for us? — [3] —. We are preparing for an important presentation tomorrow afternoon. — [4] —. Thank you for your help.\nBest, Xiaolin Yang", "tr": "수신: IT 지원 / 발신: Xiaolin Yang / 날짜: 4월 9일 / 제목: 편집부\nIT 지원팀께: 지난주 사무실용 새 데스크톱 컴퓨터를 받았습니다. 오늘까지는 잘 작동했습니다. — [1] —. 지금은 문서를 인쇄하려 할 때마다 화면이 멈추고 열려 있는 다른 모든 응용 프로그램 위에 고정된 이미지가 표시됩니다. — [2] —. 화면을 풀려면 매번 컴퓨터를 재시작해야 합니다. 또한 여전히 프린터로 아무것도 보낼 수 없습니다. 편집부의 다른 직원들에게도 같은 일이 일어나고 있습니다. 지금 바로 2층으로 사람을 보내 이 문제를 해결해 주시겠습니까? — [3] —. 내일 오후 중요한 발표를 준비하고 있습니다. — [4] — [그 전에 모든 자료를 인쇄해야 합니다.] 도움에 감사드립니다. Xiaolin Yang 드림", "vocab": "editorial 형 편집의 / freeze 동 멈추다 / display 동 표시하다 / fixed 형 고정된 / application 명 응용 프로그램 / restart 동 재시작하다 / as well 구 또한 / right away 구 즉시 / figure out 구 알아내다 / materials 명 자료", "questions": [{"no": 153, "q": "What is the purpose of the e-mail?", "options": ["To ask for assistance", "To order a new printer", "To request a repair to a freezer", "To invite a colleague to a presentation"], "answer": 0, "explain": "정답 (A) To ask for assistance\n해석: 이메일의 목적은?\n정답 근거: \"사람을 보내 이 문제를 해결해 달라\", \"도움에 감사\" → 도움 요청.\n오답 분석: (B) 새 프린터 주문 아님. / (C) 냉동고가 아니라 화면 멈춤(freeze) 문제. / (D) 발표 초대 아님.\n지문 개요: 편집부 Xiaolin Yang이 IT 지원팀에 지난주 받은 새 데스크톱이 인쇄 시 화면이 멈추고 프린터 전송이 안 되며 부서 다른 직원도 같은 문제라며, 내일 오후 중요한 발표 자료를 인쇄해야 하니 2층으로 즉시 사람을 보내 달라는 이메일.", "translation": "이메일의 목적은?", "vocab": "Paraphrase: Can you please send someone … to figure this out → ask for assistance", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "e-mail": ["명사", "이메일"]}}, {"no": 154, "q": "What is indicated about Ms. Yang?", "options": ["She was hired recently.", "She was given new office equipment.", "She works in the IT department.", "She has an office on the first floor."], "answer": 1, "explain": "정답 (B) She was given new office equipment.\n해석: Yang 씨에 대해 언급된 것은?\n정답 근거: \"지난주 사무실용 새 데스크톱 컴퓨터를 받았다\" → 새 사무 장비를 받음.\n오답 분석: (A) 최근 채용 언급 없음. / (C) 편집부 소속이며 IT는 수신자. / (D) 사무실은 2층.", "translation": "Yang 씨에 대해 언급된 것은?", "vocab": "Paraphrase: received a new desktop computer for my office → given new office equipment", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "언급된", "indicate"], "about": ["전치사", "~에 대해"], "ms": ["고유명사", "~씨(여성 호칭)"], "yang": ["고유명사", "양(성)"]}}, {"no": 155, "q": "In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"We need to print all our materials before then.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 3, "explain": "정답 (D) [4]\n해석: [1], [2], [3], [4] 중 \"We need to print all our materials before then.\"이 들어가기에 가장 적절한 곳은?\n정답 근거: \"내일 오후 중요한 발표를 준비 중\"이라는 문장 뒤에 \"그 전에(before then) 모든 자료를 인쇄해야 한다\"가 와야 then의 지시 대상(내일 오후)이 분명함 → [4].\n오답 분석: (A) [1]은 잘 작동했다는 문장 뒤라 then의 대상이 없음. / (B) [2]는 증상 설명 중간. / (C) [3]은 발표 언급 전이라 then이 가리킬 시점이 없음.", "translation": "[1], [2], [3], [4] 중 \"We need to print all our materials before then.\"이 들어가기에 가장 적절한 곳은?", "vocab": "Paraphrase: presentation tomorrow afternoon → print all our materials before then → [4]", "g": {"in": ["전치사", "~에, ~안에"], "which": ["대명사", "어느 것"], "of": ["전치사", "~의"], "the": ["관사", "그"], "positions": ["명사", "위치들", "position"], "marked": ["과거분사", "표시된", "mark"], "1": ["숫자", "1"], "2": ["숫자", "2"], "3": ["숫자", "3"], "and": ["접속사", "그리고"], "4": ["숫자", "4"], "does": ["조동사", "(의문문 조동사)", "do"], "following": ["형용사", "다음의"], "sentence": ["명사", "문장"], "best": ["부사", "(맺음말) 감사합니다", "well"], "belong": ["동사", "들어가다, 속하다"], "we": ["대명사", "우리"], "need": ["동사", "필요하다"], "to": ["전치사", "~에게, ~으로"], "print": ["동사", "인쇄하다"], "all": ["한정사", "모든"], "our": ["한정사", "우리의"], "materials": ["명사", "자료", "material"], "before": ["전치사", "~전에"], "then": ["부사", "그러고 나서"]}}], "g": {"to": ["전치사", "~에게, ~으로"], "it": ["대명사", "그것"], "support": ["명사", "지원(팀)"], "from": ["전치사", "~에서, ~로부터"], "xiaolin": ["고유명사", "샤오린(이름)"], "yang": ["고유명사", "양(성)"], "date": ["명사", "날짜"], "april": ["명사", "4월"], "9": ["숫자", "9(일)"], "subject": ["명사", "제목"], "editorial": ["형용사", "편집의"], "department": ["명사", "부서"], "dear": ["형용사", "친애하는"], "i": ["대명사", "나"], "received": ["동사", "받았다", "receive"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "desktop": ["명사", "데스크톱"], "computer": ["명사", "컴퓨터"], "last": ["형용사", "지난"], "week": ["명사", "주"], "for": ["전치사", "~을 위해, ~동안"], "my": ["한정사", "나의"], "office": ["명사", "사무실"], "was": ["동사", "~이었다", "be"], "working": ["현재분사", "작동하는", "work"], "great": ["부사", "잘, 훌륭하게"], "until": ["전치사", "~까지"], "today": ["명사", "오늘"], "1": ["숫자", "1"], "now": ["부사", "지금은"], "whenever": ["접속사", "~할 때마다"], "try": ["동사", "시도하다"], "print": ["동사", "인쇄하다"], "document": ["명사", "문서"], "the": ["관사", "그"], "screen": ["명사", "화면"], "freezes": ["동사", "멈추다", "freeze"], "and": ["접속사", "그리고"], "displays": ["동사", "표시하다", "display"], "fixed": ["형용사", "고정된"], "image": ["명사", "이미지"], "over": ["전치사", "~위에"], "all": ["한정사", "모든"], "of": ["전치사", "~의"], "other": ["형용사", "다른"], "applications": ["명사", "응용 프로그램들", "application"], "that": ["관계사", "~하는"], "are": ["동사", "~이다", "be"], "open": ["형용사", "열려 있는"], "on": ["전치사", "~에, ~에 관해"], "2": ["숫자", "2"], "have": ["동사", "가지다"], "restart": ["동사", "재시작하다"], "every": ["한정사", "매, 모든"], "time": ["명사", "번, 때"], "unfreeze": ["동사", "(멈춘 것을) 풀다"], "also": ["부사", "또한"], "still": ["부사", "여전히"], "cannot": ["조동사", "~할 수 없다", "can"], "send": ["동사", "보내다"], "anything": ["대명사", "아무것도"], "printer": ["명사", "프린터"], "this": ["한정사", "이"], "is": ["동사", "~이다", "be"], "happening": ["현재분사", "일어나는", "happen"], "others": ["대명사", "다른 사람들"], "in": ["전치사", "~에, ~안에"], "as": ["전치사", "~로서"], "well": ["부사", "(as well) 또한"], "can": ["조동사", "~할 수 있다"], "you": ["대명사", "당신"], "please": ["부사", "부디, ~해 주세요"], "someone": ["대명사", "누군가"], "up": ["부사", "위로"], "second": ["형용사", "두 번째의"], "floor": ["명사", "층"], "right": ["부사", "(right away) 즉시"], "away": ["부사", "(right away) 즉시"], "figure": ["동사", "(figure out) 알아내다"], "out": ["부사", "(figure out) 해결하는"], "us": ["대명사", "우리를"], "3": ["숫자", "3"], "we": ["대명사", "우리"], "preparing": ["현재분사", "준비하는", "prepare"], "an": ["관사", "하나의"], "important": ["형용사", "중요한"], "presentation": ["명사", "발표"], "tomorrow": ["명사", "내일"], "afternoon": ["명사", "오후"], "4": ["숫자", "4"], "thank": ["동사", "감사하다"], "your": ["한정사", "당신의"], "help": ["명사", "도움"], "best": ["부사", "(맺음말) 감사합니다", "well"]}}, {"range": "158-160", "sub": "기출독해 3문항 18회", "passage": "Construction Workers Needed\nLiving Construction, Inc., seeks part- and full-time construction workers for apartment projects throughout Murphy County. Workers will be responsible for moving heavy materials, operating machinery, and assisting with the maintenance of the work sites. Prior experience with a construction crew is preferred but not required. Entry-level positions may assist with carpentry and electrical and plumbing systems, and paid training may be offered to the right candidates. New hires will be expected to work on teams with minimal supervision. New hires will have opportunities for advancement in a growing firm.\nSubmit application and resume to Richard Hans at rhans@livingconstruct.com by May 19. Hiring will begin on June 1.", "tr": "건설 인력 구함\nLiving Construction, Inc.는 Murphy County 전역의 아파트 프로젝트를 위해 파트타임 및 풀타임 건설 인력을 찾습니다. 작업자는 무거운 자재 운반, 기계 조작, 작업 현장 유지 보조를 담당합니다. 건설팀 경력은 우대하지만 필수는 아닙니다. 신입 직위는 목공과 전기·배관 시스템을 보조할 수 있으며 적합한 후보자에게는 유급 교육이 제공될 수 있습니다. 신규 채용자는 최소한의 감독 아래 팀으로 일해야 합니다. 신규 채용자는 성장하는 회사에서 승진 기회를 갖게 됩니다. 5월 19일까지 지원서와 이력서를 Richard Hans(rhans@livingconstruct.com)에게 제출하세요. 채용은 6월 1일에 시작됩니다.", "vocab": "seek 동 구하다 / throughout 전 ~전역에 / be responsible for 구 ~을 담당하다 / operate 동 작동하다 / machinery 명 기계 / maintenance 명 유지 관리 / prior 형 이전의 / entry-level 형 초급의 / carpentry 명 목공 / plumbing 명 배관 / supervision 명 감독 / advancement 명 승진 / submit 동 제출하다", "questions": [{"no": 158, "q": "What is indicated about Living Construction, Inc.?", "options": ["It has recently promoted a project manager.", "It is planning projects at several sites.", "It is opening a new office in Murphy County.", "It is hiring temporary employees."], "answer": 1, "explain": "정답 (B) It is planning projects at several sites.\n해석: Living Construction, Inc.에 대해 언급된 것은?\n정답 근거: \"Murphy County 전역의 아파트 프로젝트(projects throughout Murphy County)\" → 여러 현장의 프로젝트계획.\n오답 분석: (A) 프로젝트 매니저 승진 언급 없음. / (C) 새 사무실 개설 언급 없음. / (D) 임시직이 아니라 파트·풀타임.\n지문 개요: Living Construction이 Murphy County 전역의 아파트 프로젝트를 위해 파트·풀타임 건설 인력을 모집하며, 경력은 우대하나 필수는 아니고 신입은 목공·전기·배관 보조와 유급 교육 기회가 있으며, 5월 19일까지 지원서·이력서를 제출하면 6월 1일부터 채용한다는 공고.", "translation": "Living Construction, Inc.에 대해 언급된 것은?", "vocab": "Paraphrase: apartment projects throughout Murphy County → planning projects at several sites", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "언급된", "indicate"], "about": ["전치사", "~에 대해"], "living": ["고유명사", "리빙(회사명)"], "construction": ["명사", "건설"], "inc": ["명사", "주식회사"]}}, {"no": 159, "q": "What is suggested about people who may be hired?", "options": ["They will have a range of skill levels.", "They have worked for Living Construction, Inc., previously.", "They will attend a training institute.", "They must have licenses to perform their duties."], "answer": 0, "explain": "정답 (A) They will have a range of skill levels.\n해석: 채용될 수 있는 사람들에 대해 시사된 것은?\n정답 근거: \"경력은 우대하지만 필수 아님\", \"신입 직위… 유급 교육\" → 다양한 숙련도의 사람들.\n오답 분석: (B) 이전 근무 경력 조건 없음. / (C) 교육 기관이 아니라 회사 유급 교육. / (D) 자격증 요구 없음.", "translation": "채용될 수 있는 사람들에 대해 시사된 것은?", "vocab": "Paraphrase: experience preferred but not required / entry-level positions → a range of skill levels", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "suggested": ["과거분사", "암시된", "suggest"], "about": ["전치사", "~에 대해"], "people": ["명사", "사람들"], "who": ["관계사", "~하는(사람)"], "may": ["명사", "5월"], "be": ["동사", "~이다, 있다"], "hired": ["과거분사", "채용되는", "hire"]}}, {"no": 160, "q": "What is expected to happen by May 19?", "options": ["Applications will have been received.", "A construction project will be completed.", "Open positions will have been filled.", "Newly hired workers will be assigned to crews."], "answer": 0, "explain": "정답 (A) Applications will have been received.\n해석: 5월 19일까지 무슨 일이 있을 것으로 예상되는가?\n정답 근거: \"5월 19일까지 지원서와 이력서를 제출하라\" → 지원서가 접수되어 있을 것.\n오답 분석: (B) 프로젝트 완료 아님. / (C) 채용은 6월 1일 시작이라 충원 완료 아님. / (D) 팀 배정은 채용 이후.", "translation": "5월 19일까지 무슨 일이 있을 것으로 예상되는가?", "vocab": "Paraphrase: Submit application and resume … by May 19 → applications will have been received", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "expected": ["과거분사", "예상되는", "expect"], "to": ["전치사", "~에게, ~으로"], "happen": ["동사", "일어나다"], "by": ["전치사", "~까지, ~에 의해"], "may": ["명사", "5월"], "19": ["숫자", "19(일)"]}}], "g": {"construction": ["명사", "건설"], "workers": ["명사", "인부들, 작업자", "worker"], "needed": ["과거분사", "필요한", "need"], "living": ["고유명사", "리빙(회사명)"], "inc": ["명사", "주식회사"], "seeks": ["동사", "구하다", "seek"], "part": ["명사", "(part-time) 시간제"], "and": ["접속사", "그리고"], "full-time": ["형용사", "정규직의"], "for": ["전치사", "~을 위해, ~동안"], "apartment": ["명사", "아파트"], "projects": ["명사", "프로젝트들", "project"], "throughout": ["전치사", "~전역에"], "murphy": ["고유명사", "머피(지명)"], "county": ["명사", "군(행정 구역)"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 있다"], "responsible": ["형용사", "책임이 있는"], "moving": ["동명사", "옮기는 것", "move"], "heavy": ["형용사", "무거운"], "materials": ["명사", "자재", "material"], "operating": ["동명사", "작동하는 것", "operate"], "machinery": ["명사", "기계류"], "assisting": ["동명사", "돕는 것", "assist"], "with": ["전치사", "~와 함께, ~으로"], "the": ["관사", "그"], "maintenance": ["명사", "유지 관리"], "of": ["전치사", "~의"], "work": ["명사", "작업"], "sites": ["명사", "현장들", "site"], "prior": ["형용사", "이전의"], "experience": ["명사", "경력"], "a": ["관사", "하나의"], "crew": ["명사", "작업반"], "is": ["동사", "~이다", "be"], "preferred": ["과거분사", "우대되는", "prefer"], "but": ["접속사", "그러나"], "not": ["부사", "~아니다"], "required": ["과거분사", "필수인", "require"], "entry-level": ["형용사", "초급의"], "positions": ["명사", "직위들", "position"], "may": ["명사", "5월"], "assist": ["동사", "돕다"], "carpentry": ["명사", "목공"], "electrical": ["형용사", "전기의"], "plumbing": ["명사", "배관"], "systems": ["명사", "시스템들", "system"], "paid": ["형용사", "유급의"], "training": ["명사", "교육"], "offered": ["과거분사", "제공되는", "offer"], "to": ["전치사", "~에게, ~으로"], "right": ["형용사", "적합한"], "candidates": ["명사", "지원자들", "candidate"], "new": ["형용사", "새로운"], "hires": ["명사", "채용된 사람들", "hire"], "expected": ["과거분사", "예상되는", "expect"], "on": ["전치사", "~에, ~에 관해"], "teams": ["명사", "팀들", "team"], "minimal": ["형용사", "최소한의"], "supervision": ["명사", "감독"], "have": ["동사", "가지다"], "opportunities": ["명사", "기회들", "opportunity"], "advancement": ["명사", "승진"], "in": ["전치사", "~에, ~안에"], "growing": ["현재분사", "성장하는", "grow"], "firm": ["명사", "회사"], "submit": ["동사", "제출하다"], "application": ["명사", "지원서"], "resume": ["명사", "이력서"], "richard": ["고유명사", "리처드(이름)"], "hans": ["고유명사", "한스(성)"], "at": ["전치사", "~에, ~에서"], "rhans@livingconstruct.com": ["고유명사", "이메일 주소"], "by": ["전치사", "~까지, ~에 의해"], "19": ["숫자", "19(일)"], "hiring": ["명사", "채용"], "begin": ["동사", "시작하다"], "june": ["명사", "6월"], "1": ["숫자", "1"]}}, {"range": "161-163", "sub": "기출독해 3문항 18회", "passage": "The Lominato Company is one of Italy's oldest seed companies, founded by Elena and Uberto Lominato three generations ago. Its prized seeds are developed and packaged according to the most rigorous standards.\nThe Lominato Company guarantees that customers will appreciate the quality fruits and vegetables that its seeds produce. Customers receive a complete refund if a purchase does not deliver as promised.\nIn addition to seeds, the company carries a variety of ornamental products to beautify any outdoor landscape, including clay pots, trellises, birdhouses, and decorative statues. Visit the Lominato Company Web site to shop for hundreds of wonderful items that can be shipped all over the world. The Web site also offers a number of instructional videos to inform users of best practices in gardening.", "tr": "Lominato Company는 3대 전 Elena와 Uberto Lominato가 설립한 이탈리아에서 가장 오래된 종자 회사 중 하나입니다. 이 회사의 소중한 종자는 가장 엄격한 기준에 따라 개발·포장됩니다. Lominato Company는 고객이 그 종자로 기른 품질 좋은 과일과 채소에 만족할 것을 보증합니다. 구매품이 약속대로 결과를 내지 못하면 고객은 전액 환불을 받습니다. 종자 외에도 회사는 점토 화분, 격자 울타리, 새집, 장식 조각상 등 야외 조경을 아름답게 하는 다양한 장식 제품을 취급합니다. Lominato Company 웹사이트를 방문해 전 세계로 배송 가능한 수백 가지 멋진 제품을 쇼핑하세요. 웹사이트는 원예 모범 사례를 알려 주는 여러 교육 영상도 제공합니다.", "vocab": "found 동 설립하다 / generation 명 세대 / prized 형 소중한 / rigorous 형 엄격한 / standard 명 기준 / guarantee 동 보장하다 / appreciate 동 진가를 알아보다 / deliver 동 (기대를) 충족하다 / ornamental 형 장식용의 / beautify 동 아름답게 하다 / landscape 명 경관 / instructional 형 교육용의 / best practice 명 모범 사례", "questions": [{"no": 161, "q": "The word \"standards\" in paragraph 1, line 3, is closest in meaning to", "options": ["facts", "rules", "objects", "needs"], "answer": 1, "explain": "정답 (B) rules\n해석: 첫 단락 세 번째 줄의 \"standards\"와 의미가 가장 가까운 것은?\n정답 근거: \"the most rigorous standards(가장 엄격한 기준)에 따라 개발·포장\" → 기준, 규칙 → rules.\n오답 분석: (A) facts: '사실' — 불일치. / (C) objects: '물건' — 불일치. / (D) needs: '필요' — 불일치.\n지문 개요: 3대째 이어 온 이탈리아 종자 회사 Lominato가 엄격한 기준으로 개발·포장한 종자의 품질을 보증하고(불만족 시 전액 환불), 화분·격자 울타리·새집·장식 조각상 등 정원 장식 제품도 판매하며, 전 세계 배송과 원예 요령 영상을 웹사이트에서 제공한다는 광고.", "translation": "첫 단락 세 번째 줄의 \"standards\"와 의미가 가장 가까운 것은?", "vocab": "Paraphrase: the most rigorous standards → rules", "g": {"the": ["관사", "그"], "word": ["명사", "단어"], "standards": ["명사", "기준들", "standard"], "in": ["전치사", "~에, ~안에"], "paragraph": ["명사", "단락"], "1": ["숫자", "1"], "line": ["명사", "줄"], "3": ["숫자", "3"], "is": ["동사", "~이다", "be"], "closest": ["형용사", "가장 가까운", "close"], "meaning": ["명사", "의미"], "to": ["전치사", "~에게, ~으로"]}}, {"no": 162, "q": "What is mentioned about the Lominato Company?", "options": ["It is a recently opened business.", "It offers free shipping.", "It sells items for decorating a garden.", "It is having a sale on fruits and vegetables."], "answer": 2, "explain": "정답 (C) It sells items for decorating a garden.\n해석: Lominato Company에 대해 언급된 것은?\n정답 근거: \"야외 조경을 아름답게 하는 장식 제품(화분, 격자 울타리, 새집, 조각상)\" → 정원 장식용 물품 판매.\n오답 분석: (A) 3대째 이어 온 오래된 회사. / (B) 무료 배송 언급 없음. / (D) 과일·채소 세일 없음 — 종자 판매.", "translation": "Lominato Company에 대해 언급된 것은?", "vocab": "Paraphrase: ornamental products to beautify any outdoor landscape → sells items for decorating a garden", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "mentioned": ["과거분사", "언급된", "mention"], "about": ["전치사", "~에 대해"], "the": ["관사", "그"], "lominato": ["고유명사", "로미나토(회사명)"], "company": ["명사", "회사"]}}, {"no": 163, "q": "What can users learn about on the Web site?", "options": ["Preparing Italian food", "Traveling in Italy", "Growing plants", "Identifying common birds"], "answer": 2, "explain": "정답 (C) Growing plants\n해석: 웹사이트에서 사용자가 배울 수 있는 것은?\n정답 근거: \"원예 모범 사례(best practices in gardening)를 알려 주는 교육 영상\" → 식물 기르기.\n오답 분석: (A) 이탈리아 요리 아님. / (B) 이탈리아 여행 아님. / (D) 새 식별이 아니라 새집 판매.", "translation": "웹사이트에서 사용자가 배울 수 있는 것은?", "vocab": "Paraphrase: instructional videos … best practices in gardening → growing plants", "g": {"what": ["대명사", "무엇"], "can": ["조동사", "~할 수 있다"], "users": ["명사", "사용자들", "user"], "learn": ["동사", "배우다"], "about": ["전치사", "~에 대해"], "on": ["전치사", "~에, ~에 관해"], "the": ["관사", "그"], "web": ["명사", "웹"], "site": ["명사", "사이트"]}}], "g": {"the": ["관사", "그"], "lominato": ["고유명사", "로미나토(회사명)"], "company": ["명사", "회사"], "is": ["동사", "~이다", "be"], "one": ["대명사", "하나, 한 사람"], "of": ["전치사", "~의"], "italy's": ["고유명사", "이탈리아의", "Italy"], "oldest": ["형용사", "가장 오래된", "old"], "seed": ["명사", "씨앗, 종자"], "companies": ["명사", "회사들", "company"], "founded": ["과거분사", "설립된", "found"], "by": ["전치사", "~까지, ~에 의해"], "elena": ["고유명사", "엘레나(이름)"], "and": ["접속사", "그리고"], "uberto": ["고유명사", "우베르토(이름)"], "three": ["숫자", "3"], "generations": ["명사", "세대", "generation"], "ago": ["부사", "~전에"], "its": ["한정사", "그것의"], "prized": ["형용사", "소중한"], "seeds": ["명사", "씨앗들", "seed"], "are": ["동사", "~이다", "be"], "developed": ["과거분사", "개발된", "develop"], "packaged": ["과거분사", "포장된", "package"], "according": ["부사", "(according to) ~에 따라"], "to": ["전치사", "~에게, ~으로"], "most": ["부사", "가장"], "rigorous": ["형용사", "엄격한"], "standards": ["명사", "기준들", "standard"], "guarantees": ["동사", "보장하다", "guarantee"], "that": ["접속사", "~라는 것"], "customers": ["명사", "고객들", "customer"], "will": ["조동사", "~할 것이다"], "appreciate": ["동사", "진가를 알다, 만족하다"], "quality": ["형용사", "질 좋은"], "fruits": ["명사", "과일들", "fruit"], "vegetables": ["명사", "채소들", "vegetable"], "produce": ["동사", "생산하다"], "receive": ["동사", "받다"], "a": ["관사", "하나의"], "complete": ["형용사", "완전한"], "refund": ["명사", "환불"], "if": ["접속사", "만약 ~라면"], "purchase": ["명사", "구매품"], "does": ["조동사", "(의문문 조동사)", "do"], "not": ["부사", "~아니다"], "deliver": ["동사", "결과를 내다"], "as": ["접속사", "~대로"], "promised": ["과거분사", "약속된", "promise"], "in": ["전치사", "~에, ~안에"], "addition": ["명사", "(in addition to) ~외에"], "carries": ["동사", "취급하다", "carry"], "variety": ["명사", "(a variety of) 다양한"], "ornamental": ["형용사", "장식용의"], "products": ["명사", "제품들", "product"], "beautify": ["동사", "아름답게 하다"], "any": ["한정사", "어떤"], "outdoor": ["형용사", "야외의"], "landscape": ["명사", "경관, 조경"], "including": ["전치사", "~을 포함하여"], "clay": ["명사", "점토"], "pots": ["명사", "화분들", "pot"], "trellises": ["명사", "격자 울타리", "trellis"], "birdhouses": ["명사", "새집들", "birdhouse"], "decorative": ["형용사", "장식용의"], "statues": ["명사", "조각상들", "statue"], "visit": ["동사", "방문하다"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "shop": ["동사", "쇼핑하다"], "for": ["전치사", "~을 위해, ~동안"], "hundreds": ["명사", "수백", "hundred"], "wonderful": ["형용사", "멋진"], "items": ["명사", "물품들", "item"], "can": ["조동사", "~할 수 있다"], "be": ["동사", "~이다, 있다"], "shipped": ["과거분사", "배송되는", "ship"], "all": ["한정사", "모든"], "over": ["전치사", "(all over) ~곳곳에"], "world": ["명사", "세계"], "also": ["부사", "또한"], "offers": ["동사", "제공하다", "offer"], "number": ["명사", "(a number of) 여러"], "instructional": ["형용사", "교육용의"], "videos": ["명사", "영상들", "video"], "inform": ["동사", "알리다"], "users": ["명사", "사용자들", "user"], "best": ["형용사", "최선의", "good"], "practices": ["명사", "관행, 방법", "practice"], "gardening": ["명사", "원예"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r1-p5',$mkd${"id": "a2-r1-p5", "area": "RC", "part": 5, "group": "A급 과제", "series": 2, "round": 1, "level": "중급", "title": "A급 과제 1회 · PART 5 (문법 1·2회)", "notes": [], "items": [{"no": 101, "q": "Customer surveys show that Brosha Toys’ newest product is too _____.", "options": ["expense", "expensed", "expensive", "expensively"], "answer": 2, "explain": "정답 (C) expensive\n해석: 고객 설문 조사는 Brosha Toys의 최신 제품이 너무 비싸다는 것을 보여 준다.\n정답 근거: 동사가 show와 is 두 개다. 접속사 that(명사절 접속사)이 이미 두 문장을 연결한다. that절 안의 be동사(2형식) 뒤는 형용사 자리다. 부사 too의 수식을 받으므로 형용사 expensive가 정답이다.\n오답 분석: (A) expense: '비용'. 명사여서 too의 수식을 받을 수 없다. / (B) expensed: 동사 과거형·과거분사. 이미 is가 동사라 또 쓸 수 없다. / (D) expensively: '비싸게'. 부사는 be동사 뒤 보어 자리에 올 수 없다.", "translation": "고객 설문 조사는 Brosha Toys의 최신 제품이 너무 비싸다는 것을 보여 준다.", "vocab": "survey 명 설문조사 / expense 명 비용 / expensive 형 비싼 / expensively 부 비싸게", "g": {"customer": ["명사", "고객"], "surveys": ["명사", "설문 조사", "survey"], "show": ["동사", "보여 주다"], "that": ["접속사", "~라는 것(명사절)"], "brosha": ["고유명사", "Brosha(회사명)"], "toys": ["명사", "장난감", "toy"], "newest": ["형용사", "최신의", "new"], "product": ["명사", "제품"], "is": ["동사", "~이다", "be"], "too": ["부사", "너무"]}, "src": "1-"}, {"no": 104, "q": "Mr. Liang’s team _____ needed a little encouragement to improve its sales results.", "options": ["simplification", "simple", "simplify", "simply"], "answer": 3, "explain": "정답 (D) simply\n해석: Liang 씨의 팀은 그저 판매 실적을 개선할 약간의 격려가 필요했을 뿐이다.\n정답 근거: 주어 team과 동사 needed 사이 빈칸이다. needed 뒤에 목적어 encouragement가 이미 있어 완전한 문장이므로 빈칸은 부사 자리다.\n오답 분석: (A) simplification: '단순화'. 명사는 주어와 동사 사이에 들어갈 수 없다. / (B) simple: '단순한'. 형용사가 꾸밀 명사가 뒤에 없다. / (C) simplify: '단순화하다'. 동사 needed가 이미 있어 동사를 또 쓸 수 없다.", "translation": "Liang 씨의 팀은 그저 판매 실적을 개선할 약간의 격려가 필요했을 뿐이다.", "vocab": "encouragement 명 격려 / improve 동 개선하다 / simply 부 그저, 단순히 / simplification 명 단순화", "g": {"mr": ["명사", "~씨(남성)"], "liang’s": ["고유명사", "Liang 씨의"], "team": ["명사", "팀"], "needed": ["동사", "필요로 했다", "need"], "a": ["관사", "하나의"], "little": ["형용사", "약간의"], "encouragement": ["명사", "격려"], "to": ["to부정사", "~할, ~하기 위한"], "improve": ["동사", "개선하다"], "its": ["대명사", "그것의"], "sales": ["명사", "판매"], "results": ["명사", "결과, 실적", "result"]}, "src": "1-"}, {"no": 106, "q": "The online form asks _____ how they prefer to receive information from the town.", "options": ["residents", "residence", "reside", "residential"], "answer": 0, "explain": "정답 (A) residents\n해석: 그 온라인 양식은 주민들에게 마을로부터 정보를 어떻게 받고 싶은지 묻는다.\n정답 근거: 타동사 asks 뒤 목적어(명사) 자리다. 뒤의 how는 명사절 접속사(의문사)로 두 번째 목적어를 이끌고, 대명사 they로 다시 받으므로 사람을 뜻하는 복수 명사 residents가 정답이다.\n오답 분석: (B) residence: '거주지'. 사물 명사여서 they로 받을 수 없다. / (C) reside: '거주하다'. 동사 asks가 이미 있어 동사 자리가 아니다. / (D) residential: '주거의'. 형용사가 꾸밀 명사가 없다.", "translation": "그 온라인 양식은 주민들에게 마을로부터 정보를 어떻게 받고 싶은지 묻는다.", "vocab": "resident 명 주민 / residence 명 거주지 / reside 동 거주하다 / prefer 동 선호하다", "g": {"the": ["관사", "그"], "online": ["형용사", "온라인의"], "form": ["명사", "양식"], "asks": ["동사", "묻다", "ask"], "how": ["부사", "어떻게"], "they": ["대명사", "그들"], "prefer": ["동사", "선호하다"], "to": ["to부정사", "~하는 것"], "receive": ["동사", "받다"], "information": ["명사", "정보"], "from": ["전치사", "~로부터"], "town": ["명사", "마을, 시"]}, "src": "1-"}, {"no": 108, "q": "When inspecting the work site, be sure to wear _____ most comfortable shoes.", "options": ["you", "yourself", "your", "yours"], "answer": 2, "explain": "정답 (C) your\n해석: 작업 현장을 점검할 때는 반드시 가장 편한 신발을 신으십시오.\n정답 근거: 빈칸 뒤에 형용사 most comfortable과 명사 shoes가 이어진다. 명사 앞자리는 소유격이 들어가는 자리이므로 your가 정답이다.\n오답 분석: (A) you: 주격·목적격 대명사. 명사 앞에서 명사를 꾸밀 수 없다. / (B) yourself: 재귀대명사. 명사를 꾸미는 기능이 없다. / (D) yours: 소유대명사. 그 자체가 명사 역할이라 뒤에 명사가 또 올 수 없다.", "translation": "작업 현장을 점검할 때는 반드시 가장 편한 신발을 신으십시오.", "vocab": "inspect 동 점검하다 / work site 명 작업 현장 / comfortable 형 편안한 / your 소유격 너의", "g": {"when": ["접속사", "~할 때"], "inspecting": ["현재분사", "점검하는", "inspect"], "the": ["관사", "그"], "work": ["명사", "작업, 업무"], "site": ["명사", "현장"], "be": ["동사", "~이다, 되다"], "sure": ["형용사", "확실한"], "to": ["to부정사", "(be sure to) 반드시 ~하다"], "wear": ["동사", "입다, 신다"], "most": ["부사", "가장"], "comfortable": ["형용사", "편안한"], "shoes": ["명사", "신발", "shoe"]}, "src": "1-"}, {"no": 110, "q": "Truck drivers for Kelton Co. are _____ for their fuels on a monthly basis.", "options": ["reimbursement", "reimbursing", "reimbursable", "reimbursed"], "answer": 3, "explain": "정답 (D) reimbursed\n해석: Kelton 사의 트럭 운전기사들은 매달 연료비를 환급받는다.\n정답 근거: reimburse는 타동사인데 빈칸 뒤에 목적어(명사)가 없고 전치사구 for their fuels만 있으므로 수동태 be p.p.가 정답이다. 주어인 운전기사가 환급을 받는 대상이다.\n오답 분석: (A) reimbursement: '환급'. 명사를 쓰면 '운전기사=환급'이 되어 뜻이 성립하지 않는다. / (B) reimbursing: 능동 진행형. 능동이면 뒤에 환급해 주는 대상(목적어)이 있어야 하는데 없다. / (C) reimbursable: '환급(교환) 가능한'. 주어가 상환·교환되는 물건이라는 뜻이 되는데, 사람인 운전기사는 교환 대상이 될 수 없어 부적절하다.", "translation": "Kelton 사의 트럭 운전기사들은 매달 연료비를 환급받는다.", "vocab": "reimburse 동 환급하다 / reimbursement 명 환급 / fuel 명 연료 / on a monthly basis 구 매 달", "g": {"truck": ["명사", "트럭"], "drivers": ["명사", "운전기사", "driver"], "for": ["전치사", "~을 위해, ~에 대해"], "kelton": ["고유명사", "Kelton(회사명)"], "co": ["명사", "회사(Co.)"], "are": ["동사", "~이다", "be"], "their": ["대명사", "그들의"], "fuels": ["명사", "연료(비)", "fuel"], "on": ["전치사", "~에, ~로"], "a": ["관사", "하나의"], "monthly": ["형용사", "매달의"], "basis": ["명사", "기준, 단위"]}, "src": "1-"}, {"no": 112, "q": "Boiton employees are encouraged to use Schoolroad Street _____ dust and noise from the construction.", "options": ["avoid", "to avoid", "avoided", "avoiding"], "answer": 1, "explain": "정답 (B) to avoid\n해석: Boiton 직원들은 공사로 인한 먼지와 소음을 피하기 위해 Schoolroad 가를 이용하도록 권장된다.\n정답 근거: 문장에 동사 are encouraged가 이미 있고 접속사가 없으므로 빈칸은 동사가 될 수 없다. 뒤에 목적어 dust and noise가 있으므로 목적을 나타내는 to부정사(타동사에서 온 to부정사 + 명사)가 정답이다.\n오답 분석: (A) avoid: 동사원형. 접속사 없이 동사를 두 개 쓸 수 없다. / (C) avoided: 과거분사. 뒤에 목적어가 있으므로 수동 형태는 불가하다. / (D) avoiding: 분사·동명사. 접속사·전치사 없이 연결되지 않아 목적의 뜻을 나타내지 못한다.", "translation": "Boiton 직원들은 공사로 인한 먼지와 소음을 피하기 위해 Schoolroad 가를 이용하도록 권장된다.", "vocab": "be encouraged to 구 ~하 도록 권장되다 / avoid 동 피하다 / dust 명 먼지 / construction 명 공사", "g": {"boiton": ["고유명사", "Boiton(회사명)"], "employees": ["명사", "직원들", "employee"], "are": ["동사", "~이다", "be"], "encouraged": ["과거분사", "권장되는", "encourage"], "to": ["to부정사", "~하도록"], "use": ["동사", "이용하다"], "schoolroad": ["고유명사", "Schoolroad(지명)"], "street": ["명사", "거리"], "dust": ["명사", "먼지"], "and": ["접속사", "그리고"], "noise": ["명사", "소음"], "from": ["전치사", "~로부터"], "the": ["관사", "그"], "construction": ["명사", "공사"]}, "src": "1-"}, {"no": 113, "q": "Ms. Pawack assured the managers that she would deliver the contract _____ after work.", "options": ["themselves", "myself", "herself", "ourselves"], "answer": 2, "explain": "정답 (C) herself\n해석: Pawack 씨는 퇴근 후 자신이 직접 계약서를 전달하겠다고 관리자들에게 장담했다.\n정답 근거: that절이 she would deliver the contract로 이미 완전한 문장이므로 빈칸은 강조 용법의 재귀대명사 자리다. 주어가 she이므로 herself가 정답이다.\n오답 분석: (A) themselves: 복수 주어를 받는 재귀대명사라 she와 맞지 않는다. / (B) myself: 1인칭 주어를 받는 재귀대명사라 she와 맞지 않는다. / (D) ourselves: 1인칭 복수 재귀대명사라 she와 맞지 않는다.", "translation": "Pawack 씨는 퇴근 후 자신이 직접 계약서를 전달하겠다고 관리자들에게 장담했다.", "vocab": "assure 동 장담하다, 확언하 다 / deliver 동 전달하다 / contract 명 계약서 / herself 재귀대명사 직접, 스 스로", "g": {"ms": ["명사", "~씨(여성)"], "pawack": ["고유명사", "Pawack(인명)"], "assured": ["동사", "장담했다", "assure"], "the": ["관사", "그"], "managers": ["명사", "관리자들", "manager"], "that": ["접속사", "~라는 것(명사절)"], "she": ["대명사", "그녀"], "would": ["조동사", "~할 것이다", "will"], "deliver": ["동사", "전달하다"], "contract": ["명사", "계약서"], "after": ["전치사", "~ 후에"], "work": ["명사", "작업, 업무"]}, "src": "1-"}, {"no": 117, "q": "Marco Villar has stated that _____ is the most important attribute for an advertising professional to possess.", "options": ["creativity", "create", "creative", "created"], "answer": 0, "explain": "정답 (A) creativity\n해석: Marco Villar는 창의성이 광고 전문가가 갖춰야 할 가장 중요한 자질이라고 말했다.\n정답 근거: 명사절 접속사 that 뒤에는 주어와 동사가 와야 한다. 빈칸 뒤가 동사 is이므로 빈칸은 주어(명사) 자리이고 creativity가 정답이다.\n오답 분석: (B) create: '창조하다'. 동사는 주어 자리에 올 수 없다. / (C) creative: '창의적인'. 형용사가 꾸밀 명사가 없다. / (D) created: 과거분사. 주어 자리에 들어갈 수 없다.", "translation": "Marco Villar는 창의성이 광고 전문가가 갖춰야 할 가장 중요한 자질이라고 말했다.", "vocab": "state 동 말하다, 언급하다 / attribute 명 자질, 속성 / possess 동 지니다 / creativity 명 창의성", "g": {"marco": ["고유명사", "Marco(인명)"], "villar": ["고유명사", "Villar(인명)"], "has": ["조동사", "(완료) ~했다", "have"], "stated": ["과거분사", "말했다", "state"], "that": ["접속사", "~라는 것(명사절)"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "most": ["부사", "가장"], "important": ["형용사", "중요한"], "attribute": ["명사", "자질, 속성"], "for": ["전치사", "~을 위해, ~에 대해"], "an": ["관사", "하나의"], "advertising": ["명사", "광고"], "professional": ["명사", "전문가"], "to": ["to부정사", "~할"], "possess": ["동사", "지니다"]}, "src": "1-"}, {"no": 120, "q": "Martine Caterers has party packages to meet all customers' _____ needs.", "options": ["entertaining", "entertained", "entertains", "entertain"], "answer": 0, "explain": "정답 (A) entertaining\n해석: Martine Caterers는 모든 고객의 오락 관련 요구를 충족하는 파티 패키지를 갖추고 있다.\n정답 근거: 소유격 customers' 뒤, 명사 needs 앞이므로 형용사 자리다. entertain은 감정동사이고 꾸며 주는 대상이 needs라는 사물이므로 -ing 형태인 entertaining이 정답이다.\n오답 분석: (B) entertained: 감정동사의 -ed형은 사람을 꾸밀 때 쓴다. 사물인 needs를 꾸밀 수 없다. / (C) entertains: 동사. 이미 has가 동사이고 명사 앞은 동사 자리가 아니다. / (D) entertain: 동사원형. 명사를 꾸밀 수 없다.", "translation": "Martine Caterers는 모든 고객의 오락 관련 요구를 충족하는 파티 패키지를 갖추고 있다.", "vocab": "meet needs 구 요구를 충족 시키다 / entertaining 형 즐거움을 주는 / caterer 명 출장 요리 업체", "g": {"martine": ["고유명사", "Martine(회사명)"], "caterers": ["명사", "출장 요리 업체", "caterer"], "has": ["동사", "가지고 있다", "have"], "party": ["명사", "파티"], "packages": ["명사", "패키지 상품", "package"], "to": ["to부정사", "~할, ~하기 위한"], "meet": ["동사", "충족시키다"], "all": ["한정사", "모든"], "customers'": ["명사", "고객들의", "customer"], "needs": ["명사", "요구", "need"]}, "src": "1-"}, {"no": 121, "q": "A reception will be held to honor all _____ contributed to a record-breaking quarter.", "options": ["who", "them", "what", "these"], "answer": 0, "explain": "정답 (A) who\n해석: 기록적인 분기에 기여한 모든 사람들을 기리기 위해 축하연이 열릴 것이다.\n정답 근거: 동사가 will be held와 contributed 두 개이므로 접속사가 필요하다. 사람을 뜻하는 all을 선행사로 받아 뒤 문장의 주어 역할까지 하는 주격 관계대명사 who가 정답이다.\n오답 분석: (B) them: 목적격 대명사. 접속사 기능이 없어 동사 두 개를 연결하지 못한다. / (C) what: 명사절 접속사로 선행사를 받을 수 없다. / (D) these: 지시대명사. 접속사 기능이 없다.", "translation": "기록적인 분기에 기여한 모든 사람들을 기리기 위해 축하연이 열릴 것이다.", "vocab": "reception 명 축하연, 리셉션 / honor 동 기리다, 예우하다 / contribute to 구 ~에 기여 하다 / record-breaking 형 기록적 인", "g": {"a": ["관사", "하나의"], "reception": ["명사", "축하연"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "held": ["과거분사", "열린", "hold"], "to": ["to부정사", "~하기 위해 / ~에"], "honor": ["동사", "기리다"], "all": ["대명사", "모든 사람"], "contributed": ["동사", "기여했다", "contribute"], "record-breaking": ["형용사", "기록적인"], "quarter": ["명사", "분기"]}, "src": "1-"}, {"no": 125, "q": "This is not an _____ list, but here are a few ways that volunteers can get involved at the Banjul Teaching Hospital.", "options": ["exhausts", "exhaustion", "exhaustive", "exhausted"], "answer": 2, "explain": "정답 (C) exhaustive\n해석: 이것이 전부를 망라한 목록은 아니지만, 자원봉사자들이 Banjul 교육 병원에서 참여할 수 있는 몇 가지 방법이 여기 있다.\n정답 근거: 관사 an과 명사 list 사이이므로 형용사 자리다. 목록의 성격을 설명하는 exhaustive(총망라한)가 문맥에 맞다.\n오답 분석: (A) exhausts: 동사. 명사를 꾸밀 수 없다. / (B) exhaustion: '탈진'. 명사가 연달아 와 뜻이 성립하지 않는다. / (D) exhausted: '지친'. 감정동사의 -ed형이라 사람을 꾸미며, 사물인 list와 어울리지 않는다.", "translation": "이것이 전부를 망라한 목록은 아니지만, 자원봉사자들이 Banjul 교육 병원에서 참여할 수 있는 몇 가지 방법이 여기 있다.", "vocab": "exhaustive 형 총망라한, 철 저한 / exhausted 형 지친 / volunteer 명 자원봉사자 / get involved 구 참여하다", "g": {"this": ["대명사", "이것"], "is": ["동사", "~이다", "be"], "not": ["부사", "~이 아닌"], "an": ["관사", "하나의"], "list": ["명사", "목록"], "but": ["접속사", "그러나"], "here": ["부사", "여기에"], "are": ["동사", "~이다", "be"], "a": ["관사", "하나의"], "few": ["형용사", "몇몇의"], "ways": ["명사", "방법", "way"], "that": ["관계사", "~하는 (방법)"], "volunteers": ["명사", "자원봉사자", "volunteer"], "can": ["조동사", "~할 수 있다"], "get": ["동사", "되다"], "involved": ["과거분사", "참여한", "involve"], "at": ["전치사", "~에서"], "the": ["관사", "그"], "banjul": ["고유명사", "Banjul(지명)"], "teaching": ["형용사", "교육의"], "hospital": ["명사", "병원"]}, "src": "1-"}, {"no": 126, "q": "By May, dairy farms in Shea County produced _____ as much milk as they had produced by August of the previous year.", "options": ["nearly", "nears", "nearest", "nearing"], "answer": 0, "explain": "정답 (A) nearly\n해석: 5월까지 Shea 카운티의 낙농장들은 전년 8월까지 생산했던 것과 거의 같은 양의 우유를 생산했다.\n정답 근거: produced 뒤에 as much milk as라는 비교 구문이 완전하게 이어지므로 빈칸은 비교 표현을 꾸미는 부사 자리다.\n오답 분석: (B) nears: 동사. produced가 이미 동사라 또 쓸 수 없다. / (C) nearest: 최상급 형용사. as ~ as 구문과 함께 쓸 수 없다. / (D) nearing: 분사. 비교 구문을 수식하는 기능이 없다.\n정답 한눈에 보기", "translation": "5월까지 Shea 카운티의 낙농장들은 전년 8월까지 생산했던 것과 거의 같은 양의 우유를 생산했다.", "vocab": "dairy farm 명 낙농장 / produce 동 생산하다 / nearly 부 거의 / previous 형 이전의", "g": {"by": ["전치사", "~까지, ~에 의해"], "may": ["명사", "5월"], "dairy": ["형용사", "낙농의"], "farms": ["명사", "농장", "farm"], "in": ["전치사", "~에, ~에서"], "shea": ["고유명사", "Shea(지명)"], "county": ["명사", "카운티, 군"], "produced": ["동사", "생산했다", "produce"], "as": ["부사", "~만큼"], "much": ["형용사", "많은"], "milk": ["명사", "우유"], "they": ["대명사", "그들"], "had": ["조동사", "(과거완료) ~했었다", "have"], "august": ["명사", "8월"], "of": ["전치사", "~의"], "the": ["관사", "그"], "previous": ["형용사", "이전의"], "year": ["명사", "해, 연도"]}, "src": "1-"}, {"no": 101, "q": "BEI refrigeration units are _____ engineered to conserve energy.", "options": ["science", "sciences", "scientific", "scientifically"], "answer": 3, "explain": "정답 (D) scientifically\n해석: BEI 냉장 장치는 에너지를 절약하도록 과학적으로 설계되어 있다.\n정답 근거: are와 과거분사 engineered 사이의 빈칸이다. 수동태 be p.p. 사이는 동사를 꾸미는 부사 자리이므로 scientifically가 정답이다.\n오답 분석: (A) science: '과학'. 명사는 be동사와 분사 사이에 들어갈 수 없다. / (B) sciences: 복수 명사도 같은 이유로 불가하다. / (C) scientific: '과학적인'. 형용사가 꾸밀 명사가 없다.", "translation": "BEI 냉장 장치는 에너지를 절약하도록 과학적으로 설계되어 있다.", "sub": "문법 2회", "vocab": "refrigeration 명 냉장, 냉동 / engineer 동 설계하다 / conserve 동 절약하다 / scientifically 부 과학적으로", "g": {"bei": ["고유명사", "BEI(회사명)"], "refrigeration": ["명사", "냉장"], "units": ["명사", "장치", "unit"], "are": ["동사", "~이다", "be"], "engineered": ["과거분사", "설계된", "engineer"], "to": ["to부정사", "~하도록"], "conserve": ["동사", "절약하다"], "energy": ["명사", "에너지"]}, "src": "2-"}, {"no": 103, "q": "The Bonview Times newspaper has quite a wide _____ for such a small operation.", "options": ["distributed", "distribution", "distributing", "distribute"], "answer": 1, "explain": "정답 (B) distribution\n해석: Bonview Times 신문은 그렇게 작은 규모의 사업체치고는 상당히 넓은 배포망을 갖고 있다.\n정답 근거: 타동사 has 뒤 목적어 자리다. 관사 a와 형용사 wide의 수식을 받으므로 명사 distribution이 정답이다.\n오답 분석: (A) distributed: 과거분사. 관사 뒤 명사 자리에 올 수 없다. / (C) distributing: 분사. a wide의 수식을 받는 명사 자리가 아니다. / (D) distribute: 동사. has가 이미 동사이므로 불가하다.", "translation": "Bonview Times 신문은 그렇게 작은 규모의 사업체치고는 상당히 넓은 배포망을 갖고 있다.", "sub": "문법 2회", "vocab": "distribution 명 배포, 보급 / operation 명 사업체, 운영 / quite 부 꽤, 상당히", "g": {"the": ["관사", "그"], "bonview": ["고유명사", "Bonview(신문명)"], "times": ["고유명사", "Times(신문명)"], "newspaper": ["명사", "신문"], "has": ["동사", "가지고 있다", "have"], "quite": ["부사", "꽤"], "a": ["관사", "하나의"], "wide": ["형용사", "넓은"], "for": ["전치사", "~을 위해, ~에 대해"], "such": ["한정사", "그렇게, 그런"], "small": ["형용사", "작은"], "operation": ["명사", "사업체, 운영"]}, "src": "2-"}, {"no": 104, "q": "Please contact Ms. Steiner and Mr. Rao, and ask if _____ are available next Wednesday for interviews.", "options": ["they", "them", "their", "themselves"], "answer": 0, "explain": "정답 (A) they\n해석: Steiner 씨와 Rao 씨에게 연락해서 다음 주 수요일 면접이 가능한지 물어보십시오.\n정답 근거: 명사절 접속사 if 뒤에는 주어와 동사가 와야 한다. 빈칸 뒤가 동사 are이므로 주격 대명사 they가 정답이다.\n오답 분석: (B) them: 목적격이라 주어 자리에 올 수 없다. / (C) their: 소유격이라 뒤에 명사가 있어야 한다. / (D) themselves: 재귀대명사는 주어 자리에 단독으로 올 수 없다.", "translation": "Steiner 씨와 Rao 씨에게 연락해서 다음 주 수요일 면접이 가능한지 물어보십시오.", "sub": "문법 2회", "vocab": "contact 동 연락하다 / available 형 시간이 되는 / they 주격 대명사 그들이", "g": {"please": ["부사", "부디, ~해 주세요"], "contact": ["동사", "연락하다"], "ms": ["명사", "~씨(여성)"], "steiner": ["고유명사", "Steiner(인명)"], "and": ["접속사", "그리고"], "mr": ["명사", "~씨(남성)"], "rao": ["고유명사", "Rao(인명)"], "ask": ["동사", "묻다"], "if": ["접속사", "~인지"], "are": ["동사", "~이다", "be"], "available": ["형용사", "시간이 되는"], "next": ["형용사", "다음의"], "wednesday": ["명사", "수요일"], "for": ["전치사", "~을 위해, ~에 대해"], "interviews": ["명사", "면접", "interview"]}, "src": "2-"}, {"no": 106, "q": "All client _____, no matter how small, are always handled with the utmost respect.", "options": ["concerns", "concerning", "concerned", "concern"], "answer": 0, "explain": "정답 (A) concerns\n해석: 아무리 사소하더라도 모든 고객 문의 사항은 항상 최대한의 존중으로 처리된다.\n정답 근거: 동사 are의 주어가 되는 명사 자리다. All의 수식을 받고 동사가 복수형 are이므로 복수 명사 concerns가 정답이다.\n오답 분석: (B) concerning: 분사·전치사. 주어 자리에 올 수 없다. / (C) concerned: 과거분사. 주어가 되는 명사가 아니다. / (D) concern: 단수 명사라 복수 동사 are와 수가 맞지 않는다.", "translation": "아무리 사소하더라도 모든 고객 문의 사항은 항상 최대한의 존중으로 처리된다.", "sub": "문법 2회", "vocab": "concern 명 우려 사항 / no matter how 구 아무리 ~ 해도 / handle 동 처리하다 / utmost 형 최대의", "g": {"all": ["한정사", "모든"], "client": ["명사", "고객"], "no": ["한정사", "어떤 ~도 아닌"], "matter": ["명사", "(no matter) 아무리 ~해도"], "how": ["부사", "어떻게"], "small": ["형용사", "작은"], "are": ["동사", "~이다", "be"], "always": ["부사", "항상"], "handled": ["과거분사", "처리되는", "handle"], "with": ["전치사", "~와 함께, ~로"], "the": ["관사", "그"], "utmost": ["형용사", "최대의"], "respect": ["명사", "존중"]}, "src": "2-"}, {"no": 108, "q": "Ms. Koh's tax guide should prove _____ to clients who are unsure about the new rules.", "options": ["instructive", "instructively", "instructions", "instructed"], "answer": 0, "explain": "정답 (A) instructive\n해석: Koh 씨의 세금 안내서는 새 규정을 잘 모르는 고객들에게 유익할 것이다.\n정답 근거: prove는 2형식 동사로 뒤에 보어인 형용사가 온다. 따라서 형용사 instructive가 정답이다.\n오답 분석: (B) instructively: 부사는 2형식 보어 자리에 올 수 없다. / (C) instructions: 명사를 쓰면 '안내서=지시들'이라는 어색한 뜻이 된다. / (D) instructed: 과거분사. 대상이 되는 사람이 없어 부적절하다.", "translation": "Koh 씨의 세금 안내서는 새 규정을 잘 모르는 고객들에게 유익할 것이다.", "sub": "문법 2회", "vocab": "prove 동 판명되다, 드러나다 / instructive 형 유익한 / unsure 형 확신이 없는", "g": {"ms": ["명사", "~씨(여성)"], "koh's": ["고유명사", "Koh 씨의"], "tax": ["명사", "세금"], "guide": ["명사", "안내서"], "should": ["조동사", "~할 것이다"], "prove": ["동사", "판명되다"], "to": ["전치사", "~에게"], "clients": ["명사", "고객들", "client"], "who": ["관계사", "~하는 (사람)"], "are": ["동사", "~이다", "be"], "unsure": ["형용사", "확신이 없는"], "about": ["전치사", "~에 관해"], "the": ["관사", "그"], "new": ["형용사", "새로운"], "rules": ["명사", "규정", "rule"]}, "src": "2-"}, {"no": 110, "q": "The management structure at the Oramo Company effectively supports _____.", "options": ["innovative", "innovatively", "innovation", "innovates"], "answer": 2, "explain": "정답 (C) innovation\n해석: Oramo 사의 관리 구조는 혁신을 효과적으로 뒷받침한다.\n정답 근거: supports는 타동사인데 뒤에 목적어가 없으므로 빈칸은 목적어(명사) 자리다. 따라서 innovation이 정답이다.\n오답 분석: (A) innovative: '혁신적인'. 형용사가 꾸밀 명사가 없다. / (B) innovatively: 부사는 타동사의 목적어가 될 수 없다. / (D) innovates: 동사. supports가 이미 동사라 불가하다.", "translation": "Oramo 사의 관리 구조는 혁신을 효과적으로 뒷받침한다.", "sub": "문법 2회", "vocab": "structure 명 구조 / effectively 부 효과적으로 / support 동 지원하다 / innovation 명 혁신", "g": {"the": ["관사", "그"], "management": ["명사", "관리, 경영"], "structure": ["명사", "구조"], "at": ["전치사", "~에서"], "oramo": ["고유명사", "Oramo(회사명)"], "company": ["명사", "회사"], "effectively": ["부사", "효과적으로"], "supports": ["동사", "뒷받침하다", "support"]}, "src": "2-"}, {"no": 112, "q": "Dai Takoma's presentation is _____ too long now, given the revisions to the conference schedule.", "options": ["certainty", "certain", "certainly", "certainties"], "answer": 2, "explain": "정답 (C) certainly\n해석: 회의 일정 변경을 고려하면 Dai Takoma의 발표는 지금 확실히 너무 길다.\n정답 근거: be동사 뒤 보어인 too long(부사+형용사)이 이미 갖춰져 있으므로 빈칸은 그것을 꾸미는 부사 자리다.\n오답 분석: (A) certainty: '확실성'. 명사는 형용사 too long을 꾸밀 수 없다. / (B) certain: '확실한'. 형용사가 형용사를 꾸밀 수 없다. / (D) certainties: 복수 명사도 같은 이유로 불가하다.", "translation": "회의 일정 변경을 고려하면 Dai Takoma의 발표는 지금 확실히 너무 길다.", "sub": "문법 2회", "vocab": "certainly 부 확실히 / given 전 ~을 고려하면 / revision 명 수정, 변경", "g": {"dai": ["고유명사", "Dai(인명)"], "takoma's": ["고유명사", "Takoma의"], "presentation": ["명사", "발표"], "is": ["동사", "~이다", "be"], "too": ["부사", "너무"], "long": ["형용사", "긴"], "now": ["부사", "지금"], "given": ["전치사", "~을 고려하면"], "the": ["관사", "그"], "revisions": ["명사", "수정, 변경", "revision"], "to": ["전치사", "~에 대한"], "conference": ["명사", "회의"], "schedule": ["명사", "일정"]}, "src": "2-"}, {"no": 114, "q": "Climate was a _____ consideration when Sordahl Properties sought a new location for its next hotel.", "options": ["largest", "largely", "large", "largeness"], "answer": 2, "explain": "정답 (C) large\n해석: Sordahl Properties가 다음 호텔의 새 부지를 찾을 때 기후는 큰 고려 사항이었다.\n정답 근거: 관사 a와 명사 consideration 사이이므로 형용사 자리다. 따라서 large가 정답이다.\n오답 분석: (A) largest: 최상급은 the와 함께 써야 하므로 a와 어울리지 않는다. / (B) largely: 부사는 명사를 꾸밀 수 없다. / (D) largeness: 명사가 연달아 와 뜻이 성립하지 않는다.", "translation": "Sordahl Properties가 다음 호텔의 새 부지를 찾을 때 기후는 큰 고려 사항이었다.", "sub": "문법 2회", "vocab": "consideration 명 고려 사항 / seek – sought 동 찾다, 모색 하다 / large 형 큰, 중요한", "g": {"climate": ["명사", "기후"], "was": ["동사", "~였다", "be"], "a": ["관사", "하나의"], "consideration": ["명사", "고려 사항"], "when": ["접속사", "~할 때"], "sordahl": ["고유명사", "Sordahl(회사명)"], "properties": ["고유명사", "Properties(회사명)"], "sought": ["동사", "찾았다", "seek"], "new": ["형용사", "새로운"], "location": ["명사", "장소, 부지"], "for": ["전치사", "~을 위해, ~에 대해"], "its": ["대명사", "그것의"], "next": ["형용사", "다음의"], "hotel": ["명사", "호텔"]}, "src": "2-"}, {"no": 117, "q": "Roundhouse Construction workers are expected to comply with all applicable state _____ while working on-site.", "options": ["regulations", "regulated", "regulates", "regulator"], "answer": 0, "explain": "정답 (A) regulations\n해석: Roundhouse Construction 직원들은 현장에서 근무하는 동안 적용 가능한 모든 주 규정을 준수해야 한다.\n정답 근거: 전치사 with의 목적어인 명사 자리다. all의 수식을 받고 앞에 a/an/the가 없으므로 복수 명사 regulations가 정답이다.\n오답 분석: (B) regulated: 과거분사. 전치사의 목적어가 될 수 없다. / (C) regulates: 동사. 명사 자리에 올 수 없다. / (D) regulator: '규제 기관'. 사람·기관을 뜻해 준수 대상과 어울리지 않고 단수라 all과도 맞지 않는다.", "translation": "Roundhouse Construction 직원들은 현장에서 근무하는 동안 적용 가능한 모든 주 규정을 준수해야 한다.", "sub": "문법 2회", "vocab": "comply with 구 ~을 준수하 다 / applicable 형 해당되는 / regulation 명 규정 / on-site 부 현장에서", "g": {"roundhouse": ["고유명사", "Roundhouse(회사명)"], "construction": ["고유명사", "Construction(회사명)"], "workers": ["명사", "직원들", "worker"], "are": ["동사", "~이다", "be"], "expected": ["과거분사", "요구되는, 예상되는", "expect"], "to": ["to부정사", "~하도록"], "comply": ["동사", "준수하다"], "with": ["전치사", "~와 함께, ~로"], "all": ["한정사", "모든"], "applicable": ["형용사", "적용 가능한"], "state": ["형용사", "주(州)의"], "while": ["접속사", "~하는 동안"], "working": ["현재분사", "일하는", "work"], "on-site": ["부사", "현장에서"]}, "src": "2-"}, {"no": 126, "q": "The new assembly-line machinery _____ with the safety of users in mind.", "options": ["to design", "has designed", "will design", "was designed"], "answer": 3, "explain": "정답 (D) was designed\n해석: 새 조립 라인 기계는 사용자의 안전을 염두에 두고 설계되었다.\n정답 근거: design은 타동사인데 빈칸 뒤에 목적어(명사)가 없고 전치사구 with ~만 있으므로 수동태가 정답이다.\n오답 분석: (A) to design: to부정사는 문장의 동사가 될 수 없다. / (B) has designed: 능동태라 뒤에 목적어가 있어야 한다. / (C) will design: 능동태라 목적어가 필요하다.", "translation": "새 조립 라인 기계는 사용자의 안전을 염두에 두고 설계되었다.", "sub": "문법 2회", "vocab": "assembly-line 명 조립 라인 / machinery 명 기계(류) / with A in mind 구 A를 염두 에 두고 / design 동 설계하다", "g": {"the": ["관사", "그"], "new": ["형용사", "새로운"], "assembly-line": ["명사", "조립 라인"], "machinery": ["명사", "기계류"], "with": ["전치사", "~와 함께, ~로"], "safety": ["명사", "안전"], "of": ["전치사", "~의"], "users": ["명사", "사용자", "user"], "in": ["전치사", "~에, ~에서"], "mind": ["명사", "마음, 염두"]}, "src": "2-"}, {"no": 130, "q": "The medical staff is reminded _____ health matters with patients in private.", "options": ["can address", "having addressed", "to address", "addressing"], "answer": 2, "explain": "정답 (C) to address\n해석: 의료진은 환자와의 건강 문제를 비공개로 이야기하도록 상기된다.\n정답 근거: remind는 「remind + 목적어 + to부정사」 구조이고 이를 수동태로 바꾸면 be reminded to do가 된다. 따라서 to부정사가 정답이다.\n오답 분석: (A) can address: 조동사+동사원형은 is reminded 뒤에 접속사 없이 이어질 수 없다. / (B) having addressed: 완료분사는 be reminded와 연결되지 않는다. / (D) addressing: 분사·동명사는 be reminded 뒤 구조에 맞지 않는다.", "translation": "의료진은 환자와의 건강 문제를 비공개로 이야기하도록 상기된다.", "sub": "문법 2회", "vocab": "be reminded to do 구 ~하 도록 상기되다 / address 동 다루다, 논의하다 / matter 명 문제, 사안 / in private 구 개별적으로, 사 적으로", "g": {"the": ["관사", "그"], "medical": ["형용사", "의료의"], "staff": ["명사", "직원"], "is": ["동사", "~이다", "be"], "reminded": ["과거분사", "상기되는", "remind"], "health": ["명사", "건강"], "matters": ["명사", "문제, 사안", "matter"], "with": ["전치사", "~와 함께, ~로"], "patients": ["명사", "환자", "patient"], "in": ["전치사", "~에, ~에서"], "private": ["형용사", "사적인, 비공개의"]}, "src": "2-"}], "sets": []}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r1-p6',$mkd${"id": "a2-r1-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 2, "round": 1, "level": "중급", "title": "A급 과제 1회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "www.scitechexpo.ca/registration\nGroup Registration\nGroups of ten or more ---131--- 15 percent off the regular registration price. All ---132--- in the group must be from the same business or organization and register together. To take advantage of this discount, visit the Group Registration page at scitechexpo.ca/group. Group leaders will be instructed to provide ---133--- registrant's name, e-mail address, and job title. ---134---. For more information, please call Sandeep Desale at 416-555-0146.", "tr": "www.scitechexpo.ca/registration\n단체 등록\n10인 이상 단체는 정규 등록 요금에서 15%를 할인받습니다 (131). 단체의 모든 개인 (132)은 같은 회사나 단체 소속이어야 하며 함께 등록해야 합니다. 이 할인을 이용하시려면 scitechexpo.ca/group의 단체 등록 페이지를 방문하십시오. 단체 대표자는 각 (133) 등록자의 이름, 이메일 주소, 직책을 제공하라는 안내를 받게 됩니다. 등록 마감일은 5월 1일입니다 (134). 더 자세한 정보는 Sandeep Desale에게 416-555-0146으로 전화하십시오.", "g": {"www.scitechexpo.ca/registration": ["고유명사", "웹 주소"], "group": ["명사", "단체"], "registration": ["명사", "등록"], "groups": ["명사", "단체들", "group"], "of": ["전치사", "~의"], "ten": ["숫자", "10"], "or": ["접속사", "또는"], "more": ["형용사", "더 많은"], "15": ["숫자", "15"], "percent": ["명사", "퍼센트"], "off": ["부사", "할인되어"], "the": ["관사", "그"], "regular": ["형용사", "정규의"], "price": ["명사", "가격"], "all": ["한정사", "모든"], "in": ["전치사", "~에, ~에서"], "must": ["조동사", "~해야 한다"], "be": ["동사", "~이다, 되다"], "from": ["전치사", "~로부터"], "same": ["형용사", "같은"], "business": ["명사", "회사, 사업"], "organization": ["명사", "단체"], "and": ["접속사", "그리고"], "register": ["동사", "등록하다"], "together": ["부사", "함께"], "to": ["전치사", "~로, ~에게 / ~하기 위해"], "take": ["동사", "취하다"], "advantage": ["명사", "이점"], "this": ["한정사", "이"], "discount": ["명사", "할인"], "visit": ["동사", "방문하다"], "page": ["명사", "페이지"], "at": ["전치사", "~에서"], "scitechexpo.ca/group": ["고유명사", "웹 주소"], "leaders": ["명사", "대표자", "leader"], "will": ["조동사", "~할 것이다"], "instructed": ["과거분사", "안내받는", "instruct"], "provide": ["동사", "제공하다"], "registrant's": ["명사", "등록자의", "registrant"], "name": ["명사", "이름"], "e-mail": ["명사", "이메일"], "address": ["명사", "주소"], "job": ["명사", "직업, 일"], "title": ["명사", "직함"], "for": ["전치사", "~을 위해, ~에 대해"], "information": ["명사", "정보"], "please": ["부사", "부디, ~해 주세요"], "call": ["동사", "전화하다"], "sandeep": ["고유명사", "Sandeep(인명)"], "desale": ["고유명사", "Desale(인명)"], "416-555-0146": ["숫자", "전화번호"]}, "questions": [{"no": 131, "q": "", "options": ["received", "receive", "to receive", "receiving"], "answer": 1, "explain": "정답 (B) receive\n지문 개요: SciTech Expo 웹사이트의 단체 등록 안내 페이지로, 10인 이상 단체에 대한 15% 할인과 등록 절차·제출 정보를 설명한다.\n정답 근거: 주어 Groups에 대한 동사가 없으므로 빈칸은 동사 자리다. 주어가 복수이고 뒤에 목적어 15 percent off가 있으므로 능동 복수 동사 receive가 정답이다.\n오답 분석: (A) received: 과거형이면 가능해 보이나 뒤 문장이 must be, will be로 현재·미래를 말하므로 시제가 맞지 않는다. / (C) to receive: to부정사는 문장의 동사가 될 수 없다. / (D) receiving: 분사·동명사는 문장의 동사가 될 수 없다.", "g": {}}, {"no": 132, "q": "", "options": ["agreements", "individuals", "payments", "assignments"], "answer": 1, "explain": "정답 (B) individuals\n정답 근거: 뒤에서 같은 회사 소속이어야 하고 함께 등록해야 한다고 했으므로 단체를 구성하는 사람을 뜻하는 individuals가 정답이다.\n오답 분석: (A) agreements: '합의'. 합의가 회사 소속일 수 없다. / (C) payments: '지불금'. 등록 주체가 될 수 없다. / (D) assignments: '과제'. 문맥과 무관하다.", "g": {}}, {"no": 133, "q": "", "options": ["many", "some", "other", "each"], "answer": 3, "explain": "정답 (D) each\n정답 근거: 빈칸 뒤가 단수 명사의 소유격 registrant's이므로 단수 명사를 꾸미는 each가 정답이다.\n오답 분석: (A) many: 복수 명사를 꾸미므로 단수와 맞지 않는다. / (B) some: 복수·불가산 명사와 어울려 단수 가산 명사와 맞지 않는다. / (C) other: 뒤에 복수 명사가 와야 한다.", "g": {}}, {"no": 134, "q": "", "options": ["The program can be viewed on the Web site.", "The registration process has been revised.", "The deadline for registration is May 1.", "The team members will be notified in advance."], "answer": 2, "explain": "정답 (C) The deadline for registration is May 1.\n정답 근거: 앞에서 등록 절차와 제출 정보를 설명했고 뒤에서 문의 전화를 안내하므로, 등록과 관련된 마감 정보를 덧붙이는 문장이 자연스럽다.\n오답 분석: (A): 프로그램 열람은 등록 절차 설명과 이어지지 않는다. / (B): 등록 절차가 변경되었다는 언급이 지문 어디에도 없다. / (D): 사전 통지 대상이 무엇인지 불분명해 흐름이 끊긴다.", "g": {}}], "vocab": "registration 명 등록 / receive 동 받다 / individual 명 개인 / organization 명 단체, 조직 / take advantage of 구 ~을 활용하다 / instruct 동 지시하다, 안내하 다 / registrant 명 등록자 / each 형 각각의 / deadline 명 마감일 / notify 동 알리다"}, {"range": "135-138", "passage": "To: John Cowen <jcowen@izzemail.com>\nFrom: Imogen Mckellen <imckellen@jocalifilestorage.com>\nDate: January 22\nSubject: Your Jocali File Storage account\nDear Mr. Cowen,\nI am reaching out to you because you created an account with Jocali File Storage last month, but there has been no further ---135--- within your account. It appears that you have not yet uploaded any documents. If you are not familiar with all the features our file storage platform has to offer, I am available to introduce you to them. Please let me know if you have a few minutes to chat. ---136---.\nHere at Jocali, we strive ---137--- your goals so that we can more easily help you reach them. ---138---, please feel free to communicate any questions or concerns with me. I am here to help you!\nSincerely,\nImogen McKellen, Customer Accounts Manager\nJocali File Storage", "tr": "수신: John Cowen / 발신: Imogen McKellen / 날짜: 1월 22일 / 제목: 귀하의 Jocali File Storage 계정\nCowen 씨께,\n지난달 Jocali File Storage에 계정을 만드셨으나 계정 내에 더 이상의 활동 (135)이 없어 연락드립니다. 아직 어떤 문서도 업로드하지 않으신 것으로 보입니다. 저희 파일 저장 플랫폼이 제공하는 기능들을 잘 모르신다면 제가 소개해 드릴 수 있습니다. 잠시 이야기 나눌 시간이 되시는지 알려 주십시오. 짧은 통화를 기꺼이 잡아 드리겠습니다 (136). 저희 Jocali는 고객님의 목표를 이해하려고 (137) 노력하며, 그래야 목표 달성을 더 쉽게 도울 수 있습니다. 그 목적을 위해 (138) 어떤 질문이나 우려든 편하게 전해 주십시오. 도와드리기 위해 있습니다!\nImogen McKellen 드림, 고객 계정 관리자, Jocali File Storage", "g": {"to": ["전치사", "~로, ~에게 / ~하기 위해"], "john": ["고유명사", "John(인명)"], "cowen": ["고유명사", "Cowen(인명)"], "jcowen@izzemail.com": ["고유명사", "이메일 주소"], "from": ["전치사", "~로부터"], "imogen": ["고유명사", "Imogen(인명)"], "mckellen": ["고유명사", "McKellen(인명)"], "imckellen@jocalifilestorage.com": ["고유명사", "이메일 주소"], "date": ["명사", "날짜"], "january": ["명사", "1월"], "22": ["숫자", "22"], "subject": ["명사", "제목"], "your": ["대명사", "당신의"], "jocali": ["고유명사", "Jocali(회사명)"], "file": ["명사", "파일"], "storage": ["명사", "저장"], "account": ["명사", "계정"], "dear": ["형용사", "~께(편지 인사)"], "mr": ["명사", "~씨(남성)"], "i": ["대명사", "나"], "am": ["동사", "~이다", "be"], "reaching": ["현재분사", "(reach out) 연락하는", "reach"], "out": ["부사", "(reach out) 연락하다"], "you": ["대명사", "당신"], "because": ["접속사", "~ 때문에"], "created": ["동사", "만들었다", "create"], "an": ["관사", "하나의"], "with": ["전치사", "~와 함께, ~로"], "last": ["형용사", "지난"], "month": ["명사", "달"], "but": ["접속사", "그러나"], "there": ["부사", "(there is) ~이 있다"], "has": ["조동사", "(완료) ~했다 / 가지고 있다", "have"], "been": ["동사", "(완료형) ~였다, ~되었다", "be"], "no": ["한정사", "어떤 ~도 아닌"], "further": ["형용사", "추가의"], "within": ["전치사", "~ 안에서"], "it": ["대명사", "그것"], "appears": ["동사", "~인 것 같다", "appear"], "that": ["접속사", "~라는 것 / (so that) ~하도록"], "have": ["조동사", "(완료) ~했다 / 가지다"], "not": ["부사", "~이 아닌"], "yet": ["부사", "아직"], "uploaded": ["과거분사", "업로드한", "upload"], "any": ["한정사", "어떤"], "documents": ["명사", "문서", "document"], "if": ["접속사", "만약 ~라면 / ~인지"], "are": ["동사", "~이다", "be"], "familiar": ["형용사", "잘 아는"], "all": ["한정사", "모든"], "the": ["관사", "그"], "features": ["명사", "기능", "feature"], "our": ["대명사", "우리의"], "platform": ["명사", "플랫폼"], "offer": ["동사", "제공하다"], "available": ["형용사", "~할 수 있는"], "introduce": ["동사", "소개하다"], "them": ["대명사", "그것들, 그들"], "please": ["부사", "부디, ~해 주세요"], "let": ["동사", "~하게 하다"], "me": ["대명사", "나에게"], "know": ["동사", "알다"], "a": ["관사", "하나의"], "few": ["형용사", "몇몇의"], "minutes": ["명사", "분", "minute"], "chat": ["동사", "이야기하다"], "here": ["부사", "여기에"], "at": ["전치사", "~에서"], "we": ["대명사", "우리"], "strive": ["동사", "노력하다"], "goals": ["명사", "목표", "goal"], "so": ["접속사", "그래서, ~하도록"], "can": ["조동사", "~할 수 있다"], "more": ["부사", "더"], "easily": ["부사", "쉽게"], "help": ["동사", "돕다"], "reach": ["동사", "도달하다"], "feel": ["동사", "느끼다"], "free": ["형용사", "자유로운"], "communicate": ["동사", "전달하다"], "questions": ["명사", "질문", "question"], "or": ["접속사", "또는"], "concerns": ["명사", "우려, 문의 사항", "concern"], "sincerely": ["부사", "진심으로(맺음말)"], "customer": ["명사", "고객"], "accounts": ["명사", "계정", "account"], "manager": ["명사", "관리자"]}, "questions": [{"no": 135, "q": "", "options": ["activity", "information", "feedback", "notice"], "answer": 0, "explain": "정답 (A) activity\n지문 개요: Jocali File Storage의 고객 관리 담당자가 계정을 만든 뒤 이용이 없는 고객에게 기능 안내와 통화를 제안하는 이메일이다.\n정답 근거: 형용사 further의 수식을 받는 명사 자리다. 뒤에서 문서를 업로드하지 않았다고 했으므로 계정 내 이용을 뜻하는 activity(활동)가 정답이다.\n오답 분석: (B) information: '정보'. 계정 안에 정보가 없다는 말은 업로드 여부와 연결되지 않는다. / (C) feedback: '의견'. 고객이 남기는 의견은 문맥과 무관하다. / (D) notice: '통지'. 회사가 보내는 통지를 뜻해 고객의 이용과 맞지 않는다.", "g": {}}, {"no": 136, "q": "", "options": ["Read the instructions carefully.", "Perhaps this was simply an oversight.", "These are the most popular services.", "I am happy to arrange a brief call."], "answer": 3, "explain": "정답 (D) I am happy to arrange a brief call.\n정답 근거: 바로 앞에서 이야기 나눌 시간이 있는지 물었으므로 통화를 잡아 주겠다는 제안이 자연스럽게 이어진다.\n오답 분석: (A): 지시 사항을 읽으라는 말은 통화 제안과 이어지지 않는다. / (B): 실수였을 것이라는 추측은 앞 문장과 연결되지 않는다. / (C): 인기 서비스 소개는 시간 문의 뒤에 올 내용이 아니다.", "g": {}}, {"no": 137, "q": "", "options": ["to understand", "understanding", "will understand", "understood"], "answer": 0, "explain": "정답 (A) to understand\n정답 근거: strive는 뒤에 to부정사를 취해 「~하려고 노력하다」를 뜻하므로 to understand가 정답이다.\n오답 분석: (B) understanding: strive는 동명사를 목적어로 취하지 않는다. / (C) will understand: 접속사 없이 동사를 또 쓸 수 없다. / (D) understood: 과거형·과거분사는 strive 뒤에 이어질 수 없다.", "g": {}}, {"no": 138, "q": "", "options": ["On the contrary", "Until now", "To that end", "As shown above"], "answer": 2, "explain": "정답 (C) To that end\n정답 근거: 앞 문장에서 고객의 목표를 이해하려 한다는 목적을 밝혔고 그 목적을 위해 질문을 달라는 흐름이므로 「그 목적을 위해」가 알맞다.\n오답 분석: (A) On the contrary: 앞 내용을 뒤집는 표현인데 반대 관계가 없다. / (B) Until now: 과거부터 지금까지를 뜻해 요청 문장과 어울리지 않는다. / (D) As shown above: 앞에 제시된 자료나 도표가 없다.", "g": {}}], "vocab": "reach out to 구 ~에게 연락 하다 / activity 명 활동 / be familiar with 구 ~을 잘 알다 / feature 명 기능, 특징 / oversight 명 실수, 간과 / arrange 동 마련하다, 잡다 / strive to do 구 ~하려고 노 력하다 / to that end 구 그 목적을 위 해 / concern 명 우려, 문의 사항"}, {"range": "139-142", "passage": "The city of Milldale has established two new rules for weekly recycling collection, effective immediately. The city ---139--- requires that citizens place materials to be recycled at the curb in a reusable container, such as a garbage can or plastic bin. ---140---. Under no circumstances should materials be left on the curb in plastic garbage bags, as was allowed in the past. Also we can no longer collect boxes that are haphazardly scattered along the curb. ---141---, residents must flatten cardboard boxes and bundle them together with twine before setting them out. If materials for recycling are not set out correctly, they will be left at the curb. Items for recycling will continue ---142--- every other Thursday morning.", "tr": "Milldale 시는 주간 재활용 수거에 대해 두 가지 새 규정을 제정했으며 즉시 시행됩니다. 시는 이제 (139) 시민들이 재활용할 물품을 쓰레기통이나 플라스틱 통 같은 재사용 가능한 용기에 담아 도로 경계석에 두도록 요구합니다. 주민들은 시청에서 무료 통을 받을 수 있습니다 (140). 과거에 허용되었던 것처럼 물품을 비닐 쓰레기봉투에 담아 경계석에 두는 것은 어떤 경우에도 안 됩니다. 또한 경계석을 따라 아무렇게나 흩어진 상자는 더 이상 수거할 수 없습니다. 대신 (141) 주민들은 종이 상자를 납작하게 접어 노끈으로 함께 묶은 뒤 내놓아야 합니다. 재활용 물품이 올바르게 배출되지 않으면 경계석에 그대로 남겨집니다. 재활용 물품은 격주 목요일 아침에 계속 수거될 것입니다 (142).", "g": {"the": ["관사", "그"], "city": ["명사", "시"], "of": ["전치사", "~의"], "milldale": ["고유명사", "Milldale(지명)"], "has": ["조동사", "(완료) ~했다", "have"], "established": ["과거분사", "제정한", "establish"], "two": ["숫자", "2"], "new": ["형용사", "새로운"], "rules": ["명사", "규정", "rule"], "for": ["전치사", "~을 위해, ~에 대해"], "weekly": ["형용사", "매주의"], "recycling": ["명사", "재활용"], "collection": ["명사", "수거"], "effective": ["형용사", "시행되는"], "immediately": ["부사", "즉시"], "requires": ["동사", "요구하다", "require"], "that": ["접속사", "~라는 것 / ~하는(관계사)"], "citizens": ["명사", "시민", "citizen"], "place": ["동사", "두다, 놓다"], "materials": ["명사", "물품", "material"], "to": ["전치사", "~로, ~에게 / ~하기 위해"], "be": ["동사", "~이다, 되다"], "recycled": ["과거분사", "재활용되는", "recycle"], "at": ["전치사", "~에서"], "curb": ["명사", "도로 경계석"], "in": ["전치사", "~에, ~에서"], "a": ["관사", "하나의"], "reusable": ["형용사", "재사용 가능한"], "container": ["명사", "용기"], "such": ["한정사", "그렇게, 그런"], "as": ["전치사", "~처럼, ~ 같은"], "garbage": ["명사", "쓰레기"], "can": ["명사", "통(garbage can) / ~할 수 있다"], "or": ["접속사", "또는"], "plastic": ["형용사", "플라스틱의"], "bin": ["명사", "통"], "under": ["전치사", "~ 아래에서"], "no": ["한정사", "어떤 ~도 아닌"], "circumstances": ["명사", "상황", "circumstance"], "should": ["조동사", "~해야 한다"], "left": ["과거분사", "남겨진", "leave"], "on": ["전치사", "~에, ~로"], "bags": ["명사", "봉투", "bag"], "was": ["동사", "~였다", "be"], "allowed": ["과거분사", "허용된", "allow"], "past": ["명사", "과거"], "also": ["부사", "또한"], "we": ["대명사", "우리"], "longer": ["부사", "더 이상(no longer)", "long"], "collect": ["동사", "수거하다"], "boxes": ["명사", "상자", "box"], "are": ["동사", "~이다", "be"], "haphazardly": ["부사", "아무렇게나"], "scattered": ["과거분사", "흩어진", "scatter"], "along": ["전치사", "~을 따라"], "residents": ["명사", "주민", "resident"], "must": ["조동사", "~해야 한다"], "flatten": ["동사", "납작하게 만들다"], "cardboard": ["명사", "판지"], "and": ["접속사", "그리고"], "bundle": ["동사", "묶다"], "them": ["대명사", "그것들, 그들"], "together": ["부사", "함께"], "with": ["전치사", "~와 함께, ~로"], "twine": ["명사", "노끈"], "before": ["전치사", "~ 전에"], "setting": ["동명사", "내놓는 것", "set"], "out": ["부사", "밖으로"], "if": ["접속사", "만약 ~라면"], "not": ["부사", "~이 아닌"], "set": ["과거분사", "내놓은", "set"], "correctly": ["부사", "올바르게"], "they": ["대명사", "그들"], "will": ["조동사", "~할 것이다"], "items": ["명사", "물품", "item"], "continue": ["동사", "계속하다"], "every": ["한정사", "모든, ~마다"], "other": ["형용사", "다른"], "thursday": ["명사", "목요일"], "morning": ["명사", "아침"]}, "questions": [{"no": 139, "q": "", "options": ["still", "now", "often", "never"], "answer": 1, "explain": "정답 (B) now\n지문 개요: Milldale 시가 주간 재활용 수거에 대해 즉시 시행되는 두 가지 새 규정(재사용 용기 사용, 상자 납작하게 묶기)을 알리는 공지다.\n정답 근거: 앞 문장에서 새 규정이 즉시 시행된다고 했으므로 지금부터 요구한다는 뜻의 now가 알맞다.\n오답 분석: (A) still: '여전히'. 예전부터 이어진 규정이라는 뜻이 되어 새 규정이라는 내용과 어긋남. / (C) often: '자주'. 규정의 강제성과 어울리지 않는다. / (D) never: '결코 ~않다'. 요구한다는 내용과 정반대다.", "g": {}}, {"no": 140, "q": "", "options": ["Residents can obtain a free bin at city hall.", "Milldale has been recycling for five decades.", "Recycling is good for the environment.", "Garbage bags are available for purchase."], "answer": 0, "explain": "정답 (A) Residents can obtain a free bin at city hall.\n정답 근거: 앞 문장에서 재사용 가능한 용기를 쓰라고 했으므로 그 용기를 무료로 받을 수 있다는 안내가 자연스럽게 이어진다.\n오답 분석: (B): 재활용 역사 언급은 규정 안내 흐름과 무관하다. / (C): 재활용이 환경에 좋다는 일반론은 구체적 지시와 이어지지 않는다. / (D): 뒤에서 비닐봉투 사용을 금지하므로 봉투 구매 안내는 모순된다.", "g": {}}, {"no": 141, "q": "", "options": ["Instead", "In addition", "In any event", "In the meantime"], "answer": 0, "explain": "정답 (A) Instead\n정답 근거: 앞 문장에서 흩어진 상자는 수거하지 않는다고 했고 뒤에서 접어서 묶으라고 하므로 대체 방법을 제시하는 「대신」이 알맞다.\n오답 분석: (B) In addition: 추가 정보를 더할 때 쓰는데 여기서는 금지에 대한 대안을 제시한다. / (C) In any event: '어쨌든'. 앞뒤 인과 관계를 나타내지 못한다. / (D) In the meantime: '그동안'. 시간의 공백이 없어 어울리지 않는다.", "g": {}}, {"no": 142, "q": "", "options": ["picked up", "picks up", "pick it up", "to be picked up"], "answer": 3, "explain": "정답 (D) to be picked up\n정답 근거: continue는 to부정사를 취하고, pick up이 타동사인데 뒤에 목적어가 없으므로 수동형 to be p.p.가 정답이다.\n오답 분석: (A) picked up: continue 뒤에 과거분사가 바로 올 수 없다. / (B) picks up: 동사 continue가 이미 있어 동사를 또 쓸 수 없다. / (C) pick it up: 목적어 it을 넣으면 주어인 물품과 중복되어 뜻이 어긋남.", "g": {}}], "vocab": "establish 동 수립하다, 제정 하다 / effective immediately 구 즉시 시행되는 / curb 명 도로 경계석, 연석 / reusable 형 재사용 가능한 / obtain 동 얻다 / under no circumstances 구 어떤 경우에도 ~ 않다 / haphazardly 부 아무렇게나 / scatter 동 흩어 놓다 / flatten 동 납작하게 만들다 / twine 명 노끈 / instead 부 대신에 / every other 구 격주의, 하나 걸러"}, {"range": "143-146", "passage": "From: elizabeth-herriot@lofnes.ie\nTo: visitorinformation@malfordmuseum.ie\nDate: 11 February\nSubject: Mobility concerns\nDear Sir or Madam,\nI visit your museum regularly and I have appreciated the exercise I get visiting the many exhibit halls while viewing the fascinating collections. ---143---, I have recently begun using a motorized wheelchair for mobility, and so I am concerned about how that might affect my visit planned for next Saturday. I fear that some areas of the museum may no longer be ---144--- to me. Specifically, I want to know how best to navigate so that I can dine at the Visitors' Cafe while I am there. As I recall, ---145--- has two separate seating areas.\n---146---?\nKind regards,\nLiz Herriot", "tr": "발신: elizabeth-herriot@lofnes.ie / 수신: visitorinformation@malfordmuseum.ie / 날짜: 2월 11일 / 제목: 이동 관련 문의\n담당자님께,\n저는 귀 박물관을 정기적으로 방문하며, 흥미로운 소장품을 보면서 여러 전시실을 걷는 운동을 좋게 여겨 왔습니다. 그러나 (143) 최근 이동을 위해 전동 휠체어를 사용하기 시작해서, 다음 주 토요일로 예정된 방문에 그것이 어떤 영향을 줄지 걱정됩니다. 박물관의 일부 구역이 더 이상 저에게 접근 가능하지 (144) 않을까 우려됩니다. 특히 그곳에 있는 동안 방문객 카페에서 식사할 수 있도록 어떻게 이동하는 것이 가장 좋은지 알고 싶습니다. 제 기억으로는 그곳 (145)에 별도의 좌석 공간이 두 곳 있습니다. 그중 어느 쪽이든 휠체어로 이용하기 편한가요 (146)?\nLiz Herriot 드림", "g": {"from": ["전치사", "~로부터"], "elizabeth-herriot@lofnes.ie": ["고유명사", "이메일 주소"], "to": ["전치사", "~로, ~에게 / ~하기 위해"], "visitorinformation@malfordmuseum.ie": ["고유명사", "이메일 주소"], "date": ["명사", "날짜"], "11": ["숫자", "11"], "february": ["명사", "2월"], "subject": ["명사", "제목"], "mobility": ["명사", "이동(성)"], "concerns": ["명사", "우려, 문의 사항", "concern"], "dear": ["형용사", "~께(편지 인사)"], "sir": ["명사", "선생님(호칭)"], "or": ["접속사", "또는"], "madam": ["명사", "부인(호칭)"], "i": ["대명사", "나"], "visit": ["동사", "방문하다"], "your": ["대명사", "당신의"], "museum": ["명사", "박물관"], "regularly": ["부사", "정기적으로"], "and": ["접속사", "그리고"], "have": ["조동사", "(완료) ~했다"], "appreciated": ["과거분사", "좋게 여긴", "appreciate"], "the": ["관사", "그"], "exercise": ["명사", "운동"], "get": ["동사", "얻다"], "visiting": ["현재분사", "방문하는", "visit"], "many": ["형용사", "많은"], "exhibit": ["명사", "전시"], "halls": ["명사", "홀, 실", "hall"], "while": ["접속사", "~하는 동안"], "viewing": ["현재분사", "보는", "view"], "fascinating": ["형용사", "매력적인"], "collections": ["명사", "소장품", "collection"], "recently": ["부사", "최근에"], "begun": ["과거분사", "시작한", "begin"], "using": ["동명사", "사용하는 것", "use"], "a": ["관사", "하나의"], "motorized": ["형용사", "전동식의"], "wheelchair": ["명사", "휠체어"], "for": ["전치사", "~을 위해, ~에 대해"], "so": ["접속사", "그래서, ~하도록"], "am": ["동사", "~이다", "be"], "concerned": ["형용사", "걱정하는"], "about": ["전치사", "~에 관해"], "how": ["부사", "어떻게"], "that": ["접속사", "~라는 것 / 그것"], "might": ["조동사", "~할지도 모른다"], "affect": ["동사", "영향을 주다"], "my": ["대명사", "나의"], "planned": ["과거분사", "계획된", "plan"], "next": ["형용사", "다음의"], "saturday": ["명사", "토요일"], "fear": ["동사", "걱정하다"], "some": ["한정사", "일부의"], "areas": ["명사", "구역", "area"], "of": ["전치사", "~의"], "may": ["조동사", "~일지도 모른다"], "no": ["한정사", "어떤 ~도 아닌"], "longer": ["부사", "더 이상(no longer)", "long"], "be": ["동사", "~이다, 되다"], "me": ["대명사", "나에게"], "specifically": ["부사", "특히"], "want": ["동사", "원하다"], "know": ["동사", "알다"], "best": ["부사", "가장 잘", "well"], "navigate": ["동사", "이동하다, 길을 찾다"], "can": ["조동사", "~할 수 있다"], "dine": ["동사", "식사하다"], "at": ["전치사", "~에서"], "visitors'": ["명사", "방문객의", "visitor"], "cafe": ["명사", "카페"], "there": ["부사", "그곳에"], "as": ["접속사", "~하듯이"], "recall": ["동사", "기억하다"], "has": ["동사", "가지고 있다", "have"], "two": ["숫자", "2"], "separate": ["형용사", "별도의"], "seating": ["명사", "좌석"], "kind": ["형용사", "따뜻한(Kind regards)"], "regards": ["명사", "안부(맺음말)", "regard"], "liz": ["고유명사", "Liz(인명)"], "herriot": ["고유명사", "Herriot(인명)"]}, "questions": [{"no": 143, "q": "", "options": ["Similarly", "However", "Therefore", "Meanwhile"], "answer": 1, "explain": "정답 (B) However\n지문 개요: 박물관을 자주 찾는 관람객이 전동 휠체어를 사용하게 되면서 관람 동선과 카페 좌석 접근성을 문의하는 이메일이다.\n정답 근거: 앞에서는 걸어 다니는 것을 좋게 여겼다고 했고 뒤에서는 휠체어를 쓰게 되었다고 하므로 대조를 나타내는 However가 알맞다.\n오답 분석: (A) Similarly: 비슷한 내용을 이을 때 쓰는데 앞뒤가 대조된다. / (C) Therefore: 인과 관계가 아니다. / (D) Meanwhile: 동시에 일어나는 일을 말할 때 쓰는데 시간 대비가 아니다.", "g": {}}, {"no": 144, "q": "", "options": ["capable", "attractive", "accessible", "sufficient"], "answer": 2, "explain": "정답 (C) accessible\n정답 근거: 휠체어 사용으로 갈 수 없는 구역이 생길까 걱정한다는 내용이므로 접근 가능한을 뜻하는 accessible이 알맞다.\n오답 분석: (A) capable: 사람이 능력을 갖췄다는 뜻이라 장소에 쓸 수 없다. / (B) attractive: '매력적인'. 이동 문제와 무관하다. / (D) sufficient: '충분한'. 접근 가능 여부를 나타내지 못한다.", "g": {}}, {"no": 145, "q": "", "options": ["it", "ours", "both", "whichever"], "answer": 0, "explain": "정답 (A) it\n정답 근거: 앞 문장의 the Visitors' Cafe를 가리키는 단수 대명사가 필요하고 뒤 동사가 단수 has이므로 it이 정답이다.\n오답 분석: (B) ours: '우리 것'. 발신자의 소유물을 뜻해 카페를 가리킬 수 없다. / (C) both: 복수 취급이라 단수 동사 has와 맞지 않는다. / (D) whichever: 복합관계대명사로 이 문장에서는 접속 대상이 없다.", "g": {}}, {"no": 146, "q": "", "options": ["Do you offer wheelchair rentals?", "What time of day is less crowded?", "Do you still serve vegetarian meals?", "Are either of them wheelchair friendly?"], "answer": 3, "explain": "정답 (D) Are either of them wheelchair friendly?\n정답 근거: 바로 앞에서 좌석 공간이 두 곳이라고 했으므로 그 두 곳(them)의 휠체어 이용 가능 여부를 묻는 질문이 자연스럽다.\n오답 분석: (A): 휠체어 대여는 이미 본인 휠체어를 사용한다는 내용과 어긋남. / (B): 한산한 시간대 문의는 좌석 두 곳 언급과 이어지지 않는다. / (C): 채식 식사 제공 여부는 이동 편의라는 글의 목적과 무관하다.\n정답 한눈에 보기\n147 || 148 || 149 || 150 || 154 || 155 || 163 || 164\n(D) || (C) || (B) || (C) || (C) || (D) || (D) || (C)\n147 || 148 || 149 || 150 || 151 || 152 || 153 || 154\n(B) || (A) || (C) || (D) || (B) || (D) || (B) || (B)", "g": {}}], "vocab": "appreciate 동 감사하다, 높 이 평가하다 / exhibit hall 명 전시실 / fascinating 형 매력적인 / however 접속부사 그러나 motorized 형 전동식의 / mobility 명 이동(성) / accessible 형 접근 가능한 / specifically 부 특히, 구체적 으로 / navigate 동 길을 찾다, 이동 하다 / dine 동 식사하다 / separate 형 분리된, 별도의"}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r1-p7',$mkd${"id": "a2-r1-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 2, "round": 1, "level": "중급", "title": "A급 과제 1회 · PART 7 (기출독해 2문항 1·2회)", "notes": [], "items": [], "sets": [{"range": "147-148", "passage": "Mercury Coaches: Official travel partner of the Oceanwaves Music Festival\nOur comfortable buses help transport concertgoers to the Oceanwaves Music Festival each day from June 17 to June 21. One-way tickets are $10.00 each. Round-trip tickets are available for $20.00. Buses depart from Coltonville at 10:30 A.M. and return from the festival main gate at 8:00 P.M. Tickets can be purchased on the bus or through our Web site. For more information, visit https://www.mercurycoaches.com.", "tr": "Mercury Coaches: Oceanwaves 음악 축제 공식 교통 협력사\n저희의 편안한 버스가 6월 17일부터 6월 21일까지 매일 콘서트 관람객을 Oceanwaves 음악 축제로 수송해 드립니다. 편도 티켓은 장당 10달러이며 왕복 티켓은 20달러에 구매하실 수 있습니다. 버스는 오전 10시 30분에 Coltonville에서 출발하고 오후 8시에 축제 정문에서 돌아옵니다. 티켓은 버스에서 또는 저희 웹사이트를 통해 구매할 수 있습니다. 더 자세한 정보는 https://www.mercurycoaches.com을 방문하십시오.", "g": {"mercury": ["고유명사", "Mercury(회사명)"], "coaches": ["명사", "장거리 버스", "coach"], "official": ["형용사", "공식적인"], "travel": ["명사", "여행, 교통"], "partner": ["명사", "협력사"], "of": ["전치사", "~의"], "the": ["관사", "그"], "oceanwaves": ["고유명사", "Oceanwaves(축제명)"], "music": ["명사", "음악"], "festival": ["명사", "축제"], "our": ["대명사", "우리의"], "comfortable": ["형용사", "편안한"], "buses": ["명사", "버스", "bus"], "help": ["동사", "돕다"], "transport": ["동사", "수송하다"], "concertgoers": ["명사", "콘서트 관람객", "concertgoer"], "to": ["전치사", "~로, ~에게 / ~하기 위해"], "each": ["한정사", "매 ~ / 각각"], "day": ["명사", "날"], "from": ["전치사", "~로부터"], "june": ["명사", "6월"], "17": ["숫자", "17"], "21": ["숫자", "21"], "one-way": ["형용사", "편도의"], "tickets": ["명사", "표", "ticket"], "are": ["동사", "~이다", "be"], "$10.00": ["숫자", "10달러"], "round-trip": ["형용사", "왕복의"], "available": ["형용사", "구매 가능한"], "for": ["전치사", "~을 위해, ~에 대해"], "$20.00": ["숫자", "20달러"], "depart": ["동사", "출발하다"], "coltonville": ["고유명사", "Coltonville(지명)"], "at": ["전치사", "~에서"], "10:30": ["숫자", "10시 30분"], "a.m": ["명사", "오전"], "and": ["접속사", "그리고"], "return": ["동사", "돌아오다"], "main": ["형용사", "주된"], "gate": ["명사", "문"], "8:00": ["숫자", "8시"], "p.m": ["명사", "오후"], "can": ["조동사", "~할 수 있다"], "be": ["동사", "~이다, 되다"], "purchased": ["과거분사", "구매되는", "purchase"], "on": ["전치사", "~에, ~로"], "bus": ["명사", "버스"], "or": ["접속사", "또는"], "through": ["전치사", "~을 통해"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "more": ["형용사", "더 많은"], "information": ["명사", "정보"], "visit": ["동사", "방문하다"], "https://www.mercurycoaches.com": ["고유명사", "웹 주소"]}, "questions": [{"no": 147, "q": "What is indicated about the Oceanwaves Music Festival?", "options": ["It is an annual event.", "It features performances in two locations.", "It starts in the evening.", "It takes place on multiple days."], "answer": 3, "explain": "정답 (D) It takes place on multiple days.\n지문 개요: Oceanwaves 음악 축제의 공식 교통 협력사인 Mercury Coaches가 축제 기간 셔틀버스 운행 일정과 요금, 티켓 구매 방법을 알리는 광고다.\n정답 근거: 축제로 매일 수송한다며 6월 17일부터 21일까지라고 밝혔으므로 여러 날에 걸쳐 열린다는 것을 알 수 있다.\n오답 분석: (A): 해마다 열린다는 언급이 없다. / (B): 공연 장소가 두 곳이라는 정보가 없다. / (C): 저녁 8시는 축제 시작이 아니라 버스 복귀 시각이다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "명시된", "indicate"], "about": ["전치사", "~에 관해"], "the": ["관사", "그"], "oceanwaves": ["고유명사", "Oceanwaves(축제명)"], "music": ["명사", "음악"], "festival": ["명사", "축제"]}}, {"no": 148, "q": "What is suggested about the bus tickets?", "options": ["They may be exchanged.", "They are discounted for round trips.", "They may be bought in advance.", "They are sold at stores in Coltonville."], "answer": 2, "explain": "정답 (C) They may be bought in advance.\n정답 근거: 티켓을 버스에서뿐 아니라 웹사이트를 통해서도 살 수 있다고 했으므로 미리 구매가 가능함을 알 수 있다.\n오답 분석: (A): 교환에 관한 언급이 없다. / (B): 왕복이 편도 두 장 값과 같아 할인이 아니다. / (D): Coltonville은 출발지일 뿐 매장 판매 언급은 없다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "suggested": ["과거분사", "암시된", "suggest"], "about": ["전치사", "~에 관해"], "the": ["관사", "그"], "bus": ["명사", "버스"], "tickets": ["명사", "표", "ticket"]}}], "vocab": "official 형 공식적인 / transport 동 수송하다 / concertgoer 명 콘서트 관람 객 / one-way 형 편도의 / round-trip 형 왕복의 / depart 동 출발하다 / purchase 동 구매하다 / indicate 동 명시하다 / annual 형 연례의 / multiple 형 여러 개의 / in advance 구 미리 || Paraphrase: 147. each day from June 17 to June 21 → takes place on multiple days 148. purchased ~ through our Web site → may be bought in advance"}, {"range": "149-150", "passage": "http://www.kitchencarts.com\nWhite kitchen cart with natural wood countertop\n➢ Fixed height of 86 centimeters; width 57 centimeters; length 98 centimeters\n➢ Includes nonadjustable shelf with two removable wire baskets\n➢ Features caster wheels (with locks) to provide easy mobility\nGet 25 percent off with promo code KSPROMO. All furniture on sale from June 8 to June 10. Delivery charges apply.", "tr": "http://www.kitchencarts.com\n천연 목재 상판이 있는 흰색 주방 카트\n· 고정 높이 86cm, 너비 57cm, 길이 98cm\n· 분리 가능한 철망 바구니 두 개가 달린 조절 불가 선반 포함\n· 손쉬운 이동을 위한 잠금장치 달린 캐스터 바퀴 탑재\n프로모션 코드 KSPROMO로 25% 할인을 받으세요. 모든 가구가 6월 8일부터 6월 10일까지 세일합니다. 배송비는 별도로 부과됩니다.", "g": {"http://www.kitchencarts.com": ["고유명사", "웹 주소"], "white": ["형용사", "흰색의"], "kitchen": ["명사", "주방"], "cart": ["명사", "카트"], "with": ["전치사", "~와 함께, ~로"], "natural": ["형용사", "천연의"], "wood": ["명사", "목재"], "countertop": ["명사", "조리대 상판"], "fixed": ["형용사", "고정된"], "height": ["명사", "높이"], "of": ["전치사", "~의"], "86": ["숫자", "86"], "centimeters": ["명사", "센티미터", "centimeter"], "width": ["명사", "너비"], "57": ["숫자", "57"], "length": ["명사", "길이"], "98": ["숫자", "98"], "includes": ["동사", "포함하다", "include"], "nonadjustable": ["형용사", "조절 불가능한"], "shelf": ["명사", "선반"], "two": ["숫자", "2"], "removable": ["형용사", "분리 가능한"], "wire": ["명사", "철사"], "baskets": ["명사", "바구니", "basket"], "features": ["동사", "~을 특징으로 갖추다", "feature"], "caster": ["명사", "캐스터(바퀴)"], "wheels": ["명사", "바퀴", "wheel"], "locks": ["명사", "잠금장치", "lock"], "to": ["전치사", "~로, ~에게 / ~하기 위해"], "provide": ["동사", "제공하다"], "easy": ["형용사", "쉬운"], "mobility": ["명사", "이동(성)"], "get": ["동사", "받다"], "25": ["숫자", "25"], "percent": ["명사", "퍼센트"], "off": ["부사", "할인되어"], "promo": ["명사", "프로모션"], "code": ["명사", "코드"], "kspromo": ["고유명사", "KSPROMO(코드명)"], "all": ["한정사", "모든"], "furniture": ["명사", "가구"], "on": ["전치사", "~에, ~로"], "sale": ["명사", "할인 판매"], "from": ["전치사", "~로부터"], "june": ["명사", "6월"], "8": ["숫자", "8"], "10": ["숫자", "10"], "delivery": ["명사", "배송"], "charges": ["명사", "요금", "charge"], "apply": ["동사", "적용되다"]}, "questions": [{"no": 149, "q": "What feature of the kitchen cart is mentioned?", "options": ["It has a removable shelf.", "It can be moved around.", "It comes in a variety of colors.", "It can easily be adjusted with a tool."], "answer": 1, "explain": "정답 (B) It can be moved around.\n지문 개요: 주방 카트 제품의 규격과 기능을 소개하고 할인 코드와 세일 기간을 안내하는 상품 페이지다.\n정답 근거: 손쉬운 이동을 위한 캐스터 바퀴가 달려 있다고 했으므로 옮길 수 있다는 것이 언급된 기능이다.\n오답 분석: (A): 선반은 조절 불가이며 분리 가능한 것은 바구니다. / (C): 색상은 흰색만 제시되어 있다. / (D): 도구로 조절할 수 있다는 언급이 없다.", "g": {"what": ["대명사", "무엇"], "feature": ["명사", "기능, 특징"], "of": ["전치사", "~의"], "the": ["관사", "그"], "kitchen": ["명사", "주방"], "cart": ["명사", "카트"], "is": ["동사", "~이다", "be"], "mentioned": ["과거분사", "언급된", "mention"]}}, {"no": 150, "q": "What is indicated about the sale?", "options": ["It lasts for ten days.", "It is for a discontinued item.", "It requires a special code.", "It includes free delivery."], "answer": 2, "explain": "정답 (C) It requires a special code.\n정답 근거: 프로모션 코드 KSPROMO를 입력해야 25% 할인을 받는다고 했으므로 특별 코드가 필요하다.\n오답 분석: (A): 세일 기간은 6월 8일부터 10일까지로 사흘이다. / (B): 단종 상품이라는 언급이 없다. / (D): 배송비가 별도로 부과된다고 명시된다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "명시된", "indicate"], "about": ["전치사", "~에 관해"], "the": ["관사", "그"], "sale": ["명사", "할인 판매"]}}], "vocab": "countertop 명 조리대 상판 / fixed 형 고정된 / nonadjustable 형 조절 불 가능한 / removable 형 분리 가능한 / caster wheel 명 바퀴(캐스 터) / mobility 명 이동성 / promo code 명 할인 코드 / apply 동 적용되다 / discontinued 형 단종된 || Paraphrase: 149. caster wheels ~ easy mobility → can be moved around 150. 25 percent off with promo code KSPROMO → requires a special code"}, {"range": "154-155", "passage": "Shadia Alotaibi [10:15 A.M.] Rocio, thanks again for chatting with me at the career fair last week. Your tips on resume writing helped. Are you still able to meet to review mine?\nRocio Souza [10:16 A.M.] Of course. Can you stop by my office downtown? Any time after 4:00 P.M. is good.\nShadia Alotaibi [10:18 A.M.] Sorry, I can’t today. My car will be in the auto shop all day.\nRocio Souza [10:19 A.M.] I live in the southeast part of town. Isn’t that close to you? We could meet somewhere in the vicinity after work hours.\nShadia Alotaibi [10:20 A.M.] That might be easier. Do you know the Lemon Tree Cafe? Say, 6:30 this evening?\nRocio Souza [10:22 A.M.] I just checked my schedule― and yes, I know where that is. See you then!", "tr": "Shadia Alotaibi [오전 10:15] Rocio, 지난주 취업 박람회에서 이야기 나눠 주셔서 다시 한번 감사해요. 이력서 작성 조언이 도움이 되었어요. 제 이력서를 검토해 주실 수 있을까요?\nRocio Souza [오전 10:16] 물론이죠. 시내에 있는 제 사무실에 들르실 수 있나요? 오후 4시 이후면 언제든 좋아요.\nShadia Alotaibi [오전 10:18] 죄송해요, 오늘은 안 돼요. 제 차가 하루 종일 정비소에 있을 거예요.\nRocio Souza [오전 10:19] 저는 시내 남동쪽에 살아요. 그쪽과 가깝지 않나요? 퇴근 후 그 근처에서 만나도 될 것 같아요.\nShadia Alotaibi [오전 10:20] 그게 더 편할 것 같아요. Lemon Tree 카페 아세요? 오늘 저녁 6시 30분 어떠세요?\nRocio Souza [오전 10:22] 일정을 확인했는데, 네, 거기 어딘지 알아요. 그때 봬요!", "g": {"shadia": ["고유명사", "Shadia(인명)"], "alotaibi": ["고유명사", "Alotaibi(인명)"], "10:15": ["숫자", "10시 15분"], "a.m": ["명사", "오전"], "rocio": ["고유명사", "Rocio(인명)"], "thanks": ["명사", "감사", "thank"], "again": ["부사", "다시"], "for": ["전치사", "~을 위해, ~에 대해"], "chatting": ["동명사", "이야기하는 것", "chat"], "with": ["전치사", "~와 함께, ~로"], "me": ["대명사", "나에게"], "at": ["전치사", "~에서"], "the": ["관사", "그"], "career": ["명사", "직업, 경력"], "fair": ["명사", "박람회"], "last": ["형용사", "지난"], "week": ["명사", "주"], "your": ["대명사", "당신의"], "tips": ["명사", "조언", "tip"], "on": ["전치사", "~에, ~로"], "resume": ["명사", "이력서"], "writing": ["동명사", "작성", "write"], "helped": ["동사", "도움이 됐다", "help"], "are": ["동사", "~이다", "be"], "you": ["대명사", "당신"], "still": ["부사", "여전히"], "able": ["형용사", "~할 수 있는"], "to": ["전치사", "~로, ~에게 / ~하기 위해"], "meet": ["동사", "만나다"], "review": ["동사", "검토하다"], "mine": ["대명사", "내 것"], "souza": ["고유명사", "Souza(인명)"], "10:16": ["숫자", "10시 16분"], "of": ["전치사", "~의"], "course": ["명사", "물론(of course)"], "can": ["조동사", "~할 수 있다"], "stop": ["동사", "들르다(stop by)"], "by": ["전치사", "~까지, ~에 의해"], "my": ["대명사", "나의"], "office": ["명사", "사무실"], "downtown": ["부사", "시내에"], "any": ["한정사", "어느 ~든"], "time": ["명사", "시간"], "after": ["전치사", "~ 후에"], "4:00": ["숫자", "4시"], "p.m": ["명사", "오후"], "is": ["동사", "~이다", "be"], "good": ["형용사", "좋은"], "10:18": ["숫자", "10시 18분"], "sorry": ["형용사", "미안한"], "i": ["대명사", "나"], "can’t": ["조동사", "~할 수 없다", "can"], "today": ["부사", "오늘"], "car": ["명사", "자동차"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "in": ["전치사", "~에, ~에서"], "auto": ["명사", "자동차"], "shop": ["명사", "정비소, 가게"], "all": ["한정사", "모든"], "day": ["명사", "날"], "10:19": ["숫자", "10시 19분"], "live": ["동사", "살다"], "southeast": ["형용사", "남동쪽의"], "part": ["명사", "부분, 지역"], "town": ["명사", "마을, 시"], "isn’t": ["동사", "~이 아니다", "be"], "that": ["대명사", "그것, 그곳"], "close": ["형용사", "가까운"], "we": ["대명사", "우리"], "could": ["조동사", "~할 수 있다", "can"], "somewhere": ["부사", "어딘가에서"], "vicinity": ["명사", "인근"], "work": ["명사", "작업, 업무"], "hours": ["명사", "시간", "hour"], "10:20": ["숫자", "10시 20분"], "might": ["조동사", "~할지도 모른다"], "easier": ["형용사", "더 쉬운", "easy"], "do": ["조동사", "(의문문 조동사)"], "know": ["동사", "알다"], "lemon": ["명사", "레몬"], "tree": ["명사", "나무"], "cafe": ["명사", "카페"], "say": ["동사", "이를테면, 말하다"], "6:30": ["숫자", "6시 30분"], "this": ["한정사", "이"], "evening": ["명사", "저녁"], "10:22": ["숫자", "10시 22분"], "just": ["부사", "방금"], "checked": ["동사", "확인했다", "check"], "schedule": ["명사", "일정"], "and": ["접속사", "그리고"], "yes": ["감탄사", "네"], "where": ["부사", "어디에"], "see": ["동사", "보다"], "then": ["부사", "그때"]}, "questions": [{"no": 154, "q": "Why is Ms. Alotaibi contacting Ms. Souza?", "options": ["To arrange a follow-up job interview", "To report on an auto shop service", "To request professional guidance", "To apologize for missing an appointment"], "answer": 2, "explain": "정답 (C) To request professional guidance\n지문 개요: 취업 박람회에서 만난 두 사람이 이력서 검토를 위한 만남 장소와 시간을 조정하는 문자 대화다.\n정답 근거: 이력서 작성 조언이 도움이 되었다며 자신의 이력서를 검토해 줄 수 있는지 물었으므로 전문적인 조언을 요청하는 것이다.\n오답 분석: (A): 후속 면접 일정을 잡는 내용이 아니다. / (B): 정비소는 오늘 만날 수 없는 이유로만 언급된다. / (D): 약속을 어긴 데 대한 사과가 아니다.", "g": {"why": ["부사", "왜"], "is": ["동사", "~이다", "be"], "ms": ["명사", "~씨(여성)"], "alotaibi": ["고유명사", "Alotaibi(인명)"], "contacting": ["현재분사", "연락하는", "contact"], "souza": ["고유명사", "Souza(인명)"]}}, {"no": 155, "q": "At 10:20 A.M., what does Ms. Alotaibi most likely mean when she writes, “That might be easier“?", "options": ["Her neighborhood has many cafes.", "Ms. Souza’s office building is familiar.", "Many bus routes go downtown.", "A suggested meeting is convenient."], "answer": 3, "explain": "정답 (D) A suggested meeting is convenient.\n정답 근거: 상대가 자기 집 근처에서 퇴근 후 만나자고 제안한 직후의 반응이므로 그 제안이 더 편하다는 뜻이다.\n오답 분석: (A): 동네에 카페가 많다는 내용은 없다. / (B): 사무실은 오히려 가지 못한다고 한 곳이다. / (C): 버스 노선 이야기는 등장하지 않는다.", "g": {"at": ["전치사", "~에서"], "10:20": ["숫자", "10시 20분"], "a.m": ["명사", "오전"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "alotaibi": ["고유명사", "Alotaibi(인명)"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "mean": ["동사", "의미하다"], "when": ["접속사", "~할 때"], "she": ["대명사", "그녀"], "writes": ["동사", "쓰다", "write"], "that": ["대명사", "그것"], "might": ["조동사", "~할지도 모른다"], "be": ["동사", "~이다, 되다"], "easier": ["형용사", "더 쉬운", "easy"]}}], "vocab": "career fair 명 취업 박람회 / tip 명 조언, 팁 / review 동 검토하다 / stop by 구 들르다 / auto shop 명 자동차 정비소 / vicinity 명 인근, 부근 / guidance 명 지도, 조언 / convenient 형 편리한 / arrange 동 마련하다, 잡다 || Paraphrase: 154. tips on resume writing ~ meet to review mine → request professional guidance 155. meet somewhere in the vicinity → That might be easier → a suggested meeting is convenient"}, {"range": "163-164", "passage": "To: Erica Yeo <ericayeo@zmail.com>\nFrom: Richard Park <r.park@mamquarium.org>\nSubject: McConnell Aquarium\nDate: January 10\nDear Ms. Yeo,\nThank you for being a valued member of the McConnell Aquarium. Please note that your membership is set to expire on January 30. Renew your membership for an annual fee of just $35, and you will continue to enjoy some amazing benefits. Among the advantages are free admission to films about marine and aquatic life at our Underwater Theater; a 15% discount when reserving our banquet room for a festive gathering; and access to our e-magazine, Aquatica Monthly, as well as various other electronic databases. Additionally, members have exclusive access to special events, including our latest exhibit, Aquatic Life of the Amazon Basin. A members-only preview of this exhibit will be held on Saturday, February 22. So as not to miss this opportunity, call us today at 555-0122 to renew your membership. Or visit us on the Web at www.maquarium.org/membership. Thank you for your continued patronage.\nSincerely,\nRichard Park\nMembership Coordinator, McConnell Aquarium", "tr": "수신: Erica Yeo / 발신: Richard Park / 제목: McConnell 수족관 / 날짜: 1월 10일\nYeo 씨께,\nMcConnell 수족관의 소중한 회원이 되어 주셔서 감사합니다. 귀하의 회원 자격이 1월 30일에 만료될 예정임을 알려 드립니다. 연회비 단 35달러로 회원을 갱신하시면 놀라운 혜택을 계속 누리실 수 있습니다. 혜택 중에는 저희 언더워터 극장에서 해양·수생 생물에 관한 영화를 무료로 관람하는 것, 축하 모임을 위해 연회장을 예약할 때 15% 할인, 전자 잡지 Aquatica Monthly를 비롯한 다양한 전자 데이터베이스 이용이 있습니다. 또한 회원은 최신 전시 「아마존 분지의 수생 생물」을 포함한 특별 행사에 독점적으로 참여할 수 있습니다. 이 전시의 회원 전용 사전 관람은 2월 22일 토요일에 열립니다. 이 기회를 놓치지 않으시려면 오늘 555-0122로 전화하여 회원을 갱신하십시오. 또는 www.maquarium.org/membership에서 갱신하실 수 있습니다. 계속된 성원에 감사드립니다.\nRichard Park 드림, 회원 담당자, McConnell 수족관", "g": {"to": ["전치사", "~로, ~에게 / ~하기 위해"], "erica": ["고유명사", "Erica(인명)"], "yeo": ["고유명사", "Yeo(인명)"], "ericayeo@zmail.com": ["고유명사", "이메일 주소"], "from": ["전치사", "~로부터"], "richard": ["고유명사", "Richard(인명)"], "park": ["고유명사", "Park(인명)"], "r.park@mamquarium.org": ["고유명사", "이메일 주소"], "subject": ["명사", "제목"], "mcconnell": ["고유명사", "McConnell(수족관명)"], "aquarium": ["명사", "수족관"], "date": ["명사", "날짜"], "january": ["명사", "1월"], "10": ["숫자", "10"], "dear": ["형용사", "~께(편지 인사)"], "ms": ["명사", "~씨(여성)"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신"], "for": ["전치사", "~을 위해, ~에 대해"], "being": ["동명사", "~인 것", "be"], "a": ["관사", "하나의"], "valued": ["형용사", "소중한"], "member": ["명사", "회원"], "of": ["전치사", "~의"], "the": ["관사", "그"], "please": ["부사", "부디, ~해 주세요"], "note": ["동사", "유의하다"], "that": ["접속사", "~라는 것(명사절)"], "your": ["대명사", "당신의"], "membership": ["명사", "회원 자격"], "is": ["동사", "~이다", "be"], "set": ["과거분사", "예정된(be set to)", "set"], "expire": ["동사", "만료되다"], "on": ["전치사", "~에, ~로"], "30": ["숫자", "30"], "renew": ["동사", "갱신하다"], "an": ["관사", "하나의"], "annual": ["형용사", "연간의"], "fee": ["명사", "요금"], "just": ["부사", "단지"], "$35": ["숫자", "35달러"], "and": ["접속사", "그리고"], "will": ["조동사", "~할 것이다"], "continue": ["동사", "계속하다"], "enjoy": ["동사", "누리다"], "some": ["한정사", "일부의"], "amazing": ["형용사", "놀라운"], "benefits": ["명사", "혜택", "benefit"], "among": ["전치사", "~ 중에"], "advantages": ["명사", "이점, 혜택", "advantage"], "are": ["동사", "~이다", "be"], "free": ["형용사", "무료의"], "admission": ["명사", "입장"], "films": ["명사", "영화", "film"], "about": ["전치사", "~에 관해"], "marine": ["형용사", "해양의"], "aquatic": ["형용사", "수생의"], "life": ["명사", "생물, 생명"], "at": ["전치사", "~에서"], "our": ["대명사", "우리의"], "underwater": ["형용사", "수중의"], "theater": ["명사", "극장"], "15%": ["숫자", "15%"], "discount": ["명사", "할인"], "when": ["접속사", "~할 때"], "reserving": ["동명사", "예약하는 것", "reserve"], "banquet": ["명사", "연회"], "room": ["명사", "방, 실"], "festive": ["형용사", "축제의"], "gathering": ["명사", "모임"], "access": ["명사", "이용, 접속"], "e-magazine": ["명사", "전자 잡지"], "aquatica": ["고유명사", "Aquatica(잡지명)"], "monthly": ["고유명사", "Monthly(잡지명)"], "as": ["부사", "(as well as) ~뿐 아니라 / (so as not to) ~하지 않도록"], "well": ["부사", "잘(as well as ~뿐만 아니라)"], "various": ["형용사", "다양한"], "other": ["형용사", "다른"], "electronic": ["형용사", "전자의"], "databases": ["명사", "데이터베이스", "database"], "additionally": ["부사", "또한"], "members": ["명사", "회원", "member"], "have": ["동사", "가지다"], "exclusive": ["형용사", "독점적인"], "special": ["형용사", "특별한"], "events": ["명사", "행사", "event"], "including": ["전치사", "~을 포함하여"], "latest": ["형용사", "최신의"], "exhibit": ["명사", "전시"], "amazon": ["고유명사", "아마존"], "basin": ["명사", "분지"], "members-only": ["형용사", "회원 전용의"], "preview": ["명사", "사전 관람"], "this": ["한정사", "이"], "be": ["동사", "~이다, 되다"], "held": ["과거분사", "열린", "hold"], "saturday": ["명사", "토요일"], "february": ["명사", "2월"], "22": ["숫자", "22"], "so": ["부사", "(so as not to) ~하지 않도록"], "not": ["부사", "~이 아닌"], "miss": ["동사", "놓치다"], "opportunity": ["명사", "기회"], "call": ["동사", "전화하다"], "us": ["대명사", "우리를"], "today": ["부사", "오늘"], "555-0122": ["숫자", "전화번호"], "or": ["접속사", "또는"], "visit": ["동사", "방문하다"], "web": ["명사", "웹"], "www.maquarium.org/membership": ["고유명사", "웹 주소"], "continued": ["형용사", "지속적인"], "patronage": ["명사", "애용, 성원"], "sincerely": ["부사", "진심으로(맺음말)"], "coordinator": ["명사", "담당자"]}, "questions": [{"no": 163, "q": "What is NOT a benefit of being a member?", "options": ["Attending special events", "Watching films about sea life", "Accessing electronic materials", "Getting discounts on gift shop items"], "answer": 3, "explain": "정답 (D) Getting discounts on gift shop items\n지문 개요: McConnell 수족관이 회원 만료를 앞둔 고객에게 갱신을 권하며 회원 혜택과 회원 전용 사전 관람 행사를 소개하는 이메일이다.\n정답 근거: 영화 무료 관람, 전자 자료 이용, 특별 행사 참여는 모두 언급되었으나 기념품점 할인은 지문에 없다.\n오답 분석: (A): 특별 행사 독점 참여가 혜택으로 제시된다. / (B): 해양 생물 영화 무료 관람이 혜택으로 제시된다. / (C): 전자 잡지와 전자 데이터베이스 이용이 혜택으로 제시된다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "not": ["부사", "~이 아닌"], "a": ["관사", "하나의"], "benefit": ["명사", "혜택"], "of": ["전치사", "~의"], "being": ["동명사", "~인 것", "be"], "member": ["명사", "회원"]}}, {"no": 164, "q": "What is Ms. Yeo asked to do?", "options": ["Reserve the banquet room", "Write a magazine article", "Contact the McConnell Aquarium", "Attend a meeting"], "answer": 2, "explain": "정답 (C) Contact the McConnell Aquarium\n정답 근거: 기회를 놓치지 않으려면 오늘 555-0122로 전화해 갱신하라고 요청했으므로 수족관에 연락하는 것이 요청 사항이다.\n오답 분석: (A): 연회장 예약은 할인 혜택의 예시일 뿐 요청이 아니다. / (B): 잡지 기사 작성을 요청한 적 없다. / (D): 회의 참석 요청은 지문에 없다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "ms": ["명사", "~씨(여성)"], "yeo": ["고유명사", "Yeo(인명)"], "asked": ["과거분사", "요청받는", "ask"], "to": ["to부정사", "~하도록"], "do": ["동사", "하다"]}}], "vocab": "valued 형 소중한 / expire 동 만료되다 / renew 동 갱신하다 / annual fee 명 연회비 / admission 명 입장 / marine 형 해양의 / banquet room 명 연회장 / festive 형 축제의 / exclusive 형 독점적인, 전용 의 / preview 명 사전 관람 / patronage 명 애용, 성원 || Paraphrase: 163. films about marine and aquatic life → watching films about sea life (혜택 O) 164. call us today at 555-0122 → contact the McConnell Aquarium"}, {"range": "147-148", "sub": "기출독해 2회", "passage": "To: Juana Reza <juana.reza@delboroughschools.org>\nFrom: Alair Collings <acollings@mansfordsports.com>\nRe: Donation\nDate: August 7\nDear Ms. Reza:\nThank you for contacting us on behalf of the Delborough School District. As you know, Mansford Sports is a proud supporter of many sports-related activities in our township. We will be happy to provide the school district with 25 free basketballs, as you requested. You can pick up the basketballs from our main store on County Line Road on Thursday, April 14, at 2 P.M. Have my extension called when you arrive, and I will meet you at the front desk.\nSincerely,\nAlair Collings, Director of Marketing\nMansford Sports", "tr": "수신: Juana Reza / 발신: Alair Collings / 제목: 기부 / 날짜: 8월 7일\nReza 씨께,\nDelborough 학교구를 대표해 연락 주셔서 감사합니다. 아시다시피 Mansford Sports는 우리 지역의 여러 스포츠 관련 활동을 자랑스럽게 후원하고 있습니다. 요청하신 대로 학교구에 농구공 25개를 무료로 기꺼이 제공해 드리겠습니다. 4월 14일 목요일 오후 2시에 County Line Road에 있는 저희 본점에서 농구공을 가져가실 수 있습니다. 도착하시면 제 내선으로 연락 주시면 안내 데스크에서 만나 뵙겠습니다.\nAlair Collings 드림, 마케팅 이사, Mansford Sports", "g": {"to": ["전치사", "~로, ~에게 / ~하기 위해"], "juana": ["고유명사", "Juana(인명)"], "reza": ["고유명사", "Reza(인명)"], "juana.reza@delboroughschools.org": ["고유명사", "이메일 주소"], "from": ["전치사", "~로부터"], "alair": ["고유명사", "Alair(인명)"], "collings": ["고유명사", "Collings(인명)"], "acollings@mansfordsports.com": ["고유명사", "이메일 주소"], "re": ["전치사", "~에 관하여(회신)"], "donation": ["명사", "기부"], "date": ["명사", "날짜"], "august": ["명사", "8월"], "7": ["숫자", "7"], "dear": ["형용사", "~께(편지 인사)"], "ms": ["명사", "~씨(여성)"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신"], "for": ["전치사", "~을 위해, ~에 대해"], "contacting": ["동명사", "연락한 것", "contact"], "us": ["대명사", "우리를"], "on": ["전치사", "~에, ~로"], "behalf": ["명사", "대표, 대신"], "of": ["전치사", "~의"], "the": ["관사", "그"], "delborough": ["고유명사", "Delborough(지명)"], "school": ["명사", "학교"], "district": ["명사", "구, 지구"], "as": ["접속사", "~하듯이, ~대로"], "know": ["동사", "알다"], "mansford": ["고유명사", "Mansford(회사명)"], "sports": ["명사", "스포츠", "sport"], "is": ["동사", "~이다", "be"], "a": ["관사", "하나의"], "proud": ["형용사", "자랑스러운"], "supporter": ["명사", "후원자"], "many": ["형용사", "많은"], "sports-related": ["형용사", "스포츠 관련의"], "activities": ["명사", "활동", "activity"], "in": ["전치사", "~에, ~에서"], "our": ["대명사", "우리의"], "township": ["명사", "군구, 지역"], "we": ["대명사", "우리"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "happy": ["형용사", "기쁜"], "provide": ["동사", "제공하다"], "with": ["전치사", "~와 함께, ~로"], "25": ["숫자", "25"], "free": ["형용사", "무료의"], "basketballs": ["명사", "농구공", "basketball"], "requested": ["동사", "요청했다", "request"], "can": ["조동사", "~할 수 있다"], "pick": ["동사", "집다(pick up 수령하다)"], "up": ["부사", "위로(pick up)"], "main": ["형용사", "주된"], "store": ["명사", "매장"], "county": ["명사", "카운티, 군"], "line": ["고유명사", "Line(지명의 일부)"], "road": ["명사", "도로"], "thursday": ["명사", "목요일"], "april": ["명사", "4월"], "14": ["숫자", "14"], "at": ["전치사", "~에서"], "2": ["숫자", "2"], "p.m": ["명사", "오후"], "have": ["동사", "~하게 하다(사역)"], "my": ["대명사", "나의"], "extension": ["명사", "내선 번호"], "called": ["과거분사", "호출된", "call"], "when": ["접속사", "~할 때"], "arrive": ["동사", "도착하다"], "and": ["접속사", "그리고"], "i": ["대명사", "나"], "meet": ["동사", "만나다"], "front": ["형용사", "앞쪽의"], "desk": ["명사", "데스크"], "sincerely": ["부사", "진심으로(맺음말)"], "director": ["명사", "이사"], "marketing": ["명사", "마케팅"]}, "questions": [{"no": 147, "q": "What is the purpose of the e-mail?", "options": ["To ask for feedback", "To respond to a request", "To apologize for a mistake", "To promote a new product"], "answer": 1, "explain": "정답 (B) To respond to a request\n지문 개요: 스포츠 용품 회사의 마케팅 이사가 학교구의 기부 요청에 응해 농구공 25개를 제공하겠다고 알리며 수령 방법을 안내하는 이메일이다.\n정답 근거: 요청하신 대로 농구공 25개를 제공하겠다고 했으므로 요청에 답하는 것이 이메일의 목적이다.\n오답 분석: (A): 의견을 요청하는 내용이 없다. / (C): 실수에 대한 사과가 아니다. / (D): 신제품 홍보 내용이 없다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "e-mail": ["명사", "이메일"]}}, {"no": 148, "q": "According to the e-mail, what is likely to happen on April 14?", "options": ["Sports equipment will be given away.", "Mansford Sports will close early.", "A basketball game will be played.", "County Line Road will be closed to traffic."], "answer": 0, "explain": "정답 (A) Sports equipment will be given away.\n정답 근거: 4월 14일 오후 2시에 무료 농구공을 본점에서 수령하라고 했으므로 그날 스포츠 용품이 무상으로 전달된다.\n오답 분석: (B): 조기 폐점 언급이 없다. / (C): 농구 경기가 열린다는 내용이 없다. / (D): 도로 통제 언급이 없다.", "g": {"according": ["부사", "(according to) ~에 따르면", "accord"], "to": ["전치사", "(according to) ~에 따르면 / ~할"], "the": ["관사", "그"], "e-mail": ["명사", "이메일"], "what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "likely": ["형용사", "~할 것 같은"], "happen": ["동사", "일어나다"], "on": ["전치사", "~에, ~로"], "april": ["명사", "4월"], "14": ["숫자", "14"]}}], "vocab": "on behalf of 구 ~을 대표하 여 / donation 명 기부 / supporter 명 후원자 / township 명 (소)지역, 군구 / provide A with B 구 A에게 B를 제공하다 / pick up 구 가져가다, 수령하 다 / extension 명 내선 번호 / give away 구 무료로 주다 / promote 동 홍보하다 || Paraphrase: 147. We will be happy to provide ~ as you requested → respond to a request 148. pick up the 25 free basketballs ~ April 14 → sports equipment will be given away"}, {"range": "149-150", "sub": "기출독해 2회", "passage": "NOTICE\nOn Monday, 23 September, Constellation Internet Service will install a new, state-of-the-art system here at Bluestone Tower. Internet service will be down for much of the day. This means that residents will not be able to access the building’s wireless network, nor will it be possible for them to contact our management or maintenance staff by e-mail. Those who require access to the Internet between 9:00 A.M. and 5:00 P.M. on 23 September will need to make other arrangements. I apologize for the inconvenience.\nClaire Cho\nProperty Manager, Bluestone Tower", "tr": "공지\n9월 23일 월요일, Constellation Internet Service가 이곳 Bluestone Tower에 새로운 최신식 시스템을 설치합니다. 인터넷 서비스는 그날 대부분 중단됩니다. 이는 입주민이 건물의 무선 네트워크에 접속할 수 없고, 이메일로 관리실이나 유지 보수 직원에게 연락하는 것도 불가능하다는 뜻입니다. 9월 23일 오전 9시부터 오후 5시 사이에 인터넷 접속이 필요한 분들은 다른 조치를 마련하셔야 합니다. 불편을 드려 죄송합니다.\nClaire Cho, 자산 관리자, Bluestone Tower", "g": {"notice": ["명사", "공지"], "on": ["전치사", "~에, ~로"], "monday": ["명사", "월요일"], "23": ["숫자", "23"], "september": ["명사", "9월"], "constellation": ["고유명사", "Constellation(회사명)"], "internet": ["명사", "인터넷"], "service": ["명사", "서비스"], "will": ["조동사", "~할 것이다"], "install": ["동사", "설치하다"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "state-of-the-art": ["형용사", "최신식의"], "system": ["명사", "시스템"], "here": ["부사", "여기에"], "at": ["전치사", "~에서"], "bluestone": ["고유명사", "Bluestone(건물명)"], "tower": ["명사", "타워"], "be": ["동사", "~이다, 되다"], "down": ["형용사", "중단된"], "for": ["전치사", "~을 위해, ~에 대해"], "much": ["대명사", "대부분"], "of": ["전치사", "~의"], "the": ["관사", "그"], "day": ["명사", "날"], "this": ["대명사", "이것"], "means": ["동사", "의미하다", "mean"], "that": ["접속사", "~라는 것(명사절)"], "residents": ["명사", "주민", "resident"], "not": ["부사", "~이 아닌"], "able": ["형용사", "~할 수 있는"], "to": ["전치사", "~로, ~에게 / ~하기 위해"], "access": ["동사", "접속하다 / 접속"], "building’s": ["명사", "건물의", "building"], "wireless": ["형용사", "무선의"], "network": ["명사", "네트워크"], "nor": ["접속사", "~도 아니다"], "it": ["대명사", "그것"], "possible": ["형용사", "가능한"], "them": ["대명사", "그것들, 그들"], "contact": ["동사", "연락하다"], "our": ["대명사", "우리의"], "management": ["명사", "관리실"], "or": ["접속사", "또는"], "maintenance": ["명사", "유지 보수"], "staff": ["명사", "직원"], "by": ["전치사", "~까지, ~에 의해"], "e-mail": ["명사", "이메일"], "those": ["대명사", "~하는 사람들"], "who": ["관계사", "~하는 (사람)"], "require": ["동사", "필요로 하다"], "between": ["전치사", "~ 사이에"], "9:00": ["숫자", "9시"], "a.m": ["명사", "오전"], "and": ["접속사", "그리고"], "5:00": ["숫자", "5시"], "p.m": ["명사", "오후"], "need": ["동사", "필요하다"], "make": ["동사", "하다, 만들다"], "other": ["형용사", "다른"], "arrangements": ["명사", "조치, 준비", "arrangement"], "i": ["대명사", "나"], "apologize": ["동사", "사과하다"], "inconvenience": ["명사", "불편"], "claire": ["고유명사", "Claire(인명)"], "cho": ["고유명사", "Cho(인명)"], "property": ["명사", "자산, 부동산"], "manager": ["명사", "관리자"]}, "questions": [{"no": 149, "q": "For whom is the notice intended?", "options": ["Construction crews", "Internet providers", "Building residents", "Maintenance workers"], "answer": 2, "explain": "정답 (C) Building residents\n지문 개요: 건물 관리인이 새 인터넷 시스템 설치로 9월 23일 하루 대부분 인터넷이 중단된다는 사실과 대체 조치 필요성을 입주민에게 알리는 공지다.\n정답 근거: 입주민이 무선 네트워크에 접속할 수 없다는 점을 알리고 대비를 요구하고 있으므로 건물 입주민을 대상으로 한 공지다.\n오답 분석: (A): 공사 인력을 대상으로 한 안내가 아니다. / (B): 인터넷 업체는 작업을 수행하는 쪽이다. / (D): 유지 보수 직원은 연락이 닿지 않는 대상으로만 언급된다.", "g": {"for": ["전치사", "~을 위해, ~에 대해"], "whom": ["대명사", "누구"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "notice": ["명사", "공지"], "intended": ["과거분사", "의도된", "intend"]}}, {"no": 150, "q": "What does the notice suggest will happen at 5:00 P.M. on September 23?", "options": ["A new Web site will be launched.", "A new service charge will take effect.", "Access to a building will be restricted.", "Internet service will be restored."], "answer": 3, "explain": "정답 (D) Internet service will be restored.\n정답 근거: 오전 9시부터 오후 5시 사이에 접속이 필요하면 다른 방법을 마련하라고 했으므로 오후 5시 이후에는 서비스가 복구됨을 알 수 있다.\n오답 분석: (A): 새 웹사이트 개설 언급이 없다. / (B): 요금 부과에 관한 내용이 없다. / (C): 건물 출입 제한이 아니라 인터넷 중단이다.", "g": {"what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "the": ["관사", "그"], "notice": ["명사", "공지"], "suggest": ["동사", "암시하다"], "will": ["조동사", "~할 것이다"], "happen": ["동사", "일어나다"], "at": ["전치사", "~에서"], "5:00": ["숫자", "5시"], "p.m": ["명사", "오후"], "on": ["전치사", "~에, ~로"], "september": ["명사", "9월"], "23": ["숫자", "23"]}}], "vocab": "install 동 설치하다 / state-of-the-art 형 최신식 의 / resident 명 거주자, 입주민 / access 동/명 접속하다; 접속 / maintenance 명 유지 보수 / arrangement 명 조치, 준비 / inconvenience 명 불편 / intended for 구 ~을 대상으 로 한 / restore 동 복구하다 || Paraphrase: 149. residents will not be able to ~ → building residents (대상 독자) 150. down ~ between 9:00 A.M. and 5:00 P.M. → Internet service will be restored (5시 이후)"}, {"range": "151-152", "sub": "기출독해 2회", "passage": "Ann Daniels [11:00 A.M.] Hello, Kenneth. I just want to let you know that the latest surveys are being sent out to our customers today.\nKenneth Jutras [11:03 A.M.] Great! The last time we did a survey, we received high ratings for having a wide variety of items in stock, particularly our kitchen accessories and apparel. Our fitting rooms were described as cramped and cluttered, though.\nAnn Daniels [11:04 A.M.] Let’s see the ratings now that the remodeling has been completed. Management assured me that they would not cut corners.\nKenneth Jutras [11:05 A.M.] The fitting rooms do look very nice now.\nAnn Daniels [11:06 A.M.] That’s what I’ve heard. I haven’t seen them yet myself.\nKenneth Jutras [11:07 A.M.] Yesterday I walked through the entire place, from the jewelry area to electronics. It all looks great!", "tr": "Ann Daniels [오전 11:00] 안녕하세요, Kenneth. 최신 설문지가 오늘 고객들에게 발송된다는 것을 알려 드리려고요.\nKenneth Jutras [오전 11:03] 좋네요! 지난번 설문에서는 다양한 상품을 재고로 갖춘 점, 특히 주방용품과 의류에서 높은 평가를 받았어요. 하지만 탈의실은 비좁고 어수선하다는 평을 들었죠.\nAnn Daniels [오전 11:04] 개조가 끝났으니 이번 평가를 봅시다. 경영진은 대충 하지 않겠다고 저에게 장담했어요.\nKenneth Jutras [오전 11:05] 탈의실이 지금은 정말 좋아 보여요.\nAnn Daniels [오전 11:06] 저도 그렇게 들었어요. 아직 직접 보지는 못했지만요.\nKenneth Jutras [오전 11:07] 어제 보석 코너부터 전자제품까지 매장 전체를 둘러봤어요. 다 훌륭해 보여요!", "g": {"ann": ["고유명사", "Ann(인명)"], "daniels": ["고유명사", "Daniels(인명)"], "11:00": ["숫자", "11시"], "a.m": ["명사", "오전"], "hello": ["감탄사", "안녕하세요"], "kenneth": ["고유명사", "Kenneth(인명)"], "i": ["대명사", "나"], "just": ["부사", "그저"], "want": ["동사", "원하다"], "to": ["전치사", "~로, ~에게 / ~하기 위해"], "let": ["동사", "~하게 하다"], "you": ["대명사", "당신"], "know": ["동사", "알다"], "that": ["접속사", "~라는 것 / (now that) ~이므로"], "the": ["관사", "그"], "latest": ["형용사", "최신의"], "surveys": ["명사", "설문 조사", "survey"], "are": ["동사", "~이다", "be"], "being": ["현재분사", "~되고 있는", "be"], "sent": ["과거분사", "보내지는", "send"], "out": ["부사", "(send out) 발송하다"], "our": ["대명사", "우리의"], "customers": ["명사", "고객들", "customer"], "today": ["부사", "오늘"], "jutras": ["고유명사", "Jutras(인명)"], "11:03": ["숫자", "11시 3분"], "great": ["형용사", "훌륭한"], "last": ["형용사", "지난"], "time": ["명사", "시간"], "we": ["대명사", "우리"], "did": ["동사", "했다", "do"], "a": ["관사", "하나의"], "survey": ["명사", "설문 조사"], "received": ["동사", "받았다", "receive"], "high": ["형용사", "높은"], "ratings": ["명사", "평가", "rating"], "for": ["전치사", "~을 위해, ~에 대해"], "having": ["동명사", "갖추고 있는 것", "have"], "wide": ["형용사", "넓은"], "variety": ["명사", "다양성"], "of": ["전치사", "~의"], "items": ["명사", "물품", "item"], "in": ["전치사", "~에, ~에서"], "stock": ["명사", "재고"], "particularly": ["부사", "특히"], "kitchen": ["명사", "주방"], "accessories": ["명사", "용품", "accessory"], "and": ["접속사", "그리고"], "apparel": ["명사", "의류"], "fitting": ["명사", "옷 입어 보기"], "rooms": ["명사", "방", "room"], "were": ["동사", "~였다", "be"], "described": ["과거분사", "묘사된", "describe"], "as": ["전치사", "~로"], "cramped": ["형용사", "비좁은"], "cluttered": ["형용사", "어수선한"], "though": ["부사", "하지만"], "11:04": ["숫자", "11시 4분"], "let’s": ["동사", "~하자", "let"], "see": ["동사", "보다"], "now": ["부사", "지금"], "remodeling": ["명사", "개조 공사"], "has": ["조동사", "(완료) ~했다", "have"], "been": ["동사", "(완료형) ~였다, ~되었다", "be"], "completed": ["과거분사", "완료된", "complete"], "management": ["명사", "경영진"], "assured": ["동사", "장담했다", "assure"], "me": ["대명사", "나에게"], "they": ["대명사", "그들"], "would": ["조동사", "~할 것이다", "will"], "not": ["부사", "~이 아닌"], "cut": ["동사", "자르다(cut corners 대충 하다)"], "corners": ["명사", "모퉁이", "corner"], "11:05": ["숫자", "11시 5분"], "do": ["조동사", "(강조) 정말"], "look": ["동사", "~해 보이다"], "very": ["부사", "매우"], "nice": ["형용사", "좋은"], "11:06": ["숫자", "11시 6분"], "that’s": ["대명사", "그것이 ~이다", "that"], "what": ["관계사", "~하는 것"], "i’ve": ["대명사", "나는 ~했다", "I"], "heard": ["과거분사", "들은", "hear"], "haven’t": ["조동사", "~하지 않았다", "have"], "seen": ["과거분사", "본", "see"], "them": ["대명사", "그것들, 그들"], "yet": ["부사", "아직"], "myself": ["대명사", "나 자신이, 직접"], "11:07": ["숫자", "11시 7분"], "yesterday": ["부사", "어제"], "walked": ["동사", "걸었다", "walk"], "through": ["전치사", "~을 통해"], "entire": ["형용사", "전체의"], "place": ["명사", "곳, 장소"], "from": ["전치사", "~로부터"], "jewelry": ["명사", "보석류"], "area": ["명사", "구역"], "electronics": ["명사", "전자제품"], "it": ["대명사", "그것"], "all": ["대명사", "모두"], "looks": ["동사", "~해 보이다", "look"]}, "questions": [{"no": 151, "q": "For what type of business do the writers most likely work?", "options": ["A hotel", "A department store", "An interior design firm", "A shipping company"], "answer": 1, "explain": "정답 (B) A department store\n지문 개요: 두 직원이 새 고객 설문 발송 소식과 지난 설문 결과, 개조가 끝난 탈의실에 관해 주고받는 대화다.\n정답 근거: 주방용품, 의류, 보석, 전자제품 등 여러 상품군과 탈의실이 함께 언급되므로 백화점에서 일하는 것으로 볼 수 있다.\n오답 분석: (A): 객실이나 숙박 관련 내용이 없다. / (C): 개조는 자기 매장에서 이루어진 일이다. / (D): 배송 업무에 관한 언급이 없다.", "g": {"for": ["전치사", "~을 위해, ~에 대해"], "what": ["대명사", "무엇"], "type": ["명사", "유형"], "of": ["전치사", "~의"], "business": ["명사", "회사, 사업"], "do": ["조동사", "(의문문 조동사)"], "the": ["관사", "그"], "writers": ["명사", "글쓴이들", "writer"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "work": ["동사", "일하다"]}}, {"no": 152, "q": "At 11:06 A.M., what does Ms. Daniels most likely mean when she writes, “That’s what I’ve heard”?", "options": ["She is pleased with a company’s dress code.", "She knows that the customer surveys have been redesigned.", "She believes that the managers will make some changes.", "She understands that the fitting rooms have been improved."], "answer": 3, "explain": "정답 (D) She understands that the fitting rooms have been improved.\n정답 근거: 상대가 탈의실이 지금은 좋아 보인다고 말한 직후의 대답이고, 아직 직접 보지 못했다고 덧붙였으므로 개선되었다고 전해 들었다는 뜻이다.\n오답 분석: (A): 복장 규정에 관한 내용이 없다. / (B): 설문지 자체가 새로 설계되었다는 언급이 없다. / (C): 변화는 이미 끝난 개조를 가리키며 앞으로의 계획이 아니다.", "g": {"at": ["전치사", "~에서"], "11:06": ["숫자", "11시 6분"], "a.m": ["명사", "오전"], "what": ["관계사", "~하는 것"], "does": ["조동사", "(의문문 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "daniels": ["고유명사", "Daniels(인명)"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "mean": ["동사", "의미하다"], "when": ["접속사", "~할 때"], "she": ["대명사", "그녀"], "writes": ["동사", "쓰다", "write"], "that’s": ["대명사", "그것이 ~이다", "that"], "i’ve": ["대명사", "나는 ~했다", "I"], "heard": ["과거분사", "들은", "hear"]}}], "vocab": "survey 명 설문 조사 / rating 명 평가, 등급 / a variety of 구 다양한 / in stock 구 재고가 있는 / apparel 명 의류 / fitting room 명 탈의실 / cramped 형 비좁은 / cluttered 형 어수선한 / remodeling 명 개조 (공사) / cut corners 구 (돈·노력을) 아끼다, 대충 하다 / improve 동 개선되다 || Paraphrase: 151. kitchen accessories, apparel, jewelry, electronics → a department store 152. The fitting rooms do look very nice now → That’s what I’ve heard → the fitting rooms have been improved"}, {"range": "153-154", "sub": "기출독해 2회", "passage": "Fisko Odometer Recall\n12 April―Fisko Motors has recalled all models of its odometers in this year’s vehicles after more than 300 were reported to overcount the kilometers driven, according to a notice posted on the Automotive Product Commission Web site. Fisko Motors’ spokesperson, Toshiaki Murata, says the parts were recalled after his company received complaints from numerous customers. Vehicle owners who are concerned about whether their cars contain faulty odometers can visit www.fisko.uk/recall. There, they can enter their vehicle’s identification number to see if their vehicle is affected. A free replacement of the defective onboard software is available through most auto service centers.", "tr": "Fisko 주행 거리계 리콜\n4월 12일 ― 자동차 제품 위원회 웹사이트에 게시된 공지에 따르면, Fisko Motors는 300건이 넘는 주행 거리 과다 계산 신고가 접수된 뒤 올해 차량에 장착된 모든 모델의 주행 거리계를 리콜했다. Fisko Motors의 대변인 Toshiaki Murata는 다수의 고객에게서 불만이 접수된 후 부품을 리콜했다고 말한다. 자기 차량에 결함 있는 주행 거리계가 들어 있는지 걱정되는 차량 소유자는 www.fisko.uk/recall을 방문하면 된다. 그곳에서 차량 식별 번호를 입력해 자신의 차량이 해당되는지 확인할 수 있다. 결함이 있는 내장 소프트웨어의 무상 교체는 대부분의 자동차 서비스 센터에서 받을 수 있다.", "g": {"fisko": ["고유명사", "Fisko(회사명)"], "odometer": ["명사", "주행 거리계"], "recall": ["명사", "리콜"], "12": ["숫자", "12"], "april―fisko": ["고유명사", "4월 ― Fisko"], "motors": ["명사", "자동차 회사(Motors)", "motor"], "has": ["조동사", "(완료) ~했다", "have"], "recalled": ["과거분사", "리콜한", "recall"], "all": ["한정사", "모든"], "models": ["명사", "모델", "model"], "of": ["전치사", "~의"], "its": ["대명사", "그것의"], "odometers": ["명사", "주행 거리계", "odometer"], "in": ["전치사", "~에, ~에서"], "this": ["한정사", "이"], "year’s": ["명사", "해의", "year"], "vehicles": ["명사", "차량", "vehicle"], "after": ["접속사", "~한 후에"], "more": ["형용사", "더 많은"], "than": ["접속사", "~보다"], "300": ["숫자", "300"], "were": ["동사", "~였다", "be"], "reported": ["과거분사", "보고된", "report"], "to": ["전치사", "~로, ~에게 / ~하기 위해"], "overcount": ["동사", "초과 계산하다"], "the": ["관사", "그"], "kilometers": ["명사", "킬로미터", "kilometer"], "driven": ["과거분사", "주행된", "drive"], "according": ["부사", "(according to) ~에 따르면", "accord"], "a": ["관사", "하나의"], "notice": ["명사", "공지"], "posted": ["과거분사", "게시된", "post"], "on": ["전치사", "~에, ~로"], "automotive": ["형용사", "자동차의"], "product": ["명사", "제품"], "commission": ["명사", "위원회"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "spokesperson": ["명사", "대변인"], "toshiaki": ["고유명사", "Toshiaki(인명)"], "murata": ["고유명사", "Murata(인명)"], "says": ["동사", "말하다", "say"], "parts": ["명사", "부품", "part"], "his": ["대명사", "그의"], "company": ["명사", "회사"], "received": ["동사", "받았다", "receive"], "complaints": ["명사", "불만", "complaint"], "from": ["전치사", "~로부터"], "numerous": ["형용사", "많은"], "customers": ["명사", "고객들", "customer"], "vehicle": ["명사", "차량"], "owners": ["명사", "소유자", "owner"], "who": ["관계사", "~하는 (사람)"], "are": ["동사", "~이다", "be"], "concerned": ["형용사", "걱정하는"], "about": ["전치사", "~에 관해"], "whether": ["접속사", "~인지 아닌지"], "their": ["대명사", "그들의"], "cars": ["명사", "자동차", "car"], "contain": ["동사", "포함하다"], "faulty": ["형용사", "결함 있는"], "can": ["조동사", "~할 수 있다"], "visit": ["동사", "방문하다"], "www.fisko.uk/recall": ["고유명사", "웹 주소"], "there": ["부사", "그곳에서"], "they": ["대명사", "그들"], "enter": ["동사", "입력하다"], "vehicle’s": ["명사", "차량의", "vehicle"], "identification": ["명사", "식별"], "number": ["명사", "번호"], "see": ["동사", "보다"], "if": ["접속사", "~인지"], "is": ["동사", "~이다", "be"], "affected": ["과거분사", "영향을 받은", "affect"], "free": ["형용사", "무료의"], "replacement": ["명사", "교체"], "defective": ["형용사", "결함 있는"], "onboard": ["형용사", "내장된"], "software": ["명사", "소프트웨어"], "available": ["형용사", "이용 가능한"], "through": ["전치사", "~을 통해"], "most": ["한정사", "대부분의"], "auto": ["명사", "자동차"], "service": ["명사", "서비스"], "centers": ["명사", "센터", "center"]}, "questions": [{"no": 153, "q": "What does the article indicate about the odometers?", "options": ["Some of them use old technology.", "They do not measure accurately.", "Only 300 of them were recalled.", "They are produced by several companies."], "answer": 1, "explain": "정답 (B) They do not measure accurately.\n지문 개요: 주행 거리를 과다 계산하는 결함으로 자동차 회사가 주행 거리계를 리콜했으며, 차량 소유자가 확인하고 무상 교체받는 방법을 전하는 기사다.\n정답 근거: 주행 거리를 실제보다 많이 계산한다는 신고가 접수되었고 결함 있는 부품이라고 했으므로 정확하게 측정하지 못한다.\n오답 분석: (A): 오래된 기술이라는 언급이 없다. / (C): 300은 신고 건수이며 리콜 대상은 모든 모델이다. / (D): 여러 회사가 생산한다는 내용이 없다.", "g": {"what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "the": ["관사", "그"], "article": ["명사", "기사"], "indicate": ["동사", "나타내다"], "about": ["전치사", "~에 관해"], "odometers": ["명사", "주행 거리계", "odometer"]}}, {"no": 154, "q": "According to the article, what should concerned vehicle owners do first?", "options": ["Contact Mr. Murata", "Check a Web site", "Download some software", "Request a vehicle number"], "answer": 1, "explain": "정답 (B) Check a Web site\n정답 근거: 걱정되는 소유자는 우선 해당 웹사이트를 방문해 차량 식별 번호로 해당 여부를 확인하라고 안내한다.\n오답 분석: (A): 대변인에게 연락하라는 안내가 없다. / (C): 소프트웨어 교체는 서비스 센터에서 이루어진다. / (D): 차량 번호는 소유자가 이미 알고 입력하는 정보다.", "g": {"according": ["부사", "(according to) ~에 따르면", "accord"], "to": ["전치사", "(according to) ~에 따르면"], "the": ["관사", "그"], "article": ["명사", "기사"], "what": ["대명사", "무엇"], "should": ["조동사", "~해야 한다"], "concerned": ["형용사", "걱정하는"], "vehicle": ["명사", "차량"], "owners": ["명사", "소유자", "owner"], "do": ["동사", "하다"], "first": ["부사", "먼저"]}}], "vocab": "recall 동/명 리콜하다; 리콜 / odometer 명 주행 거리계 / overcount 동 초과 계산하다 / spokesperson 명 대변인 / complaint 명 불만 / numerous 형 많은 / faulty 형 결함 있는 / identification number 명 식별 번호 / replacement 명 교체(품) / defective 형 결함 있는 / accurately 부 정확하게 || Paraphrase: 153. overcount the kilometers driven faulty → do not measure accurately 154. can visit www.fisko.uk recall → check a Web site"}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r10-p5',$mkd${"id": "a2-r10-p5", "area": "RC", "part": 5, "group": "A급 과제", "series": 2, "round": 10, "level": "중급", "title": "A급 과제 10회 · PART 5 (어휘 5·6회)", "notes": [], "items": [{"no": 102, "q": "Concertgoers using public transportation should take either bus 47 _____ the blue-line light-rail to get to the arena.", "options": ["and", "both", "or", "but"], "answer": 2, "explain": "정답 (C) or\n해석: 대중교통을 이용하는 관람객은 경기장에 가려면 47번 버스나 블루라인 경전철을 타야 한다.\n정답 근거: 앞에 either가 있으므로 상관접속사 either A or B 구조를 이루는 or가 정답이다.\n오답 분석: (A) and: both A and B 형태로 쓰이며 either와 짝을 이루지 않는다. / (B) both: 접속사가 아니라 either와 함께 쓸 수 없다. / (D) but: 대조를 나타내며 either와 결합하지 않는다.", "translation": "대중교통을 이용하는 관람객은 경기장에 가려면 47번 버스나 블루라인 경전철을 타야 한다.", "vocab": "either A or B 구 A 또는 B / concertgoer 명 콘서트 관람객 / public transportation 명 대중교통 / arena 명 공연장, 경기장", "g": {"concertgoers": ["명사", "콘서트 관람객들", "concertgoer"], "using": ["현재분사", "이용하는", "use"], "public": ["형용사", "공공의"], "transportation": ["명사", "교통"], "should": ["조동사", "~해야 한다"], "take": ["동사", "타다"], "either": ["접속사", "A나 B(either~or)"], "bus": ["명사", "버스"], "47": ["숫자", "47"], "the": ["관사", "그"], "blue-line": ["형용사", "블루라인의"], "light-rail": ["명사", "경전철"], "to": ["to부정사", "~하기 위해"], "get": ["동사", "도착하다"], "arena": ["명사", "경기장"]}, "src": "1-"}, {"no": 105, "q": "To accommodate the high volume of business during the summer, the garden center is open _____ 9:00 P.M.", "options": ["below", "into", "until", "as"], "answer": 2, "explain": "정답 (C) until\n해석: 여름철 많은 이용객을 수용하기 위해 원예용품점은 오후 9시까지 문을 연다.\n정답 근거: 영업이 이어지는 시점의 끝을 나타내야 하므로 「~까지」를 뜻하는 until이 알맞다.\n오답 분석: (A) below: 수치의 아래를 뜻해 시각과 어울리지 않는다. / (B) into: 시간 속으로 이어짐을 뜻하지만 특정 시각과 결합하지 않는다. / (D) as: 접속사·전치사로 쓰이며 마감 시각을 나타내지 못한다.", "translation": "여름철 많은 이용객을 수용하기 위해 원예용품점은 오후 9시까지 문을 연다.", "vocab": "until 전 ~까지 (계속) / accommodate 동 수용하다 / high volume 명 많은 양 / business 명 영업, 거래", "g": {"to": ["to부정사", "~하기 위해"], "accommodate": ["동사", "수용하다"], "the": ["관사", "그"], "high": ["형용사", "많은, 높은"], "volume": ["명사", "양"], "of": ["전치사", "~의"], "business": ["명사", "영업, 거래"], "during": ["전치사", "~ 동안"], "summer": ["명사", "여름"], "garden": ["명사", "정원"], "center": ["명사", "센터, 점포"], "is": ["동사", "~이다", "be"], "open": ["형용사", "문을 연"], "9:00": ["숫자", "9시"], "p.m": ["부사", "오후"]}, "src": "1-"}, {"no": 109, "q": "Visitors arriving after 4 P.M. must contact the security office to be _____ to the building.", "options": ["admitted", "dismissed", "purchased", "addressed"], "answer": 0, "explain": "정답 (A) admitted\n해석: 오후 4시 이후 도착하는 방문객은 건물에 들어가려면 경비실에 연락해야 한다.\n정답 근거: 건물에 들여보내진다는 뜻이므로 「입장이 허용되다」를 뜻하는 admitted가 알맞다.\n오답 분석: (B) dismissed: '해산되다'. 입장과 뜻이 반대다. / (C) purchased: '구매되다'. 사람에게 쓸 수 없다. / (D) addressed: '다뤄지다'. 입장 허가를 뜻하지 않는다.", "translation": "오후 4시 이후 도착하는 방문객은 건물에 들어가려면 경비실에 연락해야 한다.", "vocab": "admit 동 입장을 허락하다 / dismiss 동 해산시키다 / security office 명 경비실 / contact 동 연락하다", "g": {"visitors": ["명사", "방문객들", "visitor"], "arriving": ["현재분사", "도착하는", "arrive"], "after": ["전치사", "~ 이후에"], "4": ["숫자", "4(시)"], "p.m": ["부사", "오후"], "must": ["조동사", "~해야 한다"], "contact": ["동사", "연락하다"], "the": ["관사", "그"], "security": ["명사", "보안"], "office": ["명사", "사무실"], "to": ["to부정사", "~하기 위해"], "be": ["동사", "(수동) ~되다"], "building": ["명사", "건물"]}, "src": "1-"}, {"no": 111, "q": "Mr. Cartegena _____ misses a board meeting, but last Friday he had a scheduling conflict.", "options": ["main", "seldom", "following", "when"], "answer": 1, "explain": "정답 (B) seldom\n해석: Cartegena 씨는 좀처럼 이사회에 빠지지 않지만 지난 금요일에는 일정이 겹쳤다.\n정답 근거: 뒤의 but 이하에서 예외 상황을 말하므로 평소에는 거의 빠지지 않는다는 뜻의 seldom이 알맞다.\n오답 분석: (A) main: 형용사라 동사를 꾸밀 수 없다. / (C) following: 분사·형용사여서 이 자리에 맞지 않는다. / (D) when: 접속사라 부사 자리에 올 수 없다.", "translation": "Cartegena 씨는 좀처럼 이사회에 빠지지 않지만 지난 금요일에는 일정이 겹쳤다.", "vocab": "seldom 부 좀처럼 ~ 않다 / board meeting 명 이사회 (회의) / scheduling conflict 명 일정 겹침 / miss 동 놓치다, 빠지다", "g": {"mr": ["명사", "~씨(남성)"], "cartegena": ["고유명사", "Cartegena(인명)"], "misses": ["동사", "놓치다, 빠지다", "miss"], "a": ["관사", "하나의"], "board": ["명사", "이사회"], "meeting": ["명사", "회의"], "but": ["접속사", "그러나"], "last": ["형용사", "지난"], "friday": ["고유명사", "금요일"], "he": ["대명사", "그"], "had": ["동사", "가졌다, 있었다", "have"], "scheduling": ["명사", "일정 잡기"], "conflict": ["명사", "충돌, 겹침"]}, "src": "1-"}, {"no": 112, "q": "Please call the company that placed the order for sesame noodles to make sure we recorded the delivery address _____.", "options": ["frequently", "simply", "correctly", "originally"], "answer": 2, "explain": "정답 (C) correctly\n해석: 배송 주소를 정확히 기록했는지 확인하기 위해 주문한 회사에 전화해 주십시오.\n정답 근거: 주소를 제대로 적었는지 확인한다는 뜻이므로 「정확히」를 뜻하는 correctly가 알맞다.\n오답 분석: (A) frequently: '자주'. 기록의 정확성과 무관하다. / (B) simply: '단순히'. 확인 취지와 맞지 않는다. / (D) originally: '원래'. 정확성을 나타내지 못한다.", "translation": "배송 주소를 정확히 기록했는지 확인하기 위해 주문한 회사에 전화해 주십시오.", "vocab": "correctly 부 정확하게 / place an order 구 주문하다 / record 동 기록하다 / make sure 구 확실히 하다", "g": {"please": ["부사", "부디, ~해 주세요"], "call": ["동사", "전화하다"], "the": ["관사", "그"], "company": ["명사", "회사"], "that": ["관계사", "~하는(주격)"], "placed": ["동사", "(주문을) 했다", "place"], "order": ["명사", "주문"], "for": ["전치사", "~에 대한"], "sesame": ["명사", "참깨"], "noodles": ["명사", "국수", "noodle"], "to": ["to부정사", "~하기 위해"], "make": ["동사", "하다(make sure)"], "sure": ["형용사", "확실한"], "we": ["대명사", "우리"], "recorded": ["동사", "기록했다", "record"], "delivery": ["명사", "배송"], "address": ["명사", "주소"]}, "src": "1-"}, {"no": 113, "q": "At Vanoy Automotive, only _____ technicians will be handling your vehicle.", "options": ["trained", "recent", "complete", "marked"], "answer": 0, "explain": "정답 (A) trained\n해석: Vanoy Automotive에서는 훈련받은 정비사만이 고객님의 차량을 다룹니다.\n정답 근거: 정비사의 자질을 강조하는 홍보 문구이므로 「훈련된」이 알맞다.\n오답 분석: (B) recent: '최근의'. 정비사를 꾸미기에 어색하다. / (C) complete: '완전한'. 사람을 꾸미기에 부적절하다. / (D) marked: '표시된'. 문맥과 무관하다.", "translation": "Vanoy Automotive에서는 훈련받은 정비사만이 고객님의 차량을 다룹니다.", "vocab": "trained 형 숙련된, 교육받은 / technician 명 기술자 / handle 동 다루다, 취급하다 / vehicle 명 차량", "g": {"at": ["전치사", "~에서"], "vanoy": ["고유명사", "Vanoy(상호)"], "automotive": ["고유명사", "Automotive(상호)"], "only": ["부사", "오직"], "technicians": ["명사", "기술자들", "technician"], "will": ["조동사", "~할 것이다"], "be": ["동사", "(진행형) ~하고 있다"], "handling": ["현재분사", "다루는", "handle"], "your": ["대명사", "당신의"], "vehicle": ["명사", "차량"]}, "src": "1-"}, {"no": 114, "q": "Ms. Li printed two copies of the bill, one to send out and the _____ to file.", "options": ["each", "few", "other", "them"], "answer": 2, "explain": "정답 (C) other\n해석: Li 씨는 청구서를 두 부 출력해 한 부는 발송용, 나머지 한 부는 보관용으로 했다.\n정답 근거: 둘 중 하나를 one으로 받았으므로 나머지 하나는 the other로 받아야 한다.\n오답 분석: (A) each: 관사 the와 함께 쓰이지 않는다. / (B) few: 복수를 뜻해 두 부 중 나머지 하나와 맞지 않는다. / (D) them: 목적격 대명사라 the 뒤에 올 수 없다.", "translation": "Li 씨는 청구서를 두 부 출력해 한 부는 발송용, 나머지 한 부는 보관용으로 했다.", "vocab": "one ~ the other 구 (둘 중) 하나는 ~ 나머지는 / bill 명 청구서 / file 동 (서류를) 보관하다 / send out 구 발송하다", "g": {"ms": ["명사", "~씨(여성)"], "li": ["고유명사", "Li(인명)"], "printed": ["동사", "출력했다", "print"], "two": ["숫자", "둘"], "copies": ["명사", "사본, 부", "copy"], "of": ["전치사", "~의"], "the": ["관사", "그"], "bill": ["명사", "청구서"], "one": ["대명사", "하나(는)"], "to": ["to부정사", "~할, ~하기 위한"], "send": ["동사", "보내다"], "out": ["부사", "밖으로(send out)"], "and": ["접속사", "그리고"], "file": ["동사", "(서류를) 보관하다"]}, "src": "1-"}, {"no": 115, "q": "As an investment banker, Mr. Shinohara has won awards for his _____ work for clients.", "options": ["severe", "estimated", "abnormal", "exceptional"], "answer": 3, "explain": "정답 (D) exceptional\n해석: 투자 은행가로서 Shinohara 씨는 고객을 위한 뛰어난 업무로 상을 받았다.\n정답 근거: 수상 이유가 되는 업무이므로 「뛰어난」을 뜻하는 exceptional이 알맞다.\n오답 분석: (A) severe: '심한'. 수상 사유로 부적절하다. / (B) estimated: '추정된'. 업무의 질을 나타내지 못한다. / (C) abnormal: '비정상적인'. 칭찬의 뜻이 아니다.", "translation": "투자 은행가로서 Shinohara 씨는 고객을 위한 뛰어난 업무로 상을 받았다.", "vocab": "exceptional 형 뛰어난, 탁월한 / investment banker 명 투자 은행가 / win an award 구 상을 받다 / severe 형 극심한", "g": {"as": ["전치사", "~로서"], "an": ["관사", "하나의"], "investment": ["명사", "투자"], "banker": ["명사", "은행가"], "mr": ["명사", "~씨(남성)"], "shinohara": ["고유명사", "Shinohara(인명)"], "has": ["조동사", "(현재완료) ~했다", "have"], "won": ["과거분사", "받은, 탄", "win"], "awards": ["명사", "상들", "award"], "for": ["전치사", "~에 대해, ~로"], "his": ["대명사", "그의"], "work": ["명사", "업무"], "clients": ["명사", "고객들", "client"]}, "src": "1-"}, {"no": 117, "q": "The keynote speaker will give a 40-minute speech and answer questions from the audience _____.", "options": ["of late", "behind", "alike", "afterward"], "answer": 3, "explain": "정답 (D) afterward\n해석: 기조연설자는 40분간 연설한 뒤 이어서 청중의 질문에 답할 것이다.\n정답 근거: 연설 다음에 질의응답이 이어진다는 순서를 나타내야 하므로 「그 뒤에」가 알맞다.\n오답 분석: (A) of late: '최근에'. 순서를 나타내지 못한다. / (B) behind: 위치를 뜻해 시간 순서를 표현하지 못한다. / (C) alike: '비슷하게'. 문맥과 무관하다.", "translation": "기조연설자는 40분간 연설한 뒤 이어서 청중의 질문에 답할 것이다.", "vocab": "afterward 부 그 후에 / keynote speaker 명 기조 연설자 / audience 명 청중 / give a speech 구 연설하다", "g": {"the": ["관사", "그"], "keynote": ["명사", "기조(연설)"], "speaker": ["명사", "연사"], "will": ["조동사", "~할 것이다"], "give": ["동사", "하다(연설을)"], "a": ["관사", "하나의"], "40-minute": ["형용사", "40분짜리의"], "speech": ["명사", "연설"], "and": ["접속사", "그리고"], "answer": ["동사", "답하다"], "questions": ["명사", "질문들", "question"], "from": ["전치사", "~로부터"], "audience": ["명사", "청중"]}, "src": "1-"}, {"no": 118, "q": "Chefs who care about _____ in the quality of their creations cook with Garden Gem Organic Butter.", "options": ["consistently", "consistent", "consistency", "consisting"], "answer": 2, "explain": "정답 (C) consistency\n해석: 자기 요리의 품질이 한결같기를 바라는 요리사들은 Garden Gem 유기농 버터로 요리한다.\n정답 근거: 전치사 about의 목적어 자리이므로 명사가 필요하고 품질의 「일관성」을 뜻하는 consistency가 알맞다.\n오답 분석: (A) consistently: 부사는 전치사의 목적어가 될 수 없다. / (B) consistent: 형용사도 목적어 자리에 올 수 없다. / (D) consisting: 분사는 이 자리에서 명사 역할을 하지 못한다.", "translation": "자기 요리의 품질이 한결같기를 바라는 요리사들은 Garden Gem 유기농 버터로 요리한다.", "vocab": "consistency 명 일관성 / consistent 형 일관된 / creation 명 창작물, 요리 / care about 구 ~을 중요시하다", "g": {"chefs": ["명사", "요리사들", "chef"], "who": ["관계사", "~하는(주격)"], "care": ["동사", "중요시하다"], "about": ["전치사", "~에 대해"], "in": ["전치사", "~에 있어서"], "the": ["관사", "그"], "quality": ["명사", "품질"], "of": ["전치사", "~의"], "their": ["대명사", "그들의"], "creations": ["명사", "창작물, 요리", "creation"], "cook": ["동사", "요리하다"], "with": ["전치사", "~와 함께, ~으로"], "garden": ["고유명사", "Garden(상표)"], "gem": ["고유명사", "Gem(상표)"], "organic": ["형용사", "유기농의"], "butter": ["명사", "버터"]}, "src": "1-"}, {"no": 119, "q": "_____ no one has been hired for the leadership liaison position, we need to reopen the search.", "options": ["Because", "Despite", "Also", "Unless"], "answer": 0, "explain": "정답 (A) Because\n해석: 리더십 연락 담당 자리에 아무도 채용되지 않았으므로 채용을 다시 시작해야 한다.\n정답 근거: 뒤에 절이 이어지며 채용을 재개하는 이유를 설명하므로 이유 접속사 Because가 알맞다.\n오답 분석: (B) Despite: 전치사라 뒤에 명사가 와야 한다. / (C) Also: 부사라 두 절을 연결하지 못한다. / (D) Unless: '~하지 않는 한'. 이유가 아니라 조건을 나타낸다.", "translation": "리더십 연락 담당 자리에 아무도 채용되지 않았으므로 채용을 다시 시작해야 한다.", "vocab": "because 접 ~ 때문에 / hire 동 고용하다 / liaison 명 연락 담당(자) / reopen 동 재개하다", "g": {"no": ["한정사", "어떤 ~도 아닌"], "one": ["대명사", "사람(no one 아무도)"], "has": ["조동사", "(현재완료) ~했다", "have"], "been": ["과거분사", "~였던(완료)", "be"], "hired": ["과거분사", "고용된", "hire"], "for": ["전치사", "~에, ~을 위해"], "the": ["관사", "그"], "leadership": ["명사", "리더십"], "liaison": ["명사", "연락 담당"], "position": ["명사", "직책"], "we": ["대명사", "우리"], "need": ["동사", "필요하다"], "to": ["to부정사", "~하는 것"], "reopen": ["동사", "다시 시작하다"], "search": ["명사", "(인재) 물색"]}, "src": "1-"}, {"no": 121, "q": "Oscar's Market recently _____ its international foods section to feature more than 100 new items.", "options": ["announced", "indicated", "expanded", "described"], "answer": 2, "explain": "정답 (C) expanded\n해석: Oscar's Market은 최근 100가지가 넘는 신제품을 갖추기 위해 수입 식품 코너를 확장했다.\n정답 근거: 신제품을 더 갖추기 위한 조치이므로 「확장했다」가 알맞다.\n오답 분석: (A) announced: '발표했다'. 코너를 목적어로 취하기에 어색하다. / (B) indicated: '나타냈다'. 문맥과 맞지 않는다. / (D) described: '설명했다'. 신제품 확충과 이어지지 않는다.", "translation": "Oscar's Market은 최근 100가지가 넘는 신제품을 갖추기 위해 수입 식품 코너를 확장했다.", "vocab": "expand 동 확장하다 / feature 동 특별히 포함하다 / section 명 코너, 구역 / recently 부 최근에", "g": {"oscar's": ["고유명사", "Oscar's(상호)"], "market": ["명사", "시장, 마켓"], "recently": ["부사", "최근에"], "its": ["대명사", "그것의"], "international": ["형용사", "국제적인, 수입의"], "foods": ["명사", "식품들", "food"], "section": ["명사", "코너, 구역"], "to": ["to부정사", "~하기 위해"], "feature": ["동사", "특별히 갖추다"], "more": ["부사", "더"], "than": ["접속사", "~보다"], "100": ["숫자", "100"], "new": ["형용사", "새로운"], "items": ["명사", "품목들", "item"]}, "src": "1-"}, {"no": 122, "q": "Most Maywood Electronics employees left early because of inclement weather _____ a few who helped close the store.", "options": ["already", "except for", "in case of", "equally"], "answer": 1, "explain": "정답 (B) except for\n해석: 궂은 날씨 때문에 Maywood Electronics 직원 대부분이 일찍 퇴근했으나 매장 마감을 도운 몇 명은 예외였다.\n정답 근거: 대부분이 퇴근했지만 일부는 남았다는 예외를 나타내야 하므로 「~을 제외하고」가 알맞다.\n오답 분석: (A) already: 부사라 뒤의 명사구를 이끌지 못한다. / (C) in case of: '~의 경우에'. 예외를 나타내지 못한다. / (D) equally: 부사여서 이 자리에 맞지 않는다.", "translation": "궂은 날씨 때문에 Maywood Electronics 직원 대부분이 일찍 퇴근했으나 매장 마감을 도운 몇 명은 예외였다.", "vocab": "except for 구 ~을 제외하고 / inclement weather 명 궂은 날씨 / in case of 구 ~의 경우에 (대비하여) / a few 구 몇몇 (사람)", "g": {"most": ["한정사", "대부분의"], "maywood": ["고유명사", "Maywood(상호)"], "electronics": ["명사", "전자제품"], "employees": ["명사", "직원들", "employee"], "left": ["동사", "떠났다", "leave"], "early": ["부사", "일찍"], "because": ["전치사", "~ 때문에"], "of": ["전치사", "~의"], "inclement": ["형용사", "궂은"], "weather": ["명사", "날씨"], "a": ["관사", "하나의"], "few": ["대명사", "몇몇(a few)"], "who": ["대명사", "누구"], "helped": ["동사", "도왔다", "help"], "close": ["동사", "닫다"], "the": ["관사", "그"], "store": ["명사", "매장"]}, "src": "1-"}, {"no": 123, "q": "At Carson Cargo, the sales representative with the highest earnings was awarded the largest travel _____ for the coming quarter.", "options": ["budget", "generosity", "customs", "collections"], "answer": 0, "explain": "정답 (A) budget\n해석: Carson Cargo에서는 실적이 가장 높은 영업 담당자에게 다음 분기 최대 출장 예산이 주어졌다.\n정답 근거: the largest의 수식을 받아 금액 규모를 나타내야 하므로 「예산」이 알맞다.\n오답 분석: (B) generosity: '너그러움'. 포상 대상이 되지 못한다. / (C) customs: '관세·관습'. 문맥과 무관하다. / (D) collections: '수집품'. 출장과 결합해 뜻을 이루지 못한다.", "translation": "Carson Cargo에서는 실적이 가장 높은 영업 담당자에게 다음 분기 최대 출장 예산이 주어졌다.", "vocab": "budget 명 예산 / sales representative 명 영업 사원 / earnings 명 수익, 실적 / award 동 수여하다", "g": {"at": ["전치사", "~에서"], "carson": ["고유명사", "Carson(상호)"], "cargo": ["고유명사", "Cargo(상호)"], "the": ["관사", "그"], "sales": ["명사", "영업, 판매"], "representative": ["명사", "담당자, 사원"], "with": ["전치사", "~와 함께, ~으로"], "highest": ["형용사", "가장 높은", "high"], "earnings": ["명사", "수익, 실적"], "was": ["동사", "~였다", "be"], "awarded": ["과거분사", "수여받은", "award"], "largest": ["형용사", "가장 큰", "large"], "travel": ["명사", "출장, 여행"], "for": ["전치사", "~을 위한"], "coming": ["형용사", "다가오는"], "quarter": ["명사", "분기"]}, "src": "1-"}, {"no": 124, "q": "_____ its effort to modernize its menu and dining experience, Hilltop Restaurant has hired chef Lucia Granato.", "options": ["As part of", "Even though", "In case", "In order to"], "answer": 0, "explain": "정답 (A) As part of\n해석: 메뉴와 식사 경험을 현대화하려는 노력의 일환으로 Hilltop 식당은 요리사 Lucia Granato를 채용했다.\n정답 근거: 뒤에 명사구가 오고 채용이 그 노력의 하나임을 나타내야 하므로 「~의 일환으로」가 알맞다.\n오답 분석: (B) Even though: 접속사라 뒤에 절이 와야 한다. / (C) In case: 접속사로 조건절을 이끔. / (D) In order to: 뒤에 동사원형이 와야 한다.", "translation": "메뉴와 식사 경험을 현대화하려는 노력의 일환으로 Hilltop 식당은 요리사 Lucia Granato를 채용했다.", "vocab": "as part of 구 ~의 일환으로 / modernize 동 현대화하다 / effort 명 노력 / dining 명 식사", "g": {"its": ["대명사", "그것의"], "effort": ["명사", "노력"], "to": ["to부정사", "~하려는"], "modernize": ["동사", "현대화하다"], "menu": ["명사", "메뉴"], "and": ["접속사", "그리고"], "dining": ["명사", "식사"], "experience": ["명사", "경험"], "hilltop": ["고유명사", "Hilltop(상호)"], "restaurant": ["명사", "식당"], "has": ["조동사", "(현재완료) ~했다", "have"], "hired": ["과거분사", "고용한", "hire"], "chef": ["명사", "요리사"], "lucia": ["고유명사", "Lucia(인명)"], "granato": ["고유명사", "Granato(인명)"]}, "src": "1-"}, {"no": 125, "q": "Training sessions on the new accounting software will be offered _____ the month.", "options": ["because of", "even so", "throughout", "including"], "answer": 2, "explain": "정답 (C) throughout\n해석: 새 회계 소프트웨어 교육이 그달 내내 제공될 것이다.\n정답 근거: 한 달 기간 전체에 걸쳐 진행된다는 뜻이므로 「~내내」를 뜻하는 throughout이 알맞다.\n오답 분석: (A) because of: 이유를 나타내 기간을 표현하지 못한다. / (B) even so: 접속부사라 명사를 이끌지 못한다. / (D) including: '~을 포함하여'. 기간 전체를 나타내지 못한다.", "translation": "새 회계 소프트웨어 교육이 그달 내내 제공될 것이다.", "vocab": "throughout 전 ~ 동안 내내 / training session 명 교육 (과정) / accounting 명 회계 / offer 동 제공하다", "g": {"training": ["명사", "교육"], "sessions": ["명사", "시간, 과정", "session"], "on": ["전치사", "~에, ~에 대해"], "the": ["관사", "그"], "new": ["형용사", "새로운"], "accounting": ["명사", "회계"], "software": ["명사", "소프트웨어"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "offered": ["과거분사", "제공되는", "offer"], "month": ["명사", "달"]}, "src": "1-"}, {"no": 126, "q": "All Lion's flooring is finished _____ thin strips of bamboo for beauty and durability.", "options": ["under", "near", "with", "at"], "answer": 2, "explain": "정답 (C) with\n해석: Lion's의 모든 바닥재는 아름다움과 내구성을 위해 얇은 대나무 조각으로 마감된다.\n정답 근거: 마감에 쓰이는 재료를 나타내야 하므로 수단·재료를 뜻하는 with가 알맞다.\n오답 분석: (A) under: 위치를 뜻해 재료를 나타내지 못한다. / (B) near: 근접을 뜻해 문맥과 맞지 않는다. / (D) at: 지점을 나타내 재료와 결합하지 않는다.", "translation": "Lion's의 모든 바닥재는 아름다움과 내구성을 위해 얇은 대나무 조각으로 마감된다.", "vocab": "with 전 ~으로 (재료·도구) / flooring 명 바닥재 / durability 명 내구성 / strip 명 가느다란 조각", "g": {"all": ["한정사", "모든"], "lion's": ["고유명사", "Lion's(상호)"], "flooring": ["명사", "바닥재"], "is": ["동사", "~이다", "be"], "finished": ["과거분사", "마감된", "finish"], "thin": ["형용사", "얇은"], "strips": ["명사", "가느다란 조각들", "strip"], "of": ["전치사", "~의"], "bamboo": ["명사", "대나무"], "for": ["전치사", "~을 위해"], "beauty": ["명사", "아름다움"], "and": ["접속사", "그리고"], "durability": ["명사", "내구성"]}, "src": "1-"}, {"no": 127, "q": "Each component of the JNL-113 must meet the required quality _____.", "options": ["issues", "standards", "tools", "pieces"], "answer": 1, "explain": "정답 (B) standards\n해석: JNL-113의 각 부품은 요구되는 품질 기준을 충족해야 한다.\n정답 근거: meet과 결합해 「기준을 충족하다」를 이루므로 standards가 알맞다.\n오답 분석: (A) issues: '문제'. 충족의 대상이 되지 못한다. / (C) tools: '도구'. 품질과 결합해 기준을 뜻하지 않는다. / (D) pieces: '조각'. 문맥과 맞지 않는다.", "translation": "JNL-113의 각 부품은 요구되는 품질 기준을 충족해야 한다.", "vocab": "standard 명 기준, 표준 / component 명 부품 / meet 동 (기준을) 충족하다 / required 형 요구되는", "g": {"each": ["한정사", "각각의"], "component": ["명사", "부품"], "of": ["전치사", "~의"], "the": ["관사", "그"], "jnl-113": ["고유명사", "JNL-113(제품명)"], "must": ["조동사", "~해야 한다"], "meet": ["동사", "충족하다"], "required": ["형용사", "요구되는"], "quality": ["명사", "품질"]}, "src": "1-"}, {"no": 128, "q": "Candidates must have at least one year of experience to be eligible _____ the position.", "options": ["for", "from", "on", "by"], "answer": 0, "explain": "정답 (A) for\n해석: 지원자는 그 자리에 지원할 자격을 갖추려면 최소 1년의 경력이 있어야 한다.\n정답 근거: be eligible for는 「~에 대한 자격이 있다」를 뜻하는 결합이므로 for가 정답이다.\n오답 분석: (B) from: 출처를 나타내 이 결합에 쓰이지 않는다. / (C) on: 자격 표현과 결합하지 않는다. / (D) by: 수단·기한을 뜻해 문맥과 맞지 않는다.", "translation": "지원자는 그 자리에 지원할 자격을 갖추려면 최소 1년의 경력이 있어야 한다.", "vocab": "be eligible for 구 ~에 대한 자격이 있다 / candidate 명 지원자, 후보 / at least 구 최소한 / position 명 직책", "g": {"candidates": ["명사", "지원자들", "candidate"], "must": ["조동사", "~해야 한다"], "have": ["동사", "가지다"], "at": ["전치사", "(at least) 최소한"], "least": ["부사", "(at least) 최소한"], "one": ["숫자", "하나"], "year": ["명사", "해, 년"], "of": ["전치사", "~의"], "experience": ["명사", "경력"], "to": ["to부정사", "~하기 위해"], "be": ["동사", "~이다, 되다"], "eligible": ["형용사", "자격이 있는"], "the": ["관사", "그"], "position": ["명사", "직책"]}, "src": "1-"}, {"no": 130, "q": "The Crowkeepers' second album, Non Attachment, sold well on the _____ of the band's first hit record.", "options": ["strength", "time", "people", "money"], "answer": 0, "explain": "정답 (A) strength\n해석: Crowkeepers의 두 번째 앨범 Non Attachment는 밴드의 첫 히트작에 힘입어 잘 팔렸다.\n정답 근거: on the strength of는 「~에 힘입어」를 뜻하는 관용 표현이다.\n오답 분석: (B) time: 이 표현을 이루지 못한다. / (C) people: 판매의 근거를 나타내지 못한다. / (D) money: 문맥과 맞지 않는다.", "translation": "Crowkeepers의 두 번째 앨범 Non Attachment는 밴드의 첫 히트작에 힘입어 잘 팔렸다.", "vocab": "on the strength of 구 ~에 힘입어 / sell well 구 잘 팔리다 / hit record 명 히트 음반 / album 명 앨범", "g": {"the": ["관사", "그"], "crowkeepers'": ["고유명사", "Crowkeepers의"], "second": ["형용사", "두 번째의"], "album": ["명사", "앨범"], "non": ["고유명사", "Non(앨범명)"], "attachment": ["고유명사", "Attachment(앨범명)"], "sold": ["동사", "팔렸다", "sell"], "well": ["부사", "잘"], "on": ["전치사", "~에, ~에 대해"], "of": ["전치사", "~의"], "band's": ["명사", "밴드의", "band"], "first": ["형용사", "첫 번째의"], "hit": ["형용사", "히트한"], "record": ["명사", "음반"]}, "src": "1-"}, {"no": 102, "q": "Corso Athletic's newest running shoes feature a _____ design and bright colors.", "options": ["direct", "steady", "slow", "simple"], "answer": 3, "explain": "정답 (D) simple\n해석: Corso Athletic의 최신 러닝화는 단순한 디자인과 밝은 색상을 특징으로 한다.\n정답 근거: 밝은 색상과 나란히 제품의 디자인 특징을 나타내야 하므로 「단순한」이 알맞다.\n오답 분석: (A) direct: '직접적인'. 디자인을 꾸미기에 어색하다. / (B) steady: '꾸준한'. 디자인의 성격을 나타내지 못한다. / (C) slow: '느린'. 디자인과 결합하지 않는다.", "translation": "Corso Athletic의 최신 러닝화는 단순한 디자인과 밝은 색상을 특징으로 한다.", "vocab": "simple 형 단순한, 심플한 / feature 동 특징으로 하다 / design 명 디자인 / steady 형 꾸준한", "sub": "어휘 6회", "g": {"corso": ["고유명사", "Corso(상호)"], "athletic's": ["고유명사", "Athletic의(상호)"], "newest": ["형용사", "최신의", "new"], "running": ["명사", "달리기"], "shoes": ["명사", "신발", "shoe"], "feature": ["동사", "특징으로 하다"], "a": ["관사", "하나의"], "design": ["명사", "디자인"], "and": ["접속사", "그리고"], "bright": ["형용사", "밝은"], "colors": ["명사", "색상들", "color"]}, "src": "2-"}, {"no": 104, "q": "Geoff Flooring has been serving Punellas County for _____ 100 years.", "options": ["proudly", "nearly", "normally", "finally"], "answer": 1, "explain": "정답 (B) nearly\n해석: Geoff Flooring은 거의 100년간 Punellas 카운티에 서비스를 제공해 왔다.\n정답 근거: 수치 100 years를 앞에서 꾸며 근사치를 나타내야 하므로 「거의」가 알맞다.\n오답 분석: (A) proudly: '자랑스럽게'. 수치를 수식하지 못한다. / (C) normally: '보통'. 기간을 꾸미기에 어색하다. / (D) finally: '마침내'. 문맥과 맞지 않는다.", "translation": "Geoff Flooring은 거의 100년간 Punellas 카운티에 서비스를 제공해 왔다.", "vocab": "nearly 부 거의 / serve 동 (서비스를) 제공하다 / normally 부 보통 / county 명 (행정구역) 군", "sub": "어휘 6회", "g": {"geoff": ["고유명사", "Geoff(상호)"], "flooring": ["고유명사", "Flooring(상호)"], "has": ["조동사", "(현재완료) ~했다", "have"], "been": ["과거분사", "~였던(완료)", "be"], "serving": ["현재분사", "서비스를 제공하는", "serve"], "punellas": ["고유명사", "Punellas(지명)"], "county": ["명사", "카운티, 군"], "for": ["전치사", "~ 동안"], "100": ["숫자", "100"], "years": ["명사", "년", "year"]}, "src": "2-"}, {"no": 106, "q": "This month, OStento Promotions is _____ 15 percent off the price of its premier advertising package.", "options": ["producing", "encouraging", "solving", "offering"], "answer": 3, "explain": "정답 (D) offering\n해석: 이번 달 OStento Promotions는 최상위 광고 패키지 가격에서 15퍼센트 할인을 제공하고 있다.\n정답 근거: 할인을 목적어로 취해 고객에게 제공한다는 뜻이므로 offering이 알맞다.\n오답 분석: (A) producing: '생산하다'. 할인을 목적어로 취하기에 어색하다. / (B) encouraging: '장려하다'. 할인과 결합하지 않는다. / (C) solving: '해결하다'. 문맥과 무관하다.", "translation": "이번 달 OStento Promotions는 최상위 광고 패키지 가격에서 15퍼센트 할인을 제공하고 있다.", "vocab": "offer 동 (할인을) 제공하다 / premier 형 최고의 / advertising 명 광고 / percent off 구 ~퍼센트 할인", "sub": "어휘 6회", "g": {"this": ["한정사", "이"], "month": ["명사", "달"], "ostento": ["고유명사", "OStento(상호)"], "promotions": ["고유명사", "Promotions(상호)"], "is": ["동사", "~이다", "be"], "15": ["숫자", "15"], "percent": ["명사", "퍼센트"], "off": ["전치사", "~에서 할인된"], "the": ["관사", "그"], "price": ["명사", "가격"], "of": ["전치사", "~의"], "its": ["대명사", "그것의"], "premier": ["형용사", "최고의"], "advertising": ["명사", "광고"], "package": ["명사", "패키지, 상품"]}, "src": "2-"}, {"no": 108, "q": "Customers who arrive at Mila's Cafe _____ bicycle receive a free coffee.", "options": ["as", "by", "in", "for"], "answer": 1, "explain": "정답 (B) by\n해석: 자전거를 타고 Mila's Cafe에 오는 손님은 무료 커피를 받는다.\n정답 근거: 교통수단을 나타낼 때는 「by + 무관사 명사」 형태를 쓰므로 by가 정답이다.\n오답 분석: (A) as: '~로서'. 교통수단을 나타내지 못한다. / (C) in: 관사와 함께 특정 차량을 가리킬 때 쓰인다. / (D) for: 목적을 나타내 문맥과 맞지 않는다.", "translation": "자전거를 타고 Mila's Cafe에 오는 손님은 무료 커피를 받는다.", "vocab": "by + 교통수단 구 ~을 타고 / receive 동 받다 / free 형 무료의 / arrive 동 도착하다", "sub": "어휘 6회", "g": {"customers": ["명사", "고객들", "customer"], "who": ["관계사", "~하는(주격)"], "arrive": ["동사", "도착하다"], "at": ["전치사", "~에서"], "mila's": ["고유명사", "Mila's(상호)"], "cafe": ["명사", "카페"], "bicycle": ["명사", "자전거"], "receive": ["동사", "받다"], "a": ["관사", "하나의"], "free": ["형용사", "무료의"], "coffee": ["명사", "커피"]}, "src": "2-"}, {"no": 111, "q": "All Delconom employees are _____ to attend a training session on the new e-mail system tomorrow.", "options": ["considered", "indicated", "required", "insisted"], "answer": 2, "explain": "정답 (C) required\n해석: Delconom 전 직원은 내일 새 이메일 시스템 교육에 참석해야 한다.\n정답 근거: be required to do는 「~하도록 요구되다」를 뜻하므로 의무를 나타내는 문맥에 맞다.\n오답 분석: (A) considered: 뒤에 to부정사를 취해 의무를 나타내지 않는다. / (B) indicated: 사람을 주어로 하는 이 구조에 쓰이지 않는다. / (D) insisted: 수동태로 사람을 주어로 삼지 않는다.", "translation": "Delconom 전 직원은 내일 새 이메일 시스템 교육에 참석해야 한다.", "vocab": "be required to do 구 ~해야 한다 / attend 동 참석하다 / training session 명 교육 (과정) / insist 동 주장하다", "sub": "어휘 6회", "g": {"all": ["한정사", "모든"], "delconom": ["고유명사", "Delconom(회사명)"], "employees": ["명사", "직원들", "employee"], "are": ["동사", "~이다", "be"], "to": ["to부정사", "~하도록"], "attend": ["동사", "참석하다"], "a": ["관사", "하나의"], "training": ["명사", "교육"], "session": ["명사", "시간, 과정"], "on": ["전치사", "~에, ~에 대해"], "the": ["관사", "그"], "new": ["형용사", "새로운"], "e-mail": ["명사", "이메일"], "system": ["명사", "시스템"], "tomorrow": ["부사", "내일"]}, "src": "2-"}, {"no": 114, "q": "Filmmakers must hire traffic control workers to minimize disruption to _____ business.", "options": ["ready", "convenient", "pleasant", "nearby"], "answer": 3, "explain": "정답 (D) nearby\n해석: 영화 제작자는 인근 상점에 대한 방해를 최소화하기 위해 교통 통제 인력을 고용해야 한다.\n정답 근거: 촬영 현장 주변의 상점을 뜻해야 하므로 「인근의」가 알맞다.\n오답 분석: (A) ready: '준비된'. 상점을 꾸미기에 어색하다. / (B) convenient: '편리한'. 방해 대상을 특정하지 못한다. / (C) pleasant: '쾌적한'. 문맥과 맞지 않는다.", "translation": "영화 제작자는 인근 상점에 대한 방해를 최소화하기 위해 교통 통제 인력을 고용해야 한다.", "vocab": "nearby 형 인근의 / minimize 동 최소화하다 / disruption 명 지장, 방해 / filmmaker 명 영화 제작자", "sub": "어휘 6회", "g": {"filmmakers": ["명사", "영화 제작자들", "filmmaker"], "must": ["조동사", "~해야 한다"], "hire": ["동사", "고용하다"], "traffic": ["명사", "교통"], "control": ["명사", "통제"], "workers": ["명사", "인력, 근로자들", "worker"], "to": ["to부정사", "~하기 위해 / ~에 대한"], "minimize": ["동사", "최소화하다"], "disruption": ["명사", "지장, 방해"], "business": ["명사", "업체, 상점"]}, "src": "2-"}, {"no": 115, "q": "The renovation of the museum will be completed in _____ six weeks.", "options": ["early", "under", "major", "through"], "answer": 1, "explain": "정답 (B) under\n해석: 박물관 보수 공사는 6주가 채 안 되어 완료될 것이다.\n정답 근거: 기간을 앞에서 꾸며 「~이내에」라는 뜻을 만들어야 하므로 under가 알맞다.\n오답 분석: (A) early: 기간 앞에서 이런 뜻을 만들지 못한다. / (C) major: 형용사라 기간 수식에 부적절하다. / (D) through: '~내내'. in과 함께 쓰이지 않는다.", "translation": "박물관 보수 공사는 6주가 채 안 되어 완료될 것이다.", "vocab": "under 전 (기간·수량이) ~ 미만인 / renovation 명 개조 (공사) / complete 동 완료하다 / in + 기간 구 ~ 후에, ~ 안에", "sub": "어휘 6회", "g": {"the": ["관사", "그"], "renovation": ["명사", "보수 공사"], "of": ["전치사", "~의"], "museum": ["명사", "박물관"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "completed": ["과거분사", "완료된", "complete"], "in": ["전치사", "~ 만에, ~ 후에"], "six": ["숫자", "6"], "weeks": ["명사", "주", "week"]}, "src": "2-"}, {"no": 116, "q": "Zornix Commodities is seeking a systems analyst _____ two years of experience writing programs for online retailers.", "options": ["since", "along", "among", "with"], "answer": 3, "explain": "정답 (D) with\n해석: Zornix Commodities는 온라인 소매업체용 프로그램 작성 경력 2년을 갖춘 시스템 분석가를 찾고 있다.\n정답 근거: 구하는 사람이 갖춘 조건을 나타내야 하므로 「~을 갖춘」을 뜻하는 with가 알맞다.\n오답 분석: (A) since: 시점을 나타내 자격 조건을 표현하지 못한다. / (B) along: 뒤에 with 없이 명사를 이끌지 못한다. / (C) among: '~중에'. 자격 조건을 나타내지 못한다.", "translation": "Zornix Commodities는 온라인 소매업체용 프로그램 작성 경력 2년을 갖춘 시스템 분석가를 찾고 있다.", "vocab": "with + 경력 구 ~을 갖춘 / seek 동 찾다, 구하다 / analyst 명 분석가 / retailer 명 소매업체", "sub": "어휘 6회", "g": {"zornix": ["고유명사", "Zornix(회사명)"], "commodities": ["고유명사", "회사명 일부"], "is": ["동사", "~이다", "be"], "seeking": ["현재분사", "찾고 있는", "seek"], "a": ["관사", "하나의"], "systems": ["명사", "시스템"], "analyst": ["명사", "분석가"], "two": ["숫자", "둘"], "years": ["명사", "년", "year"], "of": ["전치사", "~의"], "experience": ["명사", "경력"], "writing": ["동명사", "작성하는 것", "write"], "programs": ["명사", "프로그램들", "program"], "for": ["전치사", "~을 위한"], "online": ["형용사", "온라인의"], "retailers": ["명사", "소매업체들", "retailer"]}, "src": "2-"}, {"no": 118, "q": "In the event of rain, the holiday parade scheduled for March 2 will be held on March 3 _____.", "options": ["instead", "likewise", "considering", "indeed"], "answer": 0, "explain": "정답 (A) instead\n해석: 비가 올 경우 3월 2일로 예정된 축제 행진은 대신 3월 3일에 열린다.\n정답 근거: 원래 날짜 대신 다른 날에 열린다는 뜻이므로 「대신에」를 뜻하는 instead가 알맞다.\n오답 분석: (B) likewise: '마찬가지로'. 대체 관계를 나타내지 못한다. / (C) considering: 전치사·분사라 뒤에 명사가 필요하다. / (D) indeed: '정말로'. 문맥과 맞지 않는다.", "translation": "비가 올 경우 3월 2일로 예정된 축제 행진은 대신 3월 3일에 열린다.", "vocab": "instead 부 대신에 / in the event of 구 ~할 경우에 / hold 동 개최하다 / likewise 부 마찬가지로", "sub": "어휘 6회", "g": {"in": ["전치사", "~에서, ~에"], "the": ["관사", "그"], "event": ["명사", "경우(~할 경우에)"], "of": ["전치사", "~의"], "rain": ["명사", "비"], "holiday": ["명사", "휴일, 축제"], "parade": ["명사", "퍼레이드, 행진"], "scheduled": ["과거분사", "예정된", "schedule"], "for": ["전치사", "~로"], "march": ["고유명사", "3월"], "2": ["숫자", "2"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "held": ["과거분사", "개최되는", "hold"], "on": ["전치사", "~에, ~에 대해"], "3": ["숫자", "3"]}, "src": "2-"}, {"no": 120, "q": "Ms. Raven would _____ postpone the client meeting until all relevant documents have been reviewed.", "options": ["less", "either", "yet", "rather"], "answer": 3, "explain": "정답 (D) rather\n해석: Raven 씨는 관련 서류가 모두 검토될 때까지 고객 회의를 미루는 편을 택할 것이다.\n정답 근거: would rather + 동사원형은 「차라리 ~하겠다」를 뜻하므로 rather가 정답이다.\n오답 분석: (A) less: 이 구조를 이루지 못한다. / (B) either: 상관접속사로 쓰이며 조동사 뒤에 오지 않는다. / (C) yet: 부정문·의문문에서 주로 쓰여 문맥과 맞지 않는다.", "translation": "Raven 씨는 관련 서류가 모두 검토될 때까지 고객 회의를 미루는 편을 택할 것이다.", "vocab": "would rather 구 차라리 ~하겠다 / postpone 동 연기하다 / relevant 형 관련된 / review 동 검토하다", "sub": "어휘 6회", "g": {"ms": ["명사", "~씨(여성)"], "raven": ["고유명사", "Raven(인명)"], "would": ["조동사", "차라리 ~하겠다"], "postpone": ["동사", "연기하다"], "the": ["관사", "그"], "client": ["명사", "고객"], "meeting": ["명사", "회의"], "until": ["접속사", "~할 때까지"], "all": ["한정사", "모든"], "relevant": ["형용사", "관련된"], "documents": ["명사", "서류들", "document"], "have": ["조동사", "(현재완료) ~되었다"], "been": ["과거분사", "~였던(완료)", "be"], "reviewed": ["과거분사", "검토된", "review"]}, "src": "2-"}, {"no": 122, "q": "To _____ exceptional quality, Grayson's Goods' items are produced in limited numbers.", "options": ["ensure", "apply", "confirm", "arrange"], "answer": 0, "explain": "정답 (A) ensure\n해석: 뛰어난 품질을 보장하기 위해 Grayson's Goods의 제품은 한정 수량으로 생산된다.\n정답 근거: 품질을 목적어로 취해 「보장하다」를 뜻해야 하므로 ensure가 알맞다.\n오답 분석: (B) apply: '적용하다'. 품질을 목적어로 취하기에 어색하다. / (C) confirm: '확인하다'. 이미 있는 사실을 확인할 때 쓰인다. / (D) arrange: '준비하다'. 품질과 결합하지 않는다.", "translation": "뛰어난 품질을 보장하기 위해 Grayson's Goods의 제품은 한정 수량으로 생산된다.", "vocab": "ensure 동 보장하다 / exceptional 형 뛰어난 / limited 형 한정된 / confirm 동 확인해 주다", "sub": "어휘 6회", "g": {"to": ["to부정사", "~하기 위해"], "exceptional": ["형용사", "뛰어난"], "quality": ["명사", "품질"], "grayson's": ["고유명사", "Grayson's(상호)"], "goods'": ["고유명사", "Goods의(상호)"], "items": ["명사", "제품들", "item"], "are": ["동사", "~이다", "be"], "produced": ["과거분사", "생산되는", "produce"], "in": ["전치사", "~에서, ~에"], "limited": ["형용사", "한정된"], "numbers": ["명사", "수량", "number"]}, "src": "2-"}, {"no": 123, "q": "The film At All Hours _____ depicts the inner workings of the banking world.", "options": ["brilliant", "brilliance", "brilliantly", "most brilliant"], "answer": 2, "explain": "정답 (C) brilliantly\n해석: 영화 At All Hours는 은행업계의 내부 사정을 훌륭하게 묘사한다.\n정답 근거: 주어와 동사 depicts 사이이고 뒤에 목적어가 이미 있으므로 동사를 꾸미는 부사 자리다.\n오답 분석: (A) brilliant: 형용사는 동사를 꾸밀 수 없다. / (B) brilliance: 명사는 이 자리에 들어갈 수 없다. / (D) most brilliant: 최상급 형용사도 동사를 수식하지 못한다.", "translation": "영화 At All Hours는 은행업계의 내부 사정을 훌륭하게 묘사한다.", "vocab": "brilliantly 부 훌륭하게 / depict 동 묘사하다 / inner workings 명 내부 작동 방식 / brilliance 명 탁월함", "sub": "어휘 6회", "g": {"the": ["관사", "그"], "film": ["명사", "영화"], "at": ["전치사", "~에서"], "all": ["한정사", "모든"], "hours": ["명사", "시간들(영화 제목 일부)", "hour"], "depicts": ["동사", "묘사하다", "depict"], "inner": ["형용사", "내부의"], "workings": ["명사", "작동 방식", "working"], "of": ["전치사", "~의"], "banking": ["명사", "은행업"], "world": ["명사", "세계, ~계"]}, "src": "2-"}, {"no": 124, "q": "_____ the information on the city's Web site, the swimming pool is now open until 9 P.M.", "options": ["Provided that", "Even though", "As long as", "Contrary to"], "answer": 3, "explain": "정답 (D) Contrary to\n해석: 시 웹사이트의 정보와 달리 수영장은 이제 오후 9시까지 운영한다.\n정답 근거: 뒤에 명사구가 오므로 전치사구가 필요하고, 웹사이트 정보와 다르다는 대조를 나타내야 한다.\n오답 분석: (A) Provided that: 접속사라 뒤에 절이 와야 한다. / (B) Even though: 접속사도 절이 필요하다. / (C) As long as: 조건 접속사라 절을 이끔.", "translation": "시 웹사이트의 정보와 달리 수영장은 이제 오후 9시까지 운영한다.", "vocab": "contrary to 구 ~과 반대로 / provided that 구 ~라는 조건이라면 / as long as 구 ~하는 한 / information 명 정보", "sub": "어휘 6회", "g": {"the": ["관사", "그"], "information": ["명사", "정보"], "on": ["전치사", "~에, ~에 대해"], "city's": ["명사", "시의", "city"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "swimming": ["명사", "수영"], "pool": ["명사", "수영장"], "is": ["동사", "~이다", "be"], "now": ["부사", "이제"], "open": ["형용사", "문을 연, 운영하는"], "until": ["전치사", "~까지"], "9": ["숫자", "9(시)"], "p.m": ["부사", "오후"]}, "src": "2-"}, {"no": 126, "q": "Jellaville's Chamber of Commerce has initiated plans to develop the historic waterfront into a viable tourist _____.", "options": ["destination", "population", "method", "stage"], "answer": 0, "explain": "정답 (A) destination\n해석: Jellaville 상공회의소는 역사적인 해안가를 실현 가능한 관광지로 개발할 계획에 착수했다.\n정답 근거: tourist와 결합해 「관광지」를 뜻해야 하므로 destination이 알맞다.\n오답 분석: (B) population: '인구'. 개발 대상이 되지 못한다. / (C) method: '방법'. 장소를 뜻하지 않는다. / (D) stage: '단계·무대'. 관광지를 나타내지 못한다.", "translation": "Jellaville 상공회의소는 역사적인 해안가를 실현 가능한 관광지로 개발할 계획에 착수했다.", "vocab": "destination 명 (관광)지, 목적지 / viable 형 실행 가능한 / initiate 동 시작하다 / Chamber of Commerce 명 상공회의소", "sub": "어휘 6회", "g": {"jellaville's": ["고유명사", "Jellaville의(지명)"], "chamber": ["명사", "회의소(상공회의소)"], "of": ["전치사", "~의"], "commerce": ["명사", "상업"], "has": ["조동사", "(현재완료) ~했다", "have"], "initiated": ["과거분사", "시작한", "initiate"], "plans": ["명사", "계획들", "plan"], "to": ["to부정사", "~하는"], "develop": ["동사", "개발하다"], "the": ["관사", "그"], "historic": ["형용사", "역사적인"], "waterfront": ["명사", "해안가, 물가"], "into": ["전치사", "~ 안으로"], "a": ["관사", "하나의"], "viable": ["형용사", "실현 가능한"], "tourist": ["명사", "관광객, 관광"]}, "src": "2-"}, {"no": 127, "q": "Because the actual color differed from _____ in the catalog description, Etoile Gowns returned two boxes of lace to the supplier.", "options": ["that", "including", "except", "only"], "answer": 0, "explain": "정답 (A) that\n해석: 실제 색상이 카탈로그 설명의 색상과 달라서 Etoile Gowns는 레이스 두 상자를 공급업체에 반품했다.\n정답 근거: 앞에 나온 단수 명사 color를 대신 받아 비교해야 하므로 지시대명사 that이 정답이다.\n오답 분석: (B) including: 전치사·분사라 비교 대상이 되지 못한다. / (C) except: '~을 제외하고'. 비교 구조에 맞지 않는다. / (D) only: 부사라 전치사의 목적어가 될 수 없다.", "translation": "실제 색상이 카탈로그 설명의 색상과 달라서 Etoile Gowns는 레이스 두 상자를 공급업체에 반품했다.", "vocab": "that 대 (앞의 명사를 대신) 그것 / differ from 구 ~과 다르다 / supplier 명 공급업체 / description 명 설명", "sub": "어휘 6회", "g": {"because": ["접속사", "~ 때문에"], "the": ["관사", "그"], "actual": ["형용사", "실제의"], "color": ["명사", "색상"], "differed": ["동사", "달랐다", "differ"], "from": ["전치사", "~로부터"], "in": ["전치사", "~에서, ~에"], "catalog": ["명사", "카탈로그"], "description": ["명사", "설명"], "etoile": ["고유명사", "Etoile(상호)"], "gowns": ["고유명사", "Gowns(상호)"], "returned": ["동사", "반품했다", "return"], "two": ["숫자", "둘"], "boxes": ["명사", "상자들", "box"], "of": ["전치사", "~의"], "lace": ["명사", "레이스"], "to": ["전치사", "~에게"], "supplier": ["명사", "공급업체"]}, "src": "2-"}, {"no": 128, "q": "Phone conversations are _____ in designated quiet areas of the commuter train.", "options": ["filled", "chosen", "forbidden", "resumed"], "answer": 2, "explain": "정답 (C) forbidden\n해석: 통근 열차의 지정된 조용한 구역에서는 통화가 금지된다.\n정답 근거: 조용한 구역이라고 했으므로 통화가 「금지된다」는 뜻이 알맞다.\n오답 분석: (A) filled: '채워진'. 통화를 주어로 삼기에 어색하다. / (B) chosen: '선택된'. 규정을 나타내지 못한다. / (D) resumed: '재개된'. 조용한 구역이라는 조건과 어긋남.", "translation": "통근 열차의 지정된 조용한 구역에서는 통화가 금지된다.", "vocab": "forbid 동 금지하다 / designated 형 지정된 / commuter train 명 통근 열차 / resume 동 재개하다", "sub": "어휘 6회", "g": {"phone": ["명사", "전화"], "conversations": ["명사", "대화들", "conversation"], "are": ["동사", "~이다", "be"], "in": ["전치사", "~에서, ~에"], "designated": ["형용사", "지정된"], "quiet": ["형용사", "조용한"], "areas": ["명사", "구역들", "area"], "of": ["전치사", "~의"], "the": ["관사", "그"], "commuter": ["명사", "통근자"], "train": ["명사", "열차"]}, "src": "2-"}, {"no": 129, "q": "To interest potential _____ in the medical research laboratory, Dr. Kalinya is preparing an informational session.", "options": ["investors", "supplies", "guides", "reasons"], "answer": 0, "explain": "정답 (A) investors\n해석: 의학 연구소에 관심을 가질 잠재 투자자를 끌기 위해 Kalinya 박사는 설명회를 준비하고 있다.\n정답 근거: potential의 수식을 받아 설명회의 대상이 되어야 하므로 사람을 뜻하는 「투자자」가 알맞다.\n오답 분석: (B) supplies: '물품'. 관심을 갖는 주체가 될 수 없다. / (C) guides: '안내인'. 설명회 대상으로 어색하다. / (D) reasons: '이유'. 사람이 아니어서 부적절하다.", "translation": "의학 연구소에 관심을 가질 잠재 투자자를 끌기 위해 Kalinya 박사는 설명회를 준비하고 있다.", "vocab": "investor 명 투자자 / potential 형 잠재적인 / laboratory 명 연구소 / informational 형 정보를 제공하는", "sub": "어휘 6회", "g": {"to": ["to부정사", "~하기 위해"], "interest": ["동사", "관심을 끌다"], "potential": ["형용사", "잠재적인"], "in": ["전치사", "~에"], "the": ["관사", "그"], "medical": ["형용사", "의학의"], "research": ["명사", "연구"], "laboratory": ["명사", "연구소"], "dr": ["명사", "박사"], "kalinya": ["고유명사", "Kalinya(인명)"], "is": ["동사", "~이다", "be"], "preparing": ["현재분사", "준비하고 있는", "prepare"], "an": ["관사", "하나의"], "informational": ["형용사", "정보를 주는"], "session": ["명사", "모임, 회"]}, "src": "2-"}, {"no": 130, "q": "Mr. Li's laptop malfunctioned just before the presentation, but _____ he was able to borrow another one.", "options": ["especially", "sincerely", "freely", "fortunately"], "answer": 3, "explain": "정답 (D) fortunately\n해석: Li 씨의 노트북이 발표 직전 고장 났지만 다행히 다른 것을 빌릴 수 있었다.\n정답 근거: 문제가 있었으나 해결되었다는 흐름이므로 「다행히」가 알맞다.\n오답 분석: (A) especially: '특히'. 상황의 전환을 나타내지 못한다. / (B) sincerely: '진심으로'. 문맥과 맞지 않는다. / (C) freely: '자유롭게'. 대여 상황을 설명하지 못한다.", "translation": "Li 씨의 노트북이 발표 직전 고장 났지만 다행히 다른 것을 빌릴 수 있었다.", "vocab": "fortunately 부 다행히 / malfunction 동 오작동하다 / borrow 동 빌리다 / presentation 명 발표", "sub": "어휘 6회", "g": {"mr": ["명사", "~씨(남성)"], "li's": ["고유명사", "Li의(인명)"], "laptop": ["명사", "노트북"], "malfunctioned": ["동사", "오작동했다", "malfunction"], "just": ["부사", "바로"], "before": ["전치사", "~ 전에"], "the": ["관사", "그"], "presentation": ["명사", "발표"], "but": ["접속사", "그러나"], "he": ["대명사", "그"], "was": ["동사", "~였다", "be"], "able": ["형용사", "~할 수 있는"], "to": ["to부정사", "~하는 것"], "borrow": ["동사", "빌리다"], "another": ["한정사", "또 다른"], "one": ["대명사", "것(노트북)"]}, "src": "2-"}], "sets": []}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r10-p6',$mkd${"id": "a2-r10-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 2, "round": 10, "level": "중급", "title": "A급 과제 10회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "ROTTERDAM (3 September)— Landiss Company's patented facial cleanser came on the market a couple of years ago. ---131--- strong sales, production was halted while the company adjusted its formula. Landiss Company's spokesperson, Arlette Crehen, explained that company researchers realized a foam application would be ---132--- on the skin. So the product was withdrawn from retail outlets for almost a year while they worked to develop a more lightweight formula.\n---133---. Ms. Crehen noted, \"We believe that this ---134--- will ensure that Landiss Company has the most effective product of its kind on the market.\"", "tr": "로테르담(9월 3일) ― Landiss Company의 특허 세안제는 2년쯤 전에 시장에 나왔다. 판매가 좋았음에도 (131) 회사가 성분을 조정하는 동안 생산이 중단되었다. Landiss Company 대변인 Arlette Crehen은 회사 연구진이 거품 형태로 바르는 것이 피부에 더 순하리라 (132)는 것을 알게 되었다고 설명했다. 그래서 더 가벼운 제형을 개발하는 동안 이 제품은 거의 1년간 소매점에서 회수되었다. 이제 인기 있는 이 세안제가 어느 때보다 좋아져 돌아왔다 (133). Crehen 씨는 \"이번 혁신 (134)으로 Landiss Company가 시장에서 같은 종류의 제품 가운데 가장 효과적인 제품을 갖게 되리라 믿습니다.\"라고 말했다.", "questions": [{"no": 131, "q": "", "options": ["As far as", "Because of", "Although", "Despite"], "answer": 3, "explain": "정답 (D) Despite\n지문 개요: 화장품 회사가 판매 호조에도 제품 생산을 중단하고 더 순한 거품 제형으로 개선해 재출시했다는 기사다.\n정답 근거: 판매가 좋았는데도 생산을 중단했다는 대조 관계이고 뒤에 명사구가 오므로 전치사 Despite가 알맞다.\n오답 분석: (A) As far as: 범위를 나타내며 절을 이끔. / (B) Because of: 이유를 나타내 뜻이 반대가 된다. / (C) Although: 접속사라 뒤에 절이 와야 한다.", "g": {}}, {"no": 132, "q": "", "options": ["gentler", "gentleness", "gently", "gentled"], "answer": 0, "explain": "정답 (A) gentler\n정답 근거: be동사 뒤 보어 자리이므로 형용사가 필요하고, 기존 제형과 비교해 더 순하다는 뜻이므로 비교급이 알맞다.\n오답 분석: (B) gentleness: 명사를 쓰면 '바르는 것=순함'이 되어 어색하다. / (C) gently: 부사는 be동사 뒤 보어가 될 수 없다. / (D) gentled: 과거분사는 이 문맥에 쓰이지 않는다.", "g": {}}, {"no": 133, "q": "", "options": ["Foam cleansers are known to be more expensive.", "The researchers are highly trained chemists.", "Now the popular cleanser is back and better than ever.", "Product distribution has been a challenge."], "answer": 2, "explain": "정답 (C) Now the popular cleanser is back and better than ever.\n정답 근거: 앞에서 회수와 개선 과정을 설명했고 뒤에서 가장 효과적인 제품이 될 것이라는 발언이 이어지므로 재출시를 알리는 문장이 자연스럽다.\n오답 분석: (A): 가격 비교는 제형 개선 흐름과 이어지지 않는다. / (B): 연구진의 학력 소개는 문맥과 무관하다. / (D): 유통의 어려움은 재출시 소식과 어긋남.", "g": {}}, {"no": 134, "q": "", "options": ["equipment", "innovation", "data", "document"], "answer": 1, "explain": "정답 (B) innovation\n정답 근거: 개선된 제형을 가리켜야 하므로 「혁신」이 알맞다.\n오답 분석: (A) equipment: '장비'. 제형 개선을 가리키지 못한다. / (C) data: '자료'. 효과의 근거가 되는 대상이 아니다. / (D) document: '문서'. 문맥과 무관하다.", "g": {}}], "vocab": "despite 전 ~에도 불구하고 / patented 형 특허받은 / halt 동 중단하다 / adjust 동 조정하다 / formula 명 제조법 / withdraw 동 회수하다 / lightweight 형 가벼운 / innovation 명 혁신", "g": {"rotterdam": ["고유명사", "로테르담(지명)"], "3": ["숫자", "3"], "september": ["고유명사", "9월"], "landiss": ["고유명사", "Landiss(회사명)"], "company's": ["고유명사", "Company의(회사명)", "company"], "patented": ["형용사", "특허받은"], "facial": ["형용사", "얼굴용의"], "cleanser": ["명사", "세안제"], "came": ["동사", "나왔다", "come"], "on": ["전치사", "~에, ~에 대해"], "the": ["관사", "그"], "market": ["명사", "시장"], "a": ["관사", "하나의"], "couple": ["명사", "두어 개"], "of": ["전치사", "~의"], "years": ["명사", "년", "year"], "ago": ["부사", "전에"], "strong": ["형용사", "강한, 좋은"], "sales": ["명사", "판매(량)"], "production": ["명사", "생산"], "was": ["동사", "~였다", "be"], "halted": ["과거분사", "중단된", "halt"], "while": ["접속사", "~하는 동안"], "company": ["명사", "회사"], "adjusted": ["동사", "조정했다", "adjust"], "its": ["대명사", "그것의"], "formula": ["명사", "제조법, 제형"], "spokesperson": ["명사", "대변인"], "arlette": ["고유명사", "Arlette(인명)"], "crehen": ["고유명사", "Crehen(인명)"], "explained": ["동사", "설명했다", "explain"], "that": ["접속사", "~라는 것"], "researchers": ["명사", "연구원들", "researcher"], "realized": ["동사", "깨달았다", "realize"], "foam": ["명사", "거품"], "application": ["명사", "바르기, 도포"], "would": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "skin": ["명사", "피부"], "so": ["부사", "그래서"], "product": ["명사", "제품"], "withdrawn": ["과거분사", "회수된", "withdraw"], "from": ["전치사", "~로부터"], "retail": ["형용사", "소매의"], "outlets": ["명사", "판매점들", "outlet"], "for": ["전치사", "~ 동안"], "almost": ["부사", "거의"], "year": ["명사", "해, 년"], "they": ["대명사", "그들"], "worked": ["동사", "노력했다, 일했다", "work"], "to": ["to부정사", "~하기 위해"], "develop": ["동사", "개발하다"], "more": ["부사", "더"], "lightweight": ["형용사", "가벼운"], "ms": ["명사", "~씨(여성)"], "noted": ["동사", "말했다, 언급했다", "note"], "we": ["대명사", "우리"], "believe": ["동사", "믿다"], "this": ["한정사", "이"], "will": ["조동사", "~할 것이다"], "ensure": ["동사", "보장하다"], "has": ["동사", "가지다", "have"], "most": ["부사", "가장"], "effective": ["형용사", "효과적인"], "kind": ["명사", "종류"]}}, {"range": "135-138", "passage": "To: Mark Kootman\nFrom: Batsheva Abadi\nDate: April 23\nSubject: Banquet\nMy string quartet and I are looking forward to playing at your outdoor banquet next month. Please note that we have certain requirements when we perform outside. We need to set up our ---135--- in a shady area that is protected from sun and moisture. This is essential because our violins, viola, and cello can be damaged in adverse weather conditions. ---136---, if it is very windy outside, we may need to move to an alternate location. ---137---. Finally, if the weather is very hot or cold on the performance date, we will need to move indoors. It is difficult to play with cold or sweaty fingers in ---138--- temperatures. Feel free to contact me with any questions or concerns.", "tr": "수신: Mark Kootman / 발신: Batsheva Abadi / 날짜: 4월 23일 / 제목: 연회\n저희 현악 4중주단은 다음 달 야외 연회에서 연주하기를 기대하고 있습니다. 야외에서 연주할 때 저희에게 몇 가지 요건이 있다는 점을 알아 두십시오. 저희 악기 (135)는 햇빛과 습기를 피할 수 있는 그늘진 곳에 설치해야 합니다. 바이올린, 비올라, 첼로가 좋지 않은 날씨에 손상될 수 있으므로 꼭 필요한 조건입니다. 또한 (136) 바깥에 바람이 많이 불면 다른 장소로 옮겨야 할 수도 있습니다. 보면대가 넘어지는 일은 없어야 하니까요 (137). 끝으로 공연 당일 날씨가 매우 덥거나 추우면 실내로 옮겨야 합니다. 극단적인 (138) 기온에서 손이 시리거나 땀이 나면 연주하기 어렵습니다. 질문이나 우려가 있으시면 편히 연락해 주십시오.", "questions": [{"no": 135, "q": "", "options": ["instruments", "easels", "cameras", "experiments"], "answer": 0, "explain": "정답 (A) instruments\n지문 개요: 현악 4중주단 연주자가 야외 연회 공연에 필요한 장소 조건과 날씨에 따른 대비 사항을 미리 알리는 이메일이다.\n정답 근거: 뒤에서 바이올린, 비올라, 첼로가 손상될 수 있다고 했으므로 「악기」가 알맞다.\n오답 분석: (B) easels: '이젤'. 연주와 무관하다. / (C) cameras: '카메라'. 현악기 언급과 이어지지 않는다. / (D) experiments: '실험'. 문맥과 맞지 않는다.", "g": {}}, {"no": 136, "q": "", "options": ["After all", "Despite this", "At that time", "In addition"], "answer": 3, "explain": "정답 (D) In addition\n정답 근거: 앞에서 그늘진 장소 요건을 말하고 뒤에서 바람에 따른 요건을 더하므로 추가 연결어가 알맞다.\n오답 분석: (A) After all: '결국'. 요건 나열에 어울리지 않는다. / (B) Despite this: 대조를 나타내 문맥과 맞지 않는다. / (C) At that time: 특정 시점을 가리켜야 하는데 지시 대상이 없다.", "g": {}}, {"no": 137, "q": "", "options": ["We do not want our music stands blowing over.", "If the event starts late, we will charge an extra fee.", "We usually prefer to play indoors at small events.", "It is easy to find suitable locations on our Web site."], "answer": 0, "explain": "정답 (A) We do not want our music stands blowing over.\n정답 근거: 앞 문장이 바람이 셀 때 자리를 옮겨야 한다는 내용이므로 그 이유를 밝히는 문장이 자연스럽게 이어진다.\n오답 분석: (B): 추가 요금 이야기는 장소 요건과 이어지지 않는다. / (C): 실내 선호는 야외 요건 안내와 흐름이 맞지 않는다. / (D): 웹사이트 장소 검색은 문맥과 무관하다.", "g": {}}, {"no": 138, "q": "", "options": ["extremes", "extremity", "extreme", "extremely"], "answer": 2, "explain": "정답 (C) extreme\n정답 근거: 명사 temperatures 앞 형용사 자리이고 매우 덥거나 추운 날씨를 가리키므로 extreme이 알맞다.\n오답 분석: (A) extremes: 명사가 연달아 와 뜻이 성립하지 않는다. / (B) extremity: 명사도 같은 이유로 불가하다. / (D) extremely: 부사는 명사를 꾸밀 수 없다.", "g": {}}], "vocab": "string quartet 명 현악 4중주단 / requirement 명 요건 / instrument 명 악기 / moisture 명 습기 / adverse 형 (날씨가) 좋지 않은 / in addition 구 게다가 / alternate 형 대체의 / extreme 형 극심한", "g": {"to": ["전치사", "~에게 / ~하기 위해"], "mark": ["고유명사", "Mark(인명)"], "kootman": ["고유명사", "Kootman(인명)"], "from": ["전치사", "~로부터"], "batsheva": ["고유명사", "Batsheva(인명)"], "abadi": ["고유명사", "Abadi(인명)"], "date": ["명사", "날짜"], "april": ["고유명사", "4월"], "23": ["숫자", "23"], "subject": ["명사", "제목"], "banquet": ["명사", "연회"], "my": ["대명사", "나의"], "string": ["명사", "현악기"], "quartet": ["명사", "4중주단"], "and": ["접속사", "그리고"], "i": ["대명사", "나"], "are": ["동사", "~이다", "be"], "looking": ["현재분사", "고대하고 있는", "look"], "forward": ["부사", "앞으로"], "playing": ["동명사", "연주하는 것", "play"], "at": ["전치사", "~에서"], "your": ["대명사", "당신의"], "outdoor": ["형용사", "야외의"], "next": ["형용사", "다음의"], "month": ["명사", "달"], "please": ["부사", "부디, ~해 주세요"], "note": ["동사", "유의하다"], "that": ["접속사", "~라는 것 / ~하는"], "we": ["대명사", "우리"], "have": ["동사", "가지다"], "certain": ["형용사", "몇 가지의, 특정한"], "requirements": ["명사", "요건들", "requirement"], "when": ["접속사", "~할 때"], "perform": ["동사", "공연하다"], "outside": ["부사", "야외에서"], "need": ["동사", "필요하다"], "set": ["동사", "설치하다(set up)"], "up": ["부사", "(set up) 설치하다"], "our": ["대명사", "우리의"], "in": ["전치사", "~에서, ~에"], "a": ["관사", "하나의"], "shady": ["형용사", "그늘진"], "area": ["명사", "장소"], "is": ["동사", "~이다", "be"], "protected": ["과거분사", "보호된", "protect"], "sun": ["명사", "햇빛"], "moisture": ["명사", "습기"], "this": ["한정사", "이"], "essential": ["형용사", "필수적인"], "because": ["접속사", "~ 때문에"], "violins": ["명사", "바이올린들", "violin"], "viola": ["명사", "비올라"], "cello": ["명사", "첼로"], "can": ["조동사", "~할 수 있다"], "be": ["동사", "~이다, 되다"], "damaged": ["과거분사", "손상된", "damage"], "adverse": ["형용사", "좋지 않은"], "weather": ["명사", "날씨"], "conditions": ["명사", "상태, 조건", "condition"], "if": ["접속사", "만약 ~라면"], "it": ["대명사", "그것"], "very": ["부사", "매우"], "windy": ["형용사", "바람이 부는"], "may": ["조동사", "~일지도 모른다"], "move": ["동사", "옮기다"], "an": ["관사", "하나의"], "alternate": ["형용사", "대체의"], "location": ["명사", "장소"], "finally": ["부사", "마지막으로"], "the": ["관사", "그"], "hot": ["형용사", "더운"], "or": ["접속사", "또는"], "cold": ["형용사", "추운, 차가운"], "on": ["전치사", "~에, ~에 대해"], "performance": ["명사", "공연"], "will": ["조동사", "~할 것이다"], "indoors": ["부사", "실내로"], "difficult": ["형용사", "어려운"], "play": ["동사", "연주하다"], "with": ["전치사", "~와 함께, ~으로"], "sweaty": ["형용사", "땀이 나는"], "fingers": ["명사", "손가락들", "finger"], "temperatures": ["명사", "기온", "temperature"], "feel": ["동사", "편하게 ~하다"], "free": ["형용사", "자유로운"], "contact": ["동사", "연락하다"], "me": ["대명사", "나를"], "any": ["한정사", "어떤"], "questions": ["명사", "질문들", "question"], "concerns": ["명사", "우려 사항들", "concern"]}}, {"range": "139-142", "passage": "Local Plant Sale\nMississauga residents ---139--- to stop by Johnstone Plaza for the season's largest sale of outdoor plants. Varieties available will include many suitable for sun or shade. The sale is sponsored by Forests of The Earth (FTE), an ecological nonprofit organization, which is raising funds to plant 2,000 trees in the city. All ---140--- will go toward this effort. The sale will be held on 16 March from 11 A.M. to 4 P.M.\nGrowers from ---141--- the area will participate. These include many suppliers, such as Drucker Natives, Acropolis Nursery, and Erhardt Greenhouse. ---142---. You're sure to find the right plants for your garden.", "tr": "지역 식물 판매\n미시소가 주민 여러분을 Johnstone Plaza에서 열리는 이번 철 최대 규모의 야외 식물 판매 행사에 초대합니다 (139). 볕이 드는 곳이나 그늘에 알맞은 여러 품종이 준비됩니다. 이 판매는 생태 비영리 단체 Forests of The Earth(FTE)가 후원하며, 이 단체는 시내에 나무 2천 그루를 심기 위한 기금을 모으고 있습니다. 모든 수익금 (140)은 이 사업에 쓰입니다. 판매는 3월 16일 오전 11시부터 오후 4시까지 열립니다. 이 지역 곳곳 (141)의 재배자들이 참여합니다. Drucker Natives, Acropolis Nursery, Erhardt Greenhouse 등 여러 공급업체가 포함됩니다. 참여 업체 전체 목록은 FTE 웹사이트에서 확인하십시오 (142). 정원에 알맞은 식물을 반드시 찾으실 수 있을 것입니다.", "questions": [{"no": 139, "q": "", "options": ["invitation", "to invite", "are invited", "inviting"], "answer": 2, "explain": "정답 (C) are invited\n지문 개요: 환경 단체가 나무 심기 기금 마련을 위해 여는 야외 식물 판매 행사의 일시와 참여 업체를 알리는 공지다.\n정답 근거: 문장에 동사가 없으므로 동사 자리다. 주민이 초대받는 대상이므로 수동태가 정답이다.\n오답 분석: (A) invitation: 명사는 문장의 동사가 될 수 없다. / (B) to invite: to부정사도 동사 자리에 올 수 없다. / (D) inviting: 분사는 문장의 동사가 될 수 없다.", "g": {}}, {"no": 140, "q": "", "options": ["returns", "conclusions", "investments", "proceeds"], "answer": 3, "explain": "정답 (D) proceeds\n정답 근거: 판매로 얻은 돈이 나무 심기에 쓰인다는 뜻이므로 「수익금」이 알맞다.\n오답 분석: (A) returns: '반품·수익률'. 행사 수익금을 뜻하기에 부정확하다. / (B) conclusions: '결론'. 문맥과 무관하다. / (C) investments: '투자금'. 판매 대금을 가리키지 않는다.", "g": {}}, {"no": 141, "q": "", "options": ["among", "around", "between", "plus"], "answer": 1, "explain": "정답 (B) around\n정답 근거: 지역 여러 곳에서 재배자들이 온다는 뜻이므로 「~일대의」를 뜻하는 around가 알맞다.\n오답 분석: (A) among: '~사이에'. 출신 범위를 나타내지 못한다. / (C) between: 두 지점 사이를 뜻해 맞지 않는다. / (D) plus: 덧셈을 뜻해 문맥과 무관하다.", "g": {}}, {"no": 142, "q": "", "options": ["The FTE was founded some 30 years ago.", "Visit the FTE Web site for a complete listing of vendors.", "Other companies will reduce their inventories.", "So bring along your resume and cover letter."], "answer": 1, "explain": "정답 (B) Visit the FTE Web site for a complete listing of vendors.\n정답 근거: 앞 문장이 참여 업체 몇 곳을 예로 들었으므로 전체 목록 확인 방법을 안내하는 문장이 자연스럽게 이어진다.\n오답 분석: (A): 단체 설립 연도는 판매 안내 흐름과 이어지지 않는다. / (C): 다른 회사의 재고 축소는 문맥과 무관하다. / (D): 이력서 지참 안내는 채용 행사에나 어울린다.", "g": {}}], "vocab": "be invited to do 구 ~하도록 초대되다 / stop by 구 들르다 / suitable 형 적합한 / nonprofit organization 명 비영리 단체 / raise funds 구 기금을 모으다 / proceeds 명 수익금 / grower 명 재배업자 / vendor 명 판매업체", "g": {"local": ["형용사", "지역의"], "plant": ["명사", "식물"], "sale": ["명사", "판매"], "mississauga": ["고유명사", "미시소가(지명)"], "residents": ["명사", "주민들", "resident"], "to": ["to부정사", "~하도록 / ~로(전치사)"], "stop": ["동사", "(stop by) 들르다"], "by": ["전치사", "~에 의해"], "johnstone": ["고유명사", "Johnstone(지명)"], "plaza": ["명사", "광장, 플라자"], "for": ["전치사", "~을 위해"], "the": ["관사", "그"], "season's": ["명사", "이번 철의", "season"], "largest": ["형용사", "가장 큰", "large"], "of": ["전치사", "~의"], "outdoor": ["형용사", "야외의"], "plants": ["명사", "식물들", "plant"], "varieties": ["명사", "품종들", "variety"], "available": ["형용사", "구할 수 있는"], "will": ["조동사", "~할 것이다"], "include": ["동사", "포함하다"], "many": ["대명사", "많은 것"], "suitable": ["형용사", "적합한"], "sun": ["명사", "양지, 햇빛"], "or": ["접속사", "또는"], "shade": ["명사", "그늘"], "is": ["동사", "~이다", "be"], "sponsored": ["과거분사", "후원받는", "sponsor"], "forests": ["고유명사", "Forests(단체명)"], "earth": ["고유명사", "Earth(단체명)"], "fte": ["고유명사", "FTE(단체 약칭)"], "an": ["관사", "하나의"], "ecological": ["형용사", "생태의"], "nonprofit": ["형용사", "비영리의"], "organization": ["명사", "단체"], "which": ["관계사", "그리고 그 단체는(주격)"], "raising": ["현재분사", "모으는", "raise"], "funds": ["명사", "기금", "fund"], "2,000": ["숫자", "2,000"], "trees": ["명사", "나무들", "tree"], "in": ["전치사", "~에서, ~에"], "city": ["명사", "도시"], "all": ["한정사", "모든"], "go": ["동사", "쓰이다(go toward)"], "toward": ["전치사", "~에, ~을 위해"], "this": ["한정사", "이"], "effort": ["명사", "노력, 사업"], "be": ["동사", "~이다, 되다"], "held": ["과거분사", "열리는", "hold"], "on": ["전치사", "~에, ~에 대해"], "16": ["숫자", "16"], "march": ["고유명사", "3월"], "from": ["전치사", "~로부터"], "11": ["숫자", "11"], "a.m": ["부사", "오전"], "4": ["숫자", "4"], "p.m": ["부사", "오후"], "growers": ["명사", "재배자들", "grower"], "area": ["명사", "지역"], "participate": ["동사", "참여하다"], "these": ["대명사", "이들"], "suppliers": ["명사", "공급업체들", "supplier"], "such": ["형용사", "(such as) ~ 같은"], "as": ["전치사", "(such as) ~와 같은"], "drucker": ["고유명사", "Drucker(상호)"], "natives": ["고유명사", "Natives(상호)"], "acropolis": ["고유명사", "Acropolis(상호)"], "nursery": ["고유명사", "Nursery(묘목원 상호)"], "and": ["접속사", "그리고"], "erhardt": ["고유명사", "Erhardt(상호)"], "greenhouse": ["고유명사", "Greenhouse(상호)"], "you're": ["대명사", "당신은 ~이다"], "sure": ["형용사", "확실한"], "find": ["동사", "찾다"], "right": ["형용사", "알맞은"], "your": ["대명사", "당신의"], "garden": ["명사", "정원"]}}, {"range": "143-146", "passage": "From: Falcetti, Matthew\nSent: May 17\nTo: Library staff\nSubject: Second floor Wi-Fi signal\nPlease note that a new wireless Internet access point was recently installed on the library's second floor. There is ---143--- a wireless signal in the public study area there. In the past, we had discouraged patrons ---144--- trying to access the Internet in that space because the signal was not very strong. ---145---.\nThis is the first of three new access points we will be installing. Soon we expect to improve the signal ---146--- in the art gallery and lobby as well.", "tr": "발신: Matthew Falcetti / 발송: 5월 17일 / 수신: 도서관 직원 / 제목: 2층 와이파이 신호\n최근 도서관 2층에 새 무선 인터넷 접속 장치가 설치되었음을 알려 드립니다. 그곳 공용 학습 공간에 이제 (143) 무선 신호가 잡힙니다. 예전에는 신호가 강하지 않아 그 공간에서 인터넷에 접속하려는 이용자들을 말려 (144) 왔습니다. 이제는 그럴 필요가 없습니다 (145). 이것은 앞으로 설치할 새 접속 장치 세 곳 가운데 첫 번째입니다. 곧 미술관과 로비의 신호 세기 (146)도 개선될 것으로 기대합니다.", "questions": [{"no": 143, "q": "", "options": ["still", "never", "now", "unfortunately"], "answer": 2, "explain": "정답 (C) now\n지문 개요: 도서관이 2층에 새 무선 접속 장치를 설치했으며 앞으로 다른 공간에도 신호를 개선할 계획임을 직원들에게 알리는 이메일이다.\n정답 근거: 새 장치를 설치한 결과 지금은 신호가 잡힌다는 뜻이므로 now가 알맞다.\n오답 분석: (A) still: 예전부터 이어진 상태를 뜻해 새 설치와 어긋남. / (B) never: 부정을 뜻해 설치 효과와 모순된다. / (D) unfortunately: 부정적 평가라 개선 소식과 맞지 않는다.", "g": {}}, {"no": 144, "q": "", "options": ["by", "from", "before", "across"], "answer": 1, "explain": "정답 (B) from\n정답 근거: discourage A from -ing는 「A가 ~하지 못하게 말리다」를 뜻하는 결합이므로 from이 정답이다.\n오답 분석: (A) by: 수단을 나타내 이 결합에 쓰이지 않는다. / (C) before: 시간을 나타내 문맥과 맞지 않는다. / (D) across: 위치를 뜻해 어색하다.", "g": {}}, {"no": 145, "q": "", "options": ["This will no longer be necessary.", "This area is off-limits to small children.", "It will be featured in Friday's newspaper.", "Many patrons bring their own computers."], "answer": 0, "explain": "정답 (A) This will no longer be necessary.\n정답 근거: 앞에서 신호가 약해 이용을 말려 왔다고 했고 이제는 신호가 잡히므로 더 이상 그럴 필요가 없다는 문장이 자연스럽다.\n오답 분석: (B): 어린이 출입 제한은 신호 개선과 무관하다. / (C): 신문 보도 예고는 직원 안내와 이어지지 않는다. / (D): 개인 컴퓨터 지참 언급은 흐름을 끊다.", "g": {}}, {"no": 146, "q": "", "options": ["strength", "is strong", "strongest", "strengthens"], "answer": 0, "explain": "정답 (A) strength\n정답 근거: 타동사 improve의 목적어 자리이고 the signal과 결합해 「신호 세기」를 이루므로 명사 strength가 정답이다.\n오답 분석: (B) is strong: 동사구는 목적어가 될 수 없다. / (C) strongest: 형용사 최상급은 목적어 자리에 올 수 없다. / (D) strengthens: 동사가 두 개가 되어 불가하다.", "g": {}}], "vocab": "access point 명 (무선) 접속 장치 / install 동 설치하다 / discourage A from -ing 구 A가 ~하지 못하게 하다 / patron 명 이용객 / no longer 구 더 이상 ~ 않다 / strength 명 강도, 세기 / as well 구 또한", "g": {"from": ["전치사", "~로부터"], "falcetti": ["고유명사", "Falcetti(인명)"], "matthew": ["고유명사", "Matthew(인명)"], "sent": ["동사", "보낸 날짜", "send"], "may": ["고유명사", "5월"], "17": ["숫자", "17"], "to": ["전치사", "~에게 / ~하는 것"], "library": ["명사", "도서관"], "staff": ["명사", "직원"], "subject": ["명사", "제목"], "second": ["형용사", "두 번째의"], "floor": ["명사", "층"], "wi-fi": ["명사", "와이파이"], "signal": ["명사", "신호"], "please": ["부사", "부디, ~해 주세요"], "note": ["동사", "유의하다, 알아 두다"], "that": ["접속사", "~라는 것"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "wireless": ["형용사", "무선의"], "internet": ["명사", "인터넷"], "access": ["명사", "접속"], "point": ["명사", "지점, 장치"], "was": ["동사", "~였다", "be"], "recently": ["부사", "최근에"], "installed": ["과거분사", "설치된", "install"], "on": ["전치사", "~에, ~에 대해"], "the": ["관사", "그"], "library's": ["명사", "도서관의", "library"], "there": ["부사", "~이 있다(there is)"], "is": ["동사", "~이다", "be"], "in": ["전치사", "~에서, ~에"], "public": ["형용사", "공용의"], "study": ["명사", "학습"], "area": ["명사", "공간"], "past": ["명사", "과거"], "we": ["대명사", "우리"], "had": ["조동사", "(과거완료) ~했었다", "have"], "discouraged": ["과거분사", "만류했던", "discourage"], "patrons": ["명사", "이용객들", "patron"], "trying": ["동명사", "시도하는 것", "try"], "space": ["명사", "공간"], "because": ["접속사", "~ 때문에"], "not": ["부사", "~아니다"], "very": ["부사", "매우"], "strong": ["형용사", "강한"], "this": ["한정사", "이"], "first": ["대명사", "첫 번째 것"], "of": ["전치사", "~의"], "three": ["숫자", "셋"], "points": ["명사", "장치들", "point"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "installing": ["현재분사", "설치하고 있는", "install"], "soon": ["부사", "곧"], "expect": ["동사", "기대하다"], "improve": ["동사", "개선하다"], "art": ["명사", "미술"], "gallery": ["명사", "미술관, 갤러리"], "and": ["접속사", "그리고"], "lobby": ["명사", "로비"], "as": ["부사", "(as well) 또한"], "well": ["부사", "(as well) 또한"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r10-p7',$mkd${"id": "a2-r10-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 2, "round": 10, "level": "중급", "title": "A급 과제 10회 · PART 7 (기출독해 3문항 9·10회)", "notes": [], "items": [], "sets": [{"range": "153-155", "passage": "My Mamaki — Brew, sip, relax!\nThis container is made of recycled cardboard and printed with vegetable-based ink. All of our tea leaves are sustainably sourced. For more information on our Focus Green efforts, visit www.mymamaki.com/focusgreen.\nBrewing Instructions: 200 ml\n92-100 degrees Celsius\n5-10 minutes\nUse one tea bag for hot tea and two for iced tea.\nIf you are unsatisfied for any reason, you may return this product to the place of purchase for a full refund. Use product before 1 December.", "tr": "My Mamaki ― 우리고, 마시고, 쉬세요!\n이 용기는 재활용 판지로 만들어졌고 식물성 잉크로 인쇄되었습니다. 저희 찻잎은 모두 지속 가능한 방식으로 조달됩니다. Focus Green 활동에 관한 자세한 내용은 www.mymamaki.com/focusgreen을 방문하십시오.\n우리는 법: 200ml / 섭씨 92~100도 / 5~10분\n따뜻한 차에는 티백 하나, 아이스티에는 두 개를 사용하십시오.\n어떤 이유로든 만족스럽지 않으시면 구매처에 반품하고 전액 환불받으실 수 있습니다. 12월 1일 전에 사용하십시오.", "questions": [{"no": 153, "q": "Where is the information most likely printed?", "options": ["On a box", "On a cup", "On a bag", "On a bowl"], "answer": 0, "explain": "정답 (A) On a box\n지문 개요: 친환경 포장과 재료를 강조하는 차 제품의 우려내는 방법, 환불 조건, 사용 기한을 안내하는 표기다.\n정답 근거: 용기가 재활용 판지로 만들어졌다고 했으므로 종이 상자에 인쇄된 표기다.\n오답 분석: (B): 컵에 담길 내용이 아니다. / (C): 봉지가 아니라 판지 용기다. / (D): 그릇에 인쇄되는 표기가 아니다.", "translation": "이 안내문은 어디에 인쇄되어 있겠는가?", "g": {"where": ["부사", "어디에"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "information": ["명사", "안내문, 정보"], "most": ["부사", "아마도"], "likely": ["부사", "아마"], "printed": ["과거분사", "인쇄된", "print"]}}, {"no": 154, "q": "What can customers do if they are not pleased with the product?", "options": ["Visit a Web site", "Call the manufacturer", "Return it to the store", "Mail it to the distributor"], "answer": 2, "explain": "정답 (C) Return it to the store\n정답 근거: 어떤 이유로든 만족스럽지 않으면 구매처에 반품하고 전액 환불받을 수 있다고 했다.\n오답 분석: (A): 웹사이트는 친환경 활동 안내용이다. / (B): 제조사 전화 안내가 없다. / (D): 유통업체 우편 발송 언급이 없다.", "translation": "제품이 마음에 들지 않으면 고객은 무엇을 할 수 있는가?", "g": {"what": ["대명사", "무엇"], "can": ["조동사", "~할 수 있다"], "customers": ["명사", "고객들", "customer"], "do": ["동사", "하다"], "if": ["접속사", "만약 ~라면"], "they": ["대명사", "그들"], "are": ["동사", "~이다", "be"], "not": ["부사", "~아니다"], "pleased": ["형용사", "만족한"], "with": ["전치사", "~에"], "the": ["관사", "그"], "product": ["명사", "제품"]}}, {"no": 155, "q": "What does the information NOT mention about the product?", "options": ["Its contents", "Its preparation", "Its health benefits", "Its expiration date"], "answer": 2, "explain": "정답 (C) Its health benefits\n정답 근거: 재료와 포장, 우리는 방법, 사용 기한은 제시되었으나 건강상의 이점은 나오지 않는다.\n오답 분석: (A): 재활용 판지와 찻잎 조달 방식이 제시된다. / (B): 물 양·온도·시간이 제시된다. / (D): 12월 1일 전에 사용하라고 명시된다.", "translation": "제품에 대해 언급되지 않은 것은?", "g": {"what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "the": ["관사", "그"], "information": ["명사", "안내문, 정보"], "not": ["부사", "~아니다"], "mention": ["동사", "언급하다"], "about": ["전치사", "~에 관해"], "product": ["명사", "제품"]}}], "vocab": "recycled 형 재활용된 / sustainably 부 지속 가능하게 / source 동 (원료를) 조달하다 / brew 동 (차를) 우리다 / unsatisfied 형 불만족한 / full refund 명 전액 환불 / expiration date 명 유통기한 || Paraphrase: 153. container made of recycled cardboard → printed on a box / 154. return this product to the place of purchase → return it to the store / 155. Use product before 1 December → expiration date 언급됨 → 정답은 health benefits", "g": {"my": ["고유명사", "My(상표명 일부)"], "mamaki": ["고유명사", "Mamaki(상표명)"], "brew": ["동사", "(차를) 우리다"], "sip": ["동사", "홀짝이다"], "relax": ["동사", "쉬다"], "this": ["한정사", "이"], "container": ["명사", "용기"], "is": ["동사", "~이다", "be"], "made": ["과거분사", "만들어진", "make"], "of": ["전치사", "~의"], "recycled": ["형용사", "재활용된"], "cardboard": ["명사", "판지"], "and": ["접속사", "그리고"], "printed": ["과거분사", "인쇄된", "print"], "with": ["전치사", "~와 함께, ~으로"], "vegetable-based": ["형용사", "식물성의"], "ink": ["명사", "잉크"], "all": ["한정사", "모든"], "our": ["대명사", "우리의"], "tea": ["명사", "차"], "leaves": ["명사", "잎들", "leaf"], "are": ["동사", "~이다", "be"], "sustainably": ["부사", "지속 가능하게"], "sourced": ["과거분사", "조달된", "source"], "for": ["전치사", "~을 위해, ~용으로"], "more": ["부사", "더"], "information": ["명사", "정보"], "on": ["전치사", "~에, ~에 대해"], "focus": ["고유명사", "Focus(활동명)"], "green": ["고유명사", "Green(활동명)"], "efforts": ["명사", "노력, 활동", "effort"], "visit": ["동사", "방문하다"], "www.mymamaki.com/focusgreen": ["명사", "웹사이트 주소"], "brewing": ["동명사", "우려내기", "brew"], "instructions": ["명사", "방법, 설명", "instruction"], "200": ["숫자", "200"], "ml": ["명사", "밀리리터"], "92-100": ["숫자", "92~100"], "degrees": ["명사", "도(온도)", "degree"], "celsius": ["명사", "섭씨"], "5-10": ["숫자", "5~10"], "minutes": ["명사", "분", "minute"], "use": ["동사", "사용하다"], "one": ["숫자", "하나"], "bag": ["명사", "티백, 봉지"], "hot": ["형용사", "뜨거운"], "two": ["숫자", "둘"], "iced": ["형용사", "얼음을 넣은"], "if": ["접속사", "만약 ~라면"], "you": ["대명사", "당신"], "unsatisfied": ["형용사", "불만족한"], "any": ["한정사", "어떤"], "reason": ["명사", "이유"], "may": ["조동사", "~해도 된다"], "return": ["동사", "반품하다"], "product": ["명사", "제품"], "to": ["전치사", "~로"], "the": ["관사", "그"], "place": ["명사", "장소"], "purchase": ["명사", "구매"], "a": ["관사", "하나의"], "full": ["형용사", "전액의"], "refund": ["명사", "환불"], "before": ["전치사", "~ 전에"], "1": ["숫자", "1"], "december": ["고유명사", "12월"]}}, {"range": "158-160", "passage": "Joliet General Contractors — Invoice number: 94554\nClient: Piotr Messerli\nDescription: Deck construction of stained wood sealed with weather-resistant varnish. Labor for construction and lumber treatment. Deck includes steps that lead to a brick patio that has approximate dimensions of 8 × 10 feet. Labor to install brick pavers. A 10 percent discount for a first-time client has been applied.\nConstruction of deck $1,800\nInstallation of patio $1,500\nLumber, brick pavers, hardware $1,200\nWood treatment $200\nTotal: $4,700-10%=$4,230\nAll jobs require a down payment equal to 30 percent of the total estimated charge. Orders received without credit card information will not be processed.", "tr": "Joliet General Contractors ― 청구서 번호: 94554 / 고객: Piotr Messerli\n내역: 내후성 바니시로 마감 처리한 착색 목재 데크 시공. 시공 및 목재 처리 인건비. 데크에는 가로 약 8피트, 세로 10피트의 벽돌 파티오로 이어지는 계단이 포함됨. 벽돌 포장재 시공 인건비. 첫 거래 고객 10퍼센트 할인 적용.\n데크 시공 1,800달러 / 파티오 시공 1,500달러 / 목재·벽돌 포장재·철물 1,200달러 / 목재 처리 200달러 / 합계: 4,700달러 ― 10% = 4,230달러\n모든 작업은 총 견적 금액의 30퍼센트에 해당하는 계약금이 필요합니다. 신용카드 정보 없이 접수된 주문은 처리되지 않습니다.", "questions": [{"no": 158, "q": "The word \"sealed\" in paragraph 1, line 1, is closest in meaning to", "options": ["signed", "coated", "settled", "guaranteed"], "answer": 1, "explain": "정답 (B) coated\n지문 개요: 시공사가 데크와 파티오 시공 내역과 인건비·자재비, 첫 거래 할인과 계약금 조건을 정리한 청구서다.\n정답 근거: 바니시로 표면을 덮어 마감했다는 뜻이므로 「코팅된」이 가장 가깝다.\n오답 분석: (A) signed: '서명된'. 목재 마감과 뜻이 다르다. / (C) settled: '해결된'. 문맥과 맞지 않는다. / (D) guaranteed: '보장된'. 마감 처리를 뜻하지 않는다.", "translation": "첫 단락의 \"sealed\"와 뜻이 가장 가까운 것은?", "g": {"the": ["관사", "그"], "word": ["명사", "단어"], "sealed": ["과거분사", "마감 처리된", "seal"], "in": ["전치사", "~에서, ~에"], "paragraph": ["명사", "단락"], "1": ["숫자", "1"], "line": ["명사", "줄, 행"], "is": ["동사", "~이다", "be"], "closest": ["형용사", "가장 가까운", "close"], "meaning": ["명사", "의미"], "to": ["전치사", "~와(closest to)"]}}, {"no": 159, "q": "What is indicated about the steps?", "options": ["They lead to a paved area.", "They have an unusual shape.", "They required three days of work.", "They are replacing an old structure."], "answer": 0, "explain": "정답 (A) They lead to a paved area.\n정답 근거: 데크의 계단이 벽돌 파티오로 이어진다고 했으므로 포장된 공간으로 연결된다.\n오답 분석: (B): 형태에 관한 언급이 없다. / (C): 작업 일수가 제시되지 않는다. / (D): 기존 구조물 교체라는 정보가 없다.", "translation": "계단에 대해 언급된 것은?", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "언급된, 나타난", "indicate"], "about": ["전치사", "~에 관해"], "the": ["관사", "그"], "steps": ["명사", "계단", "step"]}}, {"no": 160, "q": "What is implied about Mr. Messerli?", "options": ["He was dissatisfied with a previous service.", "He paid using a credit card.", "He has already made the down payment.", "He has hired the company for the first time."], "answer": 3, "explain": "정답 (D) He has hired the company for the first time.\n정답 근거: 첫 거래 고객 10퍼센트 할인이 적용되었으므로 이 업체를 처음 이용한다.\n오답 분석: (A): 이전 서비스에 대한 불만 언급이 없다. / (B): 신용카드 정보는 요구 조건일 뿐 결제 사실이 아니다. / (C): 계약금 납부 여부는 나타나 있지 않는다.", "translation": "Messerli 씨에 대해 암시된 것은?", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "implied": ["과거분사", "암시된", "imply"], "about": ["전치사", "~에 관해"], "mr": ["명사", "~씨(남성)"], "messerli": ["고유명사", "Messerli(인명)"]}}], "vocab": "contractor 명 도급업체 / varnish 명 니스, 광택제 / weather-resistant 형 비바람에 강한 / dimension 명 치수 / down payment 명 계약금, 착수금 / estimated 형 추산된 / apply 동 적용하다 || Paraphrase: 158. sealed with varnish → coated (동의어) / 159. steps that lead to a brick patio → lead to a paved area / 160. a 10 percent discount for a first-time client → has hired the company for the first time", "g": {"joliet": ["고유명사", "Joliet(상호)"], "general": ["형용사", "종합의"], "contractors": ["명사", "시공업체", "contractor"], "invoice": ["명사", "청구서"], "number": ["명사", "번호"], "94554": ["숫자", "94554"], "client": ["명사", "고객"], "piotr": ["고유명사", "Piotr(인명)"], "messerli": ["고유명사", "Messerli(인명)"], "description": ["명사", "내역"], "deck": ["명사", "데크"], "construction": ["명사", "시공, 건설"], "of": ["전치사", "~의"], "stained": ["형용사", "착색된"], "wood": ["명사", "목재"], "sealed": ["과거분사", "마감 처리된", "seal"], "with": ["전치사", "~와 함께, ~으로"], "weather-resistant": ["형용사", "비바람에 강한"], "varnish": ["명사", "니스, 바니시"], "labor": ["명사", "인건비, 노동"], "for": ["전치사", "~에 대한, ~을 위한"], "and": ["접속사", "그리고"], "lumber": ["명사", "목재"], "treatment": ["명사", "처리"], "includes": ["동사", "포함하다", "include"], "steps": ["명사", "계단", "step"], "that": ["관계사", "~하는(주격)"], "lead": ["동사", "이어지다"], "to": ["전치사", "~로"], "a": ["관사", "하나의"], "brick": ["명사", "벽돌"], "patio": ["명사", "파티오, 테라스"], "has": ["동사", "가지다 / ~되었다", "have"], "approximate": ["형용사", "대략의"], "dimensions": ["명사", "치수", "dimension"], "8": ["숫자", "8"], "10": ["숫자", "10"], "feet": ["명사", "피트", "foot"], "install": ["동사", "설치하다"], "pavers": ["명사", "포장용 블록", "paver"], "percent": ["명사", "퍼센트"], "discount": ["명사", "할인"], "first-time": ["형용사", "첫 거래의"], "been": ["과거분사", "~였던(완료)", "be"], "applied": ["과거분사", "적용된", "apply"], "$1,800": ["숫자", "1,800달러"], "installation": ["명사", "설치"], "$1,500": ["숫자", "1,500달러"], "hardware": ["명사", "철물"], "$1,200": ["숫자", "1,200달러"], "$200": ["숫자", "200달러"], "total": ["명사", "합계"], "$4,700-10%=$4,230": ["숫자", "4700-10%→4230달러"], "all": ["한정사", "모든"], "jobs": ["명사", "작업들", "job"], "require": ["동사", "요구하다"], "down": ["형용사", "(계약금) 선불의"], "payment": ["명사", "지불금"], "equal": ["형용사", "~와 같은(equal to)"], "30": ["숫자", "30"], "the": ["관사", "그"], "estimated": ["형용사", "추산된"], "charge": ["명사", "요금"], "orders": ["명사", "주문들", "order"], "received": ["과거분사", "접수된", "receive"], "without": ["전치사", "~ 없이"], "credit": ["명사", "신용"], "card": ["명사", "카드"], "information": ["명사", "정보"], "will": ["조동사", "~할 것이다"], "not": ["부사", "~아니다"], "be": ["동사", "~이다, 되다"], "processed": ["과거분사", "처리된", "process"]}}, {"range": "161-163", "passage": "To: Samara Baker\nFrom: Greg Wilson (Settino Credit Union)\nSubject: RE: Checking account deposit\nI can confirm that we have received through our mobile app a check in the amount of $89.41 for deposit into your checking account ending in 3950. Please understand that the funds may not yet be available to use. The check will appear in your transaction history once it clears. This may take up to 24 hours from the time of the initial deposit.\nIf you notice a delay, this likely means that your check has been held for review. — [3] —. Settino Credit Union's team members monitor mobile deposits throughout the day, working hard to help resolve any issues so that you receive your funds in a timely fashion. Expect another communication from us shortly, notifying you of the status of your deposit.\nThank you for being a member of Settino Credit Union for over twenty years!", "tr": "수신: Samara Baker / 발신: Greg Wilson(Settino Credit Union) / 제목: 회신: 입출금 계좌 입금\n3950으로 끝나는 귀하의 입출금 계좌로 89.41달러 수표가 모바일 앱을 통해 입금 접수되었음을 확인해 드립니다. 다만 자금은 아직 사용할 수 없을 수 있습니다. 수표는 결제가 완료되면 거래 내역에 표시됩니다. 최초 입금 시점부터 최대 24시간이 걸릴 수 있습니다. ―[1]―\n지연이 있다면 수표가 검토를 위해 보류되었을 가능성이 큽니다. ―[2]― ―[3]― Settino Credit Union 직원들은 하루 종일 모바일 입금을 확인하며 자금을 제때 받으실 수 있도록 문제 해결에 힘쓰고 있습니다. 곧 입금 상태를 알리는 연락을 다시 드리겠습니다. ―[4]―\n20년 넘게 Settino Credit Union의 조합원이 되어 주셔서 감사합니다!", "questions": [{"no": 161, "q": "What is one purpose of the e-mail?", "options": ["To inquire about a transaction", "To verify an account withdrawal", "To request that an account be closed", "To explain a policy about mobile banking"], "answer": 3, "explain": "정답 (D) To explain a policy about mobile banking\n지문 개요: 신용협동조합이 모바일 앱으로 접수된 수표 입금 사실과 처리 소요 시간, 검토 보류 가능성을 안내하는 이메일이다.\n정답 근거: 모바일 입금이 처리되는 절차와 소요 시간, 보류 가능성을 설명하고 있다.\n오답 분석: (A): 거래를 문의하는 것이 아니라 확인해 주는 쪽이다. / (B): 출금이 아니라 입금이다. / (C): 계좌 해지 요청이 아니다.", "translation": "이 이메일의 한 가지 목적은 무엇인가?", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "one": ["숫자", "하나"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "the": ["관사", "그"], "e-mail": ["명사", "이메일"]}}, {"no": 162, "q": "What is indicated about Ms. Baker?", "options": ["She is a longtime member of Settino Credit Union.", "She makes mobile deposits every week.", "She is an experienced financial consultant.", "She worked at Settino Credit Union in the past."], "answer": 0, "explain": "정답 (A) She is a longtime member of Settino Credit Union.\n정답 근거: 20년 넘게 조합원이 되어 주어 감사하다고 했다.\n오답 분석: (B): 매주 입금한다는 언급이 없다. / (C): 재무 상담사라는 정보가 없다. / (D): 그곳에서 근무한 적이 있다는 내용이 없다.", "translation": "Baker 씨에 대해 언급된 것은?", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "언급된, 나타난", "indicate"], "about": ["전치사", "~에 관해"], "ms": ["명사", "~씨(여성)"], "baker": ["고유명사", "Baker(인명)"]}}, {"no": 163, "q": "In which of the positions marked [1]-[4] does the following sentence best belong? \"This may occur if the image of the check is too dark or blurry.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 2, "explain": "정답 (C) [3]\n정답 근거: 제시 문장이 보류가 일어나는 이유를 설명하므로 검토를 위해 보류될 수 있다는 문장 바로 뒤가 알맞다.\n오답 분석: (A) [1]: 아직 보류 이야기가 나오기 전이라 This가 가리킬 대상이 없다. / (B) [2]: 보류 문장과 같은 위치이지만 문장 흐름상 설명이 뒤따라야 한다. / (D) [4]: 후속 연락 안내 뒤라 문맥이 끊긴다.", "translation": "[1], [2], [3], [4] 중 다음 문장이 들어가기에 가장 적절한 곳은? \"This may occur if the image of the check is too dark or blurry.\"", "g": {"in": ["전치사", "~ 중에서"], "which": ["한정사", "어느"], "of": ["전치사", "~의"], "the": ["관사", "그"], "positions": ["명사", "위치들", "position"], "marked": ["과거분사", "표시된", "mark"], "1]-[4": ["숫자", "[1]~[4]"], "does": ["조동사", "(의문문 조동사)", "do"], "following": ["형용사", "다음의"], "sentence": ["명사", "문장"], "best": ["부사", "가장 잘", "well"], "belong": ["동사", "속하다, 들어가다"], "this": ["대명사", "이것"], "may": ["조동사", "~일지도 모른다"], "occur": ["동사", "발생하다"], "if": ["접속사", "만약 ~라면"], "image": ["명사", "이미지"], "check": ["명사", "수표"], "is": ["동사", "~이다", "be"], "too": ["부사", "너무"], "dark": ["형용사", "어두운"], "or": ["접속사", "또는"], "blurry": ["형용사", "흐릿한"]}}], "vocab": "deposit 명 입금, 예금 / confirm 동 확인해 주다 / funds 명 자금 / transaction 명 거래 / clear 동 (수표가) 결제되다 / in a timely fashion 구 제때에 / notify 동 알리다 || Paraphrase: 161. check will appear once it clears / up to 24 hours → explain a policy about mobile banking / 162. a member for over twenty years → a longtime member", "g": {"to": ["전치사", "~에게 / ~까지"], "samara": ["고유명사", "Samara(인명)"], "baker": ["고유명사", "Baker(인명)"], "from": ["전치사", "~로부터"], "greg": ["고유명사", "Greg(인명)"], "wilson": ["고유명사", "Wilson(인명)"], "settino": ["고유명사", "Settino(기관명)"], "credit": ["명사", "신용"], "union": ["명사", "조합(신용협동조합)"], "subject": ["명사", "제목"], "re": ["전치사", "회신(~에 관하여)"], "checking": ["명사", "입출금(계좌)"], "account": ["명사", "계좌"], "deposit": ["명사", "입금"], "i": ["대명사", "나"], "can": ["조동사", "~할 수 있다"], "confirm": ["동사", "확인해 주다"], "that": ["접속사", "~라는 것"], "we": ["대명사", "우리"], "have": ["조동사", "(현재완료) ~했다"], "received": ["과거분사", "받은", "receive"], "through": ["전치사", "~을 통해"], "our": ["대명사", "우리의"], "mobile": ["형용사", "모바일의"], "app": ["명사", "앱"], "a