"동사", "~이다", "be"], "less": ["부사", "덜"], "formal": ["형용사", "격식을 차린"], "important": ["형용사", "중요한"], "check": ["동사", "확인하다"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r11-p5',$mkd${"id": "a2-r11-p5", "area": "RC", "part": 5, "group": "A급 과제", "series": 2, "round": 11, "level": "중급", "title": "A급 과제 11회 · PART 5 (어휘 7·8회)", "notes": [], "items": [{"no": 101, "q": "Mr. Imura is out of the office, _____ Ms. Gunadi is available to meet with clients.", "options": ["for", "too", "but", "or"], "answer": 2, "explain": "정답 (C) but\n해석: Imura 씨는 자리를 비웠지만 Gunadi 씨가 고객을 만날 수 있다.\n정답 근거: 자리를 비웠다는 사실과 다른 사람이 응대할 수 있다는 사실이 대조되므로 등위접속사 but이 알맞다.\n오답 분석: (A) for: 이유를 덧붙일 때 쓰이며 대조를 나타내지 못한다. / (B) too: 부사라 두 절을 연결하지 못한다. / (D) or: 선택을 나타내 문맥과 맞지 않는다.", "translation": "Imura 씨는 자리를 비웠지만 Gunadi 씨가 고객을 만날 수 있다.", "vocab": "but 접 그러나 / out of the office 구 부재중인 / available 형 시간이 되는 / meet with 구 ~와 만나다", "g": {"mr": ["명사", "~씨(남성)"], "imura": ["고유명사", "Imura(인명)"], "is": ["동사", "~이다", "be"], "out": ["부사", "(out of) ~ 밖에"], "of": ["전치사", "(out of) 밖에"], "the": ["관사", "그"], "office": ["명사", "사무실"], "ms": ["명사", "~씨(여성)"], "gunadi": ["고유명사", "Gunadi(인명)"], "available": ["형용사", "시간이 되는"], "to": ["to부정사", "~할"], "meet": ["동사", "만나다(meet with)"], "with": ["전치사", "~와 함께, ~으로"], "clients": ["명사", "고객들", "client"]}, "src": "1-"}, {"no": 104, "q": "Always check e-mails for errors _____ sending them to clients.", "options": ["like", "ever", "toward", "before"], "answer": 3, "explain": "정답 (D) before\n해석: 고객에게 이메일을 보내기 전에 항상 오류를 확인하십시오.\n정답 근거: 확인이 발송보다 먼저라는 순서를 나타내야 하고 뒤에 -ing가 이어지므로 before가 알맞다.\n오답 분석: (A) like: '~처럼'. 시간 순서를 나타내지 못한다. / (B) ever: 부사라 동명사를 이끌지 못한다. / (D) toward: 방향을 뜻해 문맥과 맞지 않는다.", "translation": "고객에게 이메일을 보내기 전에 항상 오류를 확인하십시오.", "vocab": "before -ing 구 ~하기 전에 / check A for B 구 B가 있는지 A를 확인하다 / error 명 오류 / client 명 고객", "g": {"always": ["부사", "항상"], "check": ["동사", "확인하다"], "e-mails": ["명사", "이메일들", "e-mail"], "for": ["전치사", "~이 있는지"], "errors": ["명사", "오류들", "error"], "sending": ["동명사", "보내는 것", "send"], "them": ["대명사", "그것들을"], "to": ["전치사", "~에게"], "clients": ["명사", "고객들", "client"]}, "src": "1-"}, {"no": 106, "q": "Most of the antiques for sale at this month's auction were in excellent _____.", "options": ["quality", "condition", "value", "result"], "answer": 1, "explain": "정답 (B) condition\n해석: 이번 달 경매에 나온 골동품 대부분은 상태가 훌륭했다.\n정답 근거: in excellent condition은 「상태가 아주 좋은」을 뜻하는 표현이다.\n오답 분석: (A) quality: in excellent quality 형태로는 쓰이지 않는다. / (C) value: '가치'. 물건의 보존 상태를 나타내지 못한다. / (D) result: '결과'. 문맥과 무관하다.", "translation": "이번 달 경매에 나온 골동품 대부분은 상태가 훌륭했다.", "vocab": "condition 명 상태 / in excellent condition 구 상태가 아주 좋은 / antique 명 골동품 / auction 명 경매", "g": {"most": ["대명사", "대부분"], "of": ["전치사", "~의"], "the": ["관사", "그"], "antiques": ["명사", "골동품들", "antique"], "for": ["전치사", "(for sale) 판매용인"], "sale": ["명사", "판매"], "at": ["전치사", "~에서"], "this": ["한정사", "이"], "month's": ["명사", "이달의", "month"], "auction": ["명사", "경매"], "were": ["동사", "~였다", "be"], "in": ["전치사", "~한 상태에"], "excellent": ["형용사", "훌륭한"]}, "src": "1-"}, {"no": 109, "q": "Ell Fry, CEO at Equidential, will _____ a seminar on investment strategies for novice investors.", "options": ["behave", "charge", "contact", "lead"], "answer": 3, "explain": "정답 (D) lead\n해석: Equidential 최고 경영자 Ell Fry가 초보 투자자를 위한 투자 전략 세미나를 진행할 것이다.\n정답 근거: 세미나를 목적어로 취해 「진행하다」를 뜻해야 하므로 lead가 알맞다.\n오답 분석: (A) behave: 자동사여서 목적어를 취할 수 없다. / (B) charge: '청구하다'. 세미나 진행을 뜻하지 않는다. / (C) contact: '연락하다'. 사람을 목적어로 취한다.", "translation": "Equidential 최고 경영자 Ell Fry가 초보 투자자를 위한 투자 전략 세미나를 진행할 것이다.", "vocab": "lead 동 (세미나를) 진행하다, 이끌다 / investment strategy 명 투자 전략 / novice 명 초보자 / charge 동 청구하다", "g": {"ell": ["고유명사", "Ell(인명)"], "fry": ["고유명사", "Fry(인명)"], "ceo": ["명사", "최고 경영자"], "at": ["전치사", "~에서"], "equidential": ["고유명사", "회사명"], "will": ["조동사", "~할 것이다"], "a": ["관사", "하나의"], "seminar": ["명사", "세미나"], "on": ["전치사", "~에 관한"], "investment": ["명사", "투자"], "strategies": ["명사", "전략들", "strategy"], "for": ["전치사", "~을 위한"], "novice": ["형용사", "초보의"], "investors": ["명사", "투자자들", "investor"]}, "src": "1-"}, {"no": 111, "q": "Ms. Nomura will be _____ for a raise at the end of the fiscal year.", "options": ["eligible", "capable", "likely", "beneficial"], "answer": 0, "explain": "정답 (A) eligible\n해석: Nomura 씨는 회계연도 말에 임금 인상 대상이 될 것이다.\n정답 근거: be eligible for는 「~에 대한 자격이 있다」를 뜻하므로 뒤의 for와 자연스럽게 이어진다.\n오답 분석: (B) capable: 뒤에 of가 와야 한다. / (C) likely: 뒤에 to부정사가 오는 것이 자연스럽다. / (D) beneficial: '유익한'. 사람을 주어로 자격을 나타내지 못한다.", "translation": "Nomura 씨는 회계연도 말에 임금 인상 대상이 될 것이다.", "vocab": "be eligible for 구 ~의 자격이 있다 / raise 명 임금 인상 / fiscal year 명 회계연도 / capable of 구 ~할 능력이 있는", "g": {"ms": ["명사", "~씨(여성)"], "nomura": ["고유명사", "Nomura(인명)"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "for": ["전치사", "~에 대한"], "a": ["관사", "하나의"], "raise": ["명사", "임금 인상"], "at": ["전치사", "~에서"], "the": ["관사", "그"], "end": ["명사", "끝"], "of": ["전치사", "~의"], "fiscal": ["형용사", "회계의"], "year": ["명사", "연도"]}, "src": "1-"}, {"no": 112, "q": "_____ inclement weather, the departure of Flight 675 has been delayed.", "options": ["Nevertheless", "In spite of", "Because of", "Whenever"], "answer": 2, "explain": "정답 (C) Because of\n해석: 궂은 날씨 때문에 675편의 출발이 지연되었다.\n정답 근거: 뒤에 명사구가 오고 지연의 원인을 나타내므로 「~때문에」가 알맞다.\n오답 분석: (A) Nevertheless: 접속부사라 명사구를 이끌지 못한다. / (B) In spite of: 양보를 뜻해 인과 관계와 어긋남. / (D) Whenever: 접속사라 뒤에 절이 와야 한다.", "translation": "궂은 날씨 때문에 675편의 출발이 지연되었다.", "vocab": "because of 구 ~ 때문에 / inclement weather 명 궂은 날씨 / departure 명 출발 / delay 동 지연시키다", "g": {"inclement": ["형용사", "궂은"], "weather": ["명사", "날씨"], "the": ["관사", "그"], "departure": ["명사", "출발"], "of": ["전치사", "~의"], "flight": ["명사", "항공편"], "675": ["숫자", "675"], "has": ["조동사", "(현재완료) ~했다", "have"], "been": ["과거분사", "~였던(완료)", "be"], "delayed": ["과거분사", "지연된", "delay"]}, "src": "1-"}, {"no": 114, "q": "_____ Vice President Richter's schedule changes, we will move the strategy session to a later date.", "options": ["Ever", "If", "Even", "So"], "answer": 1, "explain": "정답 (B) If\n해석: Richter 부사장의 일정이 바뀌면 전략 회의를 나중으로 옮길 것이다.\n정답 근거: 뒤에 절이 이어지며 조건을 나타내야 하므로 If가 알맞다.\n오답 분석: (A) Ever: 부사라 절을 이끌 수 없다. / (C) Even: 부사도 마찬가지다. / (D) So: 결과를 나타내 조건을 표현하지 못한다.", "translation": "Richter 부사장의 일정이 바뀌면 전략 회의를 나중으로 옮길 것이다.", "vocab": "if 접 만약 ~라면 / strategy session 명 전략 회의 / move A to B 구 A를 B로 옮기다 / later date 명 추후 날짜", "g": {"vice": ["형용사", "부(副)"], "president": ["명사", "사장(부사장)"], "richter's": ["고유명사", "Richter의(인명)"], "schedule": ["명사", "일정"], "changes": ["동사", "바뀌다", "change"], "we": ["대명사", "우리"], "will": ["조동사", "~할 것이다"], "move": ["동사", "옮기다"], "the": ["관사", "그"], "strategy": ["명사", "전략"], "session": ["명사", "회의"], "to": ["전치사", "~로"], "a": ["관사", "하나의"], "later": ["형용사", "나중의", "late"], "date": ["명사", "날짜"]}, "src": "1-"}, {"no": 115, "q": "Employees are encouraged to attend our Healthy Living Workshop, which _____ on Monday.", "options": ["goes over", "takes place", "bring up", "occurs to"], "answer": 1, "explain": "정답 (B) takes place\n해석: 직원들은 월요일에 열리는 건강한 생활 워크숍에 참석하도록 권장된다.\n정답 근거: 행사가 열린다는 뜻이므로 take place가 알맞다.\n오답 분석: (A) goes over: '검토하다'. 행사 개최를 뜻하지 않는다. / (C) bring up: 수 일치가 맞지 않고 뜻도 다르다. / (D) occurs to: '~에게 떠오르다'. 행사 개최를 뜻하지 않는다.", "translation": "직원들은 월요일에 열리는 건강한 생활 워크숍에 참석하도록 권장된다.", "vocab": "take place 구 개최되다, 열리다 / be encouraged to do 구 ~하도록 권장되다 / go over 구 검토하다 / occur to 구 (생각이) 떠오르다", "g": {"employees": ["명사", "직원들", "employee"], "are": ["동사", "~이다", "be"], "encouraged": ["과거분사", "권장되는", "encourage"], "to": ["to부정사", "~하도록"], "attend": ["동사", "참석하다"], "our": ["대명사", "우리의"], "healthy": ["고유명사", "Healthy(행사명)"], "living": ["고유명사", "Living(행사명)"], "workshop": ["명사", "워크숍"], "which": ["관계사", "그리고 그것은(주격)"], "on": ["전치사", "~에, ~에 대해"], "monday": ["고유명사", "월요일"]}, "src": "1-"}, {"no": 117, "q": "The technician suggested _____ we purchase a new router to improve our internet connectivity.", "options": ["that", "while", "either", "must"], "answer": 0, "explain": "정답 (A) that\n해석: 기술자는 인터넷 연결을 개선하기 위해 새 공유기를 구입할 것을 제안했다.\n정답 근거: suggest는 뒤에 명사절 접속사 that이 이끄는 절을 목적어로 취한다.\n오답 분석: (B) while: 부사절 접속사라 목적어 역할을 하지 못한다. / (C) either: 상관접속사로 절을 이끌지 못한다. / (D) must: 조동사라 접속사 자리에 올 수 없다.", "translation": "기술자는 인터넷 연결을 개선하기 위해 새 공유기를 구입할 것을 제안했다.", "vocab": "suggest that 구 ~할 것을 제안하다 / purchase 동 구매하다 / improve 동 개선하다 / connectivity 명 연결(성)", "g": {"the": ["관사", "그"], "technician": ["명사", "기술자"], "suggested": ["동사", "제안했다", "suggest"], "we": ["대명사", "우리"], "purchase": ["동사", "구매하다"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "router": ["명사", "공유기"], "to": ["to부정사", "~하기 위해"], "improve": ["동사", "개선하다"], "our": ["대명사", "우리의"], "internet": ["명사", "인터넷"], "connectivity": ["명사", "연결성"]}, "src": "1-"}, {"no": 118, "q": "The finance department approved the _____ to increase the budget for the annual picnic.", "options": ["request", "creation", "production", "permit"], "answer": 0, "explain": "정답 (A) request\n해석: 재무 부서는 연례 야유회 예산을 늘려 달라는 요청을 승인했다.\n정답 근거: 승인의 대상이 되는 것이므로 「요청」을 뜻하는 request가 알맞다.\n오답 분석: (B) creation: '창작물'. 승인 대상으로 어색하다. / (C) production: '생산'. 예산 증액과 결합하지 않는다. / (D) permit: '허가증'. 승인하는 대상이 아니라 발급되는 것이다.", "translation": "재무 부서는 연례 야유회 예산을 늘려 달라는 요청을 승인했다.", "vocab": "request 명 요청 / approve 동 승인하다 / increase 동 늘리다 / annual 형 연례의", "g": {"the": ["관사", "그"], "finance": ["명사", "재무"], "department": ["명사", "부서"], "approved": ["동사", "승인했다", "approve"], "to": ["to부정사", "~하자는"], "increase": ["동사", "늘리다"], "budget": ["명사", "예산"], "for": ["전치사", "~을 위한"], "annual": ["형용사", "연례의"], "picnic": ["명사", "야유회"]}, "src": "1-"}, {"no": 120, "q": "The conference room is available on Monday beginning at _____ 10:00 A.M.", "options": ["extremely", "variously", "exceptionally", "approximately"], "answer": 3, "explain": "정답 (D) approximately\n해석: 회의실은 월요일 오전 10시경부터 이용할 수 있다.\n정답 근거: 시각을 앞에서 꾸며 근사치를 나타내야 하므로 「대략」이 알맞다.\n오답 분석: (A) extremely: '극도로'. 시각을 수식하지 못한다. / (B) variously: '다양하게'. 문맥과 맞지 않는다. / (C) exceptionally: '유난히'. 시각 표현과 어울리지 않는다.", "translation": "회의실은 월요일 오전 10시경부터 이용할 수 있다.", "vocab": "approximately 부 대략 / available 형 이용 가능한 / beginning at 구 ~부터 / exceptionally 부 유난히", "g": {"the": ["관사", "그"], "c