insert into content(key,data,updated_at) values('sec:a2-r11-p6',$mkd${"id": "a2-r11-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 2, "round": 11, "level": "중급", "title": "A급 과제 11회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "Montreal (19 September)— The Brazilian budget hotel chain Folha ---131--- plans to bring its brand to Canada. According to a statement by company spokesperson Luisa Santos, Montreal has been confirmed as the first location for the expansion. ---132---. The new structure will have 147 rooms that are simple, ---133---, and reasonably priced. Amenities will include a casual restaurant and rooftop patio. Like Folha's other properties, the Montreal hotel will be designed to appeal to younger travelers. ---134--- is scheduled to begin next year.", "tr": "몬트리올(9월 19일) ― 브라질의 저가 호텔 체인 Folha가 캐나다에 브랜드를 들여올 계획을 발표했다 (131). 회사 대변인 Luisa Santos의 발표에 따르면 몬트리올이 이번 확장의 첫 지역으로 확정되었다. Folha 몬트리올은 도심에서 여행객에게 새로운 숙박 선택지를 제공하게 된다 (132). 새 건물에는 단순하고 편안하며 (133) 합리적인 가격의 객실 147실이 들어선다. 편의시설로는 캐주얼 식당과 옥상 테라스가 마련된다. Folha의 다른 지점들처럼 몬트리올 호텔도 젊은 여행객의 취향에 맞게 설계된다. 공사 (134)는 내년에 시작될 예정이다.", "questions": [{"no": 131, "q": "", "options": ["canceled", "managed", "announced", "received"], "answer": 2, "explain": "정답 (C) announced\n지문 개요: 브라질 저가 호텔 체인이 몬트리올을 첫 진출지로 확정하고 객실과 편의시설, 착공 시점을 알린 기사다.\n정답 근거: 대변인의 발표 내용이 이어지므로 계획을 「발표했다」가 알맞다.\n오답 분석: (A) canceled: '취소했다'. 뒤의 확장 내용과 모순된다. / (B) managed: '관리했다'. 계획을 목적어로 취하기에 어색하다. / (D) received: '받았다'. 자사 계획과 어울리지 않는다.", "g": {}}, {"no": 132, "q": "", "options": ["Folha is the most recognized name in luxury accommodations.", "Folha executives will be meeting next week to make a decision.", "Folha Montreal will give travelers a new lodging option in the city center.", "Folha Montreal's grand opening next weekend is open to the public."], "answer": 2, "explain": "정답 (C) Folha Montreal will give travelers a new lodging option in the city center.\n정답 근거: 앞에서 몬트리올이 첫 진출지로 확정되었다고 했으므로 그 지점이 어떤 의미인지 설명하는 문장이 자연스럽다.\n오답 분석: (A): 저가 체인이라고 했으므로 고급 숙박이라는 설명과 어긋남. / (B): 이미 확정되었다고 했으므로 결정을 앞두고 있다는 말과 모순된다. / (D): 공사가 내년에 시작되므로 다음 주 개관이라는 말과 어긋남.", "g": {}}, {"no": 133, "q": "", "options": ["comfort", "comforts", "comforted", "comfortable"], "answer": 3, "explain": "정답 (D) comfortable\n정답 근거: simple, reasonably priced와 나란히 객실을 꾸미는 형용사 자리이므로 comfortable이 정답이다.\n오답 분석: (A) comfort: 명사는 형용사들과 병렬을 이루지 못한다. / (B) comforts: 복수 명사도 같은 이유로 불가하다. / (C) comforted: 감정동사의 -ed형은 사람을 꾸미므로 객실과 맞지 않는다.", "g": {}}, {"no": 134, "q": "", "options": ["Construction", "Research", "Assistance", "Discussion"], "answer": 0, "explain": "정답 (A) Construction\n정답 근거: 새 건물을 짓는 이야기이고 내년에 시작된다고 했으므로 「공사」가 알맞다.\n오답 분석: (B) Research: '연구'. 호텔 건립과 이어지지 않는다. / (C) Assistance: '지원'. 시작 대상이 되기에 어색하다. / (D) Discussion: '논의'. 이미 확정되었다는 내용과 어긋남.", "g": {}}], "vocab": "budget hotel 명 저가 호텔 / announce 동 발표하다 / expansion 명 확장 / confirm 동 확정하다 / reasonably priced 구 합리적인 가격의 / amenity 명 편의시설 / appeal to 구 ~의 마음을 끌다 / lodging 명 숙박 (시설)", "g": {"montreal": ["고유명사", "몬트리올(지명)"], "19": ["숫자", "19"], "september": ["고유명사", "9월"], "the": ["관사", "그"], "brazilian": ["형용사", "브라질의"], "budget": ["명사", "저가(저가 호텔)"], "hotel": ["명사", "호텔"], "chain": ["명사", "체인"], "folha": ["고유명사", "Folha(호텔명)"], "plans": ["명사", "계획들", "plan"], "to": ["to부정사", "~하려는 / ~로(전치사)"], "bring": ["동사", "들여오다"], "its": ["대명사", "그것의"], "brand": ["명사", "브랜드"], "canada": ["고유명사", "캐나다"], "according": ["부사", "~에 따르면"], "a": ["관사", "하나의"], "statement": ["명사", "발표, 성명"], "by": ["전치사", "~에 의해"], "company": ["명사", "회사"], "spokesperson": ["명사", "대변인"], "luisa": ["고유명사", "Luisa(인명)"], "santos": ["고유명사", "Santos(인명)"], "has": ["조동사", "(현재완료) ~했다", "have"], "been": ["과거분사", "~였던(완료)", "be"], "confirmed": ["과거분사", "확정된", "confirm"], "as": ["전치사", "~로"], "first": ["형용사", "첫 번째의"], "location": ["명사", "지점, 장소"], "for": ["전치사", "~을 위한"], "expansion": ["명사", "확장"], "new": ["형용사", "새로운"], "structure": ["명사", "건물"], "will": ["조동사", "~할 것이다"], "have": ["동사", "갖추다, 가지다"], "147": ["숫자", "147"], "rooms": ["명사", "객실", "room"], "that": ["관계사", "~하는(주격)"], "are": ["동사", "~이다", "be"], "simple": ["형용사", "단순한"], "and": ["접속사", "그리고"], "reasonably": ["부사", "합리적으로"], "priced": ["형용사", "가격이 매겨진"], "amenities": ["명사", "편의시설", "amenity"], "include": ["동사", "포함하다"], "casual": ["형용사", "캐주얼한"], "restaurant": ["명사", "식당"], "rooftop": ["명사", "옥상"], "patio": ["명사", "테라스"], "like": ["전치사", "~처럼"], "folha's": ["고유명사", "Folha의"], "other": ["형용사", "다른"], "properties": ["명사", "지점들(건물)", "property"], "be": ["동사", "~이다, 되다"], "designed": ["과거분사", "설계된", "design"], "appeal": ["동사", "마음을 끌다"], "younger": ["형용사", "더 젊은", "young"], "travelers": ["명사", "여행객들", "traveler"], "is": ["동사", "~이다", "be"], "scheduled": ["과거분사", "예정된", "schedule"], "begin": ["동사", "시작하다"], "next": ["형용사", "다음의"], "year": ["명사", "해"]}}, {"range": "135-138", "passage": "Accountarium: The quarterly magazine for accountants — Call for Submissions\nOur fourth and final edition of the year will include a feature on accountants who have made a career shift. The financial service ---135--- that accountants gain are in demand even by those seeking to hire for positions outside of finance. ---136---, many professional accountants have been persuaded to take on other roles.\nIf you have made such a change in careers, we would like to hear about it. In no more than 800 words describe your background in accounting and explain ---137--- it is useful in your new profession. Send this as an attachment to features@accountarium.com.\n---138---. We regret that submissions received after this date cannot be considered.", "tr": "Accountarium: 회계사를 위한 계간지 ― 기고 모집\n올해 네 번째이자 마지막 호에는 경력을 전환한 회계사에 관한 특집이 실립니다. 회계사가 갖추는 금융 서비스 역량 (135)은 재무 이외의 자리를 채우려는 곳에서도 수요가 높습니다. 그 결과 (136) 많은 전문 회계사가 다른 역할을 맡도록 권유받아 왔습니다. 그런 경력 전환을 하셨다면 그 이야기를 듣고 싶습니다. 800단어 이내로 회계 분야의 경력을 설명하고 그것이 새 직업에서 어떻게 (137) 도움이 되는지 밝혀 주십시오. features@accountarium.com으로 첨부해 보내 주십시오. 기고 마감일은 10월 15일입니다 (138). 이 날짜 이후에 접수된 원고는 검토할 수 없는 점 양해 바랍니다.", "questions": [{"no": 135, "q": "", "options": ["industry", "skills", "needs", "fields"], "answer": 1, "explain": "정답 (B) skills\n지문 개요: 회계 전문지가 경력을 전환한 회계사의 사연을 모집하며 분량과 제출 방법, 마감일을 안내하는 글이다.\n정답 근거: 회계사가 갖추어 다른 분야에서도 수요가 있는 것이므로 「역량」이 알맞다.\n오답 분석: (A) industry: '산업'. 개인이 갖추는 대상이 아니다. / (C) needs: '요구'. 수요의 대상이 되지 못한다. / (D) fields: '분야'. gain의 목적어로 어색하다.", "g": {}}, {"no": 136, "q": "", "options": ["Nevertheless", "Once again", "In addition", "Consequently"], "answer": 3, "explain": "정답 (D) Consequently\n정답 근거: 역량 수요가 높다는 앞 내용의 결과로 다른 역할을 맡게 되었다는 흐름이므로 인과 연결어가 알맞다.\n오답 분석: (A) Nevertheless: 양보를 나타내 문맥과 어긋남. / (B) Once again: 반복을 뜻해 인과 관계를 나타내지 못한다. / (C) In addition: 추가를 뜻해 결과 관계를 표현하지 못한다.", "g": {}}, {"no": 137, "q": "", "options": ["what", "whose", "how", "which"], "answer": 2, "explain": "정답 (C) how\n정답 근거: explain의 목적어인 명사절을 이끌고 뒤 문장 it is useful이 완전하므로 의문부사 how가 정답이다.\n오답 분석: (A) what: 뒤 문장에 빠진 성분이 있어야 한다. / (B) whose: 뒤에 명사가 이어져야 한다. / (D) which: 선택 대상이 없고 뒤 문장이 완전하다.", "g": {}}, {"no": 138, "q": "", "options": ["The deadline for submissions is October 15.", "We hire accountants at all stages of their careers.", "This credential is widely recognized.", "We thank you for your response received today."], "answer": 0, "explain": "정답 (A) The deadline for submissions is October 15.\n정답 근거: 바로 뒤 문장이 이 날짜 이후 접수분은 검토할 수 없다고 하므로 마감일을 밝히는 문장이 앞에 와야 한다.\n오답 분석: (B): 회계사 채용 안내는 기고 모집과 무관하다. / (C): 자격증 인지도는 마감 안내와 이어지지 않는다. / (D): 오늘 받은 답신에 대한 감사는 문맥에 맞지 않는다.", "g": {}}], "vocab": "submission 명 제출(물) / edition 명 (간행물의) 호 / career shift 명 진로 전환 / in demand 구 수요가 많은 / consequently 부 그 결과 / persuade 동 설득하다 / attachment 명 첨부 파일 / deadline 명 마감일", "g": {"accountarium": ["고유명사", "잡지명"], "the": ["관사", "그"], "quarterly": ["형용사", "계간의"], "magazine": ["명사", "잡지"], "for": ["전치사", "~을 위해"], "accountants": ["명사", "회계사들", "accountant"], "call": ["명사", "모집, 요청"], "submissions": ["명사", "기고, 제출물", "submission"], "our": ["대명사", "우리의"], "fourth": ["형용사", "네 번째의"], "and": ["접속사", "그리고"], "final": ["형용사", "마지막의"], "edition": ["명사", "호(간행물)"], "of": ["전치사", "~의"], "year": ["명사", "해"], "will": ["조동사", "~할 것이다"], "include": ["동사", "포함하다"], "a": ["관사", "하나의"], "feature": ["명사", "특집 기사"], "on": ["전치사", "~에 관한"], "who": ["관계사", "~하는(주격)"], "have": ["조동사", "(현재완료) ~했다"], "made": ["과거분사", "한", "make"], "career": ["명사", "경력, 직업"], "shift": ["명사", "전환"], "financial": ["형용사", "금융의"], "service": ["명사", "서비스"], "that": ["관계사", "~하는(목적격) / 접속사"], "gain": ["동사", "얻다"], "are": ["동사", "~이다", "be"], "in": ["전치사", "~에서, ~에"], "demand": ["명사", "수요(수요가 많은)"], "even": ["부사", "~조차"], "by": ["전치사", "~에 의해"], "those": ["대명사", "사람들"], "seeking": ["현재분사", "찾고 있는", "seek"], "to": ["to부정사", "~하려고 / ~에게(전치사)"], "hire": ["동사", "고용하다"], "positions": ["명사", "직책들", "position"], "outside": ["전치사", "~ 밖의"], "finance": ["명사", "재무, 금융"], "many": ["한정사", "많은"], "professional": ["형용사", "전문적인"], "been": ["과거분사", "~였던(완료)", "be"], "persuaded": ["과거분사", "설득된", "persuade"], "take": ["동사", "(take on) 맡다"], "other": ["형용사", "다른"], "roles": ["명사", "역할들", "role"], "if": ["접속사", "만약 ~라면"], "you": ["대명사", "당신"], "such": ["한정사", "그러한"], "change": ["명사", "변화"], "careers": ["명사", "경력", "career"], "we": ["대명사", "우리"], "would": ["조동사", "~할 것이다"], "like": ["동사", "~하고 싶다"], "hear": ["동사", "듣다"], "about": ["전치사", "~에 관해"], "it": ["대명사", "그것"], "no": ["부사", "~ 이하로(no more)"], "more": ["부사", "더"], "than": ["접속사", "~보다"], "800": ["숫자", "800"], "words": ["명사", "단어", "word"], "describe": ["동사", "설명하다"], "your": ["대명사", "당신의"], "background": ["명사", "경력, 배경"], "accounting": ["명사", "회계"], "explain": ["동사", "설명하다"], "is": ["동사", "~이다", "be"], "useful": ["형용사", "유용한"], "new": ["형용사", "새로운"], "profession": ["명사", "직업"], "send": ["동사", "보내다"], "this": ["한정사", "이"], "as": ["전치사", "~로"], "an": ["관사", "하나의"], "attachment": ["명사", "첨부 파일"], "features@accountarium.com": ["명사", "이메일 주소"], "regret": ["동사", "유감스럽게 생각하다"], "received": ["과거분사", "접수된", "receive"], "after": ["전치사", "~ 후에"], "date": ["명사", "날짜"], "cannot": ["조동사", "~할 수 없다"], "be": ["동사", "~이다, 되다"], "considered": ["과거분사", "검토되는", "consider"]}}, {"range": "139-142", "passage": "For months, Yi Zhang, owner of Zhang Office Supplies, had been searching for a way to increase ---139---. Then, by sheer chance, he heard about an approach called Voice of the Customer (VOC). \"When I called Hsing Market Research I was really intrigued as the method was presented to me. The representative I spoke with convinced me to give ---140--- a try.\" Mr. Zhang learned that VOC uses market research as an aid to designing targeted advertisements. Using the method, he first determined ---141--- what potential customers are concerned about and what they want when shopping for office supplies. Then he used candid quotes from the people who participated in his market research to create advertisements for his Web site. ---142---. \"Thanks to VOC,\" he says, smiling, \"my customer base has expanded like never before.\"", "tr": "Zhang Office Supplies의 주인 Yi Zhang은 몇 달 동안 매출 (139)을 늘릴 방법을 찾고 있었다. 그러던 중 우연히 Voice of the Customer(VOC)라는 방법을 알게 되었다. \"Hsing Market Research에 전화했을 때 방법을 설명받고 정말 흥미로웠습니다. 통화한 담당자가 그것 (140)을 한번 해 보라고 저를 설득했지요.\" Zhang 씨는 VOC가 표적 광고를 설계하는 데 도움이 되도록 시장 조사를 활용한다는 것을 알게 되었다. 이 방법을 써서 그는 먼저 잠재 고객이 무엇을 걱정하고 사무용품을 살 때 무엇을 원하는지 정확히 (141) 파악했다. 그런 다음 시장 조사에 참여한 사람들의 솔직한 발언을 활용해 웹사이트용 광고를 만들었다. 그는 그 발언을 이메일 발송 광고에도 활용했다 (142). \"VOC 덕분에 고객층이 전에 없이 넓어졌습니다.\" 그는 웃으며 말한다.", "questions": [{"no": 139, "q": "", "options": ["production", "capacity", "sales", "wages"], "answer": 2, "explain": "정답 (C) sales\n지문 개요: 사무용품점 주인이 시장 조사 기법을 활용해 광고를 만들고 고객층을 넓힌 경험을 소개하는 후기다.\n정답 근거: 마지막에 고객층이 넓어졌다고 했으므로 늘리려던 것은 「매출」이다.\n오답 분석: (A) production: '생산'. 소매점의 목표로 어색하다. / (B) capacity: '수용력'. 광고 활용과 연결되지 않는다. / (D) wages: '임금'. 사업주가 늘리려는 대상으로 부적절하다.", "g": {}}, {"no": 140, "q": "", "options": ["anyone", "it", "mine", "those"], "answer": 1, "explain": "정답 (B) it\n정답 근거: 앞에서 소개된 방법인 VOC를 가리키는 단수 목적격 대명사가 필요하므로 it이 정답이다.\n오답 분석: (A) anyone: 사람을 가리켜 방법을 대신하지 못한다. / (C) mine: 소유대명사라 방법을 가리킬 수 없다. / (D) those: 복수라 단수인 방법과 맞지 않는다.", "g": {}}, {"no": 141, "q": "", "options": ["exactly", "exact", "exacting", "exactness"], "answer": 0, "explain": "정답 (A) exactly\n정답 근거: 뒤의 명사절 전체를 꾸며 「정확히 무엇인지」를 나타내야 하므로 부사가 정답이다.\n오답 분석: (B) exact: 형용사가 꾸밀 명사가 없다. / (C) exacting: 분사도 이 자리에 맞지 않는다. / (D) exactness: 명사는 문장 구조상 들어갈 수 없다.", "g": {}}, {"no": 142, "q": "", "options": ["He has been in business for eleven years.", "He also used them in direct e-mail campaigns.", "He also owns a local supermarket.", "He plans to move to a smaller building."], "answer": 1, "explain": "정답 (B) He also used them in direct e-mail campaigns.\n정답 근거: 앞 문장이 고객 발언을 웹 광고에 활용했다는 내용이므로 같은 자료의 다른 활용을 덧붙이는 문장이 자연스럽다.\n오답 분석: (A): 사업 연수 언급은 활용 사례 흐름과 이어지지 않는다. / (C): 다른 사업체 소유 여부는 문맥과 무관하다. / (D): 이전 계획은 성과 이야기와 어긋남.", "g": {}}], "vocab": "by sheer chance 구 순전히 우연으로 / intrigued 형 흥미를 느낀 / convince 동 설득하다 / targeted 형 표적화된 / determine 동 알아내다 / candid 형 솔직한 / customer base 명 고객층 / expand 동 확대되다", "g": {"for": ["전치사", "~ 동안 / ~을"], "months": ["명사", "개월", "month"], "yi": ["고유명사", "Yi(인명)"], "zhang": ["고유명사", "Zhang(인명)"], "owner": ["명사", "주인"], "of": ["전치사", "~의"], "office": ["명사", "사무"], "supplies": ["명사", "용품", "supply"], "had": ["조동사", "(과거완료) ~해 왔었다", "have"], "been": ["과거분사", "~였던(완료)", "be"], "searching": ["현재분사", "찾고 있는", "search"], "a": ["관사", "하나의"], "way": ["명사", "방법"], "to": ["to부정사", "~할 / ~하기 위해"], "increase": ["동사", "늘리다"], "then": ["부사", "그러던 중, 그다음"], "by": ["전치사", "~에 의해"], "sheer": ["형용사", "순전한"], "chance": ["명사", "우연"], "he": ["대명사", "그"], "heard": ["동사", "들었다", "hear"], "about": ["전치사", "~에 관해"], "an": ["관사", "하나의"], "approach": ["명사", "방법, 접근법"], "called": ["동사", "전화했다", "call"], "voice": ["고유명사", "Voice(기법명)"], "the": ["관사", "그"], "customer": ["명사", "고객 / (기법명 일부)"], "voc": ["고유명사", "VOC(고객의 소리)"], "when": ["접속사", "~할 때"], "i": ["대명사", "나"], "hsing": ["고유명사", "Hsing(회사명)"], "market": ["명사", "시장"], "research": ["명사", "조사"], "was": ["동사", "~였다", "be"], "really": ["부사", "정말"], "intrigued": ["형용사", "흥미를 느낀"], "as": ["접속사", "~할 때"], "method": ["명사", "방법"], "presented": ["과거분사", "소개된", "present"], "me": ["대명사", "나를"], "representative": ["명사", "담당자"], "spoke": ["동사", "이야기했다", "speak"], "with": ["전치사", "~와 함께, ~으로"], "convinced": ["동사", "설득했다", "convince"], "give": ["동사", "(한번) 해 보다"], "try": ["명사", "시도"], "mr": ["명사", "~씨(남성)"], "learned": ["동사", "알게 되었다", "learn"], "that": ["접속사", "~라는 것"], "uses": ["동사", "활용하다", "use"], "aid": ["명사", "도움"], "designing": ["동명사", "설계하는 것", "design"], "targeted": ["형용사", "표적화된"], "advertisements": ["명사", "광고들", "advertisement"], "using": ["현재분사", "사용하여", "use"], "first": ["형용사", "첫 번째의"], "determined": ["동사", "알아냈다", "determine"], "what": ["대명사", "무엇"], "potential": ["형용사", "잠재적인"], "customers": ["명사", "고객들", "customer"], "are": ["동사", "~이다", "be"], "concerned": ["형용사", "걱정하는"], "and": ["접속사", "그리고"], "they": ["대명사", "그들"], "want": ["동사", "원하다"], "shopping": ["현재분사", "쇼핑하는", "shop"], "used": ["동사", "활용했다", "use"], "candid": ["형용사", "솔직한"], "quotes": ["명사", "발언, 인용구", "quote"], "from": ["전치사", "~로부터"], "people": ["명사", "사람들"], "who": ["관계사", "~하는(주격)"], "participated": ["동사", "참여했다", "participate"], "in": ["전치사", "~에서, ~에"], "his": ["대명사", "그의"], "create": ["동사", "만들다"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "thanks": ["명사", "~ 덕분에"], "says": ["동사", "말하다", "say"], "smiling": ["현재분사", "웃으면서", "smile"], "my": ["대명사", "나의"], "base": ["명사", "층(고객층)"], "has": ["조동사", "(현재완료) ~했다", "have"], "expanded": ["과거분사", "확대된", "expand"], "like": ["전치사", "~처럼"], "never": ["부사", "결코 ~ 않다"], "before": ["부사", "전에"]}}, {"range": "143-146", "passage": "To help reduce traffic congestion and make parking easier, Newgrange Township will provide free bus rides to and from this year's Newgrange County Fair. ---143--- will be available from Friday, June 5, to Sunday, June 7. Planned pickup locations include the Rhinesberg Elementary School on Route 38 and the Newgrange Municipal Building on Main Street.\nBuses going to the fair will depart from these locations hourly from 8 A.M. to 5 P.M. Buses ---144--- the fairgrounds on the half hour, from 8:30 A.M. to 7:30 P.M. Please note that children under the age of 16 must be accompanied by an adult. ---145---.\nThe Newgrange County Fair Committee thanks our generous sponsors for providing buses and ---146--- this year. We hope you will join us at the Newgrange County Fair!", "tr": "교통 혼잡을 줄이고 주차를 쉽게 하기 위해 Newgrange Township은 올해 Newgrange County Fair를 오가는 무료 버스를 운행합니다. 교통편 (143)은 6월 5일 금요일부터 6월 7일 일요일까지 이용할 수 있습니다. 예정된 승차 장소는 38번 도로의 Rhinesberg 초등학교와 Main Street의 Newgrange 시청 건물입니다. 박람회로 가는 버스는 오전 8시부터 오후 5시까지 매시 정각에 이 장소들에서 출발합니다. 버스는 오전 8시 30분부터 오후 7시 30분까지 매시 30분에 박람회장에서 출발합니다 (144). 16세 미만 어린이는 반드시 성인과 동행해야 합니다. 버스 안에서는 음식물 반입이 금지됩니다 (145). Newgrange County Fair 위원회는 올해 버스와 기사 (146)를 제공해 주신 후원자들께 감사드립니다. 박람회에서 뵙기를 바랍니다!", "questions": [{"no": 143, "q": "", "options": ["Refreshments", "Information", "Transportation", "Entertainment"], "answer": 2, "explain": "정답 (C) Transportation\n지문 개요: 지자체가 지역 박람회 기간에 무료 버스를 운행하며 정류장과 배차 시간, 주의 사항을 알리는 공지다.\n정답 근거: 앞 문장이 무료 버스 운행을 알리므로 그것을 가리키는 「교통편」이 알맞다.\n오답 분석: (A) Refreshments: '다과'. 버스 운행과 무관하다. / (B) Information: '정보'. 이용 대상이 되기에 어색하다. / (D) Entertainment: '오락'. 버스 운행을 가리키지 못한다.", "g": {}}, {"no": 144, "q": "", "options": ["will leave", "have left", "leaving", "left"], "answer": 0, "explain": "정답 (A) will leave\n정답 근거: 앞 문장이 will depart로 미래 시제이고 같은 안내가 이어지므로 미래 시제 동사가 정답이다.\n오답 분석: (B) have left: 현재완료라 예정된 운행과 맞지 않는다. / (C) leaving: 분사는 문장의 동사가 될 수 없다. / (D) left: 과거 시제라 앞으로의 일정과 어긋남.", "g": {}}, {"no": 145, "q": "", "options": ["Thank you for coming to this year's auto show.", "There will be an increase in the cost of the service.", "We hope you enjoyed your stay at the hotel.", "No food or drinks are permitted on the buses."], "answer": 3, "explain": "정답 (D) No food or drinks are permitted on the buses.\n정답 근거: 앞 문장이 동반 규정이므로 버스 이용 시 지켜야 할 또 다른 규정을 덧붙이는 문장이 자연스럽다.\n오답 분석: (A): 자동차 박람회가 아니라 지역 박람회다. / (B): 무료 운행이라고 했으므로 요금 인상은 모순된다. / (C): 호텔 숙박 언급은 문맥과 무관하다.", "g": {}}, {"no": 146, "q": "", "options": ["driven", "drivers", "drivable", "drive"], "answer": 1, "explain": "정답 (B) drivers\n정답 근거: 등위접속사 and로 명사 buses와 병렬을 이루며 후원자가 제공한 것이므로 사람 명사 drivers가 정답이다.\n오답 분석: (A) driven: 과거분사는 명사와 병렬될 수 없다. / (C) drivable: 형용사도 마찬가지다. / (D) drive: 동사는 buses와 병렬을 이루지 못한다.", "g": {}}], "vocab": "congestion 명 혼잡 / transportation 명 교통(편) / pickup location 명 승차 지점 / depart 동 출발하다 / hourly 부 매시간 / accompany 동 동반하다 / permit 동 허용하다 / generous 형 후한, 아낌없는", "g": {"to": ["to부정사", "~하기 위해 / ~로"], "help": ["동사", "돕다"], "reduce": ["동사", "줄이다"], "traffic": ["명사", "교통"], "congestion": ["명사", "혼잡"], "and": ["접속사", "그리고"], "make": ["동사", "만들다"], "parking": ["명사", "주차"], "easier": ["형용사", "더 쉬운", "easy"], "newgrange": ["고유명사", "Newgrange(지명)"], "township": ["명사", "군구(지자체)"], "will": ["조동사", "~할 것이다"], "provide": ["동사", "제공하다"], "free": ["형용사", "무료의"], "bus": ["명사", "버스"], "rides": ["명사", "승차", "ride"], "from": ["전치사", "~로부터"], "this": ["한정사", "이(올해의)"], "year's": ["명사", "올해의", "year"], "county": ["명사", "카운티, 군"], "fair": ["명사", "박람회"], "be": ["동사", "~이다, 되다"], "available": ["형용사", "이용 가능한"], "friday": ["고유명사", "금요일"], "june": ["고유명사", "6월"], "5": ["숫자", "5"], "sunday": ["고유명사", "일요일"], "7": ["숫자", "7"], "planned": ["과거분사", "예정된", "plan"], "pickup": ["명사", "승차"], "locations": ["명사", "장소들", "location"], "include": ["동사", "포함하다"], "the": ["관사", "그"], "rhinesberg": ["고유명사", "Rhinesberg(지명)"], "elementary": ["형용사", "초등의"], "school": ["명사", "학교"], "on": ["전치사", "~에, ~에 대해"], "route": ["명사", "도로"], "38": ["숫자", "38"], "municipal": ["형용사", "시의, 지방 자치의"], "building": ["명사", "건물"], "main": ["고유명사", "Main(도로명)"], "street": ["명사", "거리"], "buses": ["명사", "버스들", "bus"], "going": ["현재분사", "가는", "go"], "depart": ["동사", "출발하다"], "these": ["한정사", "이것들의"], "hourly": ["부사", "매시간"], "8": ["숫자", "8"], "a.m": ["부사", "오전"], "p.m": ["부사", "오후"], "fairgrounds": ["명사", "박람회장"], "half": ["형용사", "절반의"], "hour": ["명사", "시간(매시 30분에)"], "8:30": ["숫자", "8시 30분"], "7:30": ["숫자", "7시 30분"], "please": ["부사", "부디, ~해 주세요"], "note": ["동사", "유의하다"], "that": ["접속사", "~라는 것"], "children": ["명사", "어린이들", "child"], "under": ["전치사", "~ 미만의"], "age": ["명사", "나이"], "of": ["전치사", "~의"], "16": ["숫자", "16"], "must": ["조동사", "~해야 한다"], "accompanied": ["과거분사", "동반된", "accompany"], "by": ["전치사", "~에 의해"], "an": ["관사", "하나의"], "adult": ["명사", "성인"], "committee": ["명사", "위원회"], "thanks": ["동사", "감사하다", "thank"], "our": ["대명사", "우리의"], "generous": ["형용사", "후한"], "sponsors": ["명사", "후원자들", "sponsor"], "for": ["전치사", "~에 대해"], "providing": ["동명사", "제공하는 것", "provide"], "year": ["명사", "해"], "we": ["대명사", "우리"], "hope": ["동사", "바라다"], "you": ["대명사", "당신"], "join": ["동사", "함께하다"], "us": ["대명사", "우리를"], "at": ["전치사", "~에서"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r11-p7',$mkd${"id": "a2-r11-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 2, "round": 11, "level": "중급", "title": "A급 과제 11회 · PART 7 (기출독해 4문항 1·2회)", "notes": [], "items": [], "sets": [{"range": "159-162", "passage": "TRENTON (April 4)—Lavender Skin Care Company CEO Donald McGrath has announced his company's intention to move its corporate base of operations from Hamilton, New Jersey, to Boise, Idaho. This shift is scheduled to take place early next year. The driving factor for this plan appears to be the need to reduce costs. Mr. McGrath noted that he hopes to accomplish this by moving to an area where the taxes on property tend to be lower.\nSince his promotion from vice president of marketing last October, Mr. McGrath has made several changes to the company. Some of the changes include replacing the chief financial officer and discontinuing several underperforming products.", "tr": "트렌턴(4월 4일) ― Lavender Skin Care Company 최고 경영자 Donald McGrath가 본사 운영 거점을 뉴저지주 해밀턴에서 아이다호주 보이시로 옮기겠다는 계획을 발표했다. 이 이전은 내년 초에 이루어질 예정이다. 이 계획을 이끄는 요인은 비용을 줄일 필요인 것으로 보인다. McGrath 씨는 재산세가 대체로 더 낮은 지역으로 옮겨 이를 이루기를 바란다고 밝혔다. 지난 10월 마케팅 담당 부사장에서 승진한 이후 McGrath 씨는 회사에 여러 변화를 주었다. 그중에는 최고 재무 책임자 교체와 실적이 부진한 여러 제품의 단종이 포함된다.", "questions": [{"no": 159, "q": "What is the article mainly about?", "options": ["A corporate executive appointment", "A company headquarters relocation", "A local firm's latest earnings report", "A company's workforce expansion"], "answer": 1, "explain": "정답 (B) A company headquarters relocation\n지문 개요: 화장품 회사가 비용 절감을 위해 본사를 다른 주로 옮긴다는 계획과 최고 경영자의 이력·조치를 전하는 기사다.\n정답 근거: 본사 운영 거점을 다른 주로 옮긴다는 계획과 그 이유를 다루고 있다.\n오답 분석: (A): 임원 임명이 아니라 이전 계획이 중심이다. / (C): 실적 보고서가 아니다. / (D): 인력 확충 소식이 아니다.", "translation": "이 기사는 주로 무엇에 관한 것인가?", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "article": ["명사", "기사"], "mainly": ["부사", "주로"], "about": ["전치사", "~에 관해"]}}, {"no": 160, "q": "The word \"driving\" in paragraph 1, line 7, is closest in meaning to", "options": ["commuting", "operating", "motivating", "obsessing"], "answer": 2, "explain": "정답 (C) motivating\n정답 근거: 계획을 추진하게 만든 요인이라는 뜻이므로 「동기가 되는」이 가장 가깝다.\n오답 분석: (A) commuting: '통근하는'. 뜻이 전혀 다르다. / (B) operating: '운영하는'. 원인을 나타내지 못한다. / (D) obsessing: '집착하는'. 문맥과 맞지 않는다.", "translation": "첫 단락의 \"driving\"과 뜻이 가장 가까운 것은?", "g": {"the": ["관사", "그"], "word": ["명사", "단어"], "driving": ["형용사", "추진하는, 주된"], "in": ["전치사", "~에서, ~에"], "paragraph": ["명사", "단락"], "1": ["숫자", "1"], "line": ["명사", "줄, 행"], "7": ["숫자", "7"], "is": ["동사", "~이다", "be"], "closest": ["형용사", "가장 가까운", "close"], "meaning": ["명사", "의미"], "to": ["전치사", "~와(closest to)"]}}, {"no": 161, "q": "What expense does Mr. McGrath hope to reduce?", "options": ["Taxes", "Utilities", "Salaries", "Training"], "answer": 0, "explain": "정답 (A) Taxes\n정답 근거: 재산세가 더 낮은 지역으로 옮겨 비용 절감을 이루기를 바란다고 했다.\n오답 분석: (B): 공과금 언급이 없다. / (C): 급여 절감에 관한 내용이 없다. / (D): 교육비는 언급되지 않는다.", "translation": "McGrath 씨는 어떤 비용을 줄이고 싶어 하는가?", "g": {"what": ["대명사", "무엇"], "expense": ["명사", "비용"], "does": ["조동사", "(의문문 조동사)", "do"], "mr": ["명사", "~씨(남성)"], "mcgrath": ["고유명사", "McGrath(인명)"], "hope": ["동사", "바라다"], "to": ["to부정사", "~하기를"], "reduce": ["동사", "줄이다"]}}, {"no": 162, "q": "What was Mr. McGrath's former position?", "options": ["Chief financial officer", "Vice president", "Financial advisor", "Town mayor"], "answer": 1, "explain": "정답 (B) Vice president\n정답 근거: 지난 10월 마케팅 담당 부사장에서 승진했다고 밝힌다.\n오답 분석: (A): 최고 재무 책임자는 그가 교체한 자리다. / (C): 재무 자문이라는 언급이 없다. / (D): 시장 직책과 무관하다.", "translation": "McGrath 씨의 이전 직책은 무엇이었는가?", "g": {"what": ["대명사", "무엇"], "was": ["동사", "~였다", "be"], "mr": ["명사", "~씨(남성)"], "mcgrath's": ["고유명사", "McGrath의(인명)"], "former": ["형용사", "이전의"], "position": ["명사", "직책"]}}], "vocab": "intention 명 의사, 의도 / base of operations 명 본거지, 본사 / driving factor 명 주된 요인 / property 명 부동산, 재산 / promotion 명 승진 / discontinue 동 단종하다 / underperforming 형 실적이 저조한 || Paraphrase: move its corporate base of operations → a company headquarters relocation / taxes on property tend to be lower → (reduce) taxes / his promotion from vice president of marketing → former position → vice president", "g": {"trenton": ["고유명사", "트렌턴(지명)"], "april": ["고유명사", "4월"], "4)—lavender": ["고유명사", "4일)—Lavender"], "skin": ["고유명사", "Skin(회사명)"], "care": ["고유명사", "Care(회사명)"], "company": ["고유명사", "회사명 일부 / 회사"], "ceo": ["명사", "최고 경영자"], "donald": ["고유명사", "Donald(인명)"], "mcgrath": ["고유명사", "McGrath(인명)"], "has": ["조동사", "(현재완료) ~했다", "have"], "announced": ["과거분사", "발표한", "announce"], "his": ["대명사", "그의"], "company's": ["명사", "회사의", "company"], "intention": ["명사", "의사, 의도"], "to": ["to부정사", "~하려는 / ~로(전치사)"], "move": ["동사", "옮기다"], "its": ["대명사", "그것의"], "corporate": ["형용사", "기업의"], "base": ["명사", "거점(본사)"], "of": ["전치사", "~의"], "operations": ["명사", "운영", "operation"], "from": ["전치사", "~로부터"], "hamilton": ["고유명사", "해밀턴(지명)"], "new": ["고유명사", "뉴저지(지명)"], "jersey": ["고유명사", "뉴저지(지명)"], "boise": ["고유명사", "보이시(지명)"], "idaho": ["고유명사", "아이다호(지명)"], "this": ["한정사", "이 / 대명사 이것"], "shift": ["명사", "이전, 변화"], "is": ["동사", "~이다", "be"], "scheduled": ["과거분사", "예정된", "schedule"], "take": ["동사", "일어나다"], "place": ["명사", "일어남(take place)"], "early": ["부사", "초에, 일찍"], "next": ["형용사", "다음의"], "year": ["명사", "해"], "the": ["관사", "그"], "driving": ["형용사", "주된, 추진하는"], "factor": ["명사", "요인"], "for": ["전치사", "~에 대한"], "plan": ["명사", "계획"], "appears": ["동사", "~인 것 같다", "appear"], "be": ["동사", "~이다, 되다"], "need": ["명사", "필요"], "reduce": ["동사", "줄이다"], "costs": ["명사", "비용", "cost"], "mr": ["명사", "~씨(남성)"], "noted": ["동사", "언급했다", "note"], "that": ["접속사", "~라는 것"], "he": ["대명사", "그"], "hopes": ["동사", "바라다", "hope"], "accomplish": ["동사", "달성하다"], "by": ["전치사", "~에 의해"], "moving": ["동명사", "옮기는 것", "move"], "an": ["관사", "하나의"], "area": ["명사", "지역"], "where": ["관계사", "~하는 (곳)"], "taxes": ["명사", "세금", "tax"], "on": ["전치사", "~에, ~에 대해"], "property": ["명사", "부동산"], "tend": ["동사", "경향이 있다"], "lower": ["형용사", "더 낮은", "low"], "since": ["전치사", "~ 이후로"], "promotion": ["명사", "승진"], "vice": ["형용사", "부(副)"], "president": ["명사", "사장(부사장)"], "marketing": ["명사", "마케팅"], "last": ["형용사", "지난"], "october": ["고유명사", "10월"], "made": ["과거분사", "만든, 한", "make"], "several": ["한정사", "몇몇의"], "changes": ["명사", "변화들", "change"], "some": ["대명사", "일부"], "include": ["동사", "포함하다"], "replacing": ["동명사", "교체하는 것", "replace"], "chief": ["형용사", "최고의"], "financial": ["형용사", "재무의"], "officer": ["명사", "책임자"], "and": ["접속사", "그리고"], "discontinuing": ["동명사", "단종하는 것", "discontinue"], "underperforming": ["형용사", "실적이 저조한"], "products": ["명사", "제품들", "product"]}}, {"range": "168-171", "passage": "HOUSTON (July 11)—Retexo, Inc., a leader in global product analytics, announced today an assistance program to provide startup companies with access to its world-class services for a reduced price.\nRetexo aggregates data on users' interactions with programs or applications on computers, smartphones, or handheld devices. — [2] —. The results ensure that updates to clients' programs and applications are based on actual customers' needs.\nRetexo helps companies of all sizes retain customers by improving end-user engagement and overall satisfaction. Recent Retexo projects include Io's Rumist, an interior design program for desktop computers, and Zoida's Relay 4, an exercise monitoring application for smartphones.\nWith this new pricing option, Retexo is offering startup companies access to its full suite of services at 10 to 20 percent off the regular price. Accepted clients will be able to access weekly analyses of user interactions at the reduced rate for a period of twelve months. Details and application forms are available on the company's Web site.", "tr": "휴스턴(7월 11일) ― 세계적인 제품 분석 선도 기업 Retexo 사는 오늘 신생 기업이 자사의 최고 수준 서비스를 할인가로 이용할 수 있게 하는 지원 프로그램을 발표했다.\nRetexo는 컴퓨터, 스마트폰, 휴대 기기에서 사용자가 프로그램이나 앱과 어떻게 상호작용하는지에 관한 데이터를 모은다. ―[1]― ―[2]― 그 결과 고객사의 프로그램과 앱 업데이트가 실제 이용자의 요구에 근거하도록 해 준다.\nRetexo는 최종 사용자의 참여도와 전반적 만족도를 높여 규모를 가리지 않고 기업이 고객을 유지하도록 돕는다. 최근 사례로는 데스크톱용 실내 디자인 프로그램 Io의 Rumist, 스마트폰용 운동 관리 앱 Zoida의 Relay 4가 있다. ―[3]―\n이번 새 요금제로 Retexo는 신생 기업에 전체 서비스를 정가에서 10~20퍼센트 할인해 제공한다. 승인된 고객사는 12개월 동안 할인가로 주간 사용자 상호작용 분석을 이용할 수 있다. 자세한 내용과 신청서는 회사 웹사이트에서 볼 수 있다. ―[4]―", "questions": [{"no": 168, "q": "What products can Retexo help improve?", "options": ["Computer software", "Sporting goods", "Household furnishings", "Stereo equipment"], "answer": 0, "explain": "정답 (A) Computer software\n지문 개요: 제품 분석 업체가 신생 기업에 할인가로 분석 서비스를 제공하는 지원 프로그램을 발표한 소식을 전하는 기사다.\n정답 근거: 프로그램과 앱의 이용 데이터를 분석해 업데이트에 반영하도록 돕는다고 했다.\n오답 분석: (B): 운동 관리 앱은 소프트웨어이며 운동 용품이 아니다. / (C): 실내 디자인 프로그램이지 가구가 아니다. / (D): 음향 기기 언급이 없다.", "translation": "Retexo는 어떤 제품을 개선하도록 도울 수 있는가?", "g": {"what": ["대명사", "무엇"], "products": ["명사", "제품들", "product"], "can": ["조동사", "~할 수 있다"], "retexo": ["고유명사", "Retexo(회사명)"], "help": ["동사", "돕다"], "improve": ["동사", "개선하다"]}}, {"no": 169, "q": "What is stated as a benefit companies get from Retexo's service?", "options": ["An increase in customers", "A reduction in production costs", "More effective opinions", "Greater customer loyalty"], "answer": 3, "explain": "정답 (D) Greater customer loyalty\n정답 근거: 참여도와 만족도를 높여 기업이 고객을 유지하도록 돕는다고 했다.\n오답 분석: (A): 신규 고객 증가가 아니라 기존 고객 유지다. / (B): 생산비 절감 언급이 없다. / (C): 의견의 효과에 관한 내용이 아니다.", "translation": "Retexo의 서비스로 기업이 얻는 이점으로 언급된 것은?", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "stated": ["과거분사", "언급된", "state"], "as": ["전치사", "~로서"], "a": ["관사", "하나의"], "benefit": ["명사", "이점"], "companies": ["명사", "기업들", "company"], "get": ["동사", "얻다"], "from": ["전치사", "~로부터"], "retexo's": ["고유명사", "Retexo의"], "service": ["명사", "서비스"]}}, {"no": 170, "q": "How long can clients access Retexo's services at a reduced price?", "options": ["For one week", "For twenty weeks", "For ten months", "For one year"], "answer": 3, "explain": "정답 (D) For one year\n정답 근거: 승인된 고객사는 12개월 동안 할인가로 이용할 수 있다고 명시한다.\n오답 분석: (A): 주간 분석은 제공 주기이지 이용 기간이 아니다. / (B): 20은 할인율의 백분율이다. / (C): 10도 할인율 수치다.", "translation": "고객사는 얼마 동안 할인가로 서비스를 이용할 수 있는가?", "g": {"how": ["부사", "어떻게"], "long": ["부사", "오래(얼마나 오래)"], "can": ["조동사", "~할 수 있다"], "clients": ["명사", "고객사들", "client"], "access": ["동사", "이용하다"], "retexo's": ["고유명사", "Retexo의"], "services": ["명사", "서비스들", "service"], "at": ["전치사", "~로(가격)"], "a": ["관사", "하나의"], "reduced": ["형용사", "할인된"], "price": ["명사", "가격"]}}, {"no": 171, "q": "In which of the positions marked [1]-[4] does the following sentence best belong? \"Analyses of the data are then posted online for review by the client's development team.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 1, "explain": "정답 (B) [2]\n정답 근거: 데이터를 모은다는 문장 뒤에 분석 결과를 공개한다는 절차가 이어지고, 그 결과가 업데이트에 반영된다는 문장으로 연결되어야 자연스럽다.\n오답 분석: (A) [1]: 데이터 수집 설명 앞이라 then이 가리킬 단계가 없다. / (C) [3]: 사례 소개 뒤라 절차 설명이 뒤늦어 어색하다. / (D) [4]: 요금제 안내 뒤라 흐름이 끊긴다.", "translation": "[1]~[4] 중 다음 문장이 들어가기에 가장 적절한 곳은? \"Analyses of the data are then posted online for review by the client's development team.\"", "g": {"in": ["전치사", "~ 중에서"], "which": ["한정사", "어느"], "of": ["전치사", "~의"], "the": ["관사", "그"], "positions": ["명사", "위치들", "position"], "marked": ["과거분사", "표시된", "mark"], "1]-[4": ["숫자", "[1]~[4]"], "does": ["조동사", "(의문문 조동사)", "do"], "following": ["형용사", "다음의"], "sentence": ["명사", "문장"], "best": ["부사", "가장 잘", "well"], "belong": ["동사", "속하다, 들어가다"], "analyses": ["명사", "분석 결과들", "analysis"], "data": ["명사", "데이터"], "are": ["동사", "~이다", "be"], "then": ["부사", "그다음에"], "posted": ["과거분사", "게시된", "post"], "online": ["부사", "온라인에"], "for": ["전치사", "~을 위해"], "review": ["명사", "검토"], "by": ["전치사", "~에 의한"], "client's": ["명사", "고객사의", "client"], "development": ["명사", "개발"], "team": ["명사", "팀"]}}], "vocab": "analytics 명 분석(학) / aggregate 동 집계하다 / interaction 명 상호 작용 / retain 동 (고객을) 유지하다 / engagement 명 참여(도) / suite 명 (서비스) 일체, 모음 / reduced 형 할인된 || Paraphrase: programs or applications → computer software / helps companies retain customers → greater customer loyalty / for a period of twelve months → for one year", "g": {"houston": ["고유명사", "휴스턴(지명)"], "july": ["고유명사", "7월"], "11)—retexo": ["고유명사", "11일)—Retexo"], "inc": ["명사", "주식회사(Inc.)"], "a": ["관사", "하나의"], "leader": ["명사", "선도 기업"], "in": ["전치사", "~에서, ~에"], "global": ["형용사", "세계적인"], "product": ["명사", "제품"], "analytics": ["명사", "분석"], "announced": ["동사", "발표했다", "announce"], "today": ["부사", "오늘"], "an": ["관사", "하나의"], "assistance": ["명사", "지원"], "program": ["명사", "프로그램"], "to": ["to부정사", "~하는 / ~로(전치사)"], "provide": ["동사", "제공하다"], "startup": ["명사", "신생 기업"], "companies": ["명사", "기업들", "company"], "with": ["전치사", "~와 / ~으로"], "access": ["동사", "이용하다 / 명사 이용"], "its": ["대명사", "그것의"], "world-class": ["형용사", "세계 최고 수준의"], "services": ["명사", "서비스들", "service"], "for": ["전치사", "~에, ~을 위한"], "reduced": ["형용사", "할인된"], "price": ["명사", "가격"], "retexo": ["고유명사", "Retexo(회사명)"], "aggregates": ["동사", "모으다, 집계하다", "aggregate"], "data": ["명사", "데이터"], "on": ["전치사", "~에, ~에 대해"], "users'": ["명사", "사용자들의", "user"], "interactions": ["명사", "상호 작용", "interaction"], "programs": ["명사", "프로그램들", "program"], "or": ["접속사", "또는"], "applications": ["명사", "앱, 응용 프로그램", "application"], "computers": ["명사", "컴퓨터", "computer"], "smartphones": ["명사", "스마트폰", "smartphone"], "handheld": ["형용사", "휴대용의"], "devices": ["명사", "기기", "device"], "2": ["숫자", "2"], "the": ["관사", "그"], "results": ["명사", "결과들", "result"], "ensure": ["동사", "보장하다"], "that": ["접속사", "~라는 것"], "updates": ["명사", "업데이트들", "update"], "clients'": ["명사", "고객사들의", "client"], "and": ["접속사", "그리고"], "are": ["동사", "~이다", "be"], "based": ["과거분사", "근거한(based on)", "base"], "actual": ["형용사", "실제의"], "customers'": ["명사", "고객들의", "customer"], "needs": ["명사", "요구", "need"], "helps": ["동사", "돕다", "help"], "of": ["전치사", "~의"], "all": ["한정사", "모든"], "sizes": ["명사", "규모", "size"], "retain": ["동사", "유지하다"], "customers": ["명사", "고객들", "customer"], "by": ["전치사", "~에 의해"], "improving": ["동명사", "높이는 것", "improve"], "end-user": ["명사", "최종 사용자"], "engagement": ["명사", "참여도"], "overall": ["형용사", "전반적인"], "satisfaction": ["명사", "만족도"], "recent": ["형용사", "최근의"], "projects": ["명사", "프로젝트들", "project"], "include": ["동사", "포함하다"], "io's": ["고유명사", "Io의(회사명)"], "rumist": ["고유명사", "Rumist(제품명)"], "interior": ["형용사", "실내의"], "design": ["명사", "디자인"], "desktop": ["명사", "데스크톱"], "zoida's": ["고유명사", "Zoida의(회사명)"], "relay": ["고유명사", "Relay(제품명)"], "4": ["숫자", "4"], "exercise": ["명사", "운동"], "monitoring": ["명사", "관리, 모니터링"], "application": ["명사", "앱"], "this": ["한정사", "이"], "new": ["형용사", "새로운"], "pricing": ["명사", "가격 책정"], "option": ["명사", "선택 사항"], "is": ["동사", "~이다", "be"], "offering": ["현재분사", "제공하는", "offer"], "full": ["형용사", "전체의"], "suite": ["명사", "일체, 모음"], "at": ["전치사", "~로(가격)"], "10": ["숫자", "10"], "20": ["숫자", "20"], "percent": ["명사", "퍼센트"], "off": ["전치사", "~에서 할인된"], "regular": ["형용사", "정규의"], "accepted": ["과거분사", "승인된", "accept"], "clients": ["명사", "고객사들", "client"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "able": ["형용사", "~할 수 있는"], "weekly": ["형용사", "주간의"], "analyses": ["명사", "분석 결과들", "analysis"], "user": ["명사", "사용자"], "rate": ["명사", "요금"], "period": ["명사", "기간"], "twelve": ["숫자", "12"], "months": ["명사", "개월", "month"], "details": ["명사", "세부 사항", "detail"], "forms": ["명사", "양식", "form"], "available": ["형용사", "이용 가능한"], "company's": ["명사", "회사의", "company"], "web": ["명사", "웹"], "site": ["명사", "사이트"]}}, {"range": "172-175", "passage": "Florence Clark (10:30) I'm leaving for a conference in Paris in two hours. Jae-Ho, can you give us an update on our advertising campaign?\nJae-Ho Kong (10:33) Yes. We've expanded our advertising presence on several platforms—print, social media, and Internet. It seems to be working nicely. Our pool of listeners is growing.\nFlorence Clark (10:34) Well, that's good news. Anna, can you tell the others about some of the new shows that are in development?\nAnna Goswami (10:36) Sure. We have a new show that will debut on Saturday morning. It features news, followed by a listener call-in segment. Also, do you remember Trina Thompson, who hosted the short-lived Everything Under the Sun show? She's doing a new program now, Thompson, Take Two. We've also expanded our Sunday folk music afternoons to two hours.\nEsmond Seco (10:40) Yes, definitely. I'm actually writing up some notes now with all the details about what the extra hour will involve: production costs, schedules, and so on. I'll e-mail it out to all of you later today.\nFlorence Clark (10:42) OK. Well, I'm going to wrap up the meeting then, so I can head out to the airport and catch my plane.", "tr": "Florence Clark (10:30) 저는 두 시간 뒤 파리 학회로 떠납니다. Jae-Ho, 광고 캠페인 진행 상황을 알려 주시겠어요?\nJae-Ho Kong (10:33) 네. 인쇄물, 소셜 미디어, 인터넷 등 여러 매체로 광고를 넓혔습니다. 효과가 좋아 보입니다. 청취자층이 늘고 있어요.\nFlorence Clark (10:34) 좋은 소식이네요. Anna, 개발 중인 새 프로그램들을 다른 분들께 알려 주시겠어요?\nAnna Goswami (10:36) 물론이죠. 토요일 오전에 첫 방송되는 새 프로그램이 있습니다. 뉴스에 이어 청취자 전화 참여 코너가 이어집니다. 또 짧게 끝난 Everything Under the Sun을 진행했던 Trina Thompson 기억하시죠? 지금 Thompson, Take Two라는 새 프로그램을 맡고 있습니다. 일요일 오후 포크 음악 시간도 두 시간으로 늘렸습니다.\nEsmond Seco (10:40) 네, 물론입니다. 지금 늘어난 한 시간에 무엇이 들어갈지 제작비, 일정 등 세부 사항을 정리하고 있습니다. 오늘 중으로 모두에게 이메일로 보내겠습니다.\nFlorence Clark (10:42) 좋습니다. 그럼 공항으로 출발해 비행기를 타야 하니 회의를 마치겠습니다.", "questions": [{"no": 172, "q": "For what type of business do the chat participants most likely work?", "options": ["A travel agency", "A theater company", "A radio station", "An advertising firm"], "answer": 2, "explain": "정답 (C) A radio station\n지문 개요: 방송국 관계자들이 광고 성과와 신규 프로그램 편성, 추가 방송 시간에 관한 세부 사항을 공유하는 대화다.\n정답 근거: 청취자층, 전화 참여 코너, 포크 음악 시간대 등이 언급되므로 라디오 방송국이다.\n오답 분석: (A): 파리 학회는 개인 일정일 뿐이다. / (B): 극단 운영과 관련된 내용이 없다. / (D): 광고는 자사 홍보 활동이며 광고 대행이 아니다.", "translation": "대화 참여자들은 어떤 업종에서 일하겠는가?", "g": {"for": ["전치사", "~을 위해"], "what": ["대명사", "무엇"], "type": ["명사", "종류"], "of": ["전치사", "~의"], "business": ["명사", "업종, 사업"], "do": ["조동사", "(의문문 조동사)"], "the": ["관사", "그"], "chat": ["명사", "채팅"], "participants": ["명사", "참여자들", "participant"], "most": ["부사", "아마도"], "likely": ["부사", "아마"], "work": ["동사", "일하다"]}}, {"no": 173, "q": "What does Mr. Kong indicate to the others about their business?", "options": ["It is in the process of revising its Web page.", "It is becoming more popular.", "It has corrected a computer problem.", "It is expanding to other countries."], "answer": 1, "explain": "정답 (B) It is becoming more popular.\n정답 근거: 광고 확대가 효과를 내고 청취자층이 늘고 있다고 했다.\n오답 분석: (A): 웹페이지 개편 언급이 없다. / (C): 전산 문제 해결 이야기가 아니다. / (D): 해외 진출에 관한 내용이 없다.", "translation": "Kong 씨는 회사에 대해 무엇을 알리는가?", "g": {"what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "mr": ["명사", "~씨(남성)"], "kong": ["고유명사", "Kong(인명)"], "indicate": ["동사", "나타내다, 알리다"], "to": ["전치사", "~에게"], "the": ["관사", "그"], "others": ["대명사", "다른 사람들", "other"], "about": ["전치사", "~에 관해"], "their": ["대명사", "그들의"], "business": ["명사", "회사, 사업"]}}, {"no": 174, "q": "Who most likely is Ms. Thompson?", "options": ["The host of a new show", "A call center employee", "A folk musician", "A writer for a newspaper"], "answer": 0, "explain": "정답 (A) The host of a new show\n정답 근거: 지금 Thompson, Take Two라는 새 프로그램을 맡고 있다고 했다.\n오답 분석: (B): 전화 참여 코너는 프로그램 구성일 뿐이다. / (C): 포크 음악 시간대와 그녀는 연결되지 않는다. / (D): 신문 기고 언급이 없다.", "translation": "Thompson 씨는 누구이겠는가?", "g": {"who": ["대명사", "누구"], "most": ["부사", "아마도"], "likely": ["부사", "아마"], "is": ["동사", "~이다", "be"], "ms": ["명사", "~씨(여성)"], "thompson": ["고유명사", "Thompson(인명)"]}}, {"no": 175, "q": "At 10:40 A.M., what does Mr. Seco most likely mean when he writes, \"Yes, definitely\"?", "options": ["He is sure that Ms. Goswami's information is correct.", "He believes that he can have his work completed on time.", "He is willing to do one of Ms. Clark's tasks while she is away.", "He is confident that he can provide information to the others."], "answer": 3, "explain": "정답 (D) He is confident that he can provide information to the others.\n정답 근거: 곧이어 세부 사항을 정리해 오늘 중으로 모두에게 이메일로 보내겠다고 덧붙였다.\n오답 분석: (A): 상대 정보의 정확성을 확인하는 맥락이 아니다. / (B): 자기 업무 마감을 말하는 것이 아니라 자료 공유를 약속한다. / (C): 자리를 비우는 사람의 업무를 대신하겠다는 말이 아니다.", "translation": "오전 10시 40분에 Seco 씨가 \"Yes, definitely\"라고 쓴 의도는 무엇이겠는가?", "g": {"at": ["전치사", "~에서"], "10:40": ["숫자", "10시 40분"], "a.m": ["부사", "오전"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "mr": ["명사", "~씨(남성)"], "seco": ["고유명사", "Seco(인명)"], "most": ["부사", "아마도"], "likely": ["부사", "아마"], "mean": ["동사", "의미하다"], "when": ["접속사", "~할 때"], "he": ["대명사", "그"], "writes": ["동사", "쓰다", "write"], "yes": ["감탄사", "네"], "definitely": ["부사", "물론, 확실히"]}}], "vocab": "presence 명 (광고) 노출, 존재 / pool 명 (청취자) 집단 / debut 동 첫선을 보이다 / segment 명 (프로그램) 코너 / short-lived 형 단명한, 오래가지 못한 / host 동/명 진행하다; 진행자 / wrap up 구 마무리하다 || Paraphrase: listeners, shows, call-in segment → a radio station (업종 추론) / Our pool of listeners is growing → becoming more popular / She's doing a new program now → the host of a new show", "g": {"florence": ["고유명사", "Florence(인명)"], "clark": ["고유명사", "Clark(인명)"], "10:30": ["숫자", "10시 30분"], "i'm": ["대명사", "나는 ~이다(I am)"], "leaving": ["현재분사", "떠나는", "leave"], "for": ["전치사", "~로(향해) / ~에 대해"], "a": ["관사", "하나의"], "conference": ["명사", "학회, 회의"], "in": ["전치사", "~ 후에 / ~에"], "paris": ["고유명사", "파리"], "two": ["고유명사", "Two(프로그램명)"], "hours": ["명사", "시간", "hour"], "jae-ho": ["고유명사", "Jae-Ho(인명)"], "can": ["조동사", "~할 수 있다"], "you": ["대명사", "당신"], "give": ["동사", "주다"], "us": ["대명사", "우리를"], "an": ["관사", "하나의"], "update": ["명사", "최신 소식"], "on": ["전치사", "~에"], "our": ["대명사", "우리의"], "advertising": ["명사", "광고"], "campaign": ["명사", "캠페인"], "kong": ["고유명사", "Kong(인명)"], "10:33": ["숫자", "10시 33분"], "yes": ["감탄사", "네"], "we've": ["대명사", "우리는 ~했다"], "expanded": ["과거분사", "확대한", "expand"], "presence": ["명사", "노출, 존재"], "several": ["한정사", "몇몇의"], "platforms—print": ["명사", "매체들—인쇄물"], "social": ["형용사", "사회의"], "media": ["명사", "미디어"], "and": ["접속사", "그리고"], "internet": ["명사", "인터넷"], "it": ["대명사", "그것"], "seems": ["동사", "~인 것 같다", "seem"], "to": ["to부정사", "~하는 것 / ~로(전치사)"], "be": ["동사", "~이다, 되다"], "working": ["현재분사", "효과가 있는", "work"], "nicely": [