insert into content(key,data,updated_at) values('sec:a2-r12-p5',$mkd${"id": "a2-r12-p5", "area": "RC", "part": 5, "group": "A급 과제", "series": 2, "round": 12, "level": "중급", "title": "A급 과제 12회 · PART 5 (어휘 9·10회)", "notes": [], "items": [{"no": 103, "q": "Software support professionals must _____ the training session on Tuesday afternoon.", "options": ["attend", "invite", "reply", "propose"], "answer": 0, "explain": "정답 (A) attend\n해석: 소프트웨어 지원 담당자들은 화요일 오후 교육에 참석해야 한다.\n정답 근거: 교육을 목적어로 취해 「참석하다」를 뜻해야 하므로 attend가 알맞다.\n오답 분석: (B) invite: '초대하다'. 교육을 목적어로 취하기에 어색하다. / (C) reply: 자동사여서 목적어를 바로 취할 수 없다. / (D) propose: '제안하다'. 참석 의무와 뜻이 다르다.", "translation": "소프트웨어 지원 담당자들은 화요일 오후 교육에 참석해야 한다.", "vocab": "attend 동 참석하다 / training session 명 교육 (과정) / propose 동 제안하다 / reply 동 답장하다", "g": {"software": ["명사", "소프트웨어"], "support": ["명사", "지원"], "professionals": ["명사", "전문가, 담당자", "professional"], "must": ["조동사", "~해야 한다"], "the": ["관사", "그"], "training": ["명사", "교육"], "session": ["명사", "(교육) 시간, 과정"], "on": ["전치사", "~에"], "tuesday": ["고유명사", "화요일"], "afternoon": ["명사", "오후"]}, "src": "1-"}, {"no": 105, "q": "The designer provided several _____ to choose from for the lobby walls.", "options": ["recipes", "photographs", "agreements", "signatures"], "answer": 1, "explain": "정답 (B) photographs\n해석: 디자이너는 로비 벽에 걸 것을 고를 수 있도록 사진 몇 점을 제공했다.\n정답 근거: 벽에 거는 용도로 고를 수 있는 것이므로 「사진」이 알맞다.\n오답 분석: (A) recipes: '조리법'. 벽 장식과 무관하다. / (C) agreements: '합의서'. 고르는 대상으로 어색하다. / (D) signatures: '서명'. 벽에 거는 대상이 아니다.", "translation": "디자이너는 로비 벽에 걸 것을 고를 수 있도록 사진 몇 점을 제공했다.", "vocab": "photograph 명 사진 / provide 동 제공하다 / choose from 구 ~에서 고르다 / signature 명 서명", "g": {"the": ["관사", "그"], "designer": ["명사", "디자이너"], "provided": ["동사", "제공했다", "provide"], "several": ["한정사", "몇몇의"], "to": ["to부정사", "~할 (수 있는)"], "choose": ["동사", "고르다"], "from": ["전치사", "~ 중에서"], "for": ["전치사", "~에 쓸, ~을 위한"], "lobby": ["명사", "로비"], "walls": ["명사", "벽", "wall"]}, "src": "1-"}, {"no": 107, "q": "For one week only, city residents may buy a _____ membership to the Longtree Zoological Park at half the cost.", "options": ["additional", "regular", "potential", "direct"], "answer": 1, "explain": "정답 (B) regular\n해석: 단 일주일간 시민들은 Longtree 동물원 정규 회원권을 절반 가격에 살 수 있다.\n정답 근거: 정가의 절반이라는 할인과 대비되는 평상시 회원권을 뜻해야 하므로 「정규의」가 알맞다.\n오답 분석: (A) additional: '추가의'. 할인 대상 회원권을 특정하지 못한다. / (C) potential: '잠재적인'. 회원권을 꾸미기에 어색하다. / (D) direct: '직접적인'. 문맥과 맞지 않는다.", "translation": "단 일주일간 시민들은 Longtree 동물원 정규 회원권을 절반 가격에 살 수 있다.", "vocab": "regular 형 정상의, 보통의 / resident 명 주민 / membership 명 회원권 / at half the cost 구 절반 가격에", "g": {"for": ["전치사", "~ 동안"], "one": ["숫자", "하나의, 1"], "week": ["명사", "주"], "only": ["부사", "오직, ~만"], "city": ["명사", "시, 도시"], "residents": ["명사", "주민", "resident"], "may": ["조동사", "~할 수 있다"], "buy": ["동사", "사다"], "a": ["관사", "하나의"], "membership": ["명사", "회원권"], "to": ["전치사", "~의, ~에 대한"], "the": ["관사", "그"], "longtree": ["고유명사", "Longtree(명칭)"], "zoological": ["형용사", "동물학의"], "park": ["명사", "공원"], "at": ["전치사", "~의 (가격)으로"], "half": ["한정사", "절반의"], "cost": ["명사", "비용, 가격"]}, "src": "1-"}, {"no": 108, "q": "The plans _____ the new shopping center include the construction of two new buildings.", "options": ["across", "into", "for", "on"], "answer": 2, "explain": "정답 (C) for\n해석: 새 쇼핑센터를 위한 계획에는 새 건물 두 채의 건설이 포함된다.\n정답 근거: 계획의 대상을 나타내야 하므로 「~을 위한」을 뜻하는 for가 알맞다.\n오답 분석: (A) across: '~을 가로질러'. 계획의 대상을 나타내지 못한다. / (B) into: 방향·변화를 뜻해 어색하다. / (D) on: 주제를 나타내지만 건설 계획에는 for가 자연스럽다.", "translation": "새 쇼핑센터를 위한 계획에는 새 건물 두 채의 건설이 포함된다.", "vocab": "plans for 구 ~을 위한 계획 / construction 명 건설 / include 동 포함하다 / shopping center 명 쇼핑센터", "g": {"the": ["관사", "그"], "plans": ["명사", "계획", "plan"], "new": ["형용사", "새로운"], "shopping": ["명사", "쇼핑"], "center": ["명사", "센터"], "include": ["동사", "포함하다"], "construction": ["명사", "건설"], "of": ["전치사", "~의"], "two": ["숫자", "둘, 2"], "buildings": ["명사", "건물", "building"]}, "src": "1-"}, {"no": 111, "q": "The kebab kiosk is one of the busiest shops in the food court, serving _____ thirty customers per hour.", "options": ["enough", "much", "nearly", "very"], "answer": 2, "explain": "정답 (C) nearly\n해석: 케밥 매점은 푸드코트에서 가장 붐비는 가게 중 하나로 시간당 거의 서른 명을 응대한다.\n정답 근거: 수치 thirty를 앞에서 꾸며 근사치를 나타내야 하므로 「거의」가 알맞다.\n오답 분석: (A) enough: '충분한'. 수치를 수식해 근사치를 나타내지 못한다. / (B) much: 불가산 명사를 꾸미며 수치와 맞지 않는다. / (D) very: 형용사·부사를 강조하며 수치를 꾸미지 않는다.", "translation": "케밥 매점은 푸드코트에서 가장 붐비는 가게 중 하나로 시간당 거의 서른 명을 응대한다.", "vocab": "nearly 부 거의 / serve 동 (손님을) 응대하다 / per hour 구 시간당 / kiosk 명 간이 매장", "g": {"the": ["관사", "그"], "kebab": ["명사", "케밥"], "kiosk": ["명사", "간이 매장"], "is": ["동사", "~이다", "be"], "one": ["대명사", "하나"], "of": ["전치사", "~의"], "busiest": ["형용사", "가장 바쁜", "busy"], "shops": ["명사", "가게", "shop"], "in": ["전치사", "~ 안에서"], "food": ["명사", "음식"], "court": ["명사", "(상가 내) 구역"], "serving": ["현재분사", "응대하면서", "serve"], "thirty": ["숫자", "서른, 30"], "customers": ["명사", "고객", "customer"], "per": ["전치사", "~당"], "hour": ["명사", "시간"]}, "src": "1-"}, {"no": 113, "q": "Laboratory technician trainees at Velby Hospital _____ one year learning to conduct tests and prepare reports for physicians.", "options": ["release", "supply", "spend", "exist"], "answer": 2, "explain": "정답 (C) spend\n해석: Velby 병원의 실험실 기사 수습생들은 검사 수행과 보고서 작성을 배우며 1년을 보낸다.\n정답 근거: 「spend + 시간 + -ing」 구조로 시간을 보낸다는 뜻이므로 spend가 알맞다.\n오답 분석: (A) release: '풀어 주다'. 시간과 결합하지 않는다. / (B) supply: '공급하다'. 이 구조를 이루지 못한다. / (D) exist: 자동사여서 목적어를 취할 수 없다.", "translation": "Velby 병원의 실험실 기사 수습생들은 검사 수행과 보고서 작성을 배우며 1년을 보낸다.", "vocab": "spend + 시간 -ing 구 ~하며 (시간을) 보내다 / conduct 동 수행하다 / physician 명 의사 / trainee 명 수습생", "g": {"laboratory": ["명사", "실험실"], "technician": ["명사", "기사, 기술자"], "trainees": ["명사", "수습생", "trainee"], "at": ["전치사", "~의, ~에서"], "velby": ["고유명사", "Velby(명칭)"], "hospital": ["명사", "병원"], "one": ["숫자", "하나의, 1"], "year": ["명사", "해, 1년"], "learning": ["현재분사", "배우면서", "learn"], "to": ["to부정사", "~하는 것"], "conduct": ["동사", "수행하다"], "tests": ["명사", "검사", "test"], "and": ["접속사", "그리고"], "prepare": ["동사", "준비하다, 작성하다"], "reports": ["명사", "보고서", "report"], "for": ["전치사", "~에게, ~을 위해"], "physicians": ["명사", "의사", "physician"]}, "src": "1-"}, {"no": 114, "q": "Wintone's spring performances were canceled _____ poor ticket sales.", "options": ["because of", "in place of", "as well as", "in contrast to"], "answer": 0, "explain": "정답 (A) because of\n해석: 표 판매가 저조해 Wintone의 봄 공연이 취소되었다.\n정답 근거: 뒤에 명사구가 오고 취소의 원인을 나타내므로 「~때문에」가 알맞다.\n오답 분석: (B) in place of: '~대신에'. 인과 관계를 나타내지 못한다. / (C) as well as: 병렬을 뜻해 이유를 표현하지 못한다. / (D) in contrast to: 대조를 나타내 문맥과 어긋남.", "translation": "표 판매가 저조해 Wintone의 봄 공연이 취소되었다.", "vocab": "because of 구 ~ 때문에 / cancel 동 취소하다 / poor 형 저조한 / in place of 구 ~ 대신에", "g": {"wintone's": ["고유명사", "Wintone의"], "spring": ["명사", "봄"], "performances": ["명사", "공연", "performance"], "were": ["동사", "~이었다", "be"], "canceled": ["과거분사", "취소된", "cancel"], "poor": ["형용사", "저조한"], "ticket": ["명사", "표, 티켓"], "sales": ["명사", "판매(량)", "sale"]}, "src": "1-"}, {"no": 116, "q": "For Westville City residents _____ commute by train frequently, monthly passes offer significant savings.", "options": ["one", "each", "they", "who"], "answer": 3, "explain": "정답 (D) who\n해석: 기차로 자주 통근하는 Westville 시민들에게 월정액권은 상당한 절약이 된다.\n정답 근거: 사람 명사 residents를 선행사로 받아 뒤 절의 주어 역할을 하는 주격 관계대명사가 필요하다.\n오답 분석: (A) one: 대명사라 접속 기능이 없다. / (B) each: 한정사·대명사여서 절을 이끌지 못한다. / (C) they: 접속사 기능이 없어 두 절을 연결하지 못한다.", "translation": "기차로 자주 통근하는 Westville 시민들에게 월정액권은 상당한 절약이 된다.", "vocab": "who 관계대명사 (사람 선행사 뒤) ~하는 / commute 동 통근하다 / significant 형 상당한 / savings 명 절약(액)", "g": {"for": ["전치사", "~에게"], "westville": ["고유명사", "Westville(지명)"], "city": ["명사", "시"], "residents": ["명사", "주민", "resident"], "commute": ["동사", "통근하다"], "by": ["전치사", "~을 타고, ~로"], "train": ["명사", "기차"], "frequently": ["부사", "자주"], "monthly": ["형용사", "월간의"], "passes": ["명사", "정기권", "pass"], "offer": ["동사", "제공하다"], "significant": ["형용사", "상당한"], "savings": ["명사", "절약(액)"]}, "src": "1-"}, {"no": 117, "q": "Sixteen years is the age _____ to obtain a driver's learning permit in the province.", "options": ["requirement", "desire", "influence", "schedule"], "answer": 0, "explain": "정답 (A) requirement\n해석: 이 주에서 운전 연습 면허를 받으려면 만 16세라는 연령 요건을 충족해야 한다.\n정답 근거: age와 결합해 「연령 요건」을 뜻해야 하므로 requirement가 알맞다.\n오답 분석: (B) desire: '바람'. 규정 요건을 뜻하지 않는다. / (C) influence: '영향'. 문맥과 무관하다. / (D) schedule: '일정'. 연령 기준을 나타내지 못한다.", "translation": "이 주에서 운전 연습 면허를 받으려면 만 16세라는 연령 요건을 충족해야 한다.", "vocab": "requirement 명 요건 / obtain 동 취득하다 / permit 명 허가증 / province 명 (행정구역) 주", "g": {"sixteen": ["숫자", "열여섯, 16"], "years": ["명사", "살, 해", "year"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "age": ["명사", "나이"], "to": ["to부정사", "~하기 위한"], "obtain": ["동사", "취득하다"], "a": ["관사", "하나의"], "driver's": ["명사", "운전자의", "driver"], "learning": ["명사", "학습, 연습"], "permit": ["명사", "허가증"], "in": ["전치사", "~에서"], "province": ["명사", "(행정구역) 주"]}, "src": "1-"}, {"no": 118, "q": "An authorization statement must be filed _____ funds may be transferred from your account.", "options": ["before", "while", "as if", "that"], "answer": 0, "explain": "정답 (A) before\n해석: 계좌에서 자금이 이체되기 전에 승인서를 제출해야 한다.\n정답 근거: 뒤에 절이 이어지며 제출이 이체보다 먼저라는 순서를 나타내야 하므로 before가 알맞다.\n오답 분석: (B) while: 동시성을 나타내 순서를 표현하지 못한다. / (C) as if: '마치 ~인 것처럼'. 문맥과 맞지 않는다. / (D) that: 명사절 접속사라 이 자리에 어울리지 않는다.", "translation": "계좌에서 자금이 이체되기 전에 승인서를 제출해야 한다.", "vocab": "before 접 ~하기 전에 / authorization 명 승인 / file 동 (서류를) 제출하다 / transfer 동 이체하다", "g": {"an": ["관사", "하나의"], "authorization": ["명사", "승인"], "statement": ["명사", "진술서, 서류"], "must": ["조동사", "~해야 한다"], "be": ["동사", "~이다, 되다"], "filed": ["과거분사", "제출된", "file"], "funds": ["명사", "자금", "fund"], "may": ["조동사", "~할 수 있다"], "transferred": ["과거분사", "이체된", "transfer"], "from": ["전치사", "~에서"], "your": ["대명사", "여러분의, 당신의"], "account": ["명사", "계좌"]}, "src": "1-"}, {"no": 120, "q": "Reimbursements will not be issued _____ all travel documents and receipts have been processed and approved.", "options": ["except", "about", "without", "until"], "answer": 3, "explain": "정답 (D) until\n해석: 모든 출장 서류와 영수증이 처리·승인될 때까지는 경비가 상환되지 않는다.\n정답 근거: 「not ~ until」 구조로 조건이 갖춰질 때까지 이루어지지 않는다는 뜻이므로 until이 알맞다.\n오답 분석: (A) except: 뒤에 절을 이끌기 어렵고 뜻도 맞지 않는다. / (B) about: 전치사라 절을 이끌지 못한다. / (C) without: 전치사여서 뒤에 명사가 와야 한다.", "translation": "모든 출장 서류와 영수증이 처리·승인될 때까지는 경비가 상환되지 않는다.", "vocab": "not ~ until 구 ~할 때까지 …않다 / reimbursement 명 환급 / issue 동 지급하다, 발행하다 / process 동 처리하다", "g": {"reimbursements": ["명사", "환급(금)", "reimbursement"], "will": ["조동사", "~할 것이다"], "not": ["부사", "~않다, 아니다"], "be": ["동사", "~이다, 되다"], "issued": ["과거분사", "지급된", "issue"], "all": ["한정사", "모든"], "travel": ["명사", "출장"], "documents": ["명사", "서류", "document"], "and": ["접속사", "그리고"], "receipts": ["명사", "영수증", "receipt"], "have": ["조동사", "(현재완료)", "have"], "been": ["과거분사", "~였다, 되었다", "be"], "processed": ["과거분사", "처리된", "process"], "approved": ["과거분사", "승인된", "approve"]}, "src": "1-"}, {"no": 123, "q": "_____ the success of its ultralight model domestically, Gotwo Bicycles has struggled to grow in the international market.", "options": ["In fact", "Despite", "Even though", "However"], "answer": 1, "explain": "정답 (B) Despite\n해석: 초경량 모델이 국내에서 성공했음에도 Gotwo Bicycles는 해외 시장에서 성장에 어려움을 겪었다.\n정답 근거: 국내 성공과 해외 부진이 대조되고 뒤에 명사구가 오므로 전치사 Despite가 알맞다.\n오답 분석: (A) In fact: 부사구라 명사구를 이끌지 못한다. / (C) Even though: 접속사라 뒤에 절이 와야 한다. / (D) However: 접속부사여서 명사구를 이끌 수 없다.", "translation": "초경량 모델이 국내에서 성공했음에도 Gotwo Bicycles는 해외 시장에서 성장에 어려움을 겪었다.", "vocab": "despite 전 ~에도 불구하고 / domestically 부 국내에서 / struggle to do 구 ~하는 데 고전하다 / even though 접 비록 ~이지만 (절 연결)", "g": {"the": ["관사", "그"], "success": ["명사", "성공"], "of": ["전치사", "~의"], "its": ["대명사", "그것의"], "ultralight": ["형용사", "초경량의"], "model": ["명사", "모델, 제품"], "domestically": ["부사", "국내에서"], "gotwo": ["고유명사", "Gotwo(회사명)"], "bicycles": ["명사", "자전거", "bicycle"], "has": ["조동사", "(현재완료)", "have"], "struggled": ["과거분사", "고전했다", "struggle"], "to": ["to부정사", "~하는 데"], "grow": ["동사", "성장하다"], "in": ["전치사", "~에서"], "international": ["형용사", "국제적인, 해외의"], "market": ["명사", "시장"]}, "src": "1-"}, {"no": 125, "q": "The Ravidco XL printer _____ produces sharp, full-color copies of most standard-sized documents.", "options": ["efficiently", "knowingly", "annually", "extremely"], "answer": 0, "explain": "정답 (A) efficiently\n해석: Ravidco XL 프린터는 대부분의 표준 규격 문서를 선명한 컬러로 효율적으로 출력한다.\n정답 근거: 제품 성능을 긍정적으로 설명하는 자리이므로 「효율적으로」가 알맞다.\n오답 분석: (B) knowingly: '알면서'. 기계 성능과 어울리지 않는다. / (C) annually: '해마다'. 출력 빈도로 부적절하다. / (D) extremely: 정도를 강조하는 부사라 동사를 단독으로 꾸미기에 어색하다.", "translation": "Ravidco XL 프린터는 대부분의 표준 규격 문서를 선명한 컬러로 효율적으로 출력한다.", "vocab": "efficiently 부 효율적으로 / sharp 형 선명한 / standard-sized 형 표준 크기의 / produce 동 만들어 내다", "g": {"the": ["관사", "그"], "ravidco": ["고유명사", "Ravidco(회사명)"], "xl": ["고유명사", "XL(모델명)"], "printer": ["명사", "프린터"], "produces": ["동사", "만들어 내다", "produce"], "sharp": ["형용사", "선명한"], "full-color": ["형용사", "풀 컬러의"], "copies": ["명사", "복사본, 출력물", "copy"], "of": ["전치사", "~의"], "most": ["한정사", "대부분의"], "standard-sized": ["형용사", "표준 크기의"], "documents": ["명사", "문서", "document"]}, "src": "1-"}, {"no": 126, "q": "The researchers _____ that there was not enough information to predict a trend in the market.", "options": ["finished", "terminated", "concluded", "completed"], "answer": 2, "explain": "정답 (C) concluded\n해석: 연구진은 시장 흐름을 예측하기에 정보가 충분하지 않다고 결론지었다.\n정답 근거: 뒤에 that절이 이어지며 판단을 내린다는 뜻이므로 「결론짓다」가 알맞다.\n오답 분석: (A) finished: '끝냈다'. that절을 목적어로 취하지 않는다. / (B) terminated: '종료했다'. 판단을 나타내지 못한다. / (D) completed: '완료했다'. that절과 어울리지 않는다.", "translation": "연구진은 시장 흐름을 예측하기에 정보가 충분하지 않다고 결론지었다.", "vocab": "conclude 동 결론짓다 / predict 동 예측하다 / trend 명 동향 / terminate 동 종료하다", "g": {"the": ["관사", "그"], "researchers": ["명사", "연구원", "researcher"], "that": ["접속사", "~라는 것"], "there": ["부사", "(존재 구문)"], "was": ["동사", "~이었다", "be"], "not": ["부사", "~않다"], "enough": ["한정사", "충분한"], "information": ["명사", "정보"], "to": ["to부정사", "~하기에"], "predict": ["동사", "예측하다"], "a": ["관사", "하나의"], "trend": ["명사", "동향, 추세"], "in": ["전치사", "~에서"], "market": ["명사", "시장"]}, "src": "1-"}, {"no": 128, "q": "Travelers are urged to check the large screens _____ to monitor flight changes.", "options": ["from", "up", "often", "any"], "answer": 2, "explain": "정답 (C) often\n해석: 여행객은 항공편 변경을 확인하기 위해 대형 화면을 자주 확인하도록 권고된다.\n정답 근거: 확인 행위의 빈도를 나타내야 하므로 「자주」가 알맞다.\n오답 분석: (A) from: 전치사라 뒤에 명사가 필요하다. / (B) up: 부사이지만 빈도를 나타내지 못한다. / (D) any: 한정사라 이 자리에 맞지 않는다.", "translation": "여행객은 항공편 변경을 확인하기 위해 대형 화면을 자주 확인하도록 권고된다.", "vocab": "often 부 자주 / be urged to do 구 ~하도록 권고되다 / monitor 동 (변동을) 확인하다 / flight 명 항공편", "g": {"travelers": ["명사", "여행객", "traveler"], "are": ["동사", "~이다", "be"], "urged": ["과거분사", "권고받는", "urge"], "to": ["to부정사", "~하도록"], "check": ["동사", "확인하다"], "the": ["관사", "그"], "large": ["형용사", "큰"], "screens": ["명사", "화면", "screen"], "monitor": ["동사", "(변동을) 확인하다"], "flight": ["명사", "항공편"], "changes": ["명사", "변경 사항", "change"]}, "src": "1-"}, {"no": 129, "q": "The Web site for Labricraft Technologies has been redesigned twice this year _____.", "options": ["more", "yet", "already", "forward"], "answer": 2, "explain": "정답 (C) already\n해석: Labricraft Technologies의 웹사이트는 올해 벌써 두 차례 새로 단장되었다.\n정답 근거: 현재완료와 함께 예상보다 이르게 이루어졌음을 나타내야 하므로 「벌써」가 알맞다.\n오답 분석: (A) more: 비교 대상이 없어 어색하다. / (B) yet: 부정문·의문문에서 주로 쓰인다. / (D) forward: 방향을 뜻해 문맥과 맞지 않는다.", "translation": "Labricraft Technologies의 웹사이트는 올해 벌써 두 차례 새로 단장되었다.", "vocab": "already 부 이미, 벌써 / redesign 동 다시 설계하다 / twice 부 두 번 / yet 부 아직 (부정문)", "g": {"the": ["관사", "그"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "for": ["전치사", "~의"], "labricraft": ["고유명사", "Labricraft(회사명)"], "technologies": ["고유명사", "Technologies(회사명 일부)"], "has": ["조동사", "(현재완료)", "have"], "been": ["과거분사", "~였다, 되었다", "be"], "redesigned": ["과거분사", "다시 설계된", "redesign"], "twice": ["부사", "두 번"], "this": ["한정사", "이"], "year": ["명사", "해"]}, "src": "1-"}, {"no": 130, "q": "The acquisition of Whitman Financial was a _____ decision on the part of Burbury Investment Bank.", "options": ["sensible", "numerous", "receivable", "frequent"], "answer": 0, "explain": "정답 (A) sensible\n해석: Whitman Financial 인수는 Burbury 투자은행 입장에서 현명한 결정이었다.\n정답 근거: 결정을 평가하는 자리이므로 「분별 있는·현명한」이 알맞다.\n오답 분석: (B) numerous: '많은'. 단수 명사 decision과 맞지 않는다. / (C) receivable: '받을 수 있는'. 결정을 꾸미기에 어색하다. / (D) frequent: '잦은'. 단일 결정과 어울리지 않는다.", "translation": "Whitman Financial 인수는 Burbury 투자은행 입장에서 현명한 결정이었다.", "vocab": "sensible 형 현명한, 분별 있는 / acquisition 명 인수 / on the part of 구 ~ 측에서의 / numerous 형 많은", "g": {"the": ["관사", "그"], "acquisition": ["명사", "인수"], "of": ["전치사", "~의"], "whitman": ["고유명사", "Whitman(회사명)"], "financial": ["고유명사", "Financial(회사명 일부)"], "was": ["동사", "~이었다", "be"], "a": ["관사", "하나의"], "decision": ["명사", "결정"], "on": ["전치사", "~ 측에서의"], "part": ["명사", "측, 쪽"], "burbury": ["고유명사", "Burbury(회사명)"], "investment": ["명사", "투자"], "bank": ["명사", "은행"]}, "src": "1-"}, {"no": 102, "q": "Repairs to the building's entire electrical _____ will begin at 6:00 P.M. today.", "options": ["treatment", "system", "reason", "outside"], "answer": 1, "explain": "정답 (B) system\n해석: 건물 전체 전기 설비의 수리가 오늘 오후 6시에 시작된다.\n정답 근거: electrical과 결합해 「전기 설비」를 뜻해야 하므로 system이 알맞다.\n오답 분석: (A) treatment: '처리'. 수리 대상이 되지 못한다. / (C) reason: '이유'. 문맥과 무관하다. / (D) outside: '바깥'. 수리 대상을 나타내지 못한다.", "translation": "건물 전체 전기 설비의 수리가 오늘 오후 6시에 시작된다.", "sub": "어휘 10회", "vocab": "electrical system 명 전기 설비 / repair 명 수리 / entire 형 전체의 / treatment 명 처리", "g": {"repairs": ["명사", "수리", "repair"], "to": ["전치사", "~에 대한"], "the": ["관사", "그"], "building's": ["명사", "건물의", "building"], "entire": ["형용사", "전체의"], "electrical": ["형용사", "전기의"], "will": ["조동사", "~할 것이다"], "begin": ["동사", "시작되다"], "at": ["전치사", "~에"], "6:00": ["숫자", "6시"], "p.m": ["명사", "오후"], "today": ["부사", "오늘"]}, "src": "2-"}, {"no": 104, "q": "Riders will find the new seats on the Northern Rail Line to be much more _____ than the old ones.", "options": ["average", "comfortable", "similar", "cautious"], "answer": 1, "explain": "정답 (B) comfortable\n해석: 승객들은 Northern 철도 노선의 새 좌석이 예전 것보다 훨씬 편안하다고 느낄 것이다.\n정답 근거: 좌석의 개선을 나타내야 하므로 「편안한」이 알맞다.\n오답 분석: (A) average: '평균의'. 개선을 뜻하지 않는다. / (C) similar: '비슷한'. 비교급 more와 뜻이 충돌한다. / (D) cautious: '조심스러운'. 좌석을 꾸미기에 부적절하다.", "translation": "승객들은 Northern 철도 노선의 새 좌석이 예전 것보다 훨씬 편안하다고 느낄 것이다.", "sub": "어휘 10회", "vocab": "comfortable 형 편안한 / rider 명 승객 / find A (to be) B 구 A가 B라고 느끼다 / cautious 형 조심스러운", "g": {"riders": ["명사", "승객", "rider"], "will": ["조동사", "~할 것이다"], "find": ["동사", "~라고 느끼다"], "the": ["관사", "그"], "new": ["형용사", "새로운"], "seats": ["명사", "좌석", "seat"], "on": ["전치사", "~의"], "northern": ["고유명사", "Northern(노선명)"], "rail": ["명사", "철도"], "line": ["명사", "노선"], "to": ["to부정사", "~이라고"], "be": ["동사", "~이다, 되다"], "much": ["부사", "훨씬"], "more": ["부사", "더"], "than": ["전치사", "~보다"], "old": ["형용사", "예전의"], "ones": ["대명사", "것들", "one"]}, "src": "2-"}, {"no": 106, "q": "Mr. Sam had to work _____ in order to meet his midnight deadline.", "options": ["mildly", "loudly", "commonly", "quickly"], "answer": 3, "explain": "정답 (D) quickly\n해석: Sam 씨는 자정 마감을 맞추기 위해 빠르게 일해야 했다.\n정답 근거: 마감을 맞추려는 상황이므로 「빠르게」가 알맞다.\n오답 분석: (A) mildly: '부드럽게'. 마감과 어울리지 않는다. / (B) loudly: '큰 소리로'. 문맥과 무관하다. / (C) commonly: '흔히'. 급박함을 나타내지 못한다.", "translation": "Sam 씨는 자정 마감을 맞추기 위해 빠르게 일해야 했다.", "sub": "어휘 10회", "vocab": "quickly 부 빨리 / meet a deadline 구 마감을 맞추다 / in order to do 구 ~하기 위해 / commonly 부 흔히", "g": {"mr": ["명사", "~씨(남성)"], "sam": ["고유명사", "Sam(인명)"], "had": ["동사", "~해야 했다", "have"], "to": ["to부정사", "~해야 (had to)"], "work": ["동사", "일하다"], "in": ["전치사", "(in order to) ~하기 위해"], "order": ["명사", "(in order to) ~하기 위해"], "meet": ["동사", "(마감을) 맞추다"], "his": ["대명사", "그의"], "midnight": ["명사", "자정"], "deadline": ["명사", "마감"]}, "src": "2-"}, {"no": 108, "q": "At Tuesday's meeting, Mr. Xi _____ the projects that summer interns will be doing.", "options": ["alerted", "persisted", "described", "intended"], "answer": 2, "explain": "정답 (C) described\n해석: 화요일 회의에서 Xi 씨는 여름 인턴들이 맡을 프로젝트를 설명했다.\n정답 근거: 프로젝트를 목적어로 취해 「설명하다」를 뜻해야 하므로 described가 알맞다.\n오답 분석: (A) alerted: 사람을 목적어로 취해 경고할 때 쓰인다. / (B) persisted: 자동사여서 목적어를 취할 수 없다. / (D) intended: '의도했다'. 뒤에 to부정사가 오는 것이 자연스럽다.", "translation": "화요일 회의에서 Xi 씨는 여름 인턴들이 맡을 프로젝트를 설명했다.", "sub": "어휘 10회", "vocab": "describe 동 설명하다 / intern 명 인턴 / alert 동 (위험을) 알리다 / intend 동 의도하다", "g": {"at": ["전치사", "~에서"], "tuesday's": ["고유명사", "화요일의"], "meeting": ["명사", "회의"], "mr": ["명사", "~씨(남성)"], "xi": ["고유명사", "Xi(인명)"], "the": ["관사", "그"], "projects": ["명사", "프로젝트", "project"], "that": ["관계사", "~하는 (것)"], "summer": ["명사", "여름"], "interns": ["명사", "인턴", "intern"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "doing": ["현재분사", "하고 있는", "do"]}, "src": "2-"}, {"no": 109, "q": "Megaplex Fitness members have access to all group classes, _____ strength training and high-intensity cardio.", "options": ["therefore", "along", "including", "fairly"], "answer": 2, "explain": "정답 (C) including\n해석: Megaplex Fitness 회원은 근력 운동과 고강도 유산소를 포함한 모든 단체 수업을 이용할 수 있다.\n정답 근거: 앞의 all group classes에 속하는 예를 드는 자리이므로 「~을 포함하여」가 알맞다.\n오답 분석: (A) therefore: 접속부사라 명사를 이끌지 못한다. / (B) along: 뒤에 with가 있어야 한다. / (D) fairly: 부사여서 명사를 이끌 수 없다.", "translation": "Megaplex Fitness 회원은 근력 운동과 고강도 유산소를 포함한 모든 단체 수업을 이용할 수 있다.", "sub": "어휘 10회", "vocab": "including 전 ~을 포함하여 / have access to 구 ~을 이용할 수 있다 / strength training 명 근력 운동 / high-intensity 형 고강도의", "g": {"megaplex": ["고유명사", "Megaplex(명칭)"], "fitness": ["명사", "피트니스"], "members": ["명사", "회원", "member"], "have": ["동사", "가지다"], "access": ["명사", "이용 (권한)"], "to": ["전치사", "~에 대한"], "all": ["한정사", "모든"], "group": ["명사", "단체"], "classes": ["명사", "수업", "class"], "strength": ["명사", "근력"], "training": ["명사", "운동, 훈련"], "and": ["접속사", "그리고"], "high-intensity": ["형용사", "고강도의"], "cardio": ["명사", "유산소 운동"]}, "src": "2-"}, {"no": 110, "q": "Ms. Shin works as _____ a reporter and an editor for the local newspaper.", "options": ["either", "both", "so", "rather"], "answer": 1, "explain": "정답 (B) both\n해석: Shin 씨는 지역 신문에서 기자이자 편집자로 일한다.\n정답 근거: 뒤에 and가 있으므로 상관접속사 both A and B 구조를 이루는 both가 정답이다.\n오답 분석: (A) either: either A or B 형태로 쓰이므로 and와 맞지 않는다. / (C) so: 결과를 나타내 이 구조를 이루지 못한다. / (D) rather: 부사여서 상관 구조에 쓰이지 않는다.", "translation": "Shin 씨는 지역 신문에서 기자이자 편집자로 일한다.", "sub": "어휘 10회", "vocab": "both A and B 구 A와 B 둘 다 / reporter 명 기자 / editor 명 편집자 / local 형 지역의", "g": {"ms": ["명사", "~씨(여성)"], "shin": ["고유명사", "Shin(인명)"], "works": ["동사", "일하다", "work"], "as": ["전치사", "~로서"], "a": ["관사", "하나의"], "reporter": ["명사", "기자"], "and": ["접속사", "그리고"], "an": ["관사", "하나의"], "editor": ["명사", "편집자"], "for": ["전치사", "~에서, ~을 위해"], "the": ["관사", "그"], "local": ["형용사", "지역의"], "newspaper": ["명사", "신문"]}, "src": "2-"}, {"no": 112, "q": "Based on current sales _____ for this quarter, we expect to break our previous record.", "options": ["projections", "divisions", "titles", "careers"], "answer": 0, "explain": "정답 (A) projections\n해석: 이번 분기의 현재 매출 전망을 근거로 우리는 이전 기록을 깰 것으로 예상한다.\n정답 근거: 앞으로의 실적을 예상하는 근거이므로 「전망치」가 알맞다.\n오답 분석: (B) divisions: '부서'. 예측 근거가 되지 못한다. / (C) titles: '직한다'. 문맥과 무관하다. / (D) careers: '경력'. 매출과 결합하지 않는다.", "translation": "이번 분기의 현재 매출 전망을 근거로 우리는 이전 기록을 깰 것으로 예상한다.", "sub": "어휘 10회", "vocab": "projection 명 전망(치) / based on 구 ~에 근거하여 / break a record 구 기록을 깨다 / previous 형 이전의", "g": {"based": ["과거분사", "(based on) ~에 근거하여", "base"], "on": ["전치사", "~에"], "current": ["형용사", "현재의"], "sales": ["명사", "매출", "sale"], "for": ["전치사", "~의"], "this": ["한정사", "이"], "quarter": ["명사", "분기"], "we": ["대명사", "우리"], "expect": ["동사", "예상하다"], "to": ["to부정사", "~할 것을"], "break": ["동사", "깨다"], "our": ["대명사", "우리의"], "previous": ["형용사", "이전의"], "record": ["명사", "기록"]}, "src": "2-"}, {"no": 114, "q": "Pertex Communications has _____ a new Internet service for residential customers in Bogat Province.", "options": ["provoked", "launched", "collected", "existed"], "answer": 1, "explain": "정답 (B) launched\n해석: Pertex Communications는 Bogat 주의 가정 고객을 위한 새 인터넷 서비스를 출시했다.\n정답 근거: 새 서비스를 목적어로 취해 「출시하다」를 뜻해야 하므로 launched가 알맞다.\n오답 분석: (A) provoked: '유발하다'. 서비스와 어울리지 않는다. / (C) collected: '모으다'. 출시를 뜻하지 않는다. / (D) existed: 자동사여서 목적어를 취할 수 없다.", "translation": "Pertex Communications는 Bogat 주의 가정 고객을 위한 새 인터넷 서비스를 출시했다.", "sub": "어휘 10회", "vocab": "launch 동 출시하다 / residential 형 주거의 / provoke 동 유발하다 / exist 동 존재하다", "g": {"pertex": ["고유명사", "Pertex(회사명)"], "communications": ["고유명사", "Communications(회사명 일부)"], "has": ["조동사", "(현재완료)", "have"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "internet": ["명사", "인터넷"], "service": ["명사", "서비스"], "for": ["전치사", "~을 위한"], "residential": ["형용사", "주거의, 가정의"], "customers": ["명사", "고객", "customer"], "in": ["전치사", "~에서"], "bogat": ["고유명사", "Bogat(지명)"], "province": ["명사", "(행정구역) 주"]}, "src": "2-"}, {"no": 116, "q": "This communication is strictly _____ and so is not to be shared with anyone else.", "options": ["confidential", "frequent", "online", "commercial"], "answer": 0, "explain": "정답 (A) confidential\n해석: 이 문서는 엄격히 기밀이므로 다른 누구와도 공유해서는 안 된다.\n정답 근거: 다른 사람과 공유하지 말라는 내용이 이어지므로 「기밀의」가 알맞다.\n오답 분석: (B) frequent: '잦은'. 공유 금지 이유가 되지 못한다. / (C) online: '온라인의'. 비공개 성격을 나타내지 못한다. / (D) commercial: '상업의'. 문맥과 맞지 않는다.", "translation": "이 문서는 엄격히 기밀이므로 다른 누구와도 공유해서는 안 된다.", "sub": "어휘 10회", "vocab": "confidential 형 기밀의 / strictly 부 엄격히 / share 동 공유하다 / commercial 형 상업의", "g": {"this": ["한정사", "이"], "communication": ["명사", "통신문, 문서"], "is": ["동사", "~이다", "be"], "strictly": ["부사", "엄격히"], "and": ["접속사", "그리고"], "so": ["부사", "그래서"], "not": ["부사", "~않다"], "to": ["to부정사", "(be to) ~해야 하는"], "be": ["동사", "~이다, 되다"], "shared": ["과거분사", "공유되는", "share"], "with": ["전치사", "~와"], "anyone": ["대명사", "누구"], "else": ["부사", "그 밖의"]}, "src": "2-"}, {"no": 117, "q": "Shop _____ to take advantage of Woolly Planet's end-of-year sale on all hats, scarves, and coats.", "options": ["now", "beyond", "aside", "past"], "answer": 0, "explain": "정답 (A) now\n해석: 모자, 목도리, 코트 전 품목에 대한 Woolly Planet 연말 할인을 이용하려면 지금 쇼핑하십시오.\n정답 근거: 즉시 행동을 권하는 광고 문구이므로 「지금」이 알맞다.\n오답 분석: (B) beyond: 전치사라 명령문 뒤에 단독으로 오지 못한다. / (C) aside: '옆으로'. 문맥과 무관하다. / (D) past: 시점을 지난다는 뜻이라 촉구와 맞지 않는다.", "translation": "모자, 목도리, 코트 전 품목에 대한 Woolly Planet 연말 할인을 이용하려면 지금 쇼핑하십시오.", "sub": "어휘 10회", "vocab": "now 부 지금 (명령문 강조) / take advantage of 구 ~을 이용하다 / end-of-year 형 연말의 / scarf - scarves 명 스카프", "g": {"shop": ["동사", "쇼핑하다"], "to": ["to부정사", "~하려면"], "take": ["동사", "(take advantage of) 이용하다"], "advantage": ["명사", "(take advantage of) 이용"], "of": ["전치사", "~의"], "woolly": ["고유명사", "Woolly(상호)"], "planet's": ["고유명사", "Planet의(상호)"], "end-of-year": ["형용사", "연말의"], "sale": ["명사", "할인 판매"], "on": ["전치사", "~에 대한"], "all": ["한정사", "모든"], "hats": ["명사", "모자", "hat"], "scarves": ["명사", "스카프", "scarf"], "and": ["접속사", "그리고"], "coats": ["명사", "코트", "coat"]}, "src": "2-"}, {"no": 118, "q": "The contract with Ader's Construction _____ states that the work will be completed by May 10.", "options": ["annually", "slowly", "clearly", "rarely"], "answer": 2, "explain": "정답 (C) clearly\n해석: Ader's Construction과의 계약서는 작업이 5월 10일까지 완료된다고 분명히 명시하고 있다.\n정답 근거: 계약서가 내용을 명확히 규정한다는 뜻이므로 「분명히」가 알맞다.\n오답 분석: (A) annually: '해마다'. 명시 방식과 어울리지 않는다. / (B) slowly: '천천히'. 문서 서술과 맞지 않는다. / (D) rarely: '드물게'. 명시되어 있다는 내용과 모순된다.", "translation": "Ader's Construction과의 계약서는 작업이 5월 10일까지 완료된다고 분명히 명시하고 있다.", "sub": "어휘 10회", "vocab": "clearly 부 명확하게 / contract 명 계약(서) / state 동 명시하다 / rarely 부 좀처럼 ~ 않다", "g": {"the": ["관사", "그"], "contract": ["명사", "계약(서)"], "with": ["전치사", "~와의"], "ader's": ["고유명사", "Ader's(회사명)"], "construction": ["고유명사", "Construction(회사명 일부)"], "states": ["동사", "명시하다", "state"], "that": ["접속사", "~라는 것"], "work": ["명사", "작업"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "completed": ["과거분사", "완료된", "complete"], "by": ["전치사", "~까지"], "may": ["고유명사", "5월"], "10": ["숫자", "10일"]}, "src": "2-"}, {"no": 120, "q": "More than 500,000 square meters of office space is _____ construction in London.", "options": ["despite", "about", "except", "under"], "answer": 3, "explain": "정답 (D) under\n해석: 런던에서 50만 제곱미터가 넘는 사무 공간이 공사 중이다.\n정답 근거: under construction은 「공사 중인」을 뜻하는 표현이다.\n오답 분석: (A) despite: 양보를 뜻해 상태를 나타내지 못한다. / (B) about: 주제를 나타내 문맥과 맞지 않는다. / (C) except: 제외를 뜻해 어색하다.", "translation": "런던에서 50만 제곱미터가 넘는 사무 공간이 공사 중이다.", "sub": "어휘 10회", "vocab": "under construction 구 공사 중인 / square meter 명 제곱미터 / office space 명 사무 공간 / more than 구 ~ 이상", "g": {"more": ["형용사", "더 많은"], "than": ["전치사", "~보다 (more than ~이상)"], "500,000": ["숫자", "50만"], "square": ["형용사", "제곱의"], "meters": ["명사", "미터", "meter"], "of": ["전치사", "~의"], "office": ["명사", "사무실"], "space": ["명사", "공간"], "is": ["동사", "~이다", "be"], "construction": ["명사", "공사, 건설"], "in": ["전치사", "~에서"], "london": ["고유명사", "런던"]}, "src": "2-"}, {"no": 121, "q": "Neither the producer _____ the director had expected that the play would be such a success.", "options": ["yet", "and", "since", "nor"], "answer": 3, "explain": "정답 (D) nor\n해석: 제작자도 연출자도 그 연극이 그렇게 성공하리라 예상하지 못했다.\n정답 근거: 앞에 Neither가 있으므로 상관접속사 neither A nor B 구조를 이루는 nor가 정답이다.\n오답 분석: (A) yet: 대조 부사·접속사로 이 구조에 쓰이지 않는다. / (B) and: both와 짝을 이루며 Neither와 맞지 않는다. / (C) since: 이유·시간 접속사라 이 구조를 이루지 못한다.", "translation": "제작자도 연출자도 그 연극이 그렇게 성공하리라 예상하지 못했다.", "sub": "어휘 10회", "vocab": "neither A nor B 구 A도 B도 아닌 / producer 명 제작자 / expect 동 예상하다 / success 명 성공", "g": {"neither": ["접속사", "(neither A nor B) A도 B도 아닌"], "the": ["관사", "그"], "producer": ["명사", "제작자"], "director": ["명사", "연출자, 감독"], "had": ["조동사", "(과거완료)", "have"], "expected": ["과거분사", "예상했다", "expect"], "that": ["접속사", "~라는 것"], "play": ["명사", "연극"], "would": ["조동사", "~할 것이다", "will"], "be": ["동사", "~이다, 되다"], "such": ["한정사", "그토록, 대단한"], "a": ["관사", "하나의"], "success": ["명사", "성공"]}, "src": "2-"}, {"no": 122, "q": "It is my pleasure to announce your _____ into the Sustainable Farming Internship Program.", "options": ["production", "supervision", "acceptance", "experience"], "answer": 2, "explain": "정답 (C) acceptance\n해석: 귀하의 지속 가능 농업 인턴십 프로그램 합격을 알리게 되어 기쁩니다.\n정답 근거: 프로그램에 들어가게 되었음을 알리는 자리이므로 「합격·수락」을 뜻하는 acceptance가 알맞다.\n오답 분석: (A) production: '생산'. 합격을 뜻하지 않는다. / (B) supervision: '감독'. 문맥과 무관하다. / (D) experience: '경험'. into와 결합해 합격을 나타내지 못한다.", "translation": "귀하의 지속 가능 농업 인턴십 프로그램 합격을 알리게 되어 기쁩니다.", "sub": "어휘 10회", "vocab": "acceptance 명 합격, 수락 / announce 동 알리다 / sustainable 형 지속 가능한 / supervision 명 감독", "g": {"it": ["대명사", "(가주어)"], "is": ["동사", "~이다", "be"], "my": ["대명사", "나의"], "pleasure": ["명사", "기쁨"], "to": ["to부정사", "~하는 것"], "announce": ["동사", "알리다"], "your": ["대명사", "여러분의, 당신의"], "into": ["전치사", "~으로, ~에"], "the": ["관사", "그"], "sustainable": ["형용사", "지속 가능한"], "farming": ["명사", "농업"], "internship": ["명사", "인턴십"], "program": ["명사", "프로그램"]}, "src": "2-"}, {"no": 125, "q": "The Conference Center at Woodlawn is currently booking events _____ the end of the year.", "options": ["through", "pending", "still", "while"], "answer": 0, "explain": "정답 (A) through\n해석: Woodlawn 컨벤션 센터는 현재 연말까지의 행사를 예약받고 있다.\n정답 근거: 현재부터 연말까지의 기간을 나타내야 하므로 「~까지 내내」를 뜻하는 through가 알맞다.\n오답 분석: (B) pending: '~을 기다리는 동안'. 기간의 끝을 나타내지 못한다. / (C) still: 부사라 명사구를 이끌지 못한다. / (D) while: 접속사라 뒤에 절이 와야 한다.", "translation": "Woodlawn 컨벤션 센터는 현재 연말까지의 행사를 예약받고 있다.", "sub": "어휘 10회", "vocab": "through 전 ~까지 (죽 이어서) / currently 부 현재 / book 동 예약을 받다 / pending 전 ~을 기다리는 동안", "g": {"the": ["관사", "그"], "conference": ["명사", "회의"], "center": ["명사", "센터"], "at": ["전치사", "~에 있는"], "woodlawn": ["고유명사", "Woodlawn(지명)"], "is": ["동사", "~이다", "be"], "currently": ["부사", "현재"], "booking": ["현재분사", "예약을 받는", "book"], "events": ["명사", "행사", "event"], "end": ["명사", "끝"], "of": ["전치사", "~의"], "year": ["명사", "해"]}, "src": "2-"}, {"no": 126, "q": "All Spanier Technologies' products come with a comprehensive warranty that protects _____ defects.", "options": ["upon", "toward", "against", "over"], "answer": 2, "explain": "정답 (C) against\n해석: Spanier Technologies의 모든 제품에는 결함으로부터 보호해 주는 종합 보증이 함께 제공된다.\n정답 근거: protect against는 「~로부터 보호하다」를 뜻하는 결합이므로 against가 정답이다.\n오답 분석: (A) upon: 이 결합에 쓰이지 않는다. / (B) toward: 방향을 뜻해 보호 대상을 나타내지 못한다. / (D) over: '~위에'. 문맥과 맞지 않는다.", "translation": "Spanier Technologies의 모든 제품에는 결함으로부터 보호해 주는 종합 보증이 함께 제공된다.", "sub": "어휘 10회", "vocab": "protect against 구 ~로부터 보호하다 / comprehensive 형 포괄적인 / warranty 명 품질 보증(서) / defect 명 결함", "g": {"all": ["한정사", "모든"], "spanier": ["고유명사", "Spanier(회사명)"], "technologies'": ["고유명사", "Technologies의(회사명)"], "products": ["명사", "제품", "product"], "come": ["동사", "(come with) 딸려 오다"], "with": ["전치사", "~이 함께"], "a": ["관사", "하나의"], "comprehensive": ["형용사", "포괄적인"], "warranty": ["명사", "품질 보증(서)"], "that": ["관계사", "~하는 (것)"], "protects": ["동사", "보호하다", "protect"], "defects": ["명사", "결함", "defect"]}, "src": "2-"}, {"no": 128, "q": "Construction on the Ubuntu Tower is expected to commence _____ permits are approved.", "options": ["once", "thus", "instead", "during"], "answer": 0, "explain": "정답 (A) once\n해석: Ubuntu 타워 공사는 허가가 승인되는 대로 시작될 것으로 예상된다.\n정답 근거: 뒤에 절이 이어지며 「~하는 대로」라는 시점을 나타내야 하므로 once가 알맞다.\n오답 분석: (B) thus: 접속부사라 절을 연결하지 못한다. / (C) instead: 부사여서 절을 이끌 수 없다. / (D) during: 전치사라 뒤에 명사가 와야 한다.", "translation": "Ubuntu 타워 공사는 허가가 승인되는 대로 시작될 것으로 예상된다.", "sub": "어휘 10회", "vocab": "once 접 일단 ~하면 / commence 동 시작되다 / permit 명 허가(증) / approve 동 승인하다", "g": {"construction": ["명사", "공사"], "on": ["전치사", "~의, ~에 대한"], "the": ["관사", "그"], "ubuntu": ["고유명사", "Ubuntu(명칭)"], "tower": ["명사", "타워, 고층 건물"], "is": ["동사", "~이다", "be"], "expected": ["과거분사", "예상되는", "expect"], "to": ["to부정사", "~할 것으로"], "commence": ["동사", "시작되다"], "permits": ["명사", "허가(증)", "permit"], "are": ["동사", "~이다", "be"], "approved": ["과거분사", "승인된", "approve"]}, "src": "2-"}, {"no": 130, "q": "All items in Pellecer Trading Company's online store are _____ discounted until the end of this year.", "options": ["lastly", "densely", "heavily", "shortly"], "answer": 2, "explain": "정답 (C) heavily\n해석: Pellecer Trading Company 온라인 매장의 모든 상품이 연말까지 큰 폭으로 할인된다.\n정답 근거: 할인 폭이 크다는 뜻을 나타내야 하므로 「대폭」을 뜻하는 heavily가 알맞다.\n오답 분석: (A) lastly: '마지막으로'. 할인 정도를 나타내지 못한다. / (B) densely: '빽빽하게'. 할인과 어울리지 않는다. / (D) shortly: '곧'. 할인 폭을 뜻하지 않는다.", "translation": "Pellecer Trading Company 온라인 매장의 모든 상품이 연말까지 큰 폭으로 할인된다.", "sub": "어휘 10회", "vocab": "heavily 부 대폭, 크게 / discount 동 할인하다 / until 전 ~까지 / shortly 부 곧", "g": {"all": ["한정사", "모든"], "items": ["명사", "상품", "item"], "in": ["전치사", "~에서"], "pellecer": ["고유명사", "Pellecer(회사명)"], "trading": ["고유명사", "Trading(회사명 일부)"], "company's": ["고유명사", "Company의(회사명)"], "online": ["형용사", "온라인의"], "store": ["명사", "매장"], "are": ["동사", "~이다", "be"], "discounted": ["과거분사", "할인된", "discount"], "until": ["전치사", "~까지"], "the": ["관사", "그"], "end": ["명사", "끝"], "of": ["전치사", "~의"], "this": ["한정사", "이"], "year": ["명사", "해"]}, "src": "2-"}], "sets": []}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r12-p6',$mkd${"id": "a2-r12-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 2, "round": 12, "level": "중급", "title": "A급 과제 12회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "To: All employees\nFrom: Walter C. Handy\nSubject: Sales Incentive Program\nDate: 15 November\nDear TFF Sales Team,\nI am writing to introduce you to a new, double-incentive program for the fourth quarter of this year. In addition to our standard cash bonus plan, sales associates will now have the opportunity ---131--- tickets to concerts, sporting events, and theater performances. This extra incentive is designed to help make this our greatest sales year ever. ---132---.\nMore ---133--- will be provided in the next few days. ---134---, if you have any questions about this program, contact the Human Resources Department.", "tr": "수신: 전 직원 / 발신: Walter C. Handy / 제목: 영업 성과급 제도 / 날짜: 11월 15일\nTFF 영업팀 여러분께,\n올해 4분기에 적용되는 새로운 이중 성과급 제도를 소개하려 이 글을 씁니다. 기존 현금 상여 제도에 더해 이제 영업 담당자는 콘서트, 스포츠 경기, 공연 입장권을 받을 (131) 기회를 갖게 됩니다. 이 추가 보상은 올해를 역대 최고의 영업 실적으로 만들기 위해 마련되었습니다. 이 목표를 이룰 수 있으리라 확신합니다 (132). 더 자세한 내용 (133)은 며칠 안에 안내하겠습니다. 그동안 (134) 이 제도에 관해 궁금한 점이 있으면 인사부에 연락해 주십시오.", "vocab": "incentive 명 장려책, 인센티브 / opportunity to do 구 ~할 기회 / sales associate 명 영업 사원 / be designed to do 구 ~하도록 고안되다 / achieve 동 달성하다 / detail 명 세부 사항 / in the meantime 구 그동안에", "g": {"to": ["전치사", "~에게"], "all": ["한정사", "모든"], "employees": ["명사", "직원", "employee"], "from": ["전치사", "~로부터"], "walter": ["고유명사", "Walter(인명)"], "c": ["고유명사", "C.(이름 머리글자)"], "handy": ["고유명사", "Handy(인명)"], "subject": ["명사", "제목"], "sales": ["명사", "영업, 판매", "sale"], "incentive": ["명사", "장려책, 성과급"], "program": ["명사", "제도, 프로그램"], "date": ["명사", "날짜"], "15": ["숫자", "15일"], "november": ["고유명사", "11월"], "dear": ["형용사", "친애하는"], "tff": ["고유명사", "TFF(회사명)"], "team": ["명사", "팀"], "i": ["대명사", "나"], "am": ["동사", "~이다", "be"], "writing": ["현재분사", "쓰고 있는", "write"], "introduce": ["동사", "소개하다"], "you": ["대명사", "여러분, 당신"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "double-incentive": ["형용사", "이중 성과급의"], "for": ["전치사", "~을 위한"], "the": ["관사", "그"], "fourth": ["형용사", "네 번째의"], "quarter": ["명사", "분기"], "of": ["전치사", "~의"], "this": ["한정사", "이"], "year": ["명사", "해"], "in": ["전치사", "(in addition to) ~에 더해"], "addition": ["명사", "(in addition to) 추가"], "our": ["대명사", "우리의"], "standard": ["형용사", "기존의, 표준의"], "cash": ["명사", "현금"], "bonus": ["명사", "상여금"], "plan": ["명사", "제도, 계획"], "associates": ["명사", "사원, 직원", "associate"], "will": ["조동사", "~할 것이다"], "now": ["부사", "이제"], "have": ["동사", "가지다"], "opportunity": ["명사", "기회"], "tickets": ["명사", "입장권", "ticket"], "concerts": ["명사", "콘서트", "concert"], "sporting": ["형용사", "스포츠의"], "events": ["명사", "경기, 행사", "event"], "and": ["접속사", "그리고"], "theater": ["명사", "극장, 연극"], "performances": ["명사", "공연", "performance"], "extra": ["형용사", "추가의"], "is": ["동사", "~이다", "be"], "designed": ["과거분사", "고안된", "design"], "help": ["동사", "돕다"], "make": ["동사", "만들다"], "greatest": ["형용사", "최고의", "great"], "ever": ["부사", "지금까지 중"], "more": ["형용사", "더 많은"], "be": ["동사", "~이다, 되다"], "provided": ["과거분사", "제공된", "provide"], "next": ["형용사", "다음의"], "few": ["한정사", "몇몇의"], "days": ["명사", "날, 일", "day"], "if": ["접속사", "만약 ~라면"], "any": ["한정사", "어떤"], "questions": ["명사", "질문, 궁금한 점", "question"], "about": ["전치사", "~에 대해"], "contact": ["동사", "연락하다"], "human": ["형용사", "인간의"], "resources": ["명사", "자원 (인사부)", "resource"], "department": ["명사", "부서"]}, "questions": [{"no": 131, "q": "", "options": ["to earn", "earning", "earner", "having earned"], "answer": 0, "explain": "정답 (A) to earn\n지문 개요: 영업 책임자가 4분기에 새로 도입되는 이중 성과급 제도를 소개하고 세부 안내와 문의처를 알리는 이메일이다.\n정답 근거: 명사 opportunity를 뒤에서 꾸미는 자리이므로 to부정사가 정답이고, earn이 타동사여서 뒤에 목적어 tickets가 이어진다.\n오답 분석: (B) earning: 분사·동명사는 opportunity 뒤에서 자연스럽게 이어지지 않는다. / (C) earner: 사람 명사라 뒤의 목적어와 연결되지 않는다. / (D) having earned: 완료 분사구는 이 구조에 맞지 않는다.", "g": {}}, {"no": 132, "q": "", "options": ["The fiscal year ends in October.", "I am confident that we can achieve this goal.", "Attendance at the event is mandatory.", "TFF is looking to renovate its offices next year."], "answer": 1, "explain": "정답 (B) I am confident that we can achieve this goal.\n정답 근거: 앞 문장이 역대 최고 실적이라는 목표를 제시했으므로 그 목표 달성에 대한 확신을 밝히는 문장이 자연스럽다.\n오답 분석: (A): 4분기 제도라고 했으므로 회계연도 종료 시점 언급은 흐름과 맞지 않는다. / (C): 행사 참석 의무는 성과급 제도와 무관하다. / (D): 사무실 개조 계획은 문맥과 이어지지 않는다.", "g": {}}, {"no": 133, "q": "", "options": ["supplies", "details", "products", "receipts"], "answer": 1, "explain": "정답 (B) details\n정답 근거: 제도에 관해 곧 안내될 것이므로 「자세한 내용」이 알맞다.\n오답 분석: (A) supplies: '물품'. 안내 대상이 아니다. / (C) products: '제품'. 성과급 제도 설명과 맞지 않는다. / (D) receipts: '영수증'. 문맥과 무관하다.", "g": {}}, {"no": 134, "q": "", "options": ["Similarly", "Therefore", "Above all", "In the meantime"], "answer": 3, "explain": "정답 (D) In the meantime\n정답 근거: 자세한 안내가 나오기 전까지의 기간을 가리켜야 하므로 「그동안」이 알맞다.\n오답 분석: (A) Similarly: 유사 관계가 아니다. / (B) Therefore: 인과 관계가 아니다. / (C) Above all: '무엇보다'. 문의 안내와 어울리지 않는다.", "g": {}}]}, {"range": "135-138", "passage": "Women's History at the Berkford Museum\nNow on display at the Berkford Museum is She Creates History. This ---135--- honors the leaders who earned women the right to vote in the United States. It also focuses ---136--- significant figures in modern American history who earned acclaim in science, literature, and law. Important documentary photographs and paintings are on display. Museum visitors ---137--- a short film featuring actual footage of early speeches and interviews. ---138---. She Creates History runs through April 20.", "tr": "Berkford 박물관의 여성사\n지금 Berkford 박물관에서 She Creates History가 열리고 있다. 이 전시 (135)는 미국에서 여성에게 참정권을 얻어 준 지도자들을 기린다. 또한 과학, 문학, 법률에서 명성을 얻은 현대 미국사의 주요 인물들에도 (136) 초점을 맞춘다. 중요한 기록 사진과 회화가 전시된다. 관람객은 초기 연설과 인터뷰의 실제 영상을 담은 단편 영화도 즐길 수 있다 (137). 오셔서 이 사건들이 어떻게 역사를 바꾸었는지 배워 보십시오 (138). She Creates History는 4월 20일까지 이어진다.", "vocab": "on display 구 전시 중인 / exhibit 명 전시(회) / honor 동 기리다 / focus on 구 ~에 초점을 맞추다 / significant 형 중요한 / figure 명 인물 / acclaim 명 찬사 / footage 명 (실제) 영상 / run through 구 ~까지 계속되다", "g": {"women's": ["명사", "여성의", "woman"], "history": ["명사", "역사"], "at": ["전치사", "~의, ~에서"], "the": ["관사", "그"], "berkford": ["고유명사", "Berkford(명칭)"], "museum": ["명사", "박물관"], "now": ["부사", "지금"], "on": ["전치사", "(on display) 전시 중인"], "display": ["명사", "전시"], "is": ["동사", "~이다", "be"], "she": ["고유명사", "She(전시명 일부)"], "creates": ["고유명사", "Creates(전시명 일부)"], "this": ["한정사", "이"], "honors": ["동사", "기리다", "honor"], "leaders": ["명사", "지도자", "leader"], "who": ["관계사", "~한 (사람)"], "earned": ["동사", "얻어 주었다, 얻었다", "earn"], "women": ["명사", "여성들", "woman"], "right": ["명사", "권리"], "to": ["to부정사", "~할"], "vote": ["동사", "투표하다"], "in": ["전치사", "~에서"], "united": ["고유명사", "United(국명 일부)"], "states": ["고유명사", "States(국명 일부)"], "it": ["대명사", "그것(전시)"], "also": ["부사", "또한"], "focuses": ["동사", "초점을 맞추다", "focus"], "significant": ["형용사", "중요한"], "figures": ["명사", "인물", "figure"], "modern": ["형용사", "현대의"], "american": ["형용사", "미국의"], "acclaim": ["명사", "찬사, 명성"], "science": ["명사", "과학"], "literature": ["명사", "문학"], "and": ["접속사", "그리고"], "law": ["명사", "법률"], "important": ["형용사", "중요한"], "documentary": ["형용사", "기록의"], "photographs": ["명사", "사진", "photograph"], "paintings": ["명사", "그림, 회화", "painting"], "are": ["동사", "~이다", "be"], "visitors": ["명사", "관람객", "visitor"], "a": ["관사", "하나의"], "short": ["형용사", "짧은"], "film": ["명사", "영화"], "featuring": ["현재분사", "담고 있는", "feature"], "actual": ["형용사", "실제의"], "footage": ["명사", "(실제) 영상"], "of": ["전치사", "~의"], "early": ["형용사", "초기의"], "speeches": ["명사", "연설", "speech"], "interviews": ["명사", "인터뷰", "interview"], "runs": ["동사", "계속되다", "run"], "through": ["전치사", "~까지"], "april": ["고유명사", "4월"], "20": ["숫자", "20일"]}, "questions": [{"no": 135, "q": "", "options": ["article", "award", "exhibit", "documentary"], "answer": 2, "explain": "정답 (C) exhibit\n지문 개요: 박물관에서 열리는 여성사 특별전의 주제와 전시물, 상영 영상과 전시 기간을 소개하는 글이다.\n정답 근거: 박물관에서 지금 열리고 있는 것이고 전시물이 소개되므로 「전시」가 알맞다.\n오답 분석: (A) article: '기사'. 박물관에서 열리는 대상이 아니다. / (B) award: '상'. 전시물을 갖추지 않는다. / (D) documentary: 단편 영화는 전시의 일부로 따로 언급된다.", "g": {}}, {"no": 136, "q": "", "options": ["by", "on", "with", "after"], "answer": 1, "explain": "정답 (B) on\n정답 근거: focus on은 「~에 초점을 맞추다」를 뜻하는 결합이므로 on이 정답이다.\n오답 분석: (A) by: 수단을 나타내 이 결합에 쓰이지 않는다. / (C) with: 동반을 뜻해 맞지 않는다. / (D) after: 시간 순서를 나타내 어색하다.", "g": {}}, {"no": 137, "q": "", "options": ["also enjoyed", "can also enjoy", "are also enjoying", "have also enjoyed"], "answer": 1, "explain": "정답 (B) can also enjoy\n정답 근거: 현재 진행 중인 전시의 관람 혜택을 안내하는 자리이므로 가능성을 나타내는 조동사 표현이 알맞다.\n오답 분석: (A) also enjoyed: 과거 시제라 진행 중인 전시와 맞지 않는다. / (C) are also enjoying: 특정 시점의 진행을 뜻해 안내문으로 어색하다. / (D) have also enjoyed: 이미 관람했다는 뜻이 되어 부적절하다.", "g": {}}, {"no": 138, "q": "", "options": ["The museum will be closed for maintenance on April 3.", "Unfortunately, the film is no longer available.", "Come and learn how these events changed history.", "To volunteer, please fill out an application at the museum."], "answer": 2, "explain": "정답 (C) Come and learn how these events changed history.\n정답 근거: 전시 내용을 소개한 뒤 관람을 권하고 전시 기간으로 마무리하는 흐름이 자연스럽다.\n오답 분석: (A): 휴관 안내는 관람 권유 흐름을 끊다. / (B): 영화를 볼 수 있다고 한 앞 문장과 모순된다. / (D): 자원봉사 신청 안내는 전시 소개와 무관하다.", "g": {}}]}, {"range": "139-142", "passage": "To: Alma Zoldan\nFrom: Rodney Castor (Millerton's)\nSubject: Product Demo\nDear Ms. Zoldan,\nI am writing about your upcoming product presentation to our marketing team on 19 February. Regrettably, I must postpone this ---139---. At present, because of budget restrictions, the home accessories department at Millerton's is not in a position to consider new merchandise.\n---140---. Everyone was interested in learning more about your imported pottery and baskets. They are the types of home decor items that would probably do very well in our store. We would like to ---141--- with you in six months. That is when we anticipate having ---142--- purchasing funds.\nI apologize for this postponement and hope to see you in the near future.", "tr": "수신: Alma Zoldan / 발신: Rodney Castor(Millerton's) / 제목: 제품 시연\nZoldan 씨께,\n2월 19일로 예정된 저희 마케팅 팀 대상 제품 설명회 건으로 연락드립니다. 안타깝게도 이 약속 (139)을 연기해야 합니다. 현재 예산 제약 때문에 Millerton's 생활용품 부서가 새 상품을 검토할 형편이 되지 않습니다. 저희 영업팀과 저는 이 회의를 기대하고 있었다는 점을 말씀드립니다 (140). 모두가 귀사의 수입 도자기와 바구니에 대해 더 알고 싶어 했습니다. 저희 매장에서 아주 잘 팔릴 만한 종류의 생활 장식품입니다. 6개월 뒤에 다시 연락드리고 (141) 싶습니다. 그때쯤이면 추가 (142) 구매 예산이 생길 것으로 예상합니다. 연기하게 되어 죄송하며 머지않아 뵙기를 바랍니다.", "vocab": "regrettably 부 유감스럽게도 / postpone 동 연기하다 / appointment 명 약속 / restriction 명 제한 / merchandise 명 상품 / imported 형 수입된 / reconnect 동 다시 연락하다 / anticipate 동 예상하다", "g": {"to": ["to부정사", "~할"], "alma": ["고유명사", "Alma(인명)"], "zoldan": ["고유명사", "Zoldan(인명)"], "from": ["전치사", "~로부터"], "rodney": ["고유명사", "Rodney(인명)"], "castor": ["고유명사", "Castor(인명)"], "millerton's": ["고유명사", "Millerton's(상호)"], "subject": ["명사", "제목"], "product": ["명사", "제품"], "demo": ["명사", "시연"], "dear": ["형용사", "친애하는"], "ms": ["명사", "~씨(여성)"], "i": ["대명사", "나"], "am": ["동사", "~이다", "be"], "writing": ["현재분사", "쓰고 있는", "write"], "about": ["전치사", "~에 대해"], "your": ["대명사", "여러분의, 당신의"], "upcoming": ["형용사", "다가오는"], "presentation": ["명사", "설명회, 발표"], "our": ["대명사", "우리의"], "marketing": ["명사", "마케팅"], "team": ["명사", "팀"], "on": ["전치사", "~에"], "19": ["숫자", "19일"], "february": ["고유명사", "2월"], "regrettably": ["부사", "유감스럽게도"], "must": ["조동사", "~해야 한다"], "postpone": ["동사", "연기하다"], "this": ["한정사", "이"], "at": ["전치사", "(at present) 현재"], "present": ["명사", "(at present) 현재"], "because": ["전치사", "(because of) ~때문에"], "of": ["전치사", "~의"], "budget": ["명사", "예산"], "restrictions": ["명사", "제한", "restriction"], "the": ["관사", "그"], "home": ["명사", "가정"], "accessories": ["명사", "용품", "accessory"], "department": ["명사", "부서"], "is": ["동사", "~이다", "be"], "not": ["부사", "~않다, 아니다"], "in": ["전치사", "(in a position to) ~할 형편인"], "a": ["관사", "하나의"], "position": ["명사", "처지, 입장"], "consider": ["동사", "고려하다"], "new": ["형용사", "새로운"], "merchandise": ["명사", "상품"], "everyone": ["대명사", "모두"], "was": ["동사", "~이었다", "be"], "interested": ["형용사", "관심 있는"], "learning": ["동명사", "알게 되는 것", "learn"], "more": ["부사", "더"], "imported": ["형용사", "수입된"], "pottery": ["명사", "도자기"], "and": ["접속사", "그리고"], "baskets": ["명사", "바구니", "basket"], "they": ["대명사", "그들"], "are": ["동사", "~이다", "be"], "types": ["명사", "종류", "type"], "decor": ["명사", "장식"], "items": ["명사", "물품", "item"], "that": ["관계사", "~하는 (것)"], "would": ["조동사", "~할 것이다", "will"], "probably": ["부사", "아마"], "do": ["동사", "(do well) 잘 팔리다"], "very": ["부사", "매우"], "well": ["부사", "잘"], "store": ["명사", "매장"], "we": ["대명사", "우리"], "like": ["동사", "(would like to) ~하고 싶다"], "with": ["전치사", "~와 함께"], "you": ["대명사", "여러분, 당신"], "six": ["숫자", "여섯, 6"], "months": ["명사", "달, 개월", "month"], "when": ["부사", "(~하는) 때"], "anticipate": ["동사", "예상하다"], "having": ["동명사", "가지는 것", "have"], "purchasing": ["명사", "구매"], "funds": ["명사", "자금", "fund"], "apologize": ["동사", "사과하다"], "for": ["전치사", "~을 위한"], "postponement": ["명사", "연기"], "hope": ["동사", "바라다"], "see": ["동사", "만나다"], "near": ["형용사", "가까운"], "future": ["명사", "미래"]}, "questions": [{"no": 139, "q": "", "options": ["payment", "submission", "appointment", "performance"], "answer": 2, "explain": "정답 (C) appointment\n지문 개요: 매장 담당자가 예산 사정으로 제품 설명회를 연기하며 6개월 뒤 다시 만나기를 제안하는 이메일이다.\n정답 근거: 앞 문장의 예정된 설명회를 가리켜야 하므로 「약속·일정」이 알맞다.\n오답 분석: (A) payment: '지불'. 연기 대상이 설명회다. / (B) submission: '제출'. 문맥과 맞지 않는다. / (D) performance: '공연·성과'. 설명회를 가리키지 못한다.", "g": {}}, {"no": 140, "q": "", "options": ["Note that my sales team and I were looking forward to the meeting.", "Remember, my office is now located on the third floor.", "Be aware that the store is not open on Sundays.", "As you know, we stock a variety of sportswear."], "answer": 0, "explain": "정답 (A) Note that my sales team and I were looking forward to the meeting.\n정답 근거: 뒤 문장이 모두가 제품에 관심이 있었다고 이어지므로 회의를 기대했다는 진술이 앞에 와야 자연스럽다.\n오답 분석: (B): 사무실 위치는 연기 안내와 무관하다. / (C): 일요일 휴무는 문맥과 이어지지 않는다. / (D): 운동복 취급 여부는 도자기·바구니 이야기와 맞지 않는다.", "g": {}}, {"no": 141, "q": "", "options": ["travel", "compete", "reconnect", "celebrate"], "answer": 2, "explain": "정답 (C) reconnect\n정답 근거: 지금은 연기하지만 나중에 다시 연락해 만나겠다는 뜻이므로 「다시 연락하다」가 알맞다.\n오답 분석: (A) travel: '여행하다'. 문맥과 무관하다. / (B) compete: '경쟁하다'. 거래 관계와 맞지 않는다. / (D) celebrate: '축하하다'. 연기 상황과 어울리지 않는다.", "g": {}}, {"no": 142, "q": "", "options": ["adding", "additionally", "addition", "additional"], "answer": 3, "explain": "정답 (D) additional\n정답 근거: 명사 purchasing funds 앞 형용사 자리이고 예산이 더 생긴다는 뜻이므로 additional이 정답이다.\n오답 분석: (A) adding: 분사로는 자금을 자연스럽게 꾸미지 못한다. / (B) additionally: 부사는 명사를 꾸밀 수 없다. / (C) addition: 명사가 연달아 와 뜻이 성립하지 않는다.", "g": {}}]}, {"range": "143-146", "passage": "SINGAPORE (5 April) - Peytin Tires is planning to greatly increase warehouse capacity at its tire plants in Kuala Lumpur and Bangkok. ---143--- warehouses are expected to open by the end of the year. The expansion project ---144--- the company's ability to serve tire dealers throughout Asia.\n\"The new warehouses will allow us to work more efficiently and save on costs,\" said Peytin Tires' CEO Xiaolin Cui. \"---145---, we will be able to better meet the demands of customers across Asia who have reached out to us. ---146---.\"\nPeytin Tires has been in business for over 40 years and is a major supplier of tires on the continent.", "tr": "싱가포르(4월 5일) ― Peytin Tires가 쿠알라룸푸르와 방콕 타이어 공장의 창고 수용력을 크게 늘릴 계획이다. 더 큰 (143) 창고는 연말까지 문을 열 것으로 예상된다. 이번 확장 사업은 아시아 전역의 타이어 대리점을 지원하는 회사의 역량을 높일 것이다 (144). \"새 창고 덕분에 더 효율적으로 일하고 비용도 아낄 수 있습니다.\" Peytin Tires 최고 경영자 Xiaolin Cui는 말했다. \"동시에 (145) 저희에게 요청해 온 아시아 전역 고객의 수요에 더 잘 부응할 수 있게 됩니다. 이번 조치는 그분들의 의견에 직접 응답한 것입니다 (146).\" Peytin Tires는 40년 넘게 사업을 이어 왔으며 이 대륙의 주요 타이어 공급사이다.", "vocab": "capacity 명 수용력 / plant 명 공장 / expansion 명 확장 / efficiently 부 효율적으로 / meet the demands 구 수요를 충족하다 / reach out to 구 ~에게 연락하다 / at the same time 구 동시에 / supplier 명 공급업체", "g": {"singapore": ["고유명사", "싱가포르"], "5": ["숫자", "5일"], "april": ["고유명사", "4월"], "peytin": ["고유명사", "Peytin(회사명)"], "tires": ["고유명사", "Tires(회사명 일부)"], "is": ["동사", "~이다", "be"], "planning": ["현재분사", "계획하고 있는", "plan"], "to": ["to부정사", "~할"], "greatly": ["부사", "크게"], "increase": ["동사", "늘리다"], "warehouse": ["명사", "창고"], "capacity": ["명사", "수용력"], "at": ["전치사", "~의, ~에서"], "its": ["대명사", "그것의"], "tire": ["명사", "타이어"], "plants": ["명사", "공장", "plant"], "in": ["전치사", "~에 있는"], "kuala": ["고유명사", "Kuala(쿠알라룸푸르)"], "lumpur": ["고유명사", "Lumpur(쿠알라룸푸르)"], "and": ["접속사", "그리고"], "bangkok": ["고유명사", "방콕"], "warehouses": ["명사", "창고", "warehouse"], "are": ["동사", "~이다", "be"], "expected": ["과거분사", "예상되는", "expect"], "open": ["동사", "문을 열다"], "by": ["전치사", "~까지"], "the": ["관사", "그"], "end": ["명사", "끝"], "of": ["전치사", "~의"], "year": ["명사", "해"], "expansion": ["명사", "확장"], "project": ["명사", "사업, 프로젝트"], "company's": ["명사", "회사의", "company"], "ability": ["명사", "능력, 역량"], "serve": ["동사", "(고객을) 응대하다, 지원하다"], "dealers": ["명사", "대리점, 판매업자", "dealer"], "throughout": ["전치사", "~ 전역의"], "asia": ["고유명사", "아시아"], "new": ["형용사", "새로운"], "will": ["조동사", "~할 것이다"], "allow": ["동사", "~할 수 있게 하다"], "us": ["대명사", "우리를"], "work": ["동사", "일하다"], "more": ["부사", "더"], "efficiently": ["부사", "효율적으로"], "save": ["동사", "절약하다"], "on": ["전치사", "~을, ~에 대해"], "costs": ["명사", "비용", "cost"], "said": ["동사", "말했다", "say"], "tires'": ["고유명사", "Tires의(회사명)"], "ceo": ["명사", "최고 경영자"], "xiaolin": ["고유명사", "Xiaolin(인명)"], "cui": ["고유명사", "Cui(인명)"], "we": ["대명사", "우리"], "be": ["동사", "~이다, 되다"], "able": ["형용사", "~할 수 있는"], "better": ["부사", "더 잘", "well"], "meet": ["동사", "충족하다"], "demands": ["명사", "수요", "demand"], "customers": ["명사", "고객", "customer"], "across": ["전치사", "~ 전역의"], "who": ["관계사", "~한 (사람들)"], "have": ["조동사", "(현재완료)", "have"], "reached": ["과거분사", "(reach out to) 연락했다", "reach"], "out": ["부사", "(reach out) 연락하다"], "has": ["조동사", "(현재완료)", "have"], "been": ["과거분사", "(~해) 왔다", "be"], "business": ["명사", "사업"], "for": ["전치사", "~ 동안"], "over": ["전치사", "~ 넘게"], "40": ["숫자", "40"], "years": ["명사", "년, 해", "year"], "a": ["관사", "하나의"], "major": ["형용사", "주요한"], "supplier": ["명사", "공급업체"], "continent": ["명사", "대륙"]}, "questions": [{"no": 143, "q": "", "options": ["Larger", "Cleaner", "Costly", "Temporary"], "answer": 0, "explain": "정답 (A) Larger\n지문 개요: 타이어 회사가 두 공장의 창고를 확충해 아시아 대리점 공급 역량을 높인다는 계획과 배경을 알리는 보도자료다.\n정답 근거: 창고 수용력을 크게 늘린다고 했으므로 새로 여는 창고는 더 큰 규모다.\n오답 분석: (B) Cleaner: '더 깨끗한'. 수용력 확대와 연결되지 않는다. / (C) Costly: '비용이 많이 드는'. 긍정적 발표와 어울리지 않는다. / (D) Temporary: '임시의'. 증설 계획과 어긋남.", "g": {}}, {"no": 144, "q": "", "options": ["improved", "will improve", "had improved", "has been improving"], "answer": 1, "explain": "정답 (B) will improve\n정답 근거: 창고가 연말까지 문을 열 예정이므로 그에 따른 효과도 앞으로의 일이어서 미래 시제가 알맞다.\n오답 분석: (A) improved: 과거 시제라 예정된 효과와 맞지 않는다. / (C) had improved: 과거완료라 시제가 어긋남. / (D) has been improving: 이미 진행 중이라는 뜻이 되어 부적절하다.", "g": {}}, {"no": 145, "q": "", "options": ["If not", "Nevertheless", "On the contrary", "At the same time"], "answer": 3, "explain": "정답 (D) At the same time\n정답 근거: 효율과 비용 절감에 더해 고객 수요 대응도 함께 이루어진다는 뜻이므로 「동시에」가 알맞다.\n오답 분석: (A) If not: 조건을 나타내 문맥과 맞지 않는다. / (B) Nevertheless: 양보 관계가 아니다. / (C) On the contrary: 앞 내용을 뒤집는 관계가 아니다.", "g": {}}, {"no": 146, "q": "", "options": ["Our tires are known for their high quality.", "Several managers were promoted.", "The tire market is very competitive in Asia.", "This move was made in direct response to their feedback."], "answer": 3, "explain": "정답 (D) This move was made in direct response to their feedback.\n정답 근거: 앞 문장이 요청해 온 고객들을 언급했으므로 이번 조치가 그 의견에 대한 응답이라는 문장이 자연스럽게 이어진다.\n오답 분석: (A): 품질 자랑은 창고 증설 설명과 이어지지 않는다. / (B): 관리자 승진은 문맥과 무관하다. / (C): 경쟁 심화 언급은 고객 대응 설명과 연결되지 않는다.", "g": {}}]}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r12-p7',$mkd${"id": "a2-r12-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 2, "round": 12, "level": "중급", "title": "A급 과제 12회 · PART 7 (기출독해 4문항 3·4회)", "notes": [], "items": [], "sets": [{"range": "158-161", "sub": "기출독해 3회", "passage": "To: Customer Service Team\nFrom: Scott Davis, Director of Customer Service\nDate: July 22\nToday kicks off Harkness Clothiers' Customer Service Appreciation Week. I want to take this opportunity to thank you for your dedication and professionalism this year. Each one of you has delivered exceptional customer service. We understand that last year's merger with Sporting Clothes, Inc., was confusing and difficult at times. Your service stayed steady throughout the process and you provided a seamless transition for our clients.\n— [3] —. On Tuesday, starting at 8 A.M., everyone will be treated to a breakfast served with coffee, pastries, and fruit. On Wednesday, we will have a potluck lunch in the afternoon. On Thursday, we will host a team dinner at Mo's Bistro after work. On Friday, there will be contests after lunch where you can win prizes.", "tr": "수신: 고객 서비스 팀 / 발신: 고객 서비스 책임자 Scott Davis / 날짜: 7월 22일\n오늘부터 Harkness Clothiers의 고객 서비스 감사 주간이 시작됩니다. 이 기회를 빌려 올 한 해 여러분의 헌신과 전문성에 감사드립니다. 여러분 한 분 한 분이 뛰어난 고객 서비스를 제공했습니다. 작년 Sporting Clothes 사와의 합병이 때때로 혼란스럽고 힘들었다는 것을 알고 있습니다. 그 과정 내내 여러분의 서비스는 흔들리지 않았고 고객들에게 매끄러운 전환을 제공했습니다. ―[1]― ―[2]― ―[3]―\n화요일 오전 8시부터 커피와 페이스트리, 과일이 곁들여진 아침 식사가 제공됩니다. 수요일 오후에는 각자 음식을 가져오는 점심 모임이 있습니다. 목요일에는 퇴근 후 Mo's Bistro에서 팀 저녁 식사가 열립니다. 금요일 점심 후에는 상품을 받을 수 있는 대회가 열립니다. ―[4]―", "vocab": "kick off 구 시작하다 / appreciation 명 감사 / dedication 명 헌신 / exceptional 형 뛰어난 / merger 명 합병 / seamless 형 매끄러운 / transition 명 전환 / potluck 명 각자 음식을 가져오는 식사 || Paraphrase: 158. 주간 행사 일정 안내(breakfast/lunch/dinner/contests) → provide details of a celebration / 159. last year's merger with Sporting Clothes, Inc. → has combined with another company / 160. On Tuesday, starting at 8 A.M. ~ breakfast → an event in the morning → on Tuesday", "g": {"to": ["전치사", "~에게"], "customer": ["명사", "고객"], "service": ["명사", "서비스"], "team": ["명사", "팀"], "from": ["전치사", "~로부터"], "scott": ["고유명사", "Scott(인명)"], "davis": ["고유명사", "Davis(인명)"], "director": ["명사", "책임자, 이사"], "of": ["전치사", "~의"], "date": ["명사", "날짜"], "july": ["고유명사", "7월"], "22": ["숫자", "22일"], "today": ["명사", "오늘"], "kicks": ["동사", "(kick off) 시작하다", "kick"], "off": ["부사", "(kick off) 시작하다"], "harkness": ["고유명사", "Harkness(회사명)"], "clothiers'": ["고유명사", "Clothiers의(회사명)"], "appreciation": ["명사", "감사"], "week": ["명사", "주간"], "i": ["대명사", "나"], "want": ["동사", "원하다"], "take": ["동사", "(기회를) 잡다"], "this": ["한정사", "이"], "opportunity": ["명사", "기회"], "thank": ["동사", "감사하다"], "you": ["대명사", "여러분, 당신"], "for": ["전치사", "~에 대해"], "your": ["대명사", "여러분의, 당신의"], "dedication": ["명사", "헌신"], "and": ["접속사", "그리고"], "professionalism": ["명사", "전문성"], "year": ["명사", "해"], "each": ["대명사", "각각"], "one": ["대명사", "한 사람"], "has": ["조동사", "(현재완료)", "have"], "delivered": ["과거분사", "제공했다", "deliver"], "exceptional": ["형용사", "뛰어난"], "we": ["대명사", "우리"], "understand": ["동사", "이해하다, 알다"], "that": ["접속사", "~라는 것"], "last": ["형용사", "지난"], "year's": ["명사", "해의", "year"], "merger": ["명사", "합병"], "with": ["전치사", "~와의"], "sporting": ["고유명사", "Sporting(회사명)"], "clothes": ["고유명사", "Clothes(회사명 일부)"], "inc": ["고유명사", "Inc.(주식회사)"], "was": ["동사", "~이었다", "be"], "confusing": ["형용사", "혼란스러운"], "difficult": ["형용사", "힘든"], "at": ["전치사", "(at times) 때때로"], "times": ["명사", "(at times) 때때로", "time"], "stayed": ["동사", "유지되었다", "stay"], "steady": ["형용사", "흔들림 없는"], "throughout": ["전치사", "~ 내내"], "the": ["관사", "그"], "process": ["명사", "과정"], "provided": ["동사", "제공했다", "provide"], "a": ["관사", "하나의"], "seamless": ["형용사", "매끄러운"], "transition": ["명사", "전환"], "our": ["대명사", "우리의"], "clients": ["명사", "고객", "client"], "3": ["숫자", "3 (위치 표시)"], "on": ["전치사", "~에"], "tuesday": ["고유명사", "화요일"], "starting": ["현재분사", "~부터 시작하여", "start"], "8": ["숫자", "8시"], "a.m": ["명사", "오전"], "everyone": ["대명사", "모두"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "treated": ["과거분사", "대접받는", "treat"], "breakfast": ["명사", "아침 식사"], "served": ["과거분사", "제공되는", "serve"], "coffee": ["명사", "커피"], "pastries": ["명사", "페이스트리", "pastry"], "fruit": ["명사", "과일"], "wednesday": ["고유명사", "수요일"], "have": ["동사", "갖다, 열다"], "potluck": ["명사", "각자 음식을 가져오는 식사"], "lunch": ["명사", "점심"], "in": ["전치사", "~에"], "afternoon": ["명사", "오후"], "thursday": ["고유명사", "목요일"], "host": ["동사", "열다, 주최하다"], "dinner": ["명사", "저녁 식사"], "mo's": ["고유명사", "Mo's(상호)"], "bistro": ["명사", "비스트로, 작은 식당"], "after": ["전치사", "~ 후에"], "work": ["명사", "일, 근무"], "friday": ["고유명사", "금요일"], "there": ["부사", "(존재 구문)"], "contests": ["명사", "대회", "contest"], "where": ["관계사", "~하는 (곳)"], "can": ["조동사", "~할 수 있다"], "win": ["동사", "타다, 얻다"], "prizes": ["명사", "상품", "prize"]}, "questions": [{"no": 158, "q": "Why did Mr. Davis write the memo?", "options": ["To ask employees to attend a training session", "To request that employees work overtime", "To provide details of a celebration", "To announce the end of a project"], "answer": 2, "explain": "정답 (C) To provide details of a celebration\n지문 개요: 고객 서비스 책임자가 팀의 노고에 감사하며 한 주간 마련된 행사 일정을 알리는 회람이다.\n정답 근거: 감사 주간을 알리고 요일별 행사 일정을 자세히 안내하고 있다.\n오답 분석: (A): 교육 참석 요청이 아니다. / (B): 초과 근무를 요구하는 내용이 아니다. / (D): 프로젝트 종료 발표가 아니다.", "translation": "Davis 씨는 왜 이 회람을 썼는가?", "g": {"why": ["부사", "왜"], "did": ["조동사", "(의문문 조동사)", "do"], "mr": ["명사", "~씨(남성)"], "davis": ["고유명사", "Davis(인명)"], "write": ["동사", "쓰다"], "the": ["관사", "그"], "memo": ["명사", "회람"]}}, {"no": 159, "q": "What is suggested about Harkness Clothiers?", "options": ["It has combined with another company.", "It gives awards to staff every year.", "It manufactures a line of waterproof clothing.", "It has a very small customer service team."], "answer": 0, "explain": "정답 (A) It has combined with another company.\n정답 근거: 작년에 Sporting Clothes 사와 합병했다고 언급한다.\n오답 분석: (B): 매년 시상한다는 언급이 없다. / (C): 방수 의류 생산에 관한 내용이 없다. / (D): 팀 규모에 관한 정보가 없다.", "translation": "Harkness Clothiers에 대해 알 수 있는 것은?", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "suggested": ["과거분사", "암시된", "suggest"], "about": ["전치사", "~에 대해"], "harkness": ["고유명사", "Harkness(회사명)"], "clothiers": ["고유명사", "Clothiers(회사명)"]}}, {"no": 160, "q": "When will an event take place in the morning?", "options": ["On Tuesday", "On Wednesday", "On Thursday", "On Friday"], "answer": 0, "explain": "정답 (A) On Tuesday\n정답 근거: 화요일 오전 8시부터 아침 식사가 제공된다고 했다.\n오답 분석: (B): 수요일 행사는 오후 점심 모임이다. / (C): 목요일은 퇴근 후 저녁 식사다. / (D): 금요일 대회는 점심 이후다.", "translation": "오전에 열리는 행사는 언제인가?", "g": {"when": ["부사", "언제"], "will": ["조동사", "~할 것이다"], "an": ["관사", "하나의"], "event": ["명사", "행사"], "take": ["동사", "(take place) 열리다"], "place": ["명사", "(take place) 열리다"], "in": ["전치사", "~에"], "the": ["관사", "그"], "morning": ["명사", "오전, 아침"]}}, {"no": 161, "q": "In which of the positions marked [1]-[4] does the following sentence best belong? \"To show our appreciation, management is providing some opportunities to have fun this week.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 2, "explain": "정답 (C) [3]\n정답 근거: 감사 인사를 마무리한 뒤 요일별 행사 안내로 넘어가는 자리이므로 그 사이가 알맞다.\n오답 분석: (A) [1]: 감사의 내용이 아직 이어지는 중이라 이릅니다. / (B) [2]: 합병 관련 서술이 끝나기 전이라 흐름이 끊긴다. / (D) [4]: 행사 안내가 모두 끝난 뒤라 도입 문장으로 늦다.", "translation": "[1]~[4] 중 다음 문장이 들어가기에 가장 적절한 곳은? \"To show our appreciation, management is providing some opportunities to have fun this week.\"", "g": {"in": ["전치사", "~에"], "which": ["한정사", "어느"], "of": ["전치사", "~의"], "the": ["관사", "그"], "positions": ["명사", "위치", "position"], "marked": ["과거분사", "표시된", "mark"], "1]-[4": ["숫자", "[1]~[4]"], "does": ["조동사", "(의문문 조동사)", "do"], "following": ["형용사", "다음의"], "sentence": ["명사", "문장"], "best": ["부사", "가장 잘", "well"], "belong": ["동사", "들어가다, 속하다"], "to": ["to부정사", "~하기 위해"], "show": ["동사", "보여 주다"], "our": ["대명사", "우리의"], "appreciation": ["명사", "감사"], "management": ["명사", "경영진"], "is": ["동사", "~이다", "be"], "providing": ["현재분사", "제공하고 있는", "provide"], "some": ["한정사", "약간의, 몇몇"], "opportunities": ["명사", "기회", "opportunity"], "have": ["동사", "(have fun) 즐기다"], "fun": ["명사", "재미, 즐거움"], "this": ["한정사", "이"], "week": ["명사", "주"]}}]}, {"range": "168-171", "sub": "기출독해 3회", "passage": "Friends of the Chesterton Public Library — Book Sale\nThe Chesterton Public Library will host its annual book sale this weekend on the library's second floor. The hours are Saturday, November 16, 9:00 A.M. to 5:00 P.M., and Sunday, November 17, 12:00 noon to 5:00 P.M. A special preview sale for the Friends of Chesterton Public Library (FCPL), the library's volunteer support group, will be held on Friday, November 15, from 4:00 P.M. to 8:00 P.M.\nThe sale will include books that the library no longer lends, as well as books donated by the public. Proceeds will be used to develop a children's reading room.\nWe welcome donations of books for all ages, in all genres, in both paperback and hardcover. Please note, however, that books that are torn or otherwise defaced will be rejected. Sorry, no magazines or journals, please. Donations can be dropped off at the front desk during the following times: Monday to Thursday: 9:00 A.M. to 11:00 A.M. / Wednesday: 1:00 P.M. to 8:00 P.M. / Friday: 9:00 A.M. to 3:00 P.M.", "tr": "Chesterton 공공도서관의 벗 ― 도서 판매\nChesterton 공공도서관이 이번 주말 도서관 2층에서 연례 도서 판매를 엽니다. 시간은 11월 16일 토요일 오전 9시부터 오후 5시까지, 11월 17일 일요일 정오부터 오후 5시까지입니다. 도서관 자원봉사 지원 단체인 Chesterton 공공도서관의 벗(FCPL)을 위한 사전 판매는 11월 15일 금요일 오후 4시부터 8시까지 열립니다.\n판매 도서에는 도서관이 더 이상 대출하지 않는 책과 시민이 기증한 책이 포함됩니다. 수익금은 어린이 열람실을 마련하는 데 쓰입니다.\n모든 연령대, 모든 분야의 책을 문고본과 양장본 모두 기증받습니다. 다만 찢어졌거나 훼손된 책은 받지 않습니다. 잡지와 학술지는 받지 않으니 양해 바랍니다. 기증 도서는 다음 시간에 안내 데스크로 가져오시면 됩니다. 월~목 오전 9시~11시 / 수요일 오후 1시~8시 / 금요일 오전 9시~오후 3시", "vocab": "annual 형 연례의 / preview 명 사전 (판매) 행사 / volunteer 명 자원봉사자 / donate 동 기부하다 / proceeds 명 수익금 / deface 동 훼손하다 / reject 동 거절하다 / drop off 구 갖다 놓다 || Paraphrase: 168. FCPL, the library's volunteer support group → volunteers / 170. Sorry, no magazines or journals, please → journals cannot be donated / 171. Wednesday: 1:00 P.M. to 8:00 P.M. → dropped off in the evening → on Wednesday", "g": {"friends": ["고유명사", "Friends(단체명 일부)", "friend"], "of": ["전치사", "~의"], "the": ["관사", "그"], "chesterton": ["고유명사", "Chesterton(지명)"], "public": ["형용사", "공공의, 대중"], "library": ["명사", "도서관"], "book": ["명사", "책, 도서"], "sale": ["명사", "판매"], "will": ["조동사", "~할 것이다"], "host": ["동사", "열다, 주최하다"], "its": ["대명사", "그것의"], "annual": ["형용사", "연례의"], "this": ["한정사", "이"], "weekend": ["명사", "주말"], "on": ["전치사", "~에서"], "library's": ["명사", "도서관의", "library"], "second": ["형용사", "두 번째의"], "floor": ["명사", "층"], "hours": ["명사", "(운영) 시간", "hour"], "are": ["동사", "~이다", "be"], "saturday": ["고유명사", "토요일"], "november": ["고유명사", "11월"], "16": ["숫자", "16일"], "9:00": ["숫자", "9시"], "a.m": ["명사", "오전"], "to": ["전치사", "~까지"], "5:00": ["숫자", "5시"], "p.m": ["명사", "오후"], "and": ["접속사", "그리고"], "sunday": ["고유명사", "일요일"], "17": ["숫자", "17일"], "12:00": ["숫자", "12시"], "noon": ["명사", "정오"], "a": ["관사", "하나의"], "special": ["형용사", "특별한"], "preview": ["명사", "사전 (판매) 행사"], "for": ["전치사", "~을 위한"], "fcpl": ["고유명사", "FCPL(단체 약칭)"], "volunteer": ["명사", "자원봉사"], "support": ["명사", "지원"], "group": ["명사", "단체"], "be": ["동사", "~이다, 되다"], "held": ["과거분사", "열리는", "hold"], "friday": ["고유명사", "금요일"], "15": ["숫자", "15일"], "from": ["전치사", "~에서, ~로부터"], "4:00": ["숫자", "4시"], "8:00": ["숫자", "8시"], "include": ["동사", "포함하다"], "books": ["명사", "책", "book"], "that": ["관계사", "~하는 (것)"], "no": ["부사", "(no longer) 더 이상 ~않다"], "longer": ["부사", "(no longer) 더 이상", "long"], "lends": ["동사", "빌려주다, 대출하다", "lend"], "as": ["부사", "(as well as) ~뿐 아니라"], "well": ["부사", "(as well as) ~뿐 아니라"], "donated": ["과거분사", "기증된", "donate"], "by": ["전치사", "~에 의해"], "proceeds": ["명사", "수익금"], "used": ["과거분사", "사용되는", "use"], "develop": ["동사", "마련하다, 개발하다"], "children's": ["명사", "어린이의", "child"], "reading": ["명사", "독서, 열람"], "room": ["명사", "실, 방"], "we": ["대명사", "우리"], "welcome": ["동사", "기꺼이 받