insert into content(key,data,updated_at) values('sec:a2-r14-p5',$mkd${"id": "a2-r14-p5", "area": "RC", "part": 5, "group": "A급 과제", "series": 2, "round": 14, "level": "중급", "title": "A급 과제 14회 · PART 5 (기출어휘 13·14회)", "notes": [], "items": [{"no": 103, "q": "An informational meeting _____ all staff will be held today at 1:00 P.M. in room 28.", "options": ["for", "since", "through", "until"], "answer": 0, "explain": "정답 (A) for\n해석: 전 직원을 위한 설명회가 오늘 오후 1시에 28호실에서 열린다.\n정답 근거: 회의의 대상을 나타내야 하므로 「~을 위한」을 뜻하는 for가 알맞다.\n오답 분석: (B) since: 시점·이유를 나타내 대상을 표시하지 못한다. / (C) through: 통과·기간을 뜻해 문맥과 맞지 않는다. / (D) until: 시간의 한계를 나타내 어색하다.", "translation": "전 직원을 위한 설명회가 오늘 오후 1시에 28호실에서 열린다.", "vocab": "for 전 ~을 위한 (대상) / informational 형 정보 전달의 / hold a meeting 구 회의를 열다 / until 전 ~까지 (계속)", "g": {"room": ["명사", "방"], "all": ["한정사", "모든"], "will": ["조동사", "~할 것이다"], "1:00": ["숫자", "1시"], "an": ["관사", "하나의"], "p.m": ["명사", "오후"], "in": ["전치사", "~에서"], "be": ["동사", "~되다"], "today": ["부사", "오늘"], "28": ["숫자", "28"], "staff": ["명사", "직원"], "at": ["전치사", "~에"], "held": ["과거분사", "열리는", "hold"], "meeting": ["명사", "회의"], "informational": ["형용사", "정보 제공용의"]}, "src": "1-"}, {"no": 105, "q": "Mr. Lee's main responsibility is to _____ five artists on the design team.", "options": ["supervise", "negotiate", "produce", "prefer"], "answer": 0, "explain": "정답 (A) supervise\n해석: Lee 씨의 주된 업무는 디자인 팀의 작가 다섯 명을 관리하는 것이다.\n정답 근거: 사람을 목적어로 취해 「감독·관리하다」를 뜻해야 하므로 supervise가 알맞다.\n오답 분석: (B) negotiate: '협상하다'. 사람을 목적어로 취하지 않는다. / (C) produce: '생산하다'. 사람에게 쓰이지 않는다. / (D) prefer: '선호하다'. 업무 내용으로 어색하다.", "translation": "Lee 씨의 주된 업무는 디자인 팀의 작가 다섯 명을 관리하는 것이다.", "vocab": "supervise 동 감독하다, 관리하다 / responsibility 명 책무, 담당 업무 / negotiate 동 협상하다 / produce 동 제작하다", "g": {"mr": ["명사", "~씨(남성)"], "lee's": ["고유명사", "이 씨의"], "artists": ["명사", "미술가", "artist"], "on": ["전치사", "~에 소속된"], "is": ["동사", "~이다", "be"], "responsibility": ["명사", "책무"], "team": ["명사", "팀"], "design": ["명사", "디자인"], "to": ["to부정사", "~하는 것"], "five": ["숫자", "5"], "main": ["형용사", "주된"], "the": ["관사", "그"]}, "src": "1-"}, {"no": 107, "q": "Quick Future Consultancy helps multinational corporations adapt _____ an ever-changing environment.", "options": ["if", "to", "on", "by"], "answer": 1, "explain": "정답 (B) to\n해석: Quick Future Consultancy는 다국적 기업이 끊임없이 변하는 환경에 적응하도록 돕는다.\n정답 근거: adapt to는 「~에 적응하다」를 뜻하는 결합이므로 to가 정답이다.\n오답 분석: (A) if: 접속사라 뒤에 절이 와야 한다. / (C) on: 이 결합에 쓰이지 않는다. / (D) by: 수단을 나타내 적응 대상을 표시하지 못한다.", "translation": "Quick Future Consultancy는 다국적 기업이 끊임없이 변하는 환경에 적응하도록 돕는다.", "vocab": "adapt to 구 ~에 적응하다 / multinational 형 다국적의 / ever-changing 형 끊임없이 변하는 / corporation 명 기업", "g": {"future": ["고유명사", "퓨처"], "an": ["관사", "하나의"], "adapt": ["동사", "적응하다"], "consultancy": ["고유명사", "컨설턴시"], "corporations": ["명사", "기업", "corporation"], "quick": ["고유명사", "퀵"], "multinational": ["형용사", "다국적의"], "environment": ["명사", "환경"], "ever-changing": ["형용사", "끊임없이 변하는"], "helps": ["동사", "돕다", "help"]}, "src": "1-"}, {"no": 108, "q": "Akau Tour Company can arrange stays on the island _____ with a host family or in a hotel.", "options": ["either", "where", "and", "yet"], "answer": 0, "explain": "정답 (A) either\n해석: Akau 여행사는 섬에서 홈스테이 또는 호텔 숙박을 마련해 줄 수 있다.\n정답 근거: 뒤에 or가 있으므로 상관접속사 either A or B 구조를 이루는 either가 정답이다.\n오답 분석: (B) where: 관계부사라 이 구조를 이루지 못한다. / (C) and: both와 짝을 이루며 or와 맞지 않는다. / (D) yet: 대조를 나타내 상관 구조에 쓰이지 않는다.", "translation": "Akau 여행사는 섬에서 홈스테이 또는 호텔 숙박을 마련해 줄 수 있다.", "vocab": "either A or B 구 A 또는 B 둘 중 하나 / arrange 동 마련하다, 주선하다 / stay 명 숙박, 체류 / host family 명 홈스테이 가정", "g": {"host": ["명사", "주인"], "island": ["명사", "섬"], "akau": ["고유명사", "아카우"], "can": ["조동사", "~할 수 있다"], "or": ["접속사", "또는"], "in": ["전치사", "~에서"], "hotel": ["명사", "호텔"], "company": ["명사", "회사"], "on": ["전치사", "~에서"], "with": ["전치사", "~와 함께"], "a": ["관사", "하나의"], "stays": ["명사", "숙박", "stay"], "tour": ["명사", "여행"], "family": ["명사", "가정"], "arrange": ["동사", "마련하다"], "the": ["관사", "그"]}, "src": "1-"}, {"no": 110, "q": "At Sal's Discount Fashions, clothing always costs _____ less than the manufacturers' recommended sale price.", "options": ["such", "so", "much", "very"], "answer": 2, "explain": "정답 (C) much\n해석: Sal's Discount Fashions에서는 옷값이 제조사 권장 판매가보다 훨씬 저렴하다.\n정답 근거: 비교급 less를 앞에서 강조해야 하므로 비교급 수식이 가능한 much가 알맞다.\n오답 분석: (A) such: 명사구를 강조하며 비교급을 꾸미지 않는다. / (B) so: 원급을 강조할 때 쓰인다. / (D) very: 원급을 강조하며 비교급을 수식하지 못한다.", "translation": "Sal's Discount Fashions에서는 옷값이 제조사 권장 판매가보다 훨씬 저렴하다.", "vocab": "much + 비교급 구 훨씬 (비교급 강조) / cost 동 (비용이) 들다 / manufacturer 명 제조업체 / recommended price 명 권장 가격", "g": {"manufacturers'": ["명사", "제조업체들의", "manufacturer"], "price": ["명사", "가격"], "always": ["부사", "항상"], "sal's": ["고유명사", "샐의"], "fashions": ["명사", "패션", "fashion"], "at": ["전치사", "~에"], "than": ["전치사", "~보다"], "clothing": ["명사", "의류"], "discount": ["명사", "할인"], "less": ["부사", "더 적게"], "recommended": ["과거분사", "권장된", "recommend"], "costs": ["동사", "비용이 들다", "cost"], "the": ["관사", "그"], "sale": ["명사", "판매"]}, "src": "1-"}, {"no": 113, "q": "By always doing more than expected, Ms. Cherny believed she would _____ be promoted.", "options": ["closely", "widely", "originally", "eventually"], "answer": 3, "explain": "정답 (D) eventually\n해석: 늘 기대 이상으로 일하면 결국 승진하리라고 Cherny 씨는 믿었다.\n정답 근거: 꾸준히 노력하면 언젠가 승진한다는 뜻이므로 「결국」이 알맞다.\n오답 분석: (A) closely: '면밀히'. 승진 시점을 나타내지 못한다. / (B) widely: '널리'. 문맥과 맞지 않는다. / (C) originally: '원래'. 앞으로의 일과 시제가 어긋남.", "translation": "늘 기대 이상으로 일하면 결국 승진하리라고 Cherny 씨는 믿었다.", "vocab": "eventually 부 결국, 마침내 / promote 동 승진시키다 / than expected 구 예상보다 / originally 부 원래", "g": {"expected": ["과거분사", "기대된", "expect"], "by": ["전치사", "~함으로써"], "always": ["부사", "항상"], "be": ["동사", "~되다"], "doing": ["동명사", "하기", "do"], "ms": ["명사", "~씨(여성)"], "than": ["전치사", "~보다"], "believed": ["동사", "믿었다", "believe"], "more": ["대명사", "더 많은 것"], "promoted": ["과거분사", "승진된", "promote"], "cherny": ["고유명사", "체르니"], "would": ["조동사", "~할 것이다"], "she": ["대명사", "그녀"]}, "src": "1-"}, {"no": 114, "q": "Dr. Manohar's office sends patients an e-mail _____ 24 hours prior to their appointment.", "options": ["reminder", "subscriber", "traffic", "access"], "answer": 0, "explain": "정답 (A) reminder\n해석: Manohar 박사 진료실은 예약 24시간 전에 환자에게 알림 이메일을 보낸다.\n정답 근거: 예약 전에 보내는 이메일이므로 「알림」을 뜻하는 reminder가 알맞다.\n오답 분석: (B) subscriber: '구독자'. 이메일의 성격을 나타내지 못한다. / (C) traffic: '교통량'. 문맥과 무관하다. / (D) access: '접근'. 이메일과 결합하지 않는다.", "translation": "Manohar 박사 진료실은 예약 24시간 전에 환자에게 알림 이메일을 보낸다.", "vocab": "reminder 명 (예약) 알림, 상기시켜 주는 것 / prior to 구 ~전에 / appointment 명 예약, 약속 / subscriber 명 구독자", "g": {"office": ["명사", "사무실"], "patients": ["명사", "환자", "patient"], "sends": ["동사", "보내다", "send"], "dr": ["명사", "~박사(의사)"], "manohar's": ["고유명사", "마노하르의"], "an": ["관사", "하나의"], "e-mail": ["명사", "이메일"], "hours": ["명사", "시간", "hour"], "24": ["숫자", "24"], "appointment": ["명사", "예약"], "to": ["전치사", "(prior to) ~ 전에"], "their": ["대명사", "그들의"], "prior": ["형용사", "~ 이전의"]}, "src": "1-"}, {"no": 117, "q": "Although Ms. Nakamuro had planned on the new bank teller starting next week, that was not _____.", "options": ["responsible", "possible", "valuable", "cautious"], "answer": 1, "explain": "정답 (B) possible\n해석: Nakamuro 씨는 새 창구 직원이 다음 주에 시작하기를 계획했지만 그것은 가능하지 않았다.\n정답 근거: 계획대로 되지 않았다는 뜻이므로 「가능한」이 알맞다.\n오답 분석: (A) responsible: '책임 있는'. 사람에게 쓰는 말이다. / (C) valuable: '가치 있는'. 실현 여부를 나타내지 못한다. / (D) cautious: '조심스러운'. 문맥과 맞지 않는다.", "translation": "Nakamuro 씨는 새 창구 직원이 다음 주에 시작하기를 계획했지만 그것은 가능하지 않았다.", "vocab": "possible 형 가능한 / plan on -ing 구 ~할 것을 계획하다 / bank teller 명 은행 창구 직원 / cautious 형 신중한", "g": {"bank": ["명사", "은행"], "teller": ["명사", "창구 직원"], "had": ["조동사", "~했었다(과거완료)", "have"], "although": ["접속사", "비록 ~지만"], "week": ["명사", "주"], "planned": ["과거분사", "계획한", "plan"], "on": ["전치사", "~을"], "was": ["동사", "~였다", "be"], "ms": ["명사", "~씨(여성)"], "starting": ["동명사", "시작하기", "start"], "that": ["대명사", "그것"], "not": ["부사", "~않다"], "nakamuro": ["고유명사", "나카무로"], "new": ["형용사", "새로운"], "the": ["관사", "그"], "next": ["형용사", "다음의"]}, "src": "1-"}, {"no": 118, "q": "_____ scheduled maintenance, Orange Moon's Web site will be off-line from 9:00 P.M. till midnight.", "options": ["As long as", "Due to", "Because", "However"], "answer": 1, "explain": "정답 (B) Due to\n해석: 예정된 점검으로 인해 Orange Moon 웹사이트가 오후 9시부터 자정까지 중단된다.\n정답 근거: 뒤에 명사구가 오고 중단의 원인을 나타내므로 「~때문에」가 알맞다.\n오답 분석: (A) As long as: 조건 접속사라 절이 필요하다. / (C) Because: 접속사여서 뒤에 절이 와야 한다. / (D) However: 접속부사라 명사구를 이끌지 못한다.", "translation": "예정된 점검으로 인해 Orange Moon 웹사이트가 오후 9시부터 자정까지 중단된다.", "vocab": "due to + 명사 구 ~때문에 / scheduled 형 예정된 / maintenance 명 (정기) 점검, 유지 보수 / because 접 ~때문에 (절 연결)", "g": {"moon's": ["고유명사", "문의"], "maintenance": ["명사", "유지보수"], "orange": ["고유명사", "오렌지"], "will": ["조동사", "~할 것이다"], "p.m": ["명사", "오후"], "site": ["명사", "사이트"], "be": ["동사", "~되다"], "from": ["전치사", "~부터"], "off-line": ["형용사", "접속 불가인"], "midnight": ["명사", "자정"], "9:00": ["숫자", "9시"], "till": ["전치사", "~까지"], "web": ["명사", "웹"], "scheduled": ["과거분사", "예정된", "schedule"]}, "src": "1-"}, {"no": 120, "q": "Valembois Design's wedge-shaped building features _____ parking and a restaurant on the top floor.", "options": ["underground", "relevant", "careful", "multiple"], "answer": 0, "explain": "정답 (A) underground\n해석: Valembois Design의 쐐기 모양 건물에는 지하 주차장과 꼭대기 층 식당이 있다.\n정답 근거: 주차 공간의 위치를 나타내야 하고 꼭대기 층 식당과 대비되므로 「지하의」가 알맞다.\n오답 분석: (B) relevant: '관련 있는'. 주차장을 꾸미기에 어색하다. / (C) careful: '조심스러운'. 사람의 태도를 뜻한다. / (D) multiple: '여러'. 위치 대비를 만들지 못한다.", "translation": "Valembois Design의 쐐기 모양 건물에는 지하 주차장과 꼭대기 층 식당이 있다.", "vocab": "underground 형 지하의 / feature 동 ~을 특징으로 갖추다 / wedge-shaped 형 쐐기 모양의 / relevant 형 관련 있는", "g": {"wedge-shaped": ["형용사", "쐐기 모양의"], "parking": ["명사", "주차 공간"], "on": ["전치사", "~에"], "a": ["관사", "하나의"], "and": ["접속사", "그리고"], "design's": ["고유명사", "디자인의"], "features": ["동사", "특징으로 하다", "feature"], "valembois": ["고유명사", "발렘부아"], "restaurant": ["명사", "식당"], "floor": ["명사", "층"], "building": ["명사", "건물"], "top": ["형용사", "맨 위의"], "the": ["관사", "그"]}, "src": "1-"}, {"no": 121, "q": "The theater audience _____ applauded the cast of Who is in my chair at the end of the performance.", "options": ["early", "enough", "fashionably", "enthusiastically"], "answer": 3, "explain": "정답 (D) enthusiastically\n해석: 공연이 끝나자 관객들은 출연진에게 열렬히 박수를 보냈다.\n정답 근거: 박수의 방식을 나타내야 하므로 「열렬히」가 알맞다.\n오답 분석: (A) early: '일찍'. 공연이 끝난 시점과 맞지 않는다. / (B) enough: 정도를 나타내지만 동사 앞에서 이렇게 쓰지 않는다. / (C) fashionably: '멋지게'. 박수와 어울리지 않는다.", "translation": "공연이 끝나자 관객들은 출연진에게 열렬히 박수를 보냈다.", "vocab": "enthusiastically 부 열광적으로 / applaud 동 박수갈채하다 / cast 명 출연진 / audience 명 관객", "g": {"applauded": ["동사", "박수를 보냈다", "applaud"], "in": ["고유명사", "인(작품명)"], "my": ["고유명사", "마이(작품명)"], "cast": ["명사", "출연진"], "audience": ["명사", "관객"], "is": ["고유명사", "이즈(작품명)"], "at": ["전치사", "~에"], "chair": ["고유명사", "체어(작품명)"], "theater": ["명사", "극장"], "performance": ["명사", "공연"], "end": ["명사", "끝"], "of": ["전치사", "~의"], "who": ["고유명사", "후(작품명)"], "the": ["관사", "그"]}, "src": "1-"}, {"no": 122, "q": "Ms. Oshiro has approved funding to _____ solar panels on the building.", "options": ["merge", "install", "select", "invest"], "answer": 1, "explain": "정답 (B) install\n해석: Oshiro 씨는 건물에 태양광 패널을 설치하는 자금을 승인했다.\n정답 근거: 패널을 건물에 붙인다는 뜻이므로 「설치하다」가 알맞다.\n오답 분석: (A) merge: '합병하다'. 설비와 어울리지 않는다. / (C) select: '선택하다'. 자금 승인 목적으로 어색하다. / (D) invest: 뒤에 in이 와야 자연스럽다.", "translation": "Oshiro 씨는 건물에 태양광 패널을 설치하는 자금을 승인했다.", "vocab": "install 동 설치하다 / approve 동 승인하다 / funding 명 자금 (지원) / merge 동 합병하다", "g": {"approved": ["과거분사", "승인한", "approve"], "building": ["명사", "건물"], "solar": ["형용사", "태양열의"], "on": ["전치사", "~에"], "oshiro": ["고유명사", "오시로"], "ms": ["명사", "~씨(여성)"], "funding": ["명사", "자금"], "to": ["to부정사", "~할"], "panels": ["명사", "패널", "panel"], "the": ["관사", "그"], "has": ["조동사", "~했다(완료)", "have"]}, "src": "1-"}, {"no": 124, "q": "The Boyeti photo archive _____ contains more than 8,000 images, and it will continue to expand as new images are added.", "options": ["plenty", "already", "alike", "least"], "answer": 1, "explain": "정답 (B) already\n해석: Boyeti 